CREATE OR REPLACE FUNCTION "public"."_device_ui_lease_audit"("p_lease_id" "uuid", "p_device_id" "uuid", "p_event_type" "text", "p_owner_kind" "text", "p_worker_id" "text", "p_request_id" "uuid", "p_run_id" "uuid", "p_reason" "text", "p_metadata_safe" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  insert into public.device_ui_lease_events (
    lease_id, device_id, event_type, owner_kind, worker_id, request_id, run_id, reason, metadata_safe
  ) values (
    p_lease_id, p_device_id, p_event_type, p_owner_kind, p_worker_id, p_request_id, p_run_id,
    coalesce(p_reason, ''), coalesce(p_metadata_safe, '{}'::jsonb)
  );
end;
$$;




CREATE OR REPLACE FUNCTION "public"."account_has_active_ig_run"("p_account_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.ig_runs r
    where r.account_id = p_account_id
      and lower(coalesce(r.status, '')) in (
        'running',
        'queued',
        'pending',
        'in_progress',
        'active',
        'starting'
      )
  );
$$;




CREATE OR REPLACE FUNCTION "public"."account_has_active_runtime_session"("p_account_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $_$
declare
  v_has_active boolean := false;
begin
  if p_account_id is null then
    return false;
  end if;

  if to_regclass('public.ig_runs') is not null then
    begin
      execute $query$
        select exists (
          select 1
          from public.ig_runs
          where account_id = $1
            and status in ('queued', 'pending', 'starting', 'running', 'in_progress', 'active')
        )
      $query$ into v_has_active using p_account_id;
      if v_has_active then
        return true;
      end if;
    exception
      when undefined_table or undefined_column then
        null;
    end;
  end if;

  if to_regclass('public.account_run_requests') is not null then
    begin
      execute $query$
        select exists (
          select 1
          from public.account_run_requests
          where account_id = $1
            and status in ('queued', 'claimed', 'starting', 'running', 'in_progress')
        )
      $query$ into v_has_active using p_account_id;
      if v_has_active then
        return true;
      end if;
    exception
      when undefined_table or undefined_column then
        null;
    end;
  end if;

  return false;
end;
$_$;




CREATE OR REPLACE FUNCTION "public"."account_package_runtime_contract_status"("p_account_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
declare
  v_package_code text;
  v_entitlement_package text;
  v_legacy_package_code text;
  v_entitlement_source text;
  v_package_caps jsonb;
  v_effective_preview jsonb;
  v_runtime_profiles jsonb;
  v_runtime public.commercial_package_runtime_settings%rowtype;
  v_assignment public.account_assignments%rowtype;
  v_instance public.phone_app_instances%rowtype;
  v_settings public.ig_account_settings%rowtype;
  v_sources public.account_follow_source_settings%rowtype;
  v_unfollow public.ig_account_unfollow_settings%rowtype;
  v_dm public.ig_account_dm_settings%rowtype;
  v_account public.ig_accounts%rowtype;
  v_subscription_type text;
  v_expected_clone_mode text;
  v_reason text := 'ready';
  v_follow_day integer;
  v_follow_session integer;
  v_follow_run integer;
  v_unfollow_day integer;
  v_unfollow_session integer;
  v_package_follow_day integer;
  v_package_follow_session integer;
  v_package_unfollow_day integer;
  v_package_unfollow_session integer;
begin
  select * into v_account from public.ig_accounts where id = p_account_id;

  select aps.commercial_package_code, aps.package_caps, aps.effective_caps_preview,
         to_jsonb(aps.runtime_profiles)
  into v_package_code, v_package_caps, v_effective_preview, v_runtime_profiles
  from public.account_package_summary aps
  where aps.account_id = p_account_id;

  select cae.commercial_package_code into v_entitlement_package
  from public.client_account_entitlements cae
  where cae.account_id = p_account_id and cae.status = 'entitlement_consumed'
  order by cae.consumed_at desc nulls last, cae.created_at desc
  limit 1;

  if v_entitlement_package is null then
    select acp.package_code into v_legacy_package_code
    from public.account_commercial_packages acp
    where acp.account_id = p_account_id
      and acp.status = 'active'
      and (acp.ends_at is null or acp.ends_at > now())
      and exists (
        select 1
        from public.client_subscription_accounts csa
        join public.client_subscriptions cs on cs.id = csa.subscription_id
        where csa.account_id = p_account_id
          and csa.status = 'active'
          and cs.status = 'active'
      )
    order by acp.starts_at desc, acp.created_at desc
    limit 1;
  end if;

  v_entitlement_source := case
    when v_entitlement_package is not null then 'consumed_entitlement'
    when v_legacy_package_code is not null then 'legacy_active_subscription_package'
    else 'missing'
  end;

  if v_package_code is not null then
    select prs.* into v_runtime
    from public.commercial_package_runtime_settings prs
    where prs.package_code = v_package_code;
  end if;

  select aa.* into v_assignment
  from public.account_assignments aa
  where aa.account_id = p_account_id and aa.status in ('pending', 'reserved', 'active')
  order by aa.updated_at desc, aa.created_at desc limit 1;

  if v_assignment.app_instance_id is not null then
    select pai.* into v_instance from public.phone_app_instances pai where pai.id = v_assignment.app_instance_id;
  end if;
  select s.* into v_settings
  from public.ig_account_settings s
  where s.account_id = p_account_id
  order by s.updated_at desc nulls last, s.created_at desc nulls last
  limit 1;
  select s.* into v_sources from public.account_follow_source_settings s where s.account_id = p_account_id;
  select s.* into v_unfollow from public.ig_account_unfollow_settings s where s.account_id = p_account_id;
  select s.* into v_dm from public.ig_account_dm_settings s where s.account_id = p_account_id;
  select cs.subscription_type into v_subscription_type
  from public.client_subscription_accounts csa
  join public.client_subscriptions cs on cs.id = csa.subscription_id
  where csa.account_id = p_account_id and csa.status = 'active' and cs.status = 'active'
  order by cs.starts_at desc, cs.created_at desc limit 1;

  v_expected_clone_mode := case
    when v_instance.id is null then null
    when v_instance.instance_type = 'primary_app' or coalesce(v_instance.instance_index, 0) = 0 then 'off'
    else 'clone_' || v_instance.instance_index::text
  end;
  v_package_follow_day := coalesce((v_package_caps ->> 'follow_day')::integer, 0);
  v_package_follow_session := coalesce((v_package_caps ->> 'follow_session')::integer, 0);
  v_package_unfollow_day := coalesce((v_package_caps ->> 'unfollow_day')::integer, 0);
  v_package_unfollow_session := coalesce((v_package_caps ->> 'unfollow_session')::integer, 0);

  if v_account.id is null
     or v_account.status in ('archived', 'trashed')
     or v_account.archived_at is not null
     or v_account.trashed_at is not null then
    v_reason := 'account_archived';
  elsif v_package_code is null
     or v_runtime.package_code is null
     or coalesce(v_entitlement_package, v_legacy_package_code) is distinct from v_package_code then
    v_reason := 'package_settings_incomplete';
  elsif v_assignment.id is null or v_assignment.device_id is null or v_assignment.app_instance_id is null then
    v_reason := 'assignment_package_mismatch';
  elsif v_instance.id is null
     or v_instance.device_id is distinct from v_assignment.device_id
     or nullif(trim(v_instance.package_name), '') is null
     or not coalesce(v_instance.is_launchable, false)
     or not coalesce(v_instance.usable_for_auto_login, false) then
    v_reason := 'app_instance_package_mismatch';
  elsif nullif(trim(v_settings.app_package), '') is null
     or v_settings.app_package is distinct from v_instance.package_name then
    v_reason := 'assignment_package_mismatch';
  elsif v_settings.clone_mode is distinct from v_expected_clone_mode
     or v_settings.cloned_app_mode is distinct from (v_expected_clone_mode <> 'off') then
    v_reason := 'clone_package_mismatch';
  elsif v_subscription_type is null
     or v_assignment.assignment_type is distinct from v_subscription_type
     or not coalesce(v_runtime_profiles ? v_subscription_type, false) then
    v_reason := 'runtime_profile_mismatch';
  elsif v_settings.account_id is null
     or v_sources.account_id is null
     or v_unfollow.account_id is null
     or v_dm.account_id is null
     or v_package_follow_day <= 0
     or v_package_follow_session <= 0
     or v_package_unfollow_day <= 0
     or v_package_unfollow_session <= 0
     or coalesce(v_settings.max_actions_per_day, 0) <= 0
     or coalesce(v_settings.follow_limit, 0) <= 0
     or coalesce(v_settings.max_follow_per_run, 0) <= 0
     or coalesce(v_sources.max_follows_per_target_per_run, 0) <= 0
     or coalesce(v_sources.max_targets_per_run, 0) <= 0
     or coalesce(v_unfollow.unfollow_per_day_limit, 0) <= 0
     or coalesce(v_unfollow.unfollow_per_session_limit, 0) <= 0
     or v_settings.likes_per_follow_min is null
     or v_settings.likes_per_follow_max is null
     or v_settings.total_likes_limit is null
     or v_dm.welcome_enabled is null
     or v_dm.welcome_per_session_limit is null
     or v_dm.welcome_per_day_limit is null
     or v_dm.outreach_enabled is null
     or v_dm.outreach_per_session_limit is null
     or v_dm.outreach_per_day_limit is null then
    v_reason := 'package_settings_incomplete';
  -- Account Follow and Unfollow caps are valid lower overrides. Package values
  -- are ceilings, not mandatory persisted defaults.
  elsif v_settings.max_actions_per_day > v_package_follow_day
     or v_settings.follow_limit > v_package_follow_session
     or v_settings.max_follow_per_run > least(v_package_follow_session, v_settings.follow_limit)
     or v_unfollow.unfollow_per_day_limit > v_package_unfollow_day
     or v_unfollow.unfollow_per_session_limit > v_package_unfollow_session
     -- Source rotation and Like ratios are package-owned exact fields.
     or v_sources.max_follows_per_target_per_run is distinct from v_runtime.max_follows_per_target_per_run
     or v_sources.max_targets_per_run is distinct from v_runtime.max_targets_per_run
     or v_settings.likes_per_follow_min is distinct from v_runtime.likes_per_follow_min
     or v_settings.likes_per_follow_max is distinct from v_runtime.likes_per_follow_max
     or v_settings.total_likes_limit is distinct from v_runtime.likes_per_day_limit then
    v_reason := 'package_settings_incomplete';
  elsif v_assignment.schedule_mode = 'scheduled'
     and (v_assignment.starts_at is null or v_assignment.ends_at is null or v_assignment.ends_at <= v_assignment.starts_at) then
    v_reason := 'package_settings_incomplete';
  end if;

  v_follow_day := least(coalesce(v_settings.max_actions_per_day, 2147483647),
                        nullif(v_package_follow_day, 0),
                        coalesce((v_effective_preview ->> 'follow_day')::integer, 2147483647));
  v_follow_session := least(coalesce(v_settings.follow_limit, 2147483647), nullif(v_package_follow_session, 0));
  v_follow_run := least(coalesce(v_settings.max_follow_per_run, 2147483647), v_follow_session);
  v_unfollow_day := least(coalesce(v_unfollow.unfollow_per_day_limit, 2147483647), nullif(v_package_unfollow_day, 0));
  v_unfollow_session := least(coalesce(v_unfollow.unfollow_per_session_limit, 2147483647), nullif(v_package_unfollow_session, 0));

  return jsonb_build_object(
    'ok', v_reason = 'ready',
    'reason', v_reason,
    'commercial_package_code', v_package_code,
    'entitlement_package_code', coalesce(v_entitlement_package, v_legacy_package_code),
    'consumed_entitlement_package_code', v_entitlement_package,
    'entitlement_source', v_entitlement_source,
    'runtime_profile', v_subscription_type,
    'assignment', jsonb_build_object(
      'assignment_id', v_assignment.id, 'device_id', v_assignment.device_id,
      'app_instance_id', v_assignment.app_instance_id, 'schedule_mode', v_assignment.schedule_mode,
      'slot_kind', v_assignment.slot_kind, 'starts_at', v_assignment.starts_at, 'ends_at', v_assignment.ends_at
    ),
    'android', jsonb_build_object(
      'package_name', v_instance.package_name, 'instance_type', v_instance.instance_type,
      'instance_index', v_instance.instance_index, 'expected_clone_mode', v_expected_clone_mode,
      'configured_package_name', v_settings.app_package, 'configured_clone_mode', v_settings.clone_mode
    ),
    'settings', jsonb_build_object(
      'follow_day', jsonb_build_object('db', v_settings.max_actions_per_day, 'package', v_package_follow_day, 'effective', v_follow_day, 'rule', 'positive_account_override_lte_package'),
      'follow_session', jsonb_build_object('db', v_settings.follow_limit, 'package', v_package_follow_session, 'effective', v_follow_session, 'rule', 'positive_account_override_lte_package'),
      'max_follow_per_run', jsonb_build_object('db', v_settings.max_follow_per_run, 'package', v_package_follow_session, 'effective', v_follow_run, 'rule', 'positive_account_override_lte_effective_session'),
      'max_follows_per_target_per_run', jsonb_build_object('db', v_sources.max_follows_per_target_per_run, 'package', v_runtime.max_follows_per_target_per_run, 'effective', v_sources.max_follows_per_target_per_run, 'rule', 'package_exact'),
      'max_targets_per_run', jsonb_build_object('db', v_sources.max_targets_per_run, 'package', v_runtime.max_targets_per_run, 'effective', v_sources.max_targets_per_run, 'rule', 'package_exact'),
      'unfollow_day', jsonb_build_object('db', v_unfollow.unfollow_per_day_limit, 'package', v_package_unfollow_day, 'effective', v_unfollow_day, 'rule', 'positive_account_override_lte_package'),
      'unfollow_session', jsonb_build_object('db', v_unfollow.unfollow_per_session_limit, 'package', v_package_unfollow_session, 'effective', v_unfollow_session, 'rule', 'positive_account_override_lte_package'),
      'likes_per_follow', jsonb_build_object('min', v_settings.likes_per_follow_min, 'max', v_settings.likes_per_follow_max, 'rule', 'package_exact'),
      'likes_day', jsonb_build_object('db', v_settings.total_likes_limit, 'effective', v_settings.total_likes_limit, 'rule', 'package_exact'),
      'welcome', jsonb_build_object('enabled', v_dm.welcome_enabled, 'session', v_dm.welcome_per_session_limit, 'day', v_dm.welcome_per_day_limit, 'rule', 'positive_lower_override_when_enabled'),
      'outreach', jsonb_build_object('enabled', v_dm.outreach_enabled, 'session', v_dm.outreach_per_session_limit, 'day', v_dm.outreach_per_day_limit, 'rule', 'positive_lower_override_when_enabled'),
      'ops_controls', jsonb_build_object('dry_run_enabled', v_settings.dry_run_enabled, 'send_enabled', v_settings.send_enabled, 'source', 'ig_account_settings')
    )
  );
end;
$$;




CREATE OR REPLACE FUNCTION "public"."account_scoped_credit_balance_cents"("p_client_id" "uuid", "p_account_id" "uuid", "p_currency" "text" DEFAULT 'EUR'::"text") RETURNS integer
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select coalesce(sum(
    case when direction = 'credit' then amount_cents else -amount_cents end
  ), 0)::integer
  from public.client_credit_ledger
  where client_id = p_client_id
    and currency = p_currency
    and account_id = p_account_id;
$$;




COMMENT ON FUNCTION "public"."account_scoped_credit_balance_cents"("p_client_id" "uuid", "p_account_id" "uuid", "p_currency" "text") IS 'Sum ledger credits scoped to one account. Legacy rows with account_id NULL are excluded (fail-closed for per-account flows).';



CREATE OR REPLACE FUNCTION "public"."acquire_device_ui_lease"("p_device_id" "uuid", "p_worker_id" "text", "p_account_id" "uuid", "p_app_instance_id" "uuid" DEFAULT NULL::"uuid", "p_lease_seconds" integer DEFAULT 900, "p_reason" "text" DEFAULT 'ui_operation'::"text", "p_owner_kind" "text" DEFAULT 'worker'::"text", "p_operation_phase" "text" DEFAULT 'executing'::"text") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select public.auto_restart_acquire_device_lock(
    p_device_id, p_worker_id, p_account_id, p_app_instance_id,
    p_lease_seconds, p_reason, p_owner_kind, p_operation_phase
  );
$$;




CREATE OR REPLACE FUNCTION "public"."activate_commercial_plan_change"("p_quote_id" "uuid", "p_idempotency_key" "text", "p_actor_email" "text" DEFAULT NULL::"text", "p_simulated_activation" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_quote public.commercial_plan_change_quotes%rowtype;
  v_existing_quote public.commercial_plan_change_quotes%rowtype;
  v_source_entitlement public.client_account_entitlements%rowtype;
  v_source_session public.commercial_checkout_sessions%rowtype;
  v_current_revision text;
  v_balance integer := 0;
  v_new_session_id uuid;
  v_new_entitlement_id uuid;
  v_credit_applied integer;
  v_now timestamptz := now();
  v_payment_status text;
  v_payment_provider text;
begin
  if coalesce(trim(p_idempotency_key), '') = '' then
    return jsonb_build_object('ok', false, 'code', 'idempotency_required');
  end if;
  select * into v_existing_quote from public.commercial_plan_change_quotes where idempotency_key = p_idempotency_key limit 1;
  if found and v_existing_quote.status = 'quote_activated' then
    return jsonb_build_object('ok', true, 'idempotent_replay', true, 'quote_id', v_existing_quote.id,
      'checkout_session_id', v_existing_quote.activated_checkout_session_id, 'client_id', v_existing_quote.client_id);
  end if;
  select * into v_quote from public.commercial_plan_change_quotes where id = p_quote_id for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'quote_not_found'); end if;
  if v_quote.idempotency_key <> p_idempotency_key then return jsonb_build_object('ok', false, 'code', 'idempotency_mismatch'); end if;
  if v_quote.status <> 'quote_pending' then return jsonb_build_object('ok', false, 'code', 'quote_not_pending'); end if;
  if v_quote.quote_expires_at <= v_now then
    update public.commercial_plan_change_quotes set status = 'quote_expired', updated_at = v_now where id = v_quote.id;
    return jsonb_build_object('ok', false, 'code', 'quote_expired');
  end if;
  if v_quote.amount_due_cents > 0 and coalesce(v_quote.payment_status, 'pending') not in ('confirmed', 'simulated_confirmed') and coalesce(p_simulated_activation, false) = false then
    return jsonb_build_object('ok', false, 'code', 'payment_required');
  end if;
  if v_quote.amount_due_cents > 0 and coalesce(p_simulated_activation, false) = true then
    v_payment_status := 'simulated_confirmed'; v_payment_provider := 'simulated_test';
  elsif v_quote.amount_due_cents <= 0 then v_payment_status := 'not_required'; v_payment_provider := null;
  else v_payment_status := coalesce(v_quote.payment_status, 'confirmed'); v_payment_provider := v_quote.payment_provider; end if;
  select * into v_source_entitlement from public.client_account_entitlements where id = v_quote.source_entitlement_id for update;
  select * into v_source_session from public.commercial_checkout_sessions where id = v_quote.source_checkout_session_id for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'source_missing'); end if;
  v_current_revision := public.commercial_plan_change_source_revision_for_source(v_quote.source_entitlement_id, v_quote.source_checkout_session_id, v_quote.active_commercial_period_value_cents);
  if v_current_revision is null or v_current_revision <> v_quote.source_revision then
    update public.commercial_plan_change_quotes set status = 'quote_stale', updated_at = v_now where id = v_quote.id;
    return jsonb_build_object('ok', false, 'code', 'quote_stale');
  end if;
  if v_source_entitlement.status = 'entitlement_cancelled' then return jsonb_build_object('ok', false, 'code', 'source_inactive'); end if;
  select coalesce(sum(case when direction = 'credit' then amount_cents else -amount_cents end), 0)::integer into v_balance from public.client_credit_ledger where client_id = v_quote.client_id and currency = v_quote.currency;
  if v_balance <> v_quote.existing_customer_credit_cents then
    update public.commercial_plan_change_quotes set status = 'quote_stale', updated_at = v_now where id = v_quote.id;
    return jsonb_build_object('ok', false, 'code', 'credit_balance_changed');
  end if;
  insert into public.commercial_checkout_sessions (idempotency_key, flow_type, status, client_id, auth_user_id, purchaser_email, plan_key, billing_interval_months, outreach_addon_key, billable_account_count, term_discount_percent, agency_discount_percent, applied_discount_percent, applied_discount_type, pack_base_monthly_cents, pack_monthly_discounted_cents, pack_period_total_cents, outreach_base_monthly_cents, outreach_monthly_discounted_cents, outreach_period_total_cents, total_period_cents, catalog_snapshot, metadata, activated_at)
  select p_idempotency_key || ':session', 'plan_change', 'checkout_activated_test', v_quote.client_id, v_source_session.auth_user_id, v_source_session.purchaser_email, v_quote.target_plan_key, v_quote.billing_interval_months, v_source_session.outreach_addon_key, v_source_session.billable_account_count, v_source_session.term_discount_percent, v_source_session.agency_discount_percent, v_source_session.applied_discount_percent, v_source_session.applied_discount_type, v_source_session.pack_base_monthly_cents, v_source_session.pack_monthly_discounted_cents, v_quote.target_full_period_price_cents, v_source_session.outreach_base_monthly_cents, v_source_session.outreach_monthly_discounted_cents, v_source_session.outreach_period_total_cents, v_quote.amount_due_cents, v_source_session.catalog_snapshot, jsonb_build_object('checkout_context','existing_workspace_plan_change','plan_change_quote_id',v_quote.id,'source_checkout_session_id',v_quote.source_checkout_session_id,'source_entitlement_id',v_quote.source_entitlement_id,'period_end_at',v_quote.period_end_at,'commercial_period_value_cents',v_quote.target_full_period_price_cents,'full_period_price_cents',v_quote.target_full_period_price_cents,'target_remaining_cost_cents',v_quote.target_remaining_cost_cents,'current_unused_credit_cents',v_quote.current_unused_credit_cents,'credit_applied_cents',v_quote.credit_applied_cents,'amount_due_cents',v_quote.amount_due_cents,'remaining_credit_cents',v_quote.remaining_credit_cents,'cash_collected_cents',v_quote.amount_due_cents,'payment_provider',v_payment_provider,'payment_status',v_payment_status,'provider_transaction_id',v_quote.provider_transaction_id,'payment_confirmed_at',case when v_payment_status in ('confirmed','simulated_confirmed') then v_now else null end), v_now returning id into v_new_session_id;
  update public.client_account_entitlements set status = 'entitlement_cancelled', updated_at = v_now, metadata = coalesce(metadata,'{}'::jsonb) || jsonb_build_object('superseded_by_plan_change_quote_id',v_quote.id,'superseded_at',v_now) where id = v_source_entitlement.id;
  insert into public.client_account_entitlements (client_id, checkout_session_id, plan_key, commercial_package_code, billing_interval_months, outreach_addon_key, outreach_variant, backend_addon_code, applied_discount_percent, applied_discount_type, pack_monthly_discounted_cents, pack_period_total_cents, outreach_monthly_discounted_cents, outreach_period_total_cents, total_period_cents, catalog_snapshot, status, account_id, consumed_at, metadata)
  select v_quote.client_id, v_new_session_id, v_quote.target_plan_key, v_quote.target_plan_key, v_quote.billing_interval_months, v_source_entitlement.outreach_addon_key, v_source_entitlement.outreach_variant, v_source_entitlement.backend_addon_code, v_source_entitlement.applied_discount_percent, v_source_entitlement.applied_discount_type, v_source_entitlement.pack_monthly_discounted_cents, v_quote.target_full_period_price_cents, v_source_entitlement.outreach_monthly_discounted_cents, v_source_entitlement.outreach_period_total_cents, v_quote.target_full_period_price_cents, v_source_entitlement.catalog_snapshot, 'entitlement_consumed', null, v_now, jsonb_build_object('workspace_plan',true,'period_end_at',v_quote.period_end_at,'commercial_period_value_cents',v_quote.target_full_period_price_cents,'plan_change_quote_id',v_quote.id,'source_entitlement_id',v_source_entitlement.id) returning id into v_new_entitlement_id;
  v_credit_applied := v_quote.credit_applied_cents;
  if v_quote.current_unused_credit_cents > 0 then insert into public.client_credit_ledger (client_id,currency,entry_type,direction,amount_cents,balance_after_cents,source_quote_id,source_checkout_session_id,idempotency_key,metadata) values (v_quote.client_id,v_quote.currency,'proration_credit_generated','credit',v_quote.current_unused_credit_cents,v_balance+v_quote.current_unused_credit_cents,v_quote.id,v_new_session_id,p_idempotency_key||':proration_credit',jsonb_build_object('source_entitlement_id',v_source_entitlement.id)); v_balance := v_balance + v_quote.current_unused_credit_cents; end if;
  if v_credit_applied > 0 then insert into public.client_credit_ledger (client_id,currency,entry_type,direction,amount_cents,balance_after_cents,source_quote_id,source_checkout_session_id,idempotency_key,metadata) values (v_quote.client_id,v_quote.currency,'plan_change_credit_applied','debit',v_credit_applied,greatest(0,v_balance+v_quote.current_unused_credit_cents-v_credit_applied),v_quote.id,v_new_session_id,p_idempotency_key||':credit_applied',jsonb_build_object('target_plan_key',v_quote.target_plan_key)); end if;
  insert into public.commercial_checkout_audit_events (checkout_session_id,entitlement_id,event_type,actor_email,client_id,payload) values (v_new_session_id,v_new_entitlement_id,'plan_change_activated',p_actor_email,v_quote.client_id,jsonb_build_object('quote_id',v_quote.id,'source_plan_key',v_quote.source_plan_key,'target_plan_key',v_quote.target_plan_key,'amount_due_cents',v_quote.amount_due_cents,'remaining_credit_cents',v_quote.remaining_credit_cents,'period_end_at',v_quote.period_end_at));
  update public.commercial_plan_change_quotes set status='quote_activated',activated_at=v_now,activated_checkout_session_id=v_new_session_id,payment_status=v_payment_status,payment_provider=v_payment_provider,payment_confirmed_at=case when v_payment_status in ('confirmed','simulated_confirmed') then v_now else null end,updated_at=v_now where id=v_quote.id;
  return jsonb_build_object('ok',true,'idempotent_replay',false,'quote_id',v_quote.id,'checkout_session_id',v_new_session_id,'entitlement_id',v_new_entitlement_id,'client_id',v_quote.client_id,'remaining_credit_cents',v_quote.remaining_credit_cents);
exception when unique_violation then
  select * into v_existing_quote from public.commercial_plan_change_quotes where idempotency_key=p_idempotency_key limit 1;
  if found and v_existing_quote.status='quote_activated' then return jsonb_build_object('ok',true,'idempotent_replay',true,'quote_id',v_existing_quote.id,'checkout_session_id',v_existing_quote.activated_checkout_session_id,'client_id',v_existing_quote.client_id); end if;
  return jsonb_build_object('ok',false,'code','idempotency_conflict');
end; $$;




CREATE OR REPLACE FUNCTION "public"."activate_commercial_plan_change_per_account"("p_quote_id" "uuid", "p_idempotency_key" "text", "p_actor_email" "text" DEFAULT NULL::"text", "p_simulated_activation" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_quote public.commercial_plan_change_quotes%rowtype;
  v_existing_quote public.commercial_plan_change_quotes%rowtype;
  v_source_entitlement public.client_account_entitlements%rowtype;
  v_source_session public.commercial_checkout_sessions%rowtype;
  v_current_revision text;
  v_balance integer := 0;
  v_new_session_id uuid;
  v_new_entitlement_id uuid;
  v_credit_applied integer;
  v_now timestamptz := now();
  v_payment_status text;
  v_payment_provider text;
  v_policy_revision text;
  v_account_client_id uuid;
begin
  if coalesce(trim(p_idempotency_key), '') = '' then
    return jsonb_build_object('ok', false, 'code', 'idempotency_required');
  end if;

  select * into v_existing_quote
  from public.commercial_plan_change_quotes
  where idempotency_key = p_idempotency_key
  limit 1;

  if found and v_existing_quote.status = 'quote_activated' then
    return jsonb_build_object(
      'ok', true,
      'idempotent_replay', true,
      'quote_id', v_existing_quote.id,
      'checkout_session_id', v_existing_quote.activated_checkout_session_id,
      'client_id', v_existing_quote.client_id,
      'account_id', v_existing_quote.account_id
    );
  end if;

  select * into v_quote
  from public.commercial_plan_change_quotes
  where id = p_quote_id
  for update;

  if not found then
    return jsonb_build_object('ok', false, 'code', 'quote_not_found');
  end if;

  if v_quote.change_scope <> 'per_account' or v_quote.account_id is null then
    return jsonb_build_object('ok', false, 'code', 'quote_scope_invalid');
  end if;

  if v_quote.idempotency_key <> p_idempotency_key then
    return jsonb_build_object('ok', false, 'code', 'idempotency_mismatch');
  end if;

  if v_quote.status <> 'quote_pending' then
    return jsonb_build_object('ok', false, 'code', 'quote_not_pending');
  end if;

  if v_quote.quote_expires_at <= v_now then
    update public.commercial_plan_change_quotes
      set status = 'quote_expired', updated_at = v_now
      where id = v_quote.id;
    return jsonb_build_object('ok', false, 'code', 'quote_expired');
  end if;

  select cia.client_id into v_account_client_id
  from public.client_instagram_accounts cia
  where cia.account_id = v_quote.account_id
    and cia.client_id = v_quote.client_id
  limit 1;

  if v_account_client_id is null then
    return jsonb_build_object('ok', false, 'code', 'account_client_mismatch');
  end if;

  if v_quote.amount_due_cents > 0
     and coalesce(v_quote.payment_status, 'pending') not in ('confirmed', 'simulated_confirmed')
     and coalesce(p_simulated_activation, false) = false then
    return jsonb_build_object('ok', false, 'code', 'payment_required');
  end if;

  if v_quote.amount_due_cents > 0 and coalesce(p_simulated_activation, false) = true then
    v_payment_status := 'simulated_confirmed';
    v_payment_provider := 'simulated_test';
  elsif v_quote.amount_due_cents <= 0 then
    v_payment_status := 'not_required';
    v_payment_provider := null;
  else
    v_payment_status := coalesce(v_quote.payment_status, 'confirmed');
    v_payment_provider := v_quote.payment_provider;
  end if;

  select * into v_source_entitlement
  from public.client_account_entitlements
  where id = v_quote.source_entitlement_id
  for update;

  select * into v_source_session
  from public.commercial_checkout_sessions
  where id = v_quote.source_checkout_session_id
  for update;

  if not found or v_source_entitlement.id is null or v_source_session.id is null then
    return jsonb_build_object('ok', false, 'code', 'source_missing');
  end if;

  if v_source_entitlement.account_id is distinct from v_quote.account_id then
    return jsonb_build_object('ok', false, 'code', 'entitlement_account_mismatch');
  end if;

  if v_source_entitlement.status <> 'entitlement_consumed' then
    return jsonb_build_object('ok', false, 'code', 'source_inactive');
  end if;

  v_current_revision := public.commercial_plan_change_source_revision_for_account_source(
    v_quote.source_entitlement_id,
    v_quote.source_checkout_session_id,
    v_quote.account_id,
    v_quote.active_commercial_period_value_cents
  );

  if v_current_revision is null or v_current_revision <> v_quote.source_revision then
    update public.commercial_plan_change_quotes
      set status = 'quote_stale', updated_at = v_now
      where id = v_quote.id;
    return jsonb_build_object('ok', false, 'code', 'quote_stale');
  end if;

  v_balance := public.account_scoped_credit_balance_cents(v_quote.client_id, v_quote.account_id, v_quote.currency);

  if v_balance <> v_quote.existing_customer_credit_cents then
    update public.commercial_plan_change_quotes
      set status = 'quote_stale', updated_at = v_now
      where id = v_quote.id;
    return jsonb_build_object('ok', false, 'code', 'credit_balance_changed');
  end if;

  insert into public.commercial_checkout_sessions (
    idempotency_key, flow_type, status, client_id, auth_user_id, purchaser_email,
    plan_key, billing_interval_months, outreach_addon_key, billable_account_count,
    term_discount_percent, agency_discount_percent, applied_discount_percent, applied_discount_type,
    pack_base_monthly_cents, pack_monthly_discounted_cents, pack_period_total_cents,
    outreach_base_monthly_cents, outreach_monthly_discounted_cents, outreach_period_total_cents,
    total_period_cents, catalog_snapshot, metadata, activated_at
  )
  select
    p_idempotency_key || ':session',
    'plan_change',
    'checkout_activated_test',
    v_quote.client_id,
    v_source_session.auth_user_id,
    v_source_session.purchaser_email,
    v_quote.target_plan_key,
    v_quote.billing_interval_months,
    coalesce(v_quote.target_outreach_addon_key, v_source_session.outreach_addon_key),
    v_source_session.billable_account_count,
    v_source_session.term_discount_percent,
    v_source_session.agency_discount_percent,
    v_source_session.applied_discount_percent,
    v_source_session.applied_discount_type,
    v_source_session.pack_base_monthly_cents,
    v_source_session.pack_monthly_discounted_cents,
    v_quote.target_full_period_price_cents,
    v_source_session.outreach_base_monthly_cents,
    v_source_session.outreach_monthly_discounted_cents,
    v_source_session.outreach_period_total_cents,
    v_quote.amount_due_cents,
    coalesce(v_quote.pricing_snapshot, v_source_session.catalog_snapshot),
    jsonb_build_object(
      'checkout_context', 'per_account_plan_change',
      'change_scope', 'per_account',
      'account_id', v_quote.account_id,
      'plan_change_quote_id', v_quote.id,
      'source_checkout_session_id', v_quote.source_checkout_session_id,
      'source_entitlement_id', v_quote.source_entitlement_id,
      'period_end_at', v_quote.period_end_at,
      'commercial_period_value_cents', v_quote.target_full_period_price_cents,
      'full_period_price_cents', v_quote.target_full_period_price_cents,
      'target_remaining_cost_cents', v_quote.target_remaining_cost_cents,
      'current_unused_credit_cents', v_quote.current_unused_credit_cents,
      'credit_applied_cents', v_quote.credit_applied_cents,
      'amount_due_cents', v_quote.amount_due_cents,
      'remaining_credit_cents', v_quote.remaining_credit_cents,
      'cash_collected_cents', v_quote.amount_due_cents,
      'payment_provider', v_payment_provider,
      'payment_status', v_payment_status,
      'provider_transaction_id', v_quote.provider_transaction_id,
      'payment_confirmed_at', case when v_payment_status in ('confirmed', 'simulated_confirmed') then v_now else null end
    ),
    v_now
  returning id into v_new_session_id;

  update public.client_account_entitlements
    set status = 'entitlement_cancelled',
        updated_at = v_now,
        metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
          'superseded_by_plan_change_quote_id', v_quote.id,
          'superseded_at', v_now
        )
  where id = v_source_entitlement.id;

  insert into public.client_account_entitlements (
    client_id, checkout_session_id, plan_key, commercial_package_code, billing_interval_months,
    outreach_addon_key, outreach_variant, backend_addon_code,
    applied_discount_percent, applied_discount_type,
    pack_monthly_discounted_cents, pack_period_total_cents,
    outreach_monthly_discounted_cents, outreach_period_total_cents, total_period_cents,
    catalog_snapshot, status, account_id, consumed_at, metadata
  )
  select
    v_quote.client_id,
    v_new_session_id,
    v_quote.target_plan_key,
    v_quote.target_plan_key,
    v_quote.billing_interval_months,
    coalesce(v_quote.target_outreach_addon_key, v_source_entitlement.outreach_addon_key),
    v_source_entitlement.outreach_variant,
    v_source_entitlement.backend_addon_code,
    v_source_entitlement.applied_discount_percent,
    v_source_entitlement.applied_discount_type,
    v_source_entitlement.pack_monthly_discounted_cents,
    v_quote.target_full_period_price_cents,
    v_source_entitlement.outreach_monthly_discounted_cents,
    v_source_entitlement.outreach_period_total_cents,
    v_quote.target_full_period_price_cents,
    coalesce(v_quote.pricing_snapshot, v_source_entitlement.catalog_snapshot),
    'entitlement_consumed',
    v_quote.account_id,
    v_now,
    jsonb_build_object(
      'per_account_plan', true,
      'account_id', v_quote.account_id,
      'period_end_at', v_quote.period_end_at,
      'commercial_period_value_cents', v_quote.target_full_period_price_cents,
      'plan_change_quote_id', v_quote.id,
      'source_entitlement_id', v_source_entitlement.id
    )
  returning id into v_new_entitlement_id;

  perform public.apply_account_commercial_package_plan_change(
    v_quote.account_id,
    v_quote.target_plan_key,
    v_quote.id
  );

  v_policy_revision := public.bump_account_commercial_policy_revision(
    v_quote.account_id,
    v_quote.client_id,
    v_quote.target_plan_key,
    v_new_entitlement_id,
    v_quote.id,
    jsonb_build_object('change_scope', 'per_account', 'source', 'plan_change')
  );

  v_credit_applied := v_quote.credit_applied_cents;

  if v_quote.current_unused_credit_cents > 0 then
    insert into public.client_credit_ledger (
      client_id, account_id, source_entitlement_id, currency, entry_type, direction, amount_cents, balance_after_cents,
      source_quote_id, source_checkout_session_id, idempotency_key, metadata
    ) values (
      v_quote.client_id, v_quote.account_id, v_source_entitlement.id, v_quote.currency, 'proration_credit_generated', 'credit',
      v_quote.current_unused_credit_cents,
      v_balance + v_quote.current_unused_credit_cents,
      v_quote.id, v_new_session_id,
      p_idempotency_key || ':proration_credit',
      jsonb_build_object('source_entitlement_id', v_source_entitlement.id, 'account_id', v_quote.account_id)
    );
    v_balance := v_balance + v_quote.current_unused_credit_cents;
  end if;

  if v_credit_applied > 0 then
    insert into public.client_credit_ledger (
      client_id, account_id, source_entitlement_id, currency, entry_type, direction, amount_cents, balance_after_cents,
      source_quote_id, source_checkout_session_id, idempotency_key, metadata
    ) values (
      v_quote.client_id, v_quote.account_id, v_new_entitlement_id, v_quote.currency, 'plan_change_credit_applied', 'debit',
      v_credit_applied,
      greatest(0, v_balance - v_credit_applied),
      v_quote.id, v_new_session_id,
      p_idempotency_key || ':credit_applied',
      jsonb_build_object('target_plan_key', v_quote.target_plan_key, 'account_id', v_quote.account_id)
    );
    v_balance := greatest(0, v_balance - v_credit_applied);
  end if;

  insert into public.commercial_checkout_audit_events (
    checkout_session_id, entitlement_id, event_type, actor_email, client_id, payload
  ) values (
    v_new_session_id, v_new_entitlement_id, 'plan_change_activated', p_actor_email, v_quote.client_id,
    jsonb_build_object(
      'quote_id', v_quote.id,
      'account_id', v_quote.account_id,
      'change_scope', 'per_account',
      'source_plan_key', v_quote.source_plan_key,
      'target_plan_key', v_quote.target_plan_key,
      'amount_due_cents', v_quote.amount_due_cents,
      'remaining_credit_cents', v_quote.remaining_credit_cents,
      'period_end_at', v_quote.period_end_at,
      'policy_revision', v_policy_revision
    )
  );

  update public.commercial_plan_change_quotes
    set status = 'quote_activated',
        activated_at = v_now,
        activated_checkout_session_id = v_new_session_id,
        payment_status = v_payment_status,
        payment_provider = v_payment_provider,
        payment_confirmed_at = case when v_payment_status in ('confirmed', 'simulated_confirmed') then v_now else null end,
        updated_at = v_now
  where id = v_quote.id;

  return jsonb_build_object(
    'ok', true,
    'idempotent_replay', false,
    'quote_id', v_quote.id,
    'checkout_session_id', v_new_session_id,
    'client_id', v_quote.client_id,
    'account_id', v_quote.account_id,
    'entitlement_id', v_new_entitlement_id,
    'policy_revision', v_policy_revision
  );
end;
$$;




CREATE OR REPLACE FUNCTION "public"."advance_client_instagram_onboarding"("p_session_id" "uuid", "p_client_id" "uuid", "p_actor_id" "uuid", "p_action" "text", "p_value" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_session public.client_instagram_onboarding_sessions%rowtype;
  v_eligible_count integer := 0;
begin
  if not exists (
    select 1 from public.client_users cu
     where cu.client_id = p_client_id
       and cu.auth_user_id = p_actor_id
       and cu.status = 'active'
       and cu.role in ('owner', 'admin', 'assistant')
  ) then
    return jsonb_build_object('ok', false, 'reason', 'client_access_denied');
  end if;

  select * into v_session
    from public.client_instagram_onboarding_sessions
   where id = p_session_id and client_id = p_client_id
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'onboarding_not_found');
  end if;

  if v_session.status in ('active', 'creating', 'failed_retryable')
     and v_session.expires_at <= now() then
    update public.client_instagram_onboarding_sessions
       set status = 'expired', lease_owner = null, lease_expires_at = null, updated_at = now()
     where id = p_session_id;
    return jsonb_build_object('ok', false, 'reason', 'onboarding_expired', 'status', 'expired');
  end if;
  if v_session.status = 'completed' then
    return jsonb_build_object('ok', true, 'already_completed', true, 'status', 'completed');
  end if;
  if v_session.status in ('expired', 'abandoned') then
    return jsonb_build_object('ok', false, 'reason', 'onboarding_terminal', 'status', v_session.status);
  end if;
  if v_session.status = 'creating'
     and v_session.lease_expires_at is not null
     and v_session.lease_expires_at > now() then
    return jsonb_build_object('ok', false, 'reason', 'creation_lease_active', 'status', 'creating');
  end if;
  if v_session.account_id is null then
    return jsonb_build_object('ok', false, 'reason', 'account_not_created');
  end if;

  if p_action = 'abandon' then
    update public.client_instagram_onboarding_sessions
       set status = 'abandoned', abandoned_at = now(), lease_owner = null,
           lease_expires_at = null, updated_at = now()
     where id = p_session_id;
    return jsonb_build_object('ok', true, 'status', 'abandoned');
  elsif p_action = 'save_analysis' then
    if nullif(trim(coalesce(p_value->>'username', '')), '') is null then
      return jsonb_build_object('ok', false, 'reason', 'public_analysis_required');
    end if;
    update public.client_instagram_onboarding_sessions
       set status = 'active', current_step = 'protection_lists', public_analysis = p_value,
           last_progress_at = now(), expires_at = now() + interval '7 days', updated_at = now()
     where id = p_session_id;
  elsif p_action = 'save_protection_lists' then
    if v_session.current_step not in ('protection_lists', 'targeting') then
      return jsonb_build_object('ok', false, 'reason', 'protection_lists_step_invalid');
    end if;
    if coalesce(p_value->>'mode', 'save') = 'skip' then
      update public.client_instagram_onboarding_sessions
         set status = 'active', current_step = 'targeting',
             protection_lists_skipped_at = coalesce(protection_lists_skipped_at, now()),
             last_progress_at = now(), expires_at = now() + interval '7 days', updated_at = now()
       where id = p_session_id;
    else
      if not exists (
        select 1 from public.account_protection_list_versions v
         where v.account_id = v_session.account_id
           and v.list_kind = 'unfollow_whitelist'
      ) or not exists (
        select 1 from public.account_protection_list_versions v
         where v.account_id = v_session.account_id
           and v.list_kind = 'interaction_blacklist'
      ) then
        return jsonb_build_object('ok', false, 'reason', 'protection_lists_not_saved');
      end if;
      update public.client_instagram_onboarding_sessions
         set status = 'active', current_step = 'targeting', protection_lists_skipped_at = null,
             last_progress_at = now(), expires_at = now() + interval '7 days', updated_at = now()
       where id = p_session_id;
    end if;
  elsif p_action = 'save_targeting' then
    if jsonb_typeof(p_value) <> 'object' or p_value = '{}'::jsonb then
      return jsonb_build_object('ok', false, 'reason', 'targeting_criteria_required');
    end if;
    update public.client_instagram_onboarding_sessions
       set status = 'active', current_step = 'targets', targeting_criteria = p_value,
           last_progress_at = now(), expires_at = now() + interval '7 days', updated_at = now()
     where id = p_session_id;
  elsif p_action = 'open_targets' then
    update public.client_instagram_onboarding_sessions
       set status = 'active', current_step = 'targets',
           last_progress_at = now(), expires_at = now() + interval '7 days', updated_at = now()
     where id = p_session_id;
  elsif p_action = 'complete' then
    if nullif(trim(coalesce(v_session.public_analysis->>'username', '')), '') is null then
      return jsonb_build_object('ok', false, 'reason', 'public_analysis_required');
    end if;
    if jsonb_typeof(v_session.targeting_criteria) <> 'object'
       or v_session.targeting_criteria = '{}'::jsonb then
      return jsonb_build_object('ok', false, 'reason', 'targeting_criteria_required');
    end if;
    if v_session.protection_lists_skipped_at is null and (
      not exists (
        select 1 from public.account_protection_list_versions v
         where v.account_id = v_session.account_id
           and v.list_kind = 'unfollow_whitelist'
      ) or not exists (
        select 1 from public.account_protection_list_versions v
         where v.account_id = v_session.account_id
           and v.list_kind = 'interaction_blacklist'
      )
    ) then
      return jsonb_build_object('ok', false, 'reason', 'protection_lists_not_saved');
    end if;

    select count(*)::integer into v_eligible_count
      from public.ig_targets t
     where t.account_id = v_session.account_id
       and lower(trim(coalesce(t.status, ''))) in ('valid', 'active')
       and lower(trim(coalesce(t.quality_status, ''))) = 'eligible'
       and lower(trim(coalesce(t.verification_status, ''))) = 'found'
       and t.archived_at is null
       and t.deleted_at is null;
    if v_eligible_count < 15 then
      return jsonb_build_object(
        'ok', false, 'reason', 'target_minimum_not_met',
        'eligible_count', v_eligible_count, 'required_count', 15
      );
    end if;

    update public.client_instagram_onboarding_sessions
       set status = 'completed', current_step = 'complete', completed_at = now(),
           lease_owner = null, lease_expires_at = null,
           last_progress_at = now(), updated_at = now()
     where id = p_session_id;
    update public.client_instagram_accounts
       set onboarding_status = 'configured', provisioning_status = 'not_started', updated_at = now()
     where client_id = p_client_id and account_id = v_session.account_id;
    insert into public.commercial_checkout_audit_events (
      entitlement_id, event_type, client_id, payload
    ) values (
      v_session.entitlement_id,
      'client_instagram_onboarding_completed',
      p_client_id,
      jsonb_build_object(
        'onboarding_session_id', p_session_id,
        'account_id', v_session.account_id,
        'actor_id', p_actor_id,
        'eligible_target_count', v_eligible_count,
        'required_target_count', 15,
        'protection_lists_source', 'account_protection_list_entries',
        'protection_lists_skipped', v_session.protection_lists_skipped_at is not null,
        'runtime_activation_requested', false
      )
    );
    return jsonb_build_object('ok', true, 'status', 'completed', 'eligible_count', v_eligible_count);
  else
    return jsonb_build_object('ok', false, 'reason', 'onboarding_action_invalid');
  end if;

  return jsonb_build_object('ok', true, 'status', 'active');
end;
$$;




COMMENT ON FUNCTION "public"."advance_client_instagram_onboarding"("p_session_id" "uuid", "p_client_id" "uuid", "p_actor_id" "uuid", "p_action" "text", "p_value" "jsonb") IS 'Advances resumable onboarding through canonical protection lists before targeting; completion recounts 15 strict eligible targets in PostgreSQL.';



CREATE OR REPLACE FUNCTION "public"."apply_account_commercial_package_plan_change"("p_account_id" "uuid", "p_package_code" "text", "p_quote_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_existing_id uuid;
  v_existing_code text;
begin
  select id, package_code into v_existing_id, v_existing_code
  from public.account_commercial_packages
  where account_id = p_account_id
    and status = 'active'
    and ends_at is null
  order by starts_at desc
  limit 1
  for update;

  if v_existing_code = p_package_code then
    return;
  end if;

  if v_existing_id is not null then
    update public.account_commercial_packages
      set ends_at = now(), updated_at = now()
      where id = v_existing_id;
  end if;

  insert into public.account_commercial_packages (
    account_id, package_code, status, source, metadata_safe
  ) values (
    p_account_id,
    p_package_code,
    'active',
    'plan_change',
    jsonb_build_object(
      'source', 'plan_change',
      'plan_change_quote_id', p_quote_id
    )
  );
end;
$$;




CREATE OR REPLACE FUNCTION "public"."apply_account_follow_limit_provenance_v1"("p_account_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_policy public.ig_account_follow_limit_overrides%rowtype;
  v_package_day integer;
  v_package_session integer;
  v_day integer;
  v_session integer;
  v_run integer;
  v_previous_guard text := coalesce(current_setting('bmb.package_contract_reconcile', true), '');
begin
  select
    nullif(aps.package_caps ->> 'follow_day', '')::integer,
    nullif(aps.package_caps ->> 'follow_session', '')::integer
  into v_package_day, v_package_session
  from public.account_package_summary aps
  where aps.account_id = p_account_id;

  if coalesce(v_package_day, 0) <= 0 or coalesce(v_package_session, 0) <= 0 then
    return jsonb_build_object(
      'ok', false,
      'reason', 'package_settings_incomplete',
      'account_id', p_account_id
    );
  end if;

  select * into v_policy
  from public.ig_account_follow_limit_overrides o
  where o.account_id = p_account_id;

  v_day := least(v_package_day, coalesce(v_policy.follow_day_cap_override, v_package_day));
  v_session := least(v_package_session, coalesce(v_policy.follow_session_cap_override, v_package_session));
  v_run := least(
    v_session,
    coalesce(v_policy.max_follow_per_run_legacy, v_session)
  );

  perform set_config('bmb.package_contract_reconcile', 'on', true);
  update public.ig_account_settings s
  set max_actions_per_day = v_day,
      follow_limit = v_session,
      max_follow_per_run = v_run,
      updated_at = case
        when (s.max_actions_per_day, s.follow_limit, s.max_follow_per_run)
          is distinct from (v_day, v_session, v_run)
        then now()
        else s.updated_at
      end
  where s.account_id = p_account_id;
  perform set_config('bmb.package_contract_reconcile', v_previous_guard, true);

  return jsonb_build_object(
    'ok', true,
    'reason', case
      when v_policy.account_id is null then 'package_inherited'
      else v_policy.classification
    end,
    'account_id', p_account_id,
    'package_day', v_package_day,
    'package_session', v_package_session,
    'configured_day', v_day,
    'configured_session', v_session,
    'legacy_run_cap', v_run
  );
exception when others then
  perform set_config('bmb.package_contract_reconcile', v_previous_guard, true);
  raise;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."apply_instagram_action_restriction_v1"("p_account_id" "uuid", "p_account_username" "text" DEFAULT NULL::"text", "p_run_id" "uuid" DEFAULT NULL::"uuid", "p_request_id" "uuid" DEFAULT NULL::"uuid", "p_stable_reason" "text" DEFAULT 'instagram_action_rate_limit'::"text", "p_metadata_safe" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_account public.ig_accounts%rowtype;
  v_hold public.instagram_account_restriction_holds%rowtype;
  v_incident public.account_incidents%rowtype;
  v_generation_id uuid := gen_random_uuid();
  v_dedupe_key text;
  v_deduplicated boolean := false;
  v_action jsonb;
begin
  if coalesce(auth.jwt() ->> 'role', '') <> 'service_role' then
    raise exception 'service_role_required' using errcode = '42501';
  end if;
  if p_account_id is null then
    raise exception 'account_id_required' using errcode = '22023';
  end if;
  if coalesce(nullif(trim(p_stable_reason), ''), '') <> 'instagram_action_rate_limit' then
    raise exception 'stable_reason_invalid' using errcode = '22023';
  end if;

  select * into v_account
  from public.ig_accounts
  where id = p_account_id
  for update;
  if v_account.id is null then
    raise exception 'account_not_found' using errcode = '22023';
  end if;

  select * into v_hold
  from public.instagram_account_restriction_holds
  where account_id = p_account_id
    and status in ('active', 'verification_required')
  for update;

  -- A popup reappearing after human resolution is a new restriction
  -- generation. Preserve the old row as evidence and open a new incident.
  if v_hold.id is not null and v_hold.status = 'verification_required' then
    update public.instagram_account_restriction_holds
    set status = 'superseded',
        last_seen_at = now(),
        occurrence_count = occurrence_count + 1,
        metadata_safe = coalesce(metadata_safe, '{}'::jsonb)
          || jsonb_build_object('restriction_reappeared_at', now()),
        updated_at = now()
    where id = v_hold.id;
    v_hold := null;
  end if;

  if v_hold.id is not null then
    v_generation_id := v_hold.generation_id;
    v_dedupe_key := 'account:' || p_account_id::text
      || ':instagram_action_rate_limit:' || v_generation_id::text;
    v_deduplicated := true;
  else
    v_dedupe_key := 'account:' || p_account_id::text
      || ':instagram_action_rate_limit:' || v_generation_id::text;
  end if;

  select * into v_incident
  from public.upsert_account_incident(
    p_incident_type => 'instagram_account_restriction',
    p_dedupe_key => v_dedupe_key,
    p_severity => 'error',
    p_status => 'open',
    p_account_id => p_account_id,
    p_account_username => coalesce(nullif(trim(p_account_username), ''), v_account.username),
    p_run_id => p_run_id,
    p_source => 'instagram_action_restriction_guard',
    p_reason => 'instagram_action_rate_limit',
    p_failure_reason => 'instagram_action_rate_limit',
    p_action_required => 'Open the account manually, verify whether Instagram still shows the action restriction, wait if necessary, then resolve the incident only after confirming the restriction is cleared.',
    p_safe_client_message => 'Automation paused because Instagram is temporarily limiting actions.',
    p_assistant_message => 'Instagram action restriction detected. The campaign is paused and Auto Restart is blocked.',
    p_admin_message => 'Human review and a successful physical preflight are required before business actions may resume.',
    p_metadata => coalesce(p_metadata_safe, '{}'::jsonb) || jsonb_build_object(
      'stable_reason', 'instagram_action_rate_limit',
      'risk_class', 'human_review_required',
      'severity', 'error',
      'blocking_campaign', true,
      'operator_review_required', true,
      'auto_restart_allowed', false,
      'account_pause_required', true,
      'physical_preflight_required', true,
      'request_id', p_request_id,
      'restriction_generation', v_generation_id
    )
  );

  if v_hold.id is null then
    insert into public.instagram_account_restriction_holds (
      account_id, incident_id, generation_id, stable_reason, status,
      previous_admin_lifecycle_status, metadata_safe
    ) values (
      p_account_id, v_incident.id, v_generation_id,
      'instagram_action_rate_limit', 'active',
      v_account.admin_lifecycle_status,
      coalesce(p_metadata_safe, '{}'::jsonb)
        || jsonb_build_object('request_id', p_request_id, 'run_id', p_run_id)
    ) returning * into v_hold;
  else
    update public.instagram_account_restriction_holds
    set incident_id = v_incident.id,
        last_seen_at = now(),
        occurrence_count = occurrence_count + 1,
        metadata_safe = coalesce(metadata_safe, '{}'::jsonb)
          || coalesce(p_metadata_safe, '{}'::jsonb)
          || jsonb_build_object('last_request_id', p_request_id, 'last_run_id', p_run_id),
        updated_at = now()
    where id = v_hold.id
    returning * into v_hold;
  end if;

  -- Reuse the canonical visible lifecycle pause. The hold row records prior
  -- state so only its own preflight release may restore it.
  if coalesce(v_account.admin_lifecycle_status, '') <> 'paused' then
    update public.ig_accounts
    set admin_lifecycle_status = 'paused', updated_at = now()
    where id = p_account_id;
  end if;

  select to_jsonb(a) into v_action
  from public.upsert_account_dashboard_action(
    p_account_id => p_account_id,
    p_client_id => null,
    p_incident_id => v_incident.id,
    p_action_type => 'operator_review_required',
    p_status => 'pending_verification',
    p_title => 'Instagram action restriction detected',
    p_dedupe_key => 'account:' || p_account_id::text || ':incident:' || v_incident.id::text || ':restriction_review',
    p_safe_client_message => null,
    p_admin_message => 'Verify the Instagram restriction manually. Do not resolve until it is cleared.',
    p_assistant_message => 'Campaign paused. Auto Restart remains blocked until review and physical preflight.',
    p_action_label => 'Mark reviewed',
    p_action_deep_link => '/instagram-dashboard/incidents',
    p_severity => 'error',
    p_audience => 'admin',
    p_requires_client_action => false,
    p_blocking_campaign => true,
    p_metadata => jsonb_build_object(
      'stable_reason', 'instagram_action_rate_limit',
      'restriction_generation', v_generation_id,
      'physical_preflight_required', true
    )
  ) a;

  return jsonb_build_object(
    'ok', true,
    'incident_id', v_incident.id,
    'dedupe_key', v_dedupe_key,
    'hold_id', v_hold.id,
    'hold_status', v_hold.status,
    'restriction_generation', v_generation_id,
    'deduplicated', v_deduplicated,
    'account_paused', true,
    'auto_restart_allowed', false,
    'operator_review_required', true,
    'dashboard_action', coalesce(v_action, '{}'::jsonb)
  );
end
$$;




CREATE OR REPLACE FUNCTION "public"."arm_incident_resolution_auto_resume_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_plan public.account_session_resume_plans%rowtype;
  v_assignment public.account_assignments%rowtype;
  v_window_start timestamptz;
  v_window_end timestamptz;
  v_window_key text;
  v_authorization_id uuid;
begin
  if new.status <> 'resolved'
     or old.status = 'resolved'
     or new.run_id is null
     or new.account_id is null
     or new.incident_type not in (
       'run_identity_verification_failed',
       'active_instagram_account_mismatch',
       'account_login_required',
       'assigned_instagram_package_unavailable',
       'run_device_unavailable',
       'run_worker_failure'
     ) then
    return new;
  end if;

  select p.* into v_plan
  from public.account_session_resume_plans p
  where p.run_id = new.run_id
    and p.account_id = new.account_id
    and p.resume_state = 'awaiting_human_resume_authorization'
  order by p.last_updated_at desc nulls last, p.created_at desc
  limit 1;

  if v_plan.id is null then
    return new;
  end if;

  select a.* into v_assignment
  from public.account_assignments a
  where a.account_id = new.account_id
    and a.status in ('reserved', 'active')
    and (v_plan.assignment_id is null or a.id = v_plan.assignment_id)
    and a.starts_at <= now()
    and a.ends_at > now()
  order by case when a.id = v_plan.assignment_id then 0 else 1 end,
           a.starts_at desc
  limit 1;

  v_window_start := coalesce(v_plan.scheduled_window_start, v_assignment.starts_at);
  v_window_end := coalesce(v_plan.scheduled_window_end, v_assignment.ends_at);
  if v_window_start is null or v_window_end is null
     or not (v_window_start <= now() and now() < v_window_end) then
    return new;
  end if;

  v_window_key := coalesce(
    nullif(v_plan.resume_window_key, ''),
    new.account_id::text || ':' || v_window_start::text
  );

  insert into public.incident_resume_authorizations (
    incident_id, account_id, run_id, resume_plan_id, resume_window_key,
    scheduled_window_start, scheduled_window_end, status, armed_source,
    resolution_note, metadata_safe, test
  ) values (
    new.id, new.account_id, new.run_id, v_plan.id, v_window_key,
    v_window_start, v_window_end, 'armed', 'incident_resolution',
    left(coalesce(new.resolution_note, ''), 500),
    jsonb_build_object(
      'incident_type', new.incident_type,
      'reason_code', coalesce(new.reason, new.failure_reason),
      'resolution_is_resume_authorization', true
    ),
    lower(coalesce(new.metadata ->> 'test', 'false')) in ('true', '1', 'yes')
  )
  on conflict do nothing
  returning id into v_authorization_id;

  if v_authorization_id is not null then
    update public.account_session_resume_plans
    set scheduled_window_start = v_window_start,
        scheduled_window_end = v_window_end,
        resume_window_key = v_window_key,
        last_updated_at = now()
    where id = v_plan.id;

    new.metadata := coalesce(new.metadata, '{}'::jsonb) || jsonb_build_object(
      'recovery', coalesce(new.metadata -> 'recovery', '{}'::jsonb) || jsonb_build_object(
        'state', 'ready_to_resume',
        'authorization_id', v_authorization_id,
        'armed_at', now(),
        'source', 'incident_resolution'
      )
    );
  end if;
  return new;
end
$$;




CREATE OR REPLACE FUNCTION "public"."assign_account_manual_only"("p_account_id" "uuid", "p_device_id" "uuid", "p_app_instance_id" "uuid", "p_assignment_source" "text" DEFAULT 'manual_dashboard'::"text", "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_account_id uuid := p_account_id;
  v_device_id uuid := p_device_id;
  v_app_instance_id uuid := p_app_instance_id;
  v_assignment_source text := coalesce(nullif(trim(p_assignment_source), ''), 'manual_dashboard');
  v_subscription_id uuid;
  v_client_id uuid;
  v_subscription_account_id uuid;
  v_assignment_type text;
  v_device_status text;
  v_device_pool_type text;
  v_instance_device_id uuid;
  v_instance_status text;
  v_instance_current_account_id uuid;
  v_instance_usable boolean;
  v_instance_launchable boolean;
  v_existing record;
  v_old_app_instance_id uuid;
  v_old_clone_id uuid;
  v_clone_id uuid;
  v_assignment_id uuid;
  v_metadata jsonb;
begin
  if v_account_id is null or v_device_id is null then
    raise exception 'invalid_assignment_payload';
  end if;

  if v_app_instance_id is null then
    raise exception 'manual_only_requires_app_instance';
  end if;

  if v_assignment_source not in ('manual_dashboard', 'onboarding_auto', 'ops', 'auto_assign_rpc') then
    raise exception 'invalid_assignment_source';
  end if;

  v_assignment_type := public.resolve_account_schedule_assignment_type(v_account_id);
  if v_assignment_type is null then
    raise exception 'subscription_not_active';
  end if;

  select
    csa.id,
    csa.subscription_id,
    cs.client_id
  into v_subscription_account_id, v_subscription_id, v_client_id
  from public.client_subscription_accounts csa
  join public.client_subscriptions cs on cs.id = csa.subscription_id
  where csa.account_id = v_account_id
    and csa.status = 'active'
    and cs.status = 'active'
    and cs.subscription_type = v_assignment_type
  order by cs.starts_at desc, cs.created_at desc
  limit 1;

  if v_subscription_account_id is null then
    raise exception 'subscription_not_active';
  end if;

  select pd.status, pd.pool_type
  into v_device_status, v_device_pool_type
  from public.phone_devices pd
  where pd.id = v_device_id
  for update;

  if v_device_status is null or v_device_status not in ('available', 'active') then
    raise exception 'device_unavailable';
  end if;

  if v_device_pool_type <> 'shared' and v_device_pool_type <> v_assignment_type then
    raise exception 'assignment_profile_mismatch';
  end if;

  select pai.device_id, pai.status, pai.current_account_id, pai.usable_for_auto_login, pai.is_launchable
  into v_instance_device_id, v_instance_status, v_instance_current_account_id, v_instance_usable, v_instance_launchable
  from public.phone_app_instances pai
  where pai.id = v_app_instance_id
  for update;

  if v_instance_device_id is null or v_instance_device_id <> v_device_id then
    raise exception 'preferred_app_instance_incompatible';
  end if;

  if not coalesce(v_instance_usable, false) or not coalesce(v_instance_launchable, false) then
    raise exception 'preferred_app_instance_incompatible';
  end if;

  if v_instance_current_account_id is not null and v_instance_current_account_id <> v_account_id then
    raise exception 'app_instance_already_reserved';
  end if;

  if v_instance_status <> 'available'
     and not (v_instance_status = 'occupied' and v_instance_current_account_id = v_account_id) then
    raise exception 'app_instance_already_reserved';
  end if;

  if exists (
    select 1
    from public.account_assignments aa
    where aa.app_instance_id = v_app_instance_id
      and aa.account_id <> v_account_id
      and aa.status in ('pending', 'reserved', 'active')
  ) then
    raise exception 'app_instance_already_reserved';
  end if;

  select
    aa.id,
    aa.device_id,
    aa.clone_id,
    aa.app_instance_id,
    aa.starts_at,
    aa.ends_at,
    aa.status,
    aa.schedule_mode
  into v_existing
  from public.account_assignments aa
  where aa.account_id = v_account_id
    and aa.status in ('pending', 'reserved', 'active')
  order by aa.created_at desc
  limit 1
  for update;

  v_old_app_instance_id := v_existing.app_instance_id;
  v_old_clone_id := v_existing.clone_id;

  select pc.id
  into v_clone_id
  from public.phone_clones pc
  where pc.id = v_app_instance_id;

  v_metadata := jsonb_build_object(
    'assigned_by', coalesce(p_actor_id::text, 'system'),
    'assignment_source', v_assignment_source,
    'schedule_mode', 'manual_only',
    'assigned_at', now(),
    'previous_assignment', case
      when v_existing.id is null then null
      else jsonb_build_object(
        'assignment_id', v_existing.id,
        'device_id', v_existing.device_id,
        'clone_id', v_existing.clone_id,
        'app_instance_id', v_existing.app_instance_id,
        'starts_at', v_existing.starts_at,
        'ends_at', v_existing.ends_at,
        'status', v_existing.status,
        'schedule_mode', v_existing.schedule_mode
      )
    end
  );

  if v_existing.id is not null then
    update public.account_assignments
    set
      client_id = v_client_id,
      subscription_id = v_subscription_id,
      subscription_account_id = v_subscription_account_id,
      device_id = v_device_id,
      clone_id = v_clone_id,
      app_instance_id = v_app_instance_id,
      assignment_type = v_assignment_type,
      slot_kind = 'manual_only',
      schedule_mode = 'manual_only',
      status = 'reserved',
      starts_at = null,
      ends_at = null,
      assignment_source = v_assignment_source,
      assigned_at = now(),
      metadata = coalesce(metadata, '{}'::jsonb) || v_metadata,
      updated_at = now()
    where id = v_existing.id
    returning id into v_assignment_id;
  else
    insert into public.account_assignments (
      client_id,
      subscription_id,
      subscription_account_id,
      account_id,
      device_id,
      clone_id,
      app_instance_id,
      assignment_type,
      slot_kind,
      schedule_mode,
      status,
      starts_at,
      ends_at,
      assigned_at,
      assignment_source,
      metadata
    )
    values (
      v_client_id,
      v_subscription_id,
      v_subscription_account_id,
      v_account_id,
      v_device_id,
      v_clone_id,
      v_app_instance_id,
      v_assignment_type,
      'manual_only',
      'manual_only',
      'reserved',
      null,
      null,
      now(),
      v_assignment_source,
      v_metadata
    )
    returning id into v_assignment_id;
  end if;

  update public.phone_app_instances
  set status = 'occupied',
      current_account_id = v_account_id,
      updated_at = now()
  where id = v_app_instance_id
    and status <> 'disabled';

  if v_clone_id is not null then
    update public.phone_clones
    set status = 'reserved',
        current_account_id = v_account_id,
        updated_at = now()
    where id = v_clone_id;
  end if;

  if v_old_app_instance_id is not null and v_old_app_instance_id <> v_app_instance_id then
    perform public.release_app_instance_if_unused(
      v_old_app_instance_id,
      v_account_id,
      'reassignment_release_old_instance',
      'assign_account_manual_only'
    );
  end if;

  if v_old_clone_id is not null and v_old_clone_id <> v_clone_id and not exists (
    select 1
    from public.account_assignments aa
    where aa.clone_id = v_old_clone_id
      and aa.status in ('pending', 'reserved', 'active')
  ) then
    update public.phone_clones
    set status = 'available',
        current_account_id = null,
        updated_at = now()
    where id = v_old_clone_id
      and current_account_id = v_account_id;
  end if;

  return jsonb_build_object(
    'ok', true,
    'idempotent', v_existing.id is not null
      and v_existing.schedule_mode = 'manual_only'
      and v_existing.device_id = v_device_id
      and v_existing.app_instance_id = v_app_instance_id,
    'assignment_id', v_assignment_id,
    'device_id', v_device_id,
    'clone_id', v_clone_id,
    'app_instance_id', v_app_instance_id,
    'assignment_type', v_assignment_type,
    'slot_kind', 'manual_only',
    'schedule_mode', 'manual_only',
    'starts_at', null,
    'ends_at', null,
    'assignment_source', v_assignment_source
  );
end;
$$;




COMMENT ON FUNCTION "public"."assign_account_manual_only"("p_account_id" "uuid", "p_device_id" "uuid", "p_app_instance_id" "uuid", "p_assignment_source" "text", "p_actor_id" "uuid") IS 'Reserve a device/app_instance placement for a manual-only account without creating a scheduled timeslot or run request.';



CREATE OR REPLACE FUNCTION "public"."assign_account_slot"("p_account_id" "uuid", "p_device_id" "uuid", "p_starts_at" timestamp with time zone, "p_ends_at" timestamp with time zone, "p_clone_id" "uuid" DEFAULT NULL::"uuid", "p_assignment_source" "text" DEFAULT 'manual_dashboard'::"text", "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_account_id uuid := p_account_id;
  v_device_id uuid := p_device_id;
  v_starts_at timestamptz := p_starts_at;
  v_ends_at timestamptz := p_ends_at;
  v_preferred_app_instance_id uuid := p_clone_id;
  v_app_instance_id uuid;
  v_clone_id uuid;
  v_assignment_source text := coalesce(nullif(trim(p_assignment_source), ''), 'manual_dashboard');
  v_subscription_id uuid;
  v_client_id uuid;
  v_subscription_account_id uuid;
  v_assignment_type text;
  v_slot_kind text;
  v_device_timezone text;
  v_device_status text;
  v_device_pool_type text;
  v_existing record;
  v_old_app_instance_id uuid;
  v_old_clone_id uuid;
  v_account_app_instance_id uuid;
  v_instance_device_id uuid;
  v_instance_status text;
  v_instance_current_account_id uuid;
  v_instance_usable boolean;
  v_instance_launchable boolean;
  v_assignment_id uuid;
  v_metadata jsonb;
begin
  if v_account_id is null or v_device_id is null or v_starts_at is null or v_ends_at is null then
    raise exception 'invalid_assignment_payload';
  end if;

  if v_ends_at <= v_starts_at then
    raise exception 'invalid_assignment_window';
  end if;

  if v_assignment_source not in ('manual_dashboard', 'onboarding_auto', 'ops', 'auto_assign_rpc') then
    raise exception 'invalid_assignment_source';
  end if;

  v_assignment_type := public.resolve_account_schedule_assignment_type(v_account_id);
  if v_assignment_type is null then
    raise exception 'subscription_not_active';
  end if;

  select
    csa.id,
    csa.subscription_id,
    cs.client_id
  into v_subscription_account_id, v_subscription_id, v_client_id
  from public.client_subscription_accounts csa
  join public.client_subscriptions cs on cs.id = csa.subscription_id
  where csa.account_id = v_account_id
    and csa.status = 'active'
    and cs.status = 'active'
    and cs.subscription_type = v_assignment_type
  order by cs.starts_at desc, cs.created_at desc
  limit 1;

  if v_subscription_account_id is null then
    raise exception 'subscription_not_active';
  end if;

  v_slot_kind := public.resolve_assignment_slot_kind(v_assignment_type);

  select pd.timezone, pd.status, pd.pool_type
  into v_device_timezone, v_device_status, v_device_pool_type
  from public.phone_devices pd
  where pd.id = v_device_id
  for update;

  if v_device_timezone is null then
    raise exception 'device_unavailable';
  end if;

  if v_device_status not in ('available', 'active') then
    raise exception 'device_unavailable';
  end if;

  if v_device_pool_type <> 'shared' and v_device_pool_type <> v_assignment_type then
    raise exception 'assignment_profile_mismatch';
  end if;

  if not public.validate_assignment_slot_window(
    v_assignment_type,
    v_starts_at,
    v_ends_at,
    v_device_timezone
  ) then
    raise exception 'assignment_slot_kind_window_mismatch';
  end if;

  select
    aa.id,
    aa.device_id,
    aa.clone_id,
    aa.app_instance_id,
    aa.starts_at,
    aa.ends_at,
    aa.status,
    aa.schedule_mode
  into v_existing
  from public.account_assignments aa
  where aa.account_id = v_account_id
    and aa.status in ('pending', 'reserved', 'active')
  order by aa.created_at desc
  limit 1
  for update;

  v_old_app_instance_id := v_existing.app_instance_id;
  v_old_clone_id := v_existing.clone_id;

  select pai.id
  into v_account_app_instance_id
  from public.phone_app_instances pai
  where pai.device_id = v_device_id
    and pai.status = 'occupied'
    and pai.current_account_id = v_account_id
    and pai.usable_for_auto_login
    and pai.is_launchable
  order by case when pai.instance_type = 'primary_app' then 0 else 1 end, pai.instance_index asc
  limit 1
  for update skip locked;

  if v_existing.id is not null
     and v_existing.schedule_mode = 'scheduled'
     and v_existing.device_id = v_device_id
     and v_existing.starts_at = v_starts_at
     and v_existing.ends_at = v_ends_at
     and (v_preferred_app_instance_id is null or v_preferred_app_instance_id = v_existing.app_instance_id or v_preferred_app_instance_id = v_existing.clone_id)
     and (v_account_app_instance_id is null or v_account_app_instance_id = v_existing.app_instance_id) then
    return jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'assignment_id', v_existing.id,
      'device_id', v_existing.device_id,
      'clone_id', v_existing.clone_id,
      'app_instance_id', v_existing.app_instance_id,
      'assignment_type', v_assignment_type,
      'slot_kind', v_slot_kind,
      'schedule_mode', 'scheduled',
      'starts_at', v_existing.starts_at,
      'ends_at', v_existing.ends_at,
      'assignment_source', v_assignment_source
    );
  end if;

  if public.slot_overlaps_phone_rest(v_device_id, v_starts_at, v_ends_at, v_device_timezone) then
    raise exception 'phone_rest_active';
  end if;

  if v_assignment_type = 'outreach_only'
    and public.slot_reserved_for_outreach_rest(
      v_device_id,
      ((extract(hour from (v_starts_at at time zone v_device_timezone))::integer * 60
        + extract(minute from (v_starts_at at time zone v_device_timezone))::integer) / 40) + 1
    ) then
    raise exception 'outreach_rest_reserved';
  end if;

  if exists (
    select 1
    from public.account_assignments aa
    where aa.device_id = v_device_id
      and aa.account_id <> v_account_id
      and aa.status in ('pending', 'reserved', 'active')
      and aa.schedule_mode = 'scheduled'
      and tstzrange(aa.starts_at, aa.ends_at, '[)') && tstzrange(v_starts_at, v_ends_at, '[)')
  ) then
    raise exception 'assignment_slot_conflict';
  end if;

  v_app_instance_id := v_account_app_instance_id;

  if v_app_instance_id is null and v_preferred_app_instance_id is not null then
    select pai.id
    into v_app_instance_id
    from public.phone_app_instances pai
    where pai.id = v_preferred_app_instance_id;

    if v_app_instance_id is null then
      select pai.id
      into v_app_instance_id
      from public.phone_app_instances pai
      where pai.metadata ->> 'legacy_phone_clones_id' = v_preferred_app_instance_id::text
      limit 1;
    end if;
  end if;

  if v_app_instance_id is null then
    select pai.id
    into v_app_instance_id
    from public.phone_app_instances pai
    where pai.device_id = v_device_id
      and pai.status = 'available'
      and pai.usable_for_auto_login
      and pai.is_launchable
      and pai.current_account_id is null
      and not exists (
        select 1
        from public.account_assignments aa
        where aa.app_instance_id = pai.id
          and aa.account_id <> v_account_id
          and aa.status in ('pending', 'reserved', 'active')
      )
      and not exists (
        select 1
        from public.account_assignments aa
        where aa.app_instance_id = pai.id
          and aa.status in ('pending', 'reserved', 'active')
          and aa.schedule_mode = 'scheduled'
          and tstzrange(aa.starts_at, aa.ends_at, '[)') && tstzrange(v_starts_at, v_ends_at, '[)')
      )
    order by pai.instance_index asc
    limit 1
    for update skip locked;
  else
    select pai.device_id, pai.status, pai.current_account_id, pai.usable_for_auto_login, pai.is_launchable
    into v_instance_device_id, v_instance_status, v_instance_current_account_id, v_instance_usable, v_instance_launchable
    from public.phone_app_instances pai
    where pai.id = v_app_instance_id
    for update;

    if v_instance_device_id is null or v_instance_device_id <> v_device_id then
      raise exception 'preferred_app_instance_incompatible';
    end if;

    if v_instance_status <> 'available'
       and not (v_instance_status = 'occupied' and v_instance_current_account_id = v_account_id) then
      raise exception 'preferred_app_instance_incompatible';
    end if;

    if not coalesce(v_instance_usable, false) or not coalesce(v_instance_launchable, false) then
      raise exception 'preferred_app_instance_incompatible';
    end if;

    if v_instance_current_account_id is not null and v_instance_current_account_id <> v_account_id then
      raise exception 'preferred_app_instance_incompatible';
    end if;

    if exists (
      select 1
      from public.account_assignments aa
      where aa.app_instance_id = v_app_instance_id
        and aa.account_id <> v_account_id
        and aa.status in ('pending', 'reserved', 'active')
    ) then
      raise exception 'preferred_app_instance_incompatible';
    end if;
  end if;

  if v_app_instance_id is null then
    raise exception 'no_app_instance_available';
  end if;

  select pc.id
  into v_clone_id
  from public.phone_clones pc
  where pc.id = v_app_instance_id;

  v_metadata := jsonb_build_object(
    'assigned_by', coalesce(p_actor_id::text, 'system'),
    'assignment_source', v_assignment_source,
    'schedule_mode', 'scheduled',
    'assigned_at', now(),
    'previous_assignment', case
      when v_existing.id is null then null
      else jsonb_build_object(
        'assignment_id', v_existing.id,
        'device_id', v_existing.device_id,
        'clone_id', v_existing.clone_id,
        'app_instance_id', v_existing.app_instance_id,
        'starts_at', v_existing.starts_at,
        'ends_at', v_existing.ends_at,
        'status', v_existing.status,
        'schedule_mode', v_existing.schedule_mode
      )
    end
  );

  if v_existing.id is not null then
    update public.account_assignments
    set
      client_id = v_client_id,
      subscription_id = v_subscription_id,
      subscription_account_id = v_subscription_account_id,
      device_id = v_device_id,
      clone_id = v_clone_id,
      app_instance_id = v_app_instance_id,
      assignment_type = v_assignment_type,
      slot_kind = v_slot_kind,
      schedule_mode = 'scheduled',
      status = 'reserved',
      starts_at = v_starts_at,
      ends_at = v_ends_at,
      assignment_source = v_assignment_source,
      assigned_at = now(),
      metadata = coalesce(metadata, '{}'::jsonb) || v_metadata,
      updated_at = now()
    where id = v_existing.id
    returning id into v_assignment_id;
  else
    insert into public.account_assignments (
      client_id,
      subscription_id,
      subscription_account_id,
      account_id,
      device_id,
      clone_id,
      app_instance_id,
      assignment_type,
      slot_kind,
      schedule_mode,
      status,
      starts_at,
      ends_at,
      assigned_at,
      assignment_source,
      metadata
    )
    values (
      v_client_id,
      v_subscription_id,
      v_subscription_account_id,
      v_account_id,
      v_device_id,
      v_clone_id,
      v_app_instance_id,
      v_assignment_type,
      v_slot_kind,
      'scheduled',
      'reserved',
      v_starts_at,
      v_ends_at,
      now(),
      v_assignment_source,
      v_metadata
    )
    returning id into v_assignment_id;
  end if;

  update public.phone_app_instances
  set status = 'occupied',
      current_account_id = v_account_id,
      updated_at = now()
  where id = v_app_instance_id
    and status <> 'disabled';

  if v_clone_id is not null then
    update public.phone_clones
    set status = 'reserved',
        current_account_id = v_account_id,
        updated_at = now()
    where id = v_clone_id;
  end if;

  if v_old_app_instance_id is not null and v_old_app_instance_id <> v_app_instance_id then
    perform public.release_app_instance_if_unused(
      v_old_app_instance_id,
      v_account_id,
      'reassignment_release_old_instance',
      'assign_account_slot'
    );
  end if;

  if v_old_clone_id is not null and v_old_clone_id <> v_clone_id and not exists (
    select 1
    from public.account_assignments aa
    where aa.clone_id = v_old_clone_id
      and aa.status in ('pending', 'reserved', 'active')
  ) then
    update public.phone_clones
    set status = 'available',
        current_account_id = null,
        updated_at = now()
    where id = v_old_clone_id
      and current_account_id = v_account_id;
  end if;

  return jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'assignment_id', v_assignment_id,
    'device_id', v_device_id,
    'clone_id', v_clone_id,
    'app_instance_id', v_app_instance_id,
    'assignment_type', v_assignment_type,
    'slot_kind', v_slot_kind,
    'schedule_mode', 'scheduled',
    'starts_at', v_starts_at,
    'ends_at', v_ends_at,
    'assignment_source', v_assignment_source
  );
end;
$$;




COMMENT ON FUNCTION "public"."assign_account_slot"("p_account_id" "uuid", "p_device_id" "uuid", "p_starts_at" timestamp with time zone, "p_ends_at" timestamp with time zone, "p_clone_id" "uuid", "p_assignment_source" "text", "p_actor_id" "uuid") IS 'Transactionally assigns an account to a phone slot with phone-wide anti-collision and explicit fixed-blackout validation.';



CREATE OR REPLACE FUNCTION "public"."audit_schedule_capacity_event"("p_event_type" "text", "p_account_id" "uuid", "p_assignment_id" "uuid", "p_app_instance_id" "uuid", "p_reason" "text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  insert into public.runtime_events (
    event_type,
    severity,
    visibility,
    account_id,
    assignment_id,
    reason,
    message,
    metadata
  )
  values (
    p_event_type,
    'info',
    'admin_only',
    p_account_id,
    p_assignment_id,
    p_reason,
    'Schedule app instance capacity updated.',
    coalesce(p_metadata, '{}'::jsonb) || jsonb_build_object(
      'app_instance_id', p_app_instance_id,
      'safe_audit', true
    )
  );
end;
$$;




CREATE OR REPLACE FUNCTION "public"."auto_assign_account_from_subscription"("p_subscription_account_id" "uuid", "p_starts_at" timestamp with time zone, "p_ends_at" timestamp with time zone, "p_preferred_device_id" "uuid" DEFAULT NULL::"uuid", "p_preferred_clone_id" "uuid" DEFAULT NULL::"uuid", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_subscription_id uuid;
  v_client_id uuid;
  v_account_id uuid;
  v_subscription_account_status text;
  v_subscription_status text;
  v_subscription_type text;
  v_subscription_starts_at timestamptz;
  v_subscription_ends_at timestamptz;
  v_assignment_type text;
  v_slot_kind text;
  v_device_id uuid;
  v_clone_id uuid;
  v_assignment_id uuid;
begin
  if p_subscription_account_id is null then
    raise exception 'subscription_account_not_found';
  end if;

  if p_starts_at is null or p_ends_at is null or p_ends_at <= p_starts_at then
    raise exception 'invalid_assignment_window';
  end if;

  if p_metadata is null or jsonb_typeof(p_metadata) <> 'object' then
    raise exception 'invalid_assignment_metadata';
  end if;

  select
    csa.subscription_id,
    csa.account_id,
    csa.status,
    cs.client_id,
    cs.status,
    cs.subscription_type,
    cs.starts_at,
    cs.ends_at
  into
    v_subscription_id,
    v_account_id,
    v_subscription_account_status,
    v_client_id,
    v_subscription_status,
    v_subscription_type,
    v_subscription_starts_at,
    v_subscription_ends_at
  from public.client_subscription_accounts csa
  join public.client_subscriptions cs
    on cs.id = csa.subscription_id
  where csa.id = p_subscription_account_id;

  if v_subscription_id is null then
    raise exception 'subscription_account_not_found';
  end if;

  if v_subscription_account_status <> 'active' then
    raise exception 'subscription_account_not_active';
  end if;

  if v_subscription_status <> 'active'
     or v_subscription_starts_at > p_starts_at
     or (v_subscription_ends_at is not null and v_subscription_ends_at <= p_starts_at) then
    raise exception 'subscription_not_active';
  end if;

  v_assignment_type := v_subscription_type;
  v_slot_kind := case
    when v_assignment_type = 'full_cycle' then 'full_cycle_6h'
    when v_assignment_type = 'outreach_only' then 'outreach_short'
    else null
  end;

  if v_slot_kind is null then
    raise exception 'subscription_not_active';
  end if;

  if exists (
    select 1
    from public.account_assignments aa
    where aa.account_id = v_account_id
      and aa.status in ('pending', 'reserved', 'active')
  ) then
    raise exception 'account_already_has_open_assignment';
  end if;

  if p_preferred_device_id is not null and not exists (
    select 1
    from public.phone_devices pd
    where pd.id = p_preferred_device_id
      and pd.status in ('available', 'active')
      and pd.pool_type in (v_assignment_type, 'shared')
  ) then
    raise exception 'preferred_device_incompatible';
  end if;

  if p_preferred_clone_id is not null and not exists (
    select 1
    from public.phone_clones pc
    join public.phone_devices pd
      on pd.id = pc.device_id
    where pc.id = p_preferred_clone_id
      and pc.status = 'available'
      and pc.clone_index <= pd.max_clones
      and pd.status in ('available', 'active')
      and pd.pool_type in (v_assignment_type, 'shared')
      and (p_preferred_device_id is null or pd.id = p_preferred_device_id)
      and not exists (
        select 1
        from public.account_assignments aa
        where aa.clone_id = pc.id
          and aa.status in ('pending', 'reserved', 'active')
          and tstzrange(aa.starts_at, aa.ends_at, '[)') && tstzrange(p_starts_at, p_ends_at, '[)')
      )
  ) then
    raise exception 'preferred_clone_incompatible';
  end if;

  select candidate.device_id, candidate.clone_id
  into v_device_id, v_clone_id
  from (
    select
      pd.id as device_id,
      pc.id as clone_id,
      (
        select count(*)
        from public.account_assignments aa
        where aa.device_id = pd.id
          and aa.status in ('pending', 'reserved', 'active')
      ) as open_assignments_on_device
    from public.phone_clones pc
    join public.phone_devices pd
      on pd.id = pc.device_id
    where pd.status in ('available', 'active')
      and pd.pool_type in (v_assignment_type, 'shared')
      and pc.status = 'available'
      and pc.clone_index <= pd.max_clones
      and (p_preferred_device_id is null or pd.id = p_preferred_device_id)
      and (p_preferred_clone_id is null or pc.id = p_preferred_clone_id)
      and not exists (
        select 1
        from public.account_assignments aa
        where aa.clone_id = pc.id
          and aa.status in ('pending', 'reserved', 'active')
          and tstzrange(aa.starts_at, aa.ends_at, '[)') && tstzrange(p_starts_at, p_ends_at, '[)')
      )
    order by
      case when p_preferred_device_id is not null and pd.id = p_preferred_device_id then 0 else 1 end,
      case when p_preferred_clone_id is not null and pc.id = p_preferred_clone_id then 0 else 1 end,
      case when pd.pool_type = v_assignment_type then 0 else 1 end,
      case when pd.status = 'available' then 0 else 1 end,
      open_assignments_on_device asc,
      pd.created_at asc,
      pc.clone_index asc,
      pd.id asc,
      pc.id asc
    for update of pc skip locked
    limit 1
  ) as candidate;

  if v_clone_id is null then
    raise exception 'no_capacity_available';
  end if;

  insert into public.account_assignments (
    client_id,
    subscription_id,
    subscription_account_id,
    account_id,
    device_id,
    clone_id,
    assignment_type,
    slot_kind,
    status,
    starts_at,
    ends_at,
    assigned_at,
    metadata
  )
  values (
    v_client_id,
    v_subscription_id,
    p_subscription_account_id,
    v_account_id,
    v_device_id,
    v_clone_id,
    v_assignment_type,
    v_slot_kind,
    'reserved',
    p_starts_at,
    p_ends_at,
    now(),
    p_metadata
  )
  returning id into v_assignment_id;

  update public.phone_clones
  set status = 'reserved',
      current_account_id = v_account_id,
      updated_at = now()
  where id = v_clone_id;

  return jsonb_build_object(
    'ok', true,
    'assignment_id', v_assignment_id,
    'device_id', v_device_id,
    'clone_id', v_clone_id,
    'account_id', v_account_id,
    'subscription_id', v_subscription_id,
    'subscription_account_id', p_subscription_account_id,
    'assignment_type', v_assignment_type,
    'slot_kind', v_slot_kind,
    'starts_at', p_starts_at,
    'ends_at', p_ends_at
  );
end;
$$;




COMMENT ON FUNCTION "public"."auto_assign_account_from_subscription"("p_subscription_account_id" "uuid", "p_starts_at" timestamp with time zone, "p_ends_at" timestamp with time zone, "p_preferred_device_id" "uuid", "p_preferred_clone_id" "uuid", "p_metadata" "jsonb") IS 'Entry 2C-2 service-role helper: reserve an available clone for an account-scoped subscription. Does not dispatch workers or provision logins.';



CREATE OR REPLACE FUNCTION "public"."auto_restart_acquire_device_lock"("p_device_id" "uuid", "p_worker_id" "text", "p_account_id" "uuid", "p_app_instance_id" "uuid", "p_lease_seconds" integer DEFAULT 900, "p_reason" "text" DEFAULT 'auto_restart'::"text", "p_owner_kind" "text" DEFAULT 'worker'::"text", "p_operation_phase" "text" DEFAULT 'executing'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_now timestamptz := now();
  v_expires timestamptz := v_now + make_interval(secs => greatest(p_lease_seconds, 30));
  v_existing public.auto_restart_device_locks%rowtype;
  v_lease_id uuid;
begin
  delete from public.auto_restart_device_locks as device_lock
  where device_lock.device_id = p_device_id
    and device_lock.lease_expires_at <= v_now
    and (
      device_lock.request_id is null
      or not exists (
        select 1
        from public.account_run_requests as bound_request
        where bound_request.id = device_lock.request_id
          and bound_request.status in ('queued', 'claimed', 'running', 'cancel_requested')
      )
    );

  select * into v_existing
  from public.auto_restart_device_locks
  where device_id = p_device_id
  for update;

  if found then
    if v_existing.worker_id = p_worker_id then
      update public.auto_restart_device_locks
      set lease_expires_at = v_expires,
          account_id = p_account_id,
          app_instance_id = p_app_instance_id,
          reason = coalesce(nullif(p_reason, ''), v_existing.reason),
          owner_kind = coalesce(nullif(p_owner_kind, ''), v_existing.owner_kind),
          operation_phase = coalesce(nullif(p_operation_phase, ''), v_existing.operation_phase),
          heartbeat_at = v_now,
          updated_at = v_now
      where device_id = p_device_id
      returning lease_id into v_lease_id;
      perform public._device_ui_lease_audit(
        v_lease_id, p_device_id, 'renewed', p_owner_kind, p_worker_id, v_existing.request_id, v_existing.run_id, p_reason
      );
      return jsonb_build_object(
        'ok', true, 'acquired', true, 'renewed', true,
        'lease_id', v_lease_id, 'device_id', p_device_id
      );
    end if;
    return jsonb_build_object(
      'ok', false,
      'acquired', false,
      'reason', 'device_lease_unavailable',
      'legacy_reason', 'device_lock_held',
      'holder_worker_id', v_existing.worker_id,
      'lease_id', v_existing.lease_id
    );
  end if;

  insert into public.auto_restart_device_locks (
    device_id, worker_id, account_id, app_instance_id, lease_expires_at, reason,
    owner_kind, operation_phase, heartbeat_at
  ) values (
    p_device_id, p_worker_id, p_account_id, p_app_instance_id, v_expires,
    coalesce(nullif(p_reason, ''), 'auto_restart'),
    coalesce(nullif(p_owner_kind, ''), 'worker'),
    coalesce(nullif(p_operation_phase, ''), 'executing'),
    v_now
  )
  returning lease_id into v_lease_id;

  perform public._device_ui_lease_audit(
    v_lease_id, p_device_id, 'acquired', p_owner_kind, p_worker_id, null, null, p_reason
  );

  return jsonb_build_object(
    'ok', true, 'acquired', true, 'renewed', false,
    'lease_id', v_lease_id, 'device_id', p_device_id
  );
end;
$$;




CREATE OR REPLACE FUNCTION "public"."auto_restart_bind_device_lock_to_request"("p_device_id" "uuid", "p_worker_id" "text", "p_request_id" "uuid", "p_lease_seconds" integer DEFAULT 900) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_now timestamptz := now();
  v_expires timestamptz := v_now + make_interval(secs => greatest(p_lease_seconds, 30));
  v_row public.auto_restart_device_locks%rowtype;
begin
  select * into v_row
  from public.auto_restart_device_locks
  where device_id = p_device_id
  for update;

  if not found then
    return jsonb_build_object('ok', false, 'bound', false, 'reason', 'device_lock_missing');
  end if;

  if v_row.worker_id <> p_worker_id then
    return jsonb_build_object(
      'ok', false,
      'bound', false,
      'reason', 'device_lock_owner_mismatch',
      'holder_worker_id', v_row.worker_id
    );
  end if;

  update public.auto_restart_device_locks
  set request_id = p_request_id,
      lease_expires_at = v_expires,
      updated_at = v_now,
      metadata_safe = coalesce(metadata_safe, '{}'::jsonb) || jsonb_build_object('bound_request_id', p_request_id::text)
  where device_id = p_device_id;

  return jsonb_build_object('ok', true, 'bound', true, 'request_id', p_request_id);
end;
$$;




CREATE OR REPLACE FUNCTION "public"."auto_restart_daily_action_counts_v1"("p_account_ids" "uuid"[], "p_since" timestamp with time zone) RETURNS TABLE("account_id" "uuid", "follow_done" bigint, "unfollow_done" bigint, "welcome_done" bigint, "outreach_done" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select u.account_id,
    count(*) filter (
      where u.followed_at >= p_since and coalesce(u.was_successful, true)
    ) as follow_done,
    count(*) filter (
      where u.unfollowed_at >= p_since and u.unfollow_result = 'success'
    ) as unfollow_done,
    count(*) filter (
      where u.updated_at >= p_since and coalesce(u.welcome_dm_sent, false)
    ) as welcome_done,
    count(*) filter (
      where u.updated_at >= p_since
        and coalesce(u.dm_sent, false)
        and not coalesce(u.welcome_dm_sent, false)
    ) as outreach_done
  from public.ig_interacted_users u
  where u.account_id = any(coalesce(p_account_ids, '{}'::uuid[]))
    and (
      u.followed_at >= p_since
      or u.unfollowed_at >= p_since
      or u.updated_at >= p_since
    )
  group by u.account_id
$$;




CREATE OR REPLACE FUNCTION "public"."auto_restart_latest_resume_plans_v1"("p_account_ids" "uuid"[]) RETURNS TABLE("run_id" "uuid", "account_id" "uuid", "restart_allowed" boolean, "restart_block_reason" "text", "resume_state" "text", "attempts_in_window" integer, "plan" "jsonb", "last_updated_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select distinct on (p.account_id)
    p.run_id, p.account_id, p.restart_allowed, p.restart_block_reason,
    p.resume_state, p.attempts_in_window::integer,
    coalesce(p.plan, '{}'::jsonb), p.last_updated_at
  from public.account_session_resume_plans p
  where p.account_id = any(coalesce(p_account_ids, '{}'::uuid[]))
  order by p.account_id, p.last_updated_at desc nulls last, p.created_at desc, p.id desc
$$;




CREATE OR REPLACE FUNCTION "public"."auto_restart_latest_session_runs_v1"("p_account_ids" "uuid"[]) RETURNS TABLE("id" "uuid", "account_id" "uuid", "status" "text", "finished_at" timestamp with time zone, "updated_at" timestamp with time zone, "performance_summary" "jsonb")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select distinct on (r.account_id)
    r.id, r.account_id, r.status::text, r.finished_at, r.updated_at,
    coalesce(r.performance_summary, '{}'::jsonb)
  from public.ig_runs r
  where r.account_id = any(coalesce(p_account_ids, '{}'::uuid[]))
  order by r.account_id, r.created_at desc, r.id desc
$$;




CREATE OR REPLACE FUNCTION "public"."auto_restart_phase_plan_v2_error"("p_plan" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_phase text;
  v_enabled boolean := false;
begin
  if jsonb_typeof(p_plan) <> 'object'
     or p_plan ->> 'schema' <> 'AUTO_RESTART_RESUME_PLAN_V2'
     or coalesce((p_plan ->> 'plan_version')::integer, 0) <> 2 then
    return 'phase_plan_unknown';
  end if;
  if nullif(p_plan ->> 'account_id', '') is null then
    return 'phase_plan_account_missing';
  end if;
  if p_plan -> 'phase_order' <> '["welcome","follow","unfollow"]'::jsonb then
    return 'phase_plan_order_invalid';
  end if;
  if jsonb_typeof(p_plan -> 'phases_to_run') <> 'object'
     or jsonb_typeof(p_plan -> 'quota_remaining') <> 'object' then
    return 'phase_plan_unknown';
  end if;

  if coalesce((p_plan ->> 'restriction_preflight_only')::boolean, false) then
    if p_plan ->> 'resume_kind' <> 'instagram_restriction_preflight'
       or nullif(p_plan ->> 'incident_id', '') is null
       or nullif(p_plan ->> 'authorization_id', '') is null then
      return 'restriction_preflight_contract_invalid';
    end if;
    foreach v_phase in array array['welcome','follow','unfollow'] loop
      if not (p_plan -> 'phases_to_run' ? v_phase)
         or (p_plan -> 'phases_to_run' ->> v_phase)::boolean is not false
         or coalesce((p_plan -> 'quota_remaining' ->> v_phase)::integer, -1) <> 0 then
        return 'restriction_preflight_contract_invalid';
      end if;
    end loop;
    if coalesce((p_plan -> 'quota_remaining' ->> 'outreach')::integer, -1) <> 0
       or coalesce((p_plan -> 'quota_remaining' ->> 'total')::integer, -1) <> 0 then
      return 'restriction_preflight_contract_invalid';
    end if;
    return null;
  end if;

  if coalesce((p_plan ->> 'package_contract_ready')::boolean, false) is not true then
    return 'phase_plan_package_unknown';
  end if;
  foreach v_phase in array array['welcome','follow','unfollow'] loop
    if coalesce((p_plan -> 'phases_to_run' ->> v_phase)::boolean, false) then
      v_enabled := true;
      if nullif(p_plan -> 'quota_remaining' ->> v_phase, '') is null
         or (p_plan -> 'quota_remaining' ->> v_phase)::integer <= 0 then
        return 'phase_plan_quota_invalid';
      end if;
    end if;
  end loop;
  if not v_enabled then
    return 'resume_phase_plan_not_actionable';
  end if;
  return null;
exception when invalid_text_representation or numeric_value_out_of_range then
  return 'phase_plan_invalid_field';
end
$$;




CREATE OR REPLACE FUNCTION "public"."auto_restart_release_device_lock"("p_device_id" "uuid", "p_worker_id" "text", "p_request_id" "uuid" DEFAULT NULL::"uuid", "p_release_reason" "text" DEFAULT 'terminal'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_deleted integer;
  v_row public.auto_restart_device_locks%rowtype;
begin
  select * into v_row
  from public.auto_restart_device_locks
  where device_id = p_device_id
    and worker_id = p_worker_id
    and (p_request_id is null or request_id = p_request_id)
  for update;

  if not found then
    return jsonb_build_object('ok', true, 'released', false);
  end if;

  perform public._device_ui_lease_audit(
    v_row.lease_id, p_device_id, 'released', v_row.owner_kind, p_worker_id,
    v_row.request_id, v_row.run_id, coalesce(p_release_reason, 'terminal')
  );

  delete from public.auto_restart_device_locks
  where device_id = p_device_id
    and worker_id = p_worker_id
    and (p_request_id is null or request_id = p_request_id);
  get diagnostics v_deleted = row_count;
  return jsonb_build_object('ok', true, 'released', v_deleted > 0, 'lease_id', v_row.lease_id);
end;
$$;




CREATE OR REPLACE FUNCTION "public"."auto_restart_renew_device_lock"("p_device_id" "uuid", "p_worker_id" "text", "p_request_id" "uuid", "p_lease_seconds" integer DEFAULT 900) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_now timestamptz := now();
  v_expires timestamptz := v_now + make_interval(secs => greatest(p_lease_seconds, 30));
  v_row public.auto_restart_device_locks%rowtype;
begin
  delete from public.auto_restart_device_locks
  where device_id = p_device_id
    and lease_expires_at <= v_now
    and request_id is null;

  select * into v_row
  from public.auto_restart_device_locks
  where device_id = p_device_id
  for update;

  if not found then
    return jsonb_build_object('ok', false, 'renewed', false, 'reason', 'device_lock_missing');
  end if;

  if v_row.worker_id <> p_worker_id then
    return jsonb_build_object('ok', false, 'renewed', false, 'reason', 'device_lock_owner_mismatch');
  end if;

  if v_row.request_id is not null and v_row.request_id <> p_request_id then
    return jsonb_build_object('ok', false, 'renewed', false, 'reason', 'device_lock_request_mismatch');
  end if;

  update public.auto_restart_device_locks
  set lease_expires_at = v_expires,
      request_id = coalesce(request_id, p_request_id),
      updated_at = v_now
  where device_id = p_device_id;

  return jsonb_build_object('ok', true, 'renewed', true);
end;
$$;




CREATE OR REPLACE FUNCTION "public"."auto_restart_transfer_device_lock"("p_device_id" "uuid", "p_request_id" "uuid", "p_new_worker_id" "text", "p_lease_seconds" integer DEFAULT 900) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_now timestamptz := now();
  v_expires timestamptz := v_now + make_interval(secs => greatest(p_lease_seconds, 30));
  v_row public.auto_restart_device_locks%rowtype;
begin
  select * into v_row
  from public.auto_restart_device_locks
  where device_id = p_device_id
    and request_id = p_request_id
  for update;

  if not found then
    return jsonb_build_object('ok', false, 'transferred', false, 'reason', 'device_lock_missing');
  end if;

  update public.auto_restart_device_locks
  set worker_id = p_new_worker_id,
      lease_expires_at = v_expires,
      updated_at = v_now
  where device_id = p_device_id
    and request_id = p_request_id;

  return jsonb_build_object('ok', true, 'transferred', true, 'worker_id', p_new_worker_id);
end;
$$;




CREATE OR REPLACE FUNCTION "public"."backfill_account_warmup_start_v1"("p_account_id" "uuid", "p_package_started_at" timestamp with time zone, "p_actor_id" "uuid", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_package_cap integer;
  v_existing_start timestamptz;
begin
  select package_started_at into v_existing_start
    from public.account_warmup_settings where account_id = p_account_id for update;
  if v_existing_start is not null then
    return jsonb_build_object('changed', false, 'reason', 'existing_start_preserved', 'package_started_at', v_existing_start);
  end if;
  select (package_caps ->> 'follow_day')::integer into v_package_cap
    from public.account_package_summary where account_id = p_account_id;
  if v_package_cap is null then raise exception 'package_follow_cap_unavailable'; end if;
  insert into public.account_warmup_settings (
    account_id,warmup_enabled,package_started_at,warmup_profile_code,
    day_1_follow_cap,day_2_follow_cap,day_3_follow_cap,day_4_plus_follow_cap,status,updated_at
  ) values (p_account_id,true,p_package_started_at,'follow_default_v1',10,20,40,v_package_cap,'active',now())
  on conflict (account_id) do update set package_started_at=excluded.package_started_at,
    warmup_enabled=true,day_1_follow_cap=10,day_2_follow_cap=20,day_3_follow_cap=40,
    day_4_plus_follow_cap=v_package_cap,status='active',updated_at=now()
  where public.account_warmup_settings.package_started_at is null;
  insert into public.ig_action_logs(account_id,action_type,status,message,payload)
  select p_account_id,'follow_warmup_start_backfilled','success','Warmup start backfilled from verified account history.',
    jsonb_build_object('actor_type','admin','actor_id',p_actor_id,'source_surface','controlled_backfill',
      'idempotency_key',p_idempotency_key,'package_started_at',p_package_started_at,'day_caps',jsonb_build_array(10,20,40,v_package_cap))
  where not exists (select 1 from public.ig_action_logs where account_id=p_account_id
    and action_type='follow_warmup_start_backfilled' and payload->>'idempotency_key'=p_idempotency_key);
  return jsonb_build_object('changed', true, 'package_started_at', p_package_started_at, 'day_4_plus_follow_cap', v_package_cap);
end;
$$;




CREATE OR REPLACE FUNCTION "public"."backfill_ig_target_followbacks"("p_limit" integer DEFAULT 500) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_target record;
  v_results jsonb := '[]'::jsonb;
  v_one jsonb;
  v_synced integer := 0;
  v_certified integer := 0;
  v_limit integer := greatest(1, least(coalesce(p_limit, 500), 5000));
begin
  for v_target in
    select t.id
    from public.ig_targets t
    where coalesce(t.follows_sent_count, 0) > 0
      and t.followbacks_metrics_reliable_at is null
      and exists (
        select 1
        from public.ig_interacted_users iu
        where iu.account_id = t.account_id
          and iu.is_following_back = true
          and iu.followed_by_bot = true
          and coalesce(iu.follow_status, 'following') = 'following'
          and iu.unfollowed_at is null
          and (
            iu.source_target_id = t.id
            or (
              iu.source_target_id is null
              and iu.source_target_username is not null
              and lower(trim(both '@' from iu.source_target_username)) = lower(t.normalized_username)
            )
          )
      )
    order by t.follows_sent_count desc, t.id
    limit v_limit
  loop
    v_one := public.sync_ig_target_followbacks_count(v_target.id, false);
    v_results := v_results || jsonb_build_array(v_one);
    if coalesce(v_one->>'ok', 'false') = 'true' then
      v_synced := v_synced + 1;
      if coalesce(v_one->>'certified', 'false') = 'true' then
        v_certified := v_certified + 1;
      end if;
    end if;
  end loop;

  return jsonb_build_object(
    'ok', true,
    'synced_targets', v_synced,
    'certified_targets', v_certified,
    'left_unmeasured', greatest(0, v_synced - v_certified),
    'limit', v_limit,
    'results', v_results
  );
end;
$$;




COMMENT ON FUNCTION "public"."backfill_ig_target_followbacks"("p_limit" integer) IS 'Global positive-only backfill: certifies CT rows with attributable followbacks_count > 0 only.';



CREATE OR REPLACE FUNCTION "public"."begin_client_instagram_onboarding"("p_client_id" "uuid", "p_actor_id" "uuid", "p_entitlement_id" "uuid", "p_idempotency_key" "uuid", "p_attempt_id" "uuid", "p_lease_owner" "text", "p_requested_username" "text", "p_login_email" "text", "p_password" "text", "p_public_analysis" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'vault'
    AS $_$
declare
  v_session public.client_instagram_onboarding_sessions%rowtype;
  v_entitlement public.client_account_entitlements%rowtype;
  v_account_id uuid;
  v_client_account_id uuid;
  v_subscription_id uuid;
  v_secret_id uuid;
  v_package_code text;
  v_username text := lower(trim(coalesce(p_requested_username, '')));
  v_failure text;
begin
  perform pg_advisory_xact_lock(hashtextextended(
    'client_instagram_onboarding:idempotency:' || p_client_id::text || ':' || p_idempotency_key::text,
    0
  ));
  perform pg_advisory_xact_lock(hashtextextended(
    'client_instagram_onboarding:entitlement:' || p_entitlement_id::text,
    0
  ));

  if not exists (
    select 1
      from public.client_users cu
      join public.clients c on c.id = cu.client_id and c.status = 'active'
     where cu.client_id = p_client_id
       and cu.auth_user_id = p_actor_id
       and cu.status = 'active'
       and cu.role in ('owner', 'admin', 'assistant')
  ) then
    return jsonb_build_object('ok', false, 'reason', 'client_access_denied');
  end if;
  if v_username = '' or trim(coalesce(p_password, '')) = '' then
    return jsonb_build_object('ok', false, 'reason', 'credentials_required');
  end if;
  if p_attempt_id is null or nullif(trim(coalesce(p_lease_owner, '')), '') is null then
    return jsonb_build_object('ok', false, 'reason', 'attempt_lease_required');
  end if;

  select * into v_session
    from public.client_instagram_onboarding_sessions
   where client_id = p_client_id
     and idempotency_key = p_idempotency_key
   for update;

  if found then
    if v_session.entitlement_id <> p_entitlement_id then
      return jsonb_build_object('ok', false, 'reason', 'idempotency_entitlement_mismatch');
    end if;
    if v_session.status in ('active', 'completed') then
      return jsonb_build_object(
        'ok', true,
        'already_started', true,
        'session_id', v_session.id,
        'account_id', v_session.account_id,
        'status', v_session.status
      );
    end if;
    if v_session.status = 'creating'
       and v_session.lease_expires_at is not null
       and v_session.lease_expires_at > now() then
      return jsonb_build_object(
        'ok', false,
        'reason', 'creation_lease_active',
        'session_id', v_session.id,
        'status', v_session.status
      );
    end if;
    if v_session.status in ('expired', 'abandoned') then
      return jsonb_build_object('ok', false, 'reason', 'terminal_session_requires_restart');
    end if;

  end if;

  select * into v_entitlement
    from public.client_account_entitlements
   where id = p_entitlement_id
     and client_id = p_client_id
   for update;
  if not found or v_entitlement.status <> 'entitlement_reserved' then
    return jsonb_build_object('ok', false, 'reason', 'entitlement_not_reserved');
  end if;

  v_package_code := lower(trim(coalesce(v_entitlement.commercial_package_code, '')));
  if v_package_code not in ('growth', 'pro', 'premium') then
    return jsonb_build_object('ok', false, 'reason', 'entitlement_package_invalid');
  end if;

  if v_session.id is not null then
    update public.client_instagram_onboarding_sessions
       set package_code = v_package_code,
           status = 'creating',
           attempt_id = p_attempt_id,
           lease_owner = left(trim(p_lease_owner), 160),
           lease_expires_at = now() + interval '90 seconds',
           last_error_code = null,
           failure_reason = null,
           updated_at = now()
     where id = v_session.id
     returning * into v_session;
  else
    insert into public.client_instagram_onboarding_sessions (
      client_id,
      entitlement_id,
      created_by,
      idempotency_key,
      requested_username,
      package_code,
      status,
      current_step,
      attempt_id,
      lease_owner,
      lease_expires_at,
      expires_at,
      last_progress_at
    ) values (
      p_client_id,
      p_entitlement_id,
      p_actor_id,
      p_idempotency_key,
      v_username,
      v_package_code,
      'creating',
      'connection',
      p_attempt_id,
      left(trim(p_lease_owner), 160),
      now() + interval '90 seconds',
      now() + interval '7 days',
      now()
    ) returning * into v_session;
  end if;

  begin
    select cs.id into v_subscription_id
      from public.client_subscriptions cs
     where cs.client_id = p_client_id
       and cs.subscription_type = 'full_cycle'
       and cs.status = 'active'
       and (cs.ends_at is null or cs.ends_at > now())
     order by cs.starts_at desc
     limit 1
     for update;
    if v_subscription_id is null then
      raise exception 'active_subscription_required';
    end if;

    if exists (
      select 1 from public.ig_accounts a
       where lower(trim(a.username)) = v_username
    ) then
      raise exception 'username_already_linked';
    end if;

    insert into public.ig_accounts (
      username,
      display_name,
      status,
      login_method,
      avatar_url,
      followers_count,
      is_private,
      is_verified,
      username_verified_at,
      username_verification_status,
      public_profile_metadata
    ) values (
      v_username,
      coalesce(p_public_analysis->>'displayName', ''),
      'inactive',
      'credentials',
      nullif(trim(coalesce(p_public_analysis->>'avatarUrl', '')), ''),
      case when (p_public_analysis->>'followersCount') ~ '^\d+$' then (p_public_analysis->>'followersCount')::integer else null end,
      case when jsonb_typeof(p_public_analysis->'isPrivate') = 'boolean' then (p_public_analysis->>'isPrivate')::boolean else null end,
      case when jsonb_typeof(p_public_analysis->'isVerified') = 'boolean' then (p_public_analysis->>'isVerified')::boolean else null end,
      now(),
      'verified',
      jsonb_build_object(
        'source', 'client_instagram_onboarding',
        'lookup_status', coalesce(p_public_analysis->>'lookupStatus', 'found'),
        'provider_biography', nullif(trim(coalesce(p_public_analysis->>'biography', '')), '')
      )
    ) returning id into v_account_id;

    insert into public.ig_account_settings (
      account_id, username, display_name, email, password, account_status,
      app_package, dry_run_enabled, follow_enabled, like_enabled,
      welcome_dm_enabled, cold_dm_enabled, unfollow_enabled
    ) values (
      v_account_id, v_username, coalesce(p_public_analysis->>'displayName', ''),
      lower(trim(coalesce(p_login_email, ''))), '', 'inactive',
      'com.instagram.android', true, false, false, false, false, false
    );
    insert into public.ig_account_filters (account_id) values (v_account_id);
    insert into public.ig_account_follow_settings (account_id) values (v_account_id);
    insert into public.ig_account_unfollow_settings (account_id, unfollow_enabled)
      values (v_account_id, false);
    insert into public.ig_account_dm_settings (account_id, welcome_enabled, outreach_enabled)
      values (v_account_id, false, false);

    v_secret_id := public.create_instagram_credentials_vault_secret(
      p_password,
      'instagram:' || v_account_id::text || ':v1',
      'Client onboarding Instagram credentials'
    );
    perform public.rotate_instagram_account_credentials(
      v_account_id,
      p_client_id,
      v_username,
      'supabase_vault://' || v_secret_id::text,
      'supabase_vault',
      1,
      'submit',
      p_attempt_id::text,
      v_session.id::text,
      p_actor_id,
      'client_dashboard'
    );

    insert into public.client_instagram_accounts (
      client_id, account_id, label, onboarding_status, provisioning_status, login_status
    ) values (
      p_client_id, v_account_id, 'Client onboarding - ' || v_username,
      'pending', 'not_started', 'unknown'
    ) returning id into v_client_account_id;

    insert into public.account_commercial_packages (
      account_id, package_code, status, source, metadata_safe
    ) values (
      v_account_id, v_package_code, 'active', 'client_onboarding',
      jsonb_build_object(
        'source', 'client_instagram_onboarding',
        'entitlement_id', p_entitlement_id,
        'runtime_activation_requested', false
      )
    );

    insert into public.client_subscription_accounts (
      subscription_id, client_instagram_account_id, account_id, status
    ) values (
      v_subscription_id, v_client_account_id, v_account_id, 'active'
    );

    update public.client_account_entitlements
       set status = 'entitlement_consumed',
           account_id = v_account_id,
           consumed_at = now(),
           updated_at = now()
     where id = p_entitlement_id
       and client_id = p_client_id
       and status = 'entitlement_reserved';
    if not found then
      raise exception 'entitlement_consume_conflict';
    end if;

    update public.client_instagram_onboarding_sessions
       set account_id = v_account_id,
           requested_username = v_username,
           package_code = v_package_code,
           status = 'active',
           current_step = 'analysis',
           public_analysis = coalesce(p_public_analysis, '{}'::jsonb),
           last_error_code = null,
           failure_reason = null,
           lease_owner = null,
           lease_expires_at = null,
           last_progress_at = now(),
           expires_at = now() + interval '7 days',
           updated_at = now()
     where id = v_session.id;

    insert into public.commercial_checkout_audit_events (
      entitlement_id, event_type, client_id, payload
    ) values (
      p_entitlement_id,
      'client_instagram_onboarding_started',
      p_client_id,
      jsonb_build_object(
        'onboarding_session_id', v_session.id,
        'account_id', v_account_id,
        'attempt_id', p_attempt_id,
        'package_code', v_package_code,
        'credentials_stored_in_vault', true,
        'runtime_activation_requested', false
      )
    );
  exception when others then
    v_failure := left(sqlerrm, 160);
    update public.client_instagram_onboarding_sessions
       set status = 'failed_retryable',
           last_error_code = 'atomic_provisioning_failed',
           failure_reason = v_failure,
           lease_owner = null,
           lease_expires_at = null,
           updated_at = now()
     where id = v_session.id;
    return jsonb_build_object(
      'ok', false,
      'reason', 'atomic_provisioning_failed',
      'session_id', v_session.id
    );
  end;

  return jsonb_build_object(
    'ok', true,
    'session_id', v_session.id,
    'account_id', v_account_id,
    'status', 'active'
  );
end;
$_$;




COMMENT ON FUNCTION "public"."begin_client_instagram_onboarding"("p_client_id" "uuid", "p_actor_id" "uuid", "p_entitlement_id" "uuid", "p_idempotency_key" "uuid", "p_attempt_id" "uuid", "p_lease_owner" "text", "p_requested_username" "text", "p_login_email" "text", "p_password" "text", "p_public_analysis" "jsonb") IS 'Creates the account, Vault secret, ownership, entitlement consumption, and resumable session in one PostgreSQL transaction.';


SET default_tablespace = '';

SET default_table_access_method = "heap";


CREATE TABLE IF NOT EXISTS "public"."scheduled_session_preflights" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "account_id" "uuid" NOT NULL,
    "assignment_id" "uuid" NOT NULL,
    "device_id" "uuid" NOT NULL,
    "app_instance_id" "uuid" NOT NULL,
    "expected_package" "text" DEFAULT ''::"text" NOT NULL,
    "expected_username" "text" DEFAULT ''::"text" NOT NULL,
    "scheduled_window_start" timestamp with time zone NOT NULL,
    "scheduled_window_end" timestamp with time zone NOT NULL,
    "business_action_deadline" timestamp with time zone NOT NULL,
    "preflight_start" timestamp with time zone NOT NULL,
    "status" "text" DEFAULT 'preflight_due'::"text" NOT NULL,
    "reason_code" "text",
    "checked_at" timestamp with time zone,
    "expires_at" timestamp with time zone NOT NULL,
    "lease_id" "uuid",
    "request_id" "uuid",
    "metadata_safe" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "scheduled_session_preflights_status_check" CHECK (("status" = ANY (ARRAY['preflight_due'::"text", 'preflight_running'::"text", 'preflight_ready'::"text", 'preflight_blocked'::"text", 'preflight_lease_unavailable'::"text", 'preflight_expired'::"text", 'preflight_invalidated'::"text", 'preflight_skipped_scheduler_off'::"text"])))
);




CREATE OR REPLACE FUNCTION "public"."bind_scheduled_session_preflight_request"("p_preflight_id" "uuid", "p_request_id" "uuid", "p_lease_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."scheduled_session_preflights"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ declare v_row public.scheduled_session_preflights%rowtype; begin update public.scheduled_session_preflights set request_id = p_request_id, lease_id = coalesce(p_lease_id, lease_id), status = 'preflight_running', updated_at = now() where id = p_preflight_id and status in ('preflight_due', 'preflight_lease_unavailable') returning * into v_row; if not found then raise exception 'preflight_not_bindable'; end if; return v_row; end; $$;




CREATE OR REPLACE FUNCTION "public"."block_invalid_login_package_runtime_contract"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_contract jsonb;
  v_reason text;
begin
  if new.requested_run_type in ('login_provisioning', 'login_email_code_resume') then
    v_contract := public.account_package_runtime_contract_status(new.account_id);
    v_reason := coalesce(v_contract ->> 'reason', 'package_settings_incomplete');
    if not coalesce((v_contract ->> 'ok')::boolean, false) then
      raise exception '%', v_reason;
    end if;
  end if;
  return new;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."bump_account_commercial_policy_revision"("p_account_id" "uuid", "p_client_id" "uuid", "p_package_code" "text", "p_entitlement_id" "uuid" DEFAULT NULL::"uuid", "p_plan_change_quote_id" "uuid" DEFAULT NULL::"uuid", "p_metadata_safe" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_token text;
begin
  v_token := md5(
    coalesce(p_account_id::text, '') || '|' ||
    coalesce(p_package_code, '') || '|' ||
    coalesce(p_entitlement_id::text, '') || '|' ||
    coalesce(p_plan_change_quote_id::text, '') || '|' ||
    coalesce(extract(epoch from now())::text, '')
  );

  insert into public.account_commercial_policy_revisions (
    account_id, client_id, package_code, entitlement_id, plan_change_quote_id, revision_token, metadata_safe
  ) values (
    p_account_id, p_client_id, p_package_code, p_entitlement_id, p_plan_change_quote_id, v_token, coalesce(p_metadata_safe, '{}'::jsonb)
  );

  return v_token;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."run_control_metadata_is_safe"("p_metadata" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  select
    jsonb_typeof(coalesce(p_metadata, '{}'::jsonb)) = 'object'
    and not exists (
      select 1
      from jsonb_object_keys(coalesce(p_metadata, '{}'::jsonb)) as k(key)
      where lower(k.key) in (
        'password', 'secret', 'secret_ref', 'raw_secret', 'token', 'cookie',
        'webhook', 'webhook_url', 'vault', 'service_role', 'authorization', 'bearer',
        'raw_xml', 'xml', 'screenshot', 'adb_serial', 'device_udid'
      )
    );
$$;




CREATE TABLE IF NOT EXISTS "public"."account_run_requests" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "account_id" "uuid" NOT NULL,
    "requested_by" "uuid",
    "actor_type" "text" DEFAULT 'admin'::"text" NOT NULL,
    "source_surface" "text" DEFAULT 'instagram_dashboard'::"text" NOT NULL,
    "requested_run_type" "text" NOT NULL,
    "status" "text" DEFAULT 'queued'::"text" NOT NULL,
    "priority" integer DEFAULT 0 NOT NULL,
    "idempotency_key" "text" NOT NULL,
    "run_id" "uuid",
    "claimed_by" "text",
    "lease_expires_at" timestamp with time zone,
    "cancel_requested_at" timestamp with time zone,
    "cancel_reason" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "claimed_at" timestamp with time zone,
    "started_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "canceled_at" timestamp with time zone,
    "metadata_safe" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "error_code" "text",
    "error_message_safe" "text",
    CONSTRAINT "account_run_requests_actor_type_check" CHECK (("actor_type" = ANY (ARRAY['admin'::"text", 'assistant'::"text", 'ops'::"text", 'system'::"text", 'internal'::"text", 'client'::"text"]))),
    CONSTRAINT "account_run_requests_cancel_reason_safe" CHECK ((("cancel_reason" IS NULL) OR (("char_length"(TRIM(BOTH FROM "cancel_reason")) > 0) AND ("char_length"(TRIM(BOTH FROM "cancel_reason")) <= 500) AND ("cancel_reason" !~* '(token|secret|authorization|cookie|service_role|vault|password)'::"text")))),
    CONSTRAINT "account_run_requests_claimed_by_safe" CHECK ((("claimed_by" IS NULL) OR (("char_length"(TRIM(BOTH FROM "claimed_by")) > 0) AND ("char_length"(TRIM(BOTH FROM "claimed_by")) <= 160) AND ("claimed_by" !~* '(token|secret|authorization|cookie|service_role|vault|password)'::"text")))),
    CONSTRAINT "account_run_requests_error_code_safe" CHECK ((("error_code" IS NULL) OR (("char_length"(TRIM(BOTH FROM "error_code")) > 0) AND ("char_length"(TRIM(BOTH FROM "error_code")) <= 120) AND ("error_code" !~* '(token|secret|authorization|cookie|service_role|vault|password)'::"text")))),
    CONSTRAINT "account_run_requests_error_message_safe_check" CHECK ((("error_message_safe" IS NULL) OR (("char_length"(TRIM(BOTH FROM "error_message_safe")) > 0) AND ("char_length"(TRIM(BOTH FROM "error_message_safe")) <= 500) AND ("error_message_safe" !~* '(token|secret|authorization|cookie|service_role|vault|password)'::"text")))),
    CONSTRAINT "account_run_requests_idempotency_key_nonempty" CHECK (("char_length"(TRIM(BOTH FROM "idempotency_key")) > 0)),
    CONSTRAINT "account_run_requests_metadata_safe_guard_check" CHECK ("public"."run_control_metadata_is_safe"("metadata_safe")),
    CONSTRAINT "account_run_requests_metadata_safe_object_check" CHECK (("jsonb_typeof"("metadata_safe") = 'object'::"text")),
    CONSTRAINT "account_run_requests_requested_run_type_nonempty" CHECK (("char_length"(TRIM(BOTH FROM "requested_run_type")) > 0)),
    CONSTRAINT "account_run_requests_source_surface_safe" CHECK ((("char_length"(TRIM(BOTH FROM "source_surface")) > 0) AND ("source_surface" !~* '(token|secret|authorization|cookie|service_role|vault|password)'::"text"))),
    CONSTRAINT "account_run_requests_status_check" CHECK (("status" = ANY (ARRAY['queued'::"text", 'claimed'::"text", 'starting'::"text", 'running'::"text", 'completed'::"text", 'failed'::"text", 'canceled'::"text", 'blocked'::"text"])))
);




CREATE OR REPLACE FUNCTION "public"."cancel_account_run_request"("p_request_id" "uuid" DEFAULT NULL::"uuid", "p_account_id" "uuid" DEFAULT NULL::"uuid", "p_actor_id" "uuid" DEFAULT NULL::"uuid", "p_reason" "text" DEFAULT 'manual_stop'::"text") RETURNS "public"."account_run_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ declare v_reason text := left(coalesce(nullif(trim(p_reason), ''), 'manual_stop'), 500); v_target_id uuid; v_row public.account_run_requests; begin if p_request_id is null and p_account_id is null then raise exception 'request_or_account_required' using errcode = '22023'; end if; if p_request_id is not null then v_target_id := p_request_id; else select arr.id into v_target_id from public.account_run_requests arr where arr.account_id = p_account_id and arr.status in ('queued', 'claimed', 'starting', 'running') order by arr.created_at desc limit 1; end if; if v_target_id is null then return null; end if; update public.account_run_requests arr set cancel_requested_at = coalesce(arr.cancel_requested_at, now()), cancel_reason = coalesce(arr.cancel_reason, v_reason), status = case when arr.status in ('queued', 'claimed', 'starting') then 'canceled' else arr.status end, canceled_at = case when arr.status in ('queued', 'claimed', 'starting') then coalesce(arr.canceled_at, now()) else arr.canceled_at end, lease_expires_at = case when arr.status in ('queued', 'claimed', 'starting') then null else arr.lease_expires_at end, updated_at = now() where arr.id = v_target_id and arr.status in ('queued', 'claimed', 'starting', 'running') returning * into v_row; return v_row; end; $$;




CREATE OR REPLACE FUNCTION "public"."claim_commercial_stripe_webhook_event"("p_stripe_event_id" "text", "p_event_type" "text", "p_livemode" boolean, "p_stripe_object_id" "text" DEFAULT NULL::"text", "p_stripe_customer_id" "text" DEFAULT NULL::"text", "p_stripe_subscription_id" "text" DEFAULT NULL::"text", "p_stripe_checkout_session_id" "text" DEFAULT NULL::"text", "p_metadata_safe" "jsonb" DEFAULT '{}'::"jsonb", "p_stale_after_seconds" integer DEFAULT 120) RETURNS TABLE("event_row_id" "uuid", "claim_result" "text", "prior_status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_row public.commercial_stripe_webhook_events%rowtype;
  v_now timestamptz := now();
  v_stale_before timestamptz := v_now - make_interval(secs => greatest(p_stale_after_seconds, 30));
begin
  if p_livemode then raise exception 'stripe_livemode_rejected'; end if;
  select * into v_row from public.commercial_stripe_webhook_events where stripe_event_id = p_stripe_event_id for update;
  if not found then
    insert into public.commercial_stripe_webhook_events (stripe_event_id, event_type, livemode, status, stripe_object_id, stripe_customer_id, stripe_subscription_id, stripe_checkout_session_id, metadata_safe, processing_started_at, attempts_count, received_at)
    values (p_stripe_event_id, p_event_type, false, 'processing', p_stripe_object_id, p_stripe_customer_id, p_stripe_subscription_id, p_stripe_checkout_session_id, coalesce(p_metadata_safe, '{}'::jsonb), v_now, 1, v_now)
    returning id into event_row_id;
    claim_result := 'claimed'; prior_status := null; return next; return;
  end if;
  event_row_id := v_row.id; prior_status := v_row.status;
  if v_row.status in ('processed', 'ignored') then claim_result := 'deduplicated'; return next; return; end if;
  if v_row.status = 'processing' and v_row.processing_started_at is not null and v_row.processing_started_at > v_stale_before then claim_result := 'concurrent'; return next; return; end if;
  update public.commercial_stripe_webhook_events set status='processing', processing_started_at=v_now, attempts_count=v_row.attempts_count+1, event_type=p_event_type, stripe_object_id=coalesce(p_stripe_object_id,v_row.stripe_object_id), stripe_customer_id=coalesce(p_stripe_customer_id,v_row.stripe_customer_id), stripe_subscription_id=coalesce(p_stripe_subscription_id,v_row.stripe_subscription_id), stripe_checkout_session_id=coalesce(p_stripe_checkout_session_id,v_row.stripe_checkout_session_id), metadata_safe=coalesce(p_metadata_safe,v_row.metadata_safe), last_error_redacted=null, processed_at=null where id=v_row.id;
  if v_row.status = 'processing' then claim_result := 'reclaimed_stale'; else claim_result := 'claimed'; end if;
  return next;
end; $$;




CREATE OR REPLACE FUNCTION "public"."jsonb_has_forbidden_safe_metadata_key"("p_metadata" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  with recursive walk(value) as (
    select coalesce(p_metadata, '{}'::jsonb)
    union all
    select child.value
    from walk w
    cross join lateral (
      select e.value
      from jsonb_each(
        case when jsonb_typeof(w.value) = 'object' then w.value else '{}'::jsonb end
      ) as e
      union all
      select a.value
      from jsonb_array_elements(
        case when jsonb_typeof(w.value) = 'array' then w.value else '[]'::jsonb end
      ) as a
    ) as child
  ),
  keys as (
    select lower(k.key) as key
    from walk w
    cross join lateral jsonb_object_keys(
      case when jsonb_typeof(w.value) = 'object' then w.value else '{}'::jsonb end
    ) as k(key)
  )
  select exists (
    select 1
    from keys
    where key in (
      'password',
      'password_hash',
      'password_length',
      'secret',
      'secret_ref',
      'secret_provider',
      'raw_secret',
      'token',
      'raw_token',
      'authorization',
      'bearer',
      'cookie',
      'session_cookie',
      'vault',
      'vault_id',
      'vault_payload',
      'service_role',
      'service_role_key',
      'internal_api_token',
      'webhook',
      'webhook_url',
      'slack_url',
      'discord_url',
      'raw_xml',
      'xml',
      'screenshot',
      'screenshot_path',
      'raw_logs',
      'raw_metadata',
      'request_body',
      'raw_request_body',
      'adb_serial',
      'usb_port',
      'hub_port',
      'device_udid'
    )
  );
$$;




COMMENT ON FUNCTION "public"."jsonb_has_forbidden_safe_metadata_key"("p_metadata" "jsonb") IS 'Credential pipeline safe-metadata guard. Returns true when JSON contains forbidden secret, token, raw log/XML, screenshot, or device-internal keys.';



CREATE TABLE IF NOT EXISTS "public"."ct_target_verification_jobs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "target_id" "uuid" NOT NULL,
    "account_id" "uuid" NOT NULL,
    "batch_id" "uuid",
    "normalized_username" "text" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "attempt_count" integer DEFAULT 0 NOT NULL,
    "max_attempts" integer DEFAULT 3 NOT NULL,
    "next_attempt_at" timestamp with time zone,
    "locked_at" timestamp with time zone,
    "locked_by" "text",
    "last_error_code" "text",
    "last_error_message" "text",
    "provider_status" "text",
    "metadata_safe" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "ct_target_verification_jobs_attempt_count_check" CHECK (("attempt_count" >= 0)),
    CONSTRAINT "ct_target_verification_jobs_error_code_check" CHECK ((("last_error_code" IS NULL) OR (("char_length"("last_error_code") <= 120) AND ("last_error_code" ~ '^[a-z0-9_:-]+$'::"text")))),
    CONSTRAINT "ct_target_verification_jobs_error_message_check" CHECK ((("last_error_message" IS NULL) OR (("char_length"("last_error_message") <= 240) AND ("last_error_message" !~* '(token|secret|authorization|cookie|service_role|vault|password|raw|html)'::"text")))),
    CONSTRAINT "ct_target_verification_jobs_locked_by_check" CHECK ((("locked_by" IS NULL) OR (("char_length"("locked_by") <= 120) AND ("locked_by" !~* '(token|secret|authorization|cookie|service_role|vault)'::"text")))),
    CONSTRAINT "ct_target_verification_jobs_max_attempts_check" CHECK ((("max_attempts" >= 1) AND ("max_attempts" <= 10))),
    CONSTRAINT "ct_target_verification_jobs_metadata_safe_check" CHECK ((("jsonb_typeof"("metadata_safe") = 'object'::"text") AND (NOT "public"."jsonb_has_forbidden_safe_metadata_key"("metadata_safe")))),
    CONSTRAINT "ct_target_verification_jobs_normalized_username_check" CHECK ((("normalized_username" ~ '^[a-z0-9._]{1,30}$'::"text") AND ("normalized_username" !~~ '%.'::"text") AND ("normalized_username" !~~ '.%'::"text") AND ("normalized_username" !~~ '%..%'::"text"))),
    CONSTRAINT "ct_target_verification_jobs_provider_status_check" CHECK ((("provider_status" IS NULL) OR ("provider_status" = ANY (ARRAY['pending'::"text", 'found'::"text", 'not_found'::"text", 'unavailable'::"text", 'rate_limited'::"text", 'provider_error'::"text", 'provider_not_configured'::"text", 'username_invalid'::"text"])))),
    CONSTRAINT "ct_target_verification_jobs_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'processing'::"text", 'succeeded'::"text", 'failed'::"text", 'skipped'::"text", 'retry_scheduled'::"text"])))
);




COMMENT ON TABLE "public"."ct_target_verification_jobs" IS 'Durable CT target verification jobs for bulk-imported target accounts. Stores safe status, retry and provider summary only; never raw provider responses, full URLs, headers, cookies, sessions, tokens, secret refs, Vault ids, raw HTML, XML, screenshots or logs.';



CREATE OR REPLACE FUNCTION "public"."claim_ct_target_verification_jobs"("batch_limit" integer DEFAULT 5, "worker_id" "text" DEFAULT 'dashboard_verify_batch'::"text") RETURNS SETOF "public"."ct_target_verification_jobs"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  safe_limit integer := least(greatest(coalesce(batch_limit, 5), 1), 10);
  safe_worker_id text := left(regexp_replace(coalesce(worker_id, 'dashboard_verify_batch'), '[^a-zA-Z0-9_.:-]', '_', 'g'), 120);
begin
  return query
  with next_jobs as (
    select j.id
    from public.ct_target_verification_jobs j
    join public.ig_targets t on t.id = j.target_id
    where (
        j.status in ('pending', 'retry_scheduled')
        or (j.status = 'processing' and j.locked_at < now() - interval '15 minutes')
      )
      and coalesce(j.next_attempt_at, now()) <= now()
      and (j.locked_at is null or j.locked_at < now() - interval '15 minutes')
      and t.status not in ('archived', 'deleted')
      and t.archived_at is null
      and t.deleted_at is null
    order by coalesce(j.next_attempt_at, j.created_at), j.created_at
    limit safe_limit
    for update of j skip locked
  ),
  claimed as (
    update public.ct_target_verification_jobs j
    set
      status = 'processing',
      attempt_count = j.attempt_count + 1,
      locked_at = now(),
      locked_by = safe_worker_id,
      updated_at = now()
    from next_jobs
    where j.id = next_jobs.id
    returning j.*
  )
  select * from claimed;
end;
$$;




COMMENT ON FUNCTION "public"."claim_ct_target_verification_jobs"("batch_limit" integer, "worker_id" "text") IS 'Atomically claims a small CT target verification batch with FOR UPDATE SKIP LOCKED, including expired processing jobs. Intended for service-role dashboard/API use only.';



CREATE OR REPLACE FUNCTION "public"."claim_ct_target_verification_scheduler_lock"("worker_id" "text" DEFAULT 'ct_verify_cron'::"text", "ttl_seconds" integer DEFAULT 120) RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  safe_worker_id text := left(
    regexp_replace(coalesce(worker_id, 'ct_verify_cron'), '[^a-zA-Z0-9_.:-]', '_', 'g'),
    120
  );
  safe_ttl integer := least(greatest(coalesce(ttl_seconds, 120), 30), 600);
  lock_name constant text := 'ct_target_verification';
begin
  if safe_worker_id is null or safe_worker_id = '' then
    safe_worker_id := 'ct_verify_cron';
  end if;

  insert into public.ct_target_verification_scheduler_locks (
    lock_key,
    worker_id,
    locked_at,
    expires_at
  )
  values (
    lock_name,
    safe_worker_id,
    now(),
    now() - interval '1 second'
  )
  on conflict (lock_key) do nothing;

  update public.ct_target_verification_scheduler_locks
  set
    worker_id = safe_worker_id,
    locked_at = now(),
    expires_at = now() + make_interval(secs => safe_ttl)
  where lock_key = lock_name
    and (
      expires_at <= now()
      or ct_target_verification_scheduler_locks.worker_id = safe_worker_id
    );

  return found;
end;
$$;




COMMENT ON FUNCTION "public"."claim_ct_target_verification_scheduler_lock"("worker_id" "text", "ttl_seconds" integer) IS 'Claims or renews the CT verification scheduler lock when free or expired. Returns false when another active worker holds the lock.';



CREATE TABLE IF NOT EXISTS "public"."ig_social_profile_snapshot_jobs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "account_id" "uuid" NOT NULL,
    "username_normalized" "text" NOT NULL,
    "snapshot_local_date" "date" NOT NULL,
    "account_timezone" "text" NOT NULL,
    "timezone_source" "text" NOT NULL,
    "source_trigger" "text" NOT NULL,
    "source_event_id" "text",
    "source_run_id" "uuid",
    "source_business_session_id" "uuid",
    "idempotency_key" "text" NOT NULL,
    "status" "text" DEFAULT 'queued'::"text" NOT NULL,
    "attempts" integer DEFAULT 0 NOT NULL,
    "available_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "lease_owner" "text",
    "lease_expires_at" timestamp with time zone,
    "last_error_code" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "ig_social_profile_snapshot_jobs_attempts_check" CHECK (("attempts" >= 0)),
    CONSTRAINT "ig_social_profile_snapshot_jobs_source_trigger_check" CHECK (("source_trigger" = ANY (ARRAY['session_end'::"text", 'daily_fallback'::"text", 'admin_manual_refresh'::"text", 'baseline_one_shot'::"text"]))),
    CONSTRAINT "ig_social_profile_snapshot_jobs_status_check" CHECK (("status" = ANY (ARRAY['queued'::"text", 'processing'::"text", 'succeeded'::"text", 'failed'::"text", 'discarded'::"text"]))),
    CONSTRAINT "ig_social_profile_snapshot_jobs_timezone_source_check" CHECK (("timezone_source" = ANY (ARRAY['device_assignment'::"text", 'schedule'::"text", 'platform_default'::"text"]))),
    CONSTRAINT "ig_social_profile_snapshot_jobs_username_normalized_check" CHECK ((("username_normalized" = "lower"(TRIM(BOTH FROM "username_normalized"))) AND ("username_normalized" ~ '^[a-z0-9._]{1,30}$'::"text")))
);




CREATE OR REPLACE FUNCTION "public"."claim_ig_social_profile_baseline_jobs"("p_source_event_id" "text", "p_lease_owner" "text", "p_limit" integer DEFAULT 10, "p_lease_seconds" integer DEFAULT 120) RETURNS SETOF "public"."ig_social_profile_snapshot_jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
begin
  if nullif(trim(p_source_event_id), '') is null then
    return;
  end if;

  return query
  with candidates as (
    select j.id
      from public.ig_social_profile_snapshot_jobs j
      join public.ig_accounts account on account.id = j.account_id
     where j.source_trigger = 'baseline_one_shot'
       and j.source_event_id = p_source_event_id
       and j.available_at <= now()
       and (j.status = 'queued' or (j.status = 'processing' and j.lease_expires_at < now()))
       and j.attempts < 3
       and lower(coalesce(nullif(account.admin_lifecycle_status, ''), account.status, '')) = 'active'
       and lower(trim(leading '@' from account.username)) = j.username_normalized
       and lower(trim(leading '@' from account.username)) ~ '^[a-z0-9._]{1,30}$'
       and (
         select count(*)
           from public.account_assignments assignment
          where assignment.account_id = j.account_id
            and assignment.status in ('pending', 'reserved', 'active')
       ) <= 1
       and not exists (
         select 1
           from public.ig_account_social_profile_snapshots snapshot
          where snapshot.account_id = j.account_id
            and snapshot.source_trigger <> 'legacy_import'
            and snapshot.observed_at >= now() - interval '36 hours'
       )
     order by j.available_at, j.created_at
     for update of j skip locked
     limit greatest(1, least(coalesce(p_limit, 10), 10))
  )
  update public.ig_social_profile_snapshot_jobs j
     set status = 'processing',
         attempts = j.attempts + 1,
         lease_owner = left(trim(p_lease_owner), 160),
         lease_expires_at = now() + make_interval(secs => greatest(30, least(coalesce(p_lease_seconds, 120), 300))),
         updated_at = now()
    from candidates c
   where j.id = c.id
  returning j.*;
end;
$_$;




COMMENT ON FUNCTION "public"."claim_ig_social_profile_baseline_jobs"("p_source_event_id" "text", "p_lease_owner" "text", "p_limit" integer, "p_lease_seconds" integer) IS 'Claims at most ten eligible jobs from one hashed baseline batch; never claims recurring or historical queue work.';



CREATE OR REPLACE FUNCTION "public"."claim_ig_social_profile_snapshot_jobs"("p_lease_owner" "text", "p_limit" integer DEFAULT 10, "p_lease_seconds" integer DEFAULT 120) RETURNS SETOF "public"."ig_social_profile_snapshot_jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  return query
  with candidates as (
    select j.id
      from public.ig_social_profile_snapshot_jobs j
     where j.available_at <= now()
       and (j.status = 'queued' or (j.status = 'processing' and j.lease_expires_at < now()))
       and j.attempts < 3
     order by j.available_at, j.created_at
     for update skip locked
     limit greatest(1, least(coalesce(p_limit, 10), 25))
  )
  update public.ig_social_profile_snapshot_jobs j
     set status = 'processing',
         attempts = j.attempts + 1,
         lease_owner = left(trim(p_lease_owner), 160),
         lease_expires_at = now() + make_interval(secs => greatest(30, least(coalesce(p_lease_seconds, 120), 300))),
         updated_at = now()
    from candidates c
   where j.id = c.id
  returning j.*;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."claim_next_account_run_request"("p_worker_id" "text", "p_lease_seconds" integer DEFAULT 120, "p_allowed_run_types" "text"[] DEFAULT NULL::"text"[]) RETURNS "public"."account_run_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ declare v_worker_id text := left(regexp_replace(coalesce(nullif(trim(p_worker_id), ''), 'run-dispatcher'), '[^a-zA-Z0-9_.:-]', '_', 'g'), 160); v_lease_seconds integer := least(greatest(coalesce(p_lease_seconds, 120), 30), 3600); v_request_id uuid; v_row public.account_run_requests; begin if v_worker_id is null or v_worker_id = '' then raise exception 'worker_id_required' using errcode = '22023'; end if; perform public.reclaim_stale_account_run_requests(v_worker_id); select arr.id into v_request_id from public.account_run_requests arr where arr.status = 'queued' and arr.cancel_requested_at is null and (p_allowed_run_types is null or arr.requested_run_type = any (p_allowed_run_types)) and not public.account_has_active_ig_run(arr.account_id) order by arr.priority desc, arr.created_at asc for update skip locked limit 1; if v_request_id is null then return null; end if; update public.account_run_requests arr set status = 'claimed', claimed_by = v_worker_id, claimed_at = now(), lease_expires_at = now() + make_interval(secs => v_lease_seconds), updated_at = now() where arr.id = v_request_id and arr.status = 'queued' and arr.cancel_requested_at is null returning * into v_row; return v_row; end; $$;




CREATE TABLE IF NOT EXISTS "public"."ig_dm_jobs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "account_id" "uuid" NOT NULL,
    "dm_type" "public"."dm_type" NOT NULL,
    "recipient_username" "text" NOT NULL,
    "recipient_username_normalized" "text" GENERATED ALWAYS AS ("lower"(TRIM(BOTH FROM "recipient_username"))) STORED,
    "message_body" "text",
    "template_id" "uuid",
    "source" "public"."dm_job_source" DEFAULT 'manual'::"public"."dm_job_source" NOT NULL,
    "campaign_id" "uuid",
    "priority" integer DEFAULT 0 NOT NULL,
    "status" "public"."dm_job_status" DEFAULT 'pending'::"public"."dm_job_status" NOT NULL,
    "skip_reason" "text",
    "attempts" integer DEFAULT 0 NOT NULL,
    "max_attempts" integer DEFAULT 3 NOT NULL,
    "next_retry_at" timestamp with time zone,
    "reserved_at" timestamp with time zone,
    "reserved_by" "text",
    "started_at" timestamp with time zone,
    "finished_at" timestamp with time zone,
    "sent_at" timestamp with time zone,
    "last_error" "text",
    "idempotency_key" "text" NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "ig_dm_jobs_attempts_nonnegative" CHECK (("attempts" >= 0)),
    CONSTRAINT "ig_dm_jobs_idempotency_key_nonempty" CHECK (("char_length"(TRIM(BOTH FROM "idempotency_key")) > 0)),
    CONSTRAINT "ig_dm_jobs_max_attempts_positive" CHECK (("max_attempts" >= 1)),
    CONSTRAINT "ig_dm_jobs_message_or_template" CHECK (((("message_body" IS NOT NULL) AND ("char_length"(TRIM(BOTH FROM "message_body")) > 0)) OR ("template_id" IS NOT NULL))),
    CONSTRAINT "ig_dm_jobs_recipient_nonempty" CHECK (("char_length"(TRIM(BOTH FROM "recipient_username")) > 0)),
    CONSTRAINT "ig_dm_jobs_sent_at_when_sent" CHECK ((("status" <> 'sent'::"public"."dm_job_status") OR ("sent_at" IS NOT NULL)))
);




COMMENT ON TABLE "public"."ig_dm_jobs" IS 'V4 unified DM queue (welcome + outreach); claimed by Python worker via claim_next_dm_job.';



CREATE OR REPLACE FUNCTION "public"."claim_next_dm_job"("p_account_id" "uuid", "p_reserved_by" "text", "p_dm_type" "public"."dm_type" DEFAULT NULL::"public"."dm_type") RETURNS "public"."ig_dm_jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_job_id uuid;
  v_job public.ig_dm_jobs;
begin
  if p_reserved_by is null or char_length(trim(p_reserved_by)) = 0 then
    raise exception 'reserved_by must be non-empty (worker id / device serial)';
  end if;

  select j.id
  into v_job_id
  from public.ig_dm_jobs j
  where j.account_id = p_account_id
    and j.status = 'pending'
    and (j.next_retry_at is null or j.next_retry_at <= now())
    and (p_dm_type is null or j.dm_type = p_dm_type)
  order by j.priority desc, j.created_at asc
  for update skip locked
  limit 1;

  if v_job_id is null then
    return null;
  end if;

  update public.ig_dm_jobs j
  set
    status = 'reserved',
    reserved_at = now(),
    reserved_by = trim(p_reserved_by),
    updated_at = now()
  where j.id = v_job_id
  returning * into v_job;

  return v_job;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."claim_target_auto_archive_low_fbr_scheduler_lock"("worker_id" "text" DEFAULT 'target_auto_archive_low_fbr_cron'::"text", "ttl_seconds" integer DEFAULT 900) RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  safe_worker_id text := left(
    regexp_replace(coalesce(worker_id, 'target_auto_archive_low_fbr_cron'), '[^a-zA-Z0-9_.:-]', '_', 'g'),
    120
  );
  safe_ttl integer := least(greatest(coalesce(ttl_seconds, 900), 60), 3600);
  lock_name constant text := 'target_auto_archive_low_fbr';
begin
  if safe_worker_id is null or safe_worker_id = '' then
    safe_worker_id := 'target_auto_archive_low_fbr_cron';
  end if;

  insert into public.target_auto_archive_low_fbr_scheduler_locks (
    lock_key,
    worker_id,
    locked_at,
    expires_at
  )
  values (
    lock_name,
    safe_worker_id,
    now(),
    now() - interval '1 second'
  )
  on conflict (lock_key) do nothing;

  update public.target_auto_archive_low_fbr_scheduler_locks
  set
    worker_id = safe_worker_id,
    locked_at = now(),
    expires_at = now() + make_interval(secs => safe_ttl)
  where lock_key = lock_name
    and expires_at <= now();

  return found;
end;
$$;




COMMENT ON FUNCTION "public"."claim_target_auto_archive_low_fbr_scheduler_lock"("worker_id" "text", "ttl_seconds" integer) IS 'Claims the low-FBR auto-archive scheduler lock only when free or expired. Returns false when another active run holds the lock.';



CREATE OR REPLACE FUNCTION "public"."claim_target_followers_resume_checkpoint_v3"("p_account_id" "uuid", "p_target_id" "uuid", "p_surface" "text", "p_run_id" "uuid", "p_mode" "text", "p_expected_version" bigint DEFAULT NULL::bigint, "p_lease_seconds" integer DEFAULT 3600) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_row public.ig_target_followers_resume_checkpoints%rowtype;
  v_previous_version bigint;
  v_new_version bigint;
  v_reclaimed boolean := false;
  v_expiry timestamptz;
begin
  if p_account_id is null or p_target_id is null or p_run_id is null
     or p_surface <> 'followers' or p_mode not in ('shadow', 'enforce')
     or p_lease_seconds not between 300 and 7200 then
    return jsonb_build_object('ok', false, 'reason', 'invalid_claim_input');
  end if;
  if not exists (select 1 from public.ig_targets t where t.id = p_target_id and t.account_id = p_account_id) then
    return jsonb_build_object('ok', false, 'reason', 'target_account_mismatch');
  end if;

  insert into public.ig_target_followers_resume_checkpoints(account_id, target_id, surface, checkpoint_version)
  values (p_account_id, p_target_id, p_surface, 3)
  on conflict (account_id, target_id, surface) do nothing;

  select * into v_row from public.ig_target_followers_resume_checkpoints c
  where c.account_id = p_account_id and c.target_id = p_target_id and c.surface = p_surface for update;
  if v_row.status not in ('active', 'exhausted') then
    return jsonb_build_object('ok', false, 'reason', 'checkpoint_not_claimable', 'optimistic_version', v_row.optimistic_version);
  end if;
  if p_expected_version is not null and v_row.optimistic_version <> p_expected_version then
    return jsonb_build_object('ok', false, 'reason', 'optimistic_version_conflict', 'optimistic_version', v_row.optimistic_version);
  end if;
  if v_row.lease_owner_run_id is not null and v_row.lease_owner_run_id <> p_run_id and v_row.lease_expires_at > now() then
    if exists (
      select 1 from public.ig_runs r
      where r.id = v_row.lease_owner_run_id and r.status not in ('completed', 'failed', 'stopped')
    ) or not exists (select 1 from public.ig_runs r where r.id = v_row.lease_owner_run_id) then
      return jsonb_build_object('ok', false, 'reason', 'lease_held', 'optimistic_version', v_row.optimistic_version, 'lease_expires_at', v_row.lease_expires_at);
    end if;
    v_reclaimed := true;
  elsif v_row.lease_owner_run_id is not null and v_row.lease_owner_run_id <> p_run_id then
    v_reclaimed := true;
  end if;

  v_previous_version := v_row.optimistic_version;
  v_expiry := now() + make_interval(secs => p_lease_seconds);
  update public.ig_target_followers_resume_checkpoints c
  set lease_owner_run_id = p_run_id, lease_mode = p_mode,
      lease_expires_at = v_expiry, lease_heartbeat_at = now(),
      lease_generation = c.lease_generation + 1, last_run_id = p_run_id,
      optimistic_version = c.optimistic_version + 1, updated_at = now()
  where c.id = v_row.id returning c.optimistic_version into v_new_version;

  insert into public.ig_target_followers_resume_checkpoint_events(
    checkpoint_id, account_id, target_id, run_id, event_type, mode,
    previous_optimistic_version, new_optimistic_version, previous_depth, new_depth, reason
  ) values (
    v_row.id, p_account_id, p_target_id, p_run_id,
    case when v_reclaimed then 'reclaimed' else 'claimed' end, p_mode,
    v_previous_version, v_new_version,
    case when p_mode = 'enforce' then v_row.last_safe_depth else v_row.shadow_last_safe_depth end,
    case when p_mode = 'enforce' then v_row.last_safe_depth else v_row.shadow_last_safe_depth end,
    case when v_reclaimed then 'lease_reclaimed' else 'lease_claimed' end
  );
  return jsonb_build_object('ok', true, 'reason', case when v_reclaimed then 'reclaimed' else 'claimed' end,
    'optimistic_version', v_new_version, 'lease_expires_at', v_expiry, 'lease_generation', v_row.lease_generation + 1);
end
$$;




CREATE OR REPLACE FUNCTION "public"."cleanup_instagram_smoke_account"("p_username" "text", "p_request_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_username text := lower(regexp_replace(btrim(coalesce(p_username, '')), '^@+', ''));
  v_request_id text := nullif(btrim(coalesce(p_request_id, '')), '');
  v_account_id uuid;
  v_request_match boolean := false;
  v_revoke_result jsonb := '{}'::jsonb;
  v_credential_update_requests_removed integer := 0;
  v_dashboard_actions_removed integer := 0;
  v_credentials_removed integer := 0;
  v_client_links_removed integer := 0;
  v_filters_removed integer := 0;
  v_settings_removed integer := 0;
  v_accounts_removed integer := 0;
begin
  if auth.role() <> 'service_role' then
    raise exception 'service_role_required'
      using errcode = '42501';
  end if;

  if v_username !~ '^smoke_[a-z0-9._]{1,24}$' then
    raise exception 'smoke_username_required'
      using errcode = '22023';
  end if;

  if v_request_id is null or v_request_id !~ '^[a-zA-Z0-9._:-]{1,120}$' then
    raise exception 'request_id_required'
      using errcode = '22023';
  end if;

  select ia.id
    into v_account_id
  from public.ig_accounts ia
  where lower(ia.username) = v_username
  order by ia.created_at desc
  limit 1
  for update;

  if v_account_id is null then
    return jsonb_build_object(
      'ok', true,
      'account_removed', false,
      'credentials_removed', 0,
      'credentials_revoked', 0,
      'vault_cleanup_attempted', false,
      'vault_cleanup_status', 'not_applicable',
      'actions_removed', 0,
      'requests_removed', 0,
      'settings_removed', 0,
      'filters_removed', 0
    );
  end if;

  select exists (
    select 1
    from public.account_credentials ac
    where ac.account_id = v_account_id
      and (
        ac.metadata_safe->>'request_id' = v_request_id
        or ac.metadata_safe->>'external_request_id' = v_request_id
        or ac.metadata->>'request_id' = v_request_id
        or ac.metadata->>'external_request_id' = v_request_id
      )
    union all
    select 1
    from public.account_dashboard_actions ada
    where ada.account_id = v_account_id
      and (
        ada.metadata_safe->>'request_id' = v_request_id
        or ada.metadata_safe->>'external_request_id' = v_request_id
        or ada.metadata->>'request_id' = v_request_id
        or ada.metadata->>'external_request_id' = v_request_id
      )
    union all
    select 1
    from public.credential_update_requests cur
    where cur.account_id = v_account_id
      and (
        cur.metadata_safe->>'request_id' = v_request_id
        or cur.metadata_safe->>'external_request_id' = v_request_id
      )
  )
    into v_request_match;

  if not v_request_match then
    raise exception 'smoke_request_id_not_matched'
      using errcode = '22023';
  end if;

  v_revoke_result := public.revoke_instagram_account_credentials(
    v_account_id,
    'instagram',
    'smoke_cleanup',
    v_request_id
  );

  delete from public.credential_update_requests cur
  where cur.account_id = v_account_id;
  get diagnostics v_credential_update_requests_removed = row_count;

  delete from public.account_dashboard_actions ada
  where ada.account_id = v_account_id;
  get diagnostics v_dashboard_actions_removed = row_count;

  delete from public.account_credentials ac
  where ac.account_id = v_account_id;
  get diagnostics v_credentials_removed = row_count;

  delete from public.client_instagram_accounts cia
  where cia.account_id = v_account_id;
  get diagnostics v_client_links_removed = row_count;

  delete from public.ig_account_filters iaf
  where iaf.account_id = v_account_id;
  get diagnostics v_filters_removed = row_count;

  delete from public.ig_account_settings ias
  where ias.account_id = v_account_id;
  get diagnostics v_settings_removed = row_count;

  delete from public.ig_accounts ia
  where ia.id = v_account_id;
  get diagnostics v_accounts_removed = row_count;

  return jsonb_build_object(
    'ok', true,
    'account_removed', v_accounts_removed > 0,
    'credentials_removed', v_credentials_removed,
    'credentials_revoked', coalesce((v_revoke_result->>'credentials_revoked')::integer, 0),
    'vault_cleanup_attempted', coalesce((v_revoke_result->>'vault_cleanup_attempted')::boolean, false),
    'vault_cleanup_status', coalesce(v_revoke_result->>'vault_cleanup_status', 'not_applicable'),
    'actions_removed', v_dashboard_actions_removed,
    'requests_removed', v_credential_update_requests_removed,
    'settings_removed', v_settings_removed,
    'filters_removed', v_filters_removed,
    'client_links_removed', v_client_links_removed
  );
end;
$_$;




COMMENT ON FUNCTION "public"."cleanup_instagram_smoke_account"("p_username" "text", "p_request_id" "text") IS 'Patch 2C-1 service-role-only smoke cleanup helper. Requires username prefix smoke_ and a matching safe request_id in related metadata before deleting rows.';



CREATE OR REPLACE FUNCTION "public"."client_account_has_outreach_entitlement"("p_account_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.clients c
    join public.client_instagram_accounts cia
      on cia.client_id = c.id
     and cia.account_id = p_account_id
    join public.client_entitlements ce
      on ce.client_id = c.id
     and (ce.account_id is null or ce.account_id = p_account_id)
     and ce.feature_code = 'outreach'
     and ce.active = true
     and (ce.valid_from is null or ce.valid_from <= now())
     and (ce.valid_until is null or ce.valid_until > now())
    join public.ig_account_dm_settings s
      on s.account_id = cia.account_id
     and s.outreach_enabled = true
    where c.status = 'active'
      and p_account_id is not null
  );
$$;




CREATE OR REPLACE FUNCTION "public"."client_can_enqueue_outreach"("p_auth_user_id" "uuid", "p_account_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.client_users cu
    join public.clients c
      on c.id = cu.client_id
     and c.status = 'active'
    join public.client_instagram_accounts cia
      on cia.client_id = c.id
     and cia.account_id = p_account_id
    join public.client_entitlements ce
      on ce.client_id = c.id
     and (ce.account_id is null or ce.account_id = p_account_id)
     and ce.feature_code = 'outreach'
     and ce.active = true
     and (ce.valid_from is null or ce.valid_from <= now())
     and (ce.valid_until is null or ce.valid_until > now())
    join public.ig_account_dm_settings s
      on s.account_id = cia.account_id
     and s.outreach_enabled = true
    where cu.auth_user_id = p_auth_user_id
      and cu.status = 'active'
      and p_auth_user_id is not null
      and p_account_id is not null
  );
$$;




CREATE OR REPLACE FUNCTION "public"."client_can_manage_instagram_account"("p_auth_user_id" "uuid", "p_account_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.client_users cu
    join public.clients c
      on c.id = cu.client_id
     and c.status = 'active'
    join public.client_instagram_accounts cia
      on cia.client_id = c.id
     and cia.account_id = p_account_id
     and cia.active = true
    join public.ig_accounts a
      on a.id = cia.account_id
     and a.archived_at is null
     and a.trashed_at is null
     and lower(coalesce(a.status, '')) not in (
       'archived', 'trashed', 'cancelled', 'canceled', 'deleted', 'rolled_back_test_onboarding'
     )
     and lower(coalesce(a.admin_lifecycle_status, '')) not in (
       'archived', 'trashed', 'cancelled', 'canceled', 'deleted', 'rolled_back_test_onboarding'
     )
    where cu.auth_user_id = p_auth_user_id
      and cu.status = 'active'
      and cu.role in ('owner', 'admin', 'assistant')
      and p_auth_user_id is not null
      and p_account_id is not null
  );
$$;




COMMENT ON FUNCTION "public"."client_can_manage_instagram_account"("p_auth_user_id" "uuid", "p_account_id" "uuid") IS 'Entry 2D-2B generic client/account ownership helper for credentials APIs. Does not require outreach entitlement.';



CREATE OR REPLACE FUNCTION "public"."client_id_for_instagram_account"("p_account_id" "uuid") RETURNS "uuid"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select cia.client_id
  from public.client_instagram_accounts cia
  join public.clients c
    on c.id = cia.client_id
   and c.status = 'active'
  where cia.account_id = p_account_id
    and p_account_id is not null
  limit 1;
$$;




COMMENT ON FUNCTION "public"."client_id_for_instagram_account"("p_account_id" "uuid") IS 'Entry 2D-2B service-role helper returning the active owning client for an Instagram account.';



CREATE OR REPLACE FUNCTION "public"."commercial_plan_change_source_revision"("p_entitlement_updated_at" timestamp with time zone, "p_session_updated_at" timestamp with time zone, "p_plan_key" "text", "p_active_commercial_period_value_cents" integer, "p_entitlement_id" "uuid", "p_session_id" "uuid") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO 'public'
    AS $$
  select md5(
    coalesce(p_entitlement_updated_at::text, '') || '|' ||
    coalesce(p_session_updated_at::text, '') || '|' ||
    coalesce(p_plan_key, '') || '|' ||
    coalesce(p_active_commercial_period_value_cents::text, '') || '|' ||
    coalesce(p_entitlement_id::text, '') || '|' ||
    coalesce(p_session_id::text, '')
  );
$$;




CREATE OR REPLACE FUNCTION "public"."commercial_plan_change_source_revision_for_account_source"("p_entitlement_id" "uuid", "p_session_id" "uuid", "p_account_id" "uuid", "p_active_commercial_period_value_cents" integer) RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select public.commercial_plan_change_source_revision(
    e.updated_at,
    s.updated_at,
    e.plan_key,
    p_active_commercial_period_value_cents,
    e.id,
    s.id
  ) || ':' || coalesce(p_account_id::text, '')
  from public.client_account_entitlements e
  inner join public.commercial_checkout_sessions s on s.id = p_session_id
  where e.id = p_entitlement_id
    and p_account_id is not null
    and e.account_id is not null
    and e.account_id = p_account_id
    and e.client_id = s.client_id;
$$;




COMMENT ON FUNCTION "public"."commercial_plan_change_source_revision_for_account_source"("p_entitlement_id" "uuid", "p_session_id" "uuid", "p_account_id" "uuid", "p_active_commercial_period_value_cents" integer) IS 'Per-account plan change revision: canonical workspace revision suffixed with account_id. Returns NULL when entitlement/session/account linkage is inconsistent (fail-closed).';



CREATE OR REPLACE FUNCTION "public"."commercial_plan_change_source_revision_for_source"("p_entitlement_id" "uuid", "p_session_id" "uuid", "p_active_commercial_period_value_cents" integer) RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select public.commercial_plan_change_source_revision(
    e.updated_at,
    s.updated_at,
    e.plan_key,
    p_active_commercial_period_value_cents,
    e.id,
    s.id
  )
  from public.client_account_entitlements e
  inner join public.commercial_checkout_sessions s on s.id = p_session_id
  where e.id = p_entitlement_id;
$$;




CREATE OR REPLACE FUNCTION "public"."commit_target_followers_resume_checkpoint_v3"("p_account_id" "uuid", "p_target_id" "uuid", "p_surface" "text", "p_run_id" "uuid", "p_mode" "text", "p_expected_version" bigint, "p_last_safe_depth" integer, "p_last_safe_anchor" "text" DEFAULT NULL::"text", "p_anchor_fingerprint" "text" DEFAULT NULL::"text", "p_last_visible_anchor_hashes" "jsonb" DEFAULT '[]'::"jsonb", "p_last_instagram_version" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT 'active'::"text", "p_end_reached" boolean DEFAULT false, "p_reason" "text" DEFAULT 'validated_transition'::"text", "p_lease_seconds" integer DEFAULT 3600) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_row public.ig_target_followers_resume_checkpoints%rowtype;
  v_previous_depth integer;
  v_new_version bigint;
  v_reclaimed boolean;
  v_expiry timestamptz;
begin
  if p_expected_version is null or p_surface <> 'followers' or p_mode not in ('shadow','enforce')
     or p_last_safe_depth not between 0 and 80 or p_status not in ('active','exhausted')
     or p_reason !~ '^[a-z0-9_:-]{1,120}$' or p_lease_seconds not between 300 and 7200
     or coalesce(p_last_safe_anchor,'') !~ '^(|a3:[0-9a-f]{32})$'
     or coalesce(p_anchor_fingerprint,'') !~ '^(|v3:[0-9a-f]{32})$'
     or jsonb_typeof(p_last_visible_anchor_hashes) <> 'array'
     or jsonb_array_length(p_last_visible_anchor_hashes) > 12
     or exists (select 1 from jsonb_array_elements_text(p_last_visible_anchor_hashes) a(value) where a.value !~ '^a3:[0-9a-f]{32}$') then
    return jsonb_build_object('ok', false, 'reason', 'invalid_commit_input');
  end if;
  select * into v_row from public.ig_target_followers_resume_checkpoints c
  where c.account_id=p_account_id and c.target_id=p_target_id and c.surface=p_surface for update;
  if not found then return jsonb_build_object('ok',false,'reason','checkpoint_missing'); end if;
  if v_row.optimistic_version <> p_expected_version then
    return jsonb_build_object('ok',false,'reason','optimistic_version_conflict','optimistic_version',v_row.optimistic_version);
  end if;
  if v_row.lease_owner_run_id <> p_run_id or v_row.lease_mode <> p_mode then
    return jsonb_build_object('ok',false,'reason','lease_owner_mismatch','optimistic_version',v_row.optimistic_version);
  end if;
  v_reclaimed := v_row.lease_expires_at is null or v_row.lease_expires_at <= now();
  v_previous_depth := case when p_mode='enforce' then v_row.last_safe_depth else v_row.shadow_last_safe_depth end;
  if p_last_safe_depth < v_previous_depth then return jsonb_build_object('ok',false,'reason','depth_regression_rejected','previous_depth',v_previous_depth); end if;
  if p_last_safe_depth > v_previous_depth + 1 then return jsonb_build_object('ok',false,'reason','unproven_depth_jump_rejected','previous_depth',v_previous_depth); end if;
  v_expiry := now() + make_interval(secs => p_lease_seconds);
  if v_reclaimed then
    insert into public.ig_target_followers_resume_checkpoint_events(
      checkpoint_id,account_id,target_id,run_id,event_type,mode,previous_optimistic_version,new_optimistic_version,
      previous_depth,new_depth,reason
    ) values (v_row.id,p_account_id,p_target_id,p_run_id,'reclaimed',p_mode,v_row.optimistic_version,v_row.optimistic_version,
      v_previous_depth,v_previous_depth,'lease_reclaimed_before_commit');
  end if;
  update public.ig_target_followers_resume_checkpoints c set
    last_safe_depth=case when p_mode='enforce' then p_last_safe_depth else c.last_safe_depth end,
    last_safe_anchor=case when p_mode='enforce' then p_last_safe_anchor else c.last_safe_anchor end,
    anchor_fingerprint=case when p_mode='enforce' then p_anchor_fingerprint else c.anchor_fingerprint end,
    last_visible_anchor_hashes=case when p_mode='enforce' then p_last_visible_anchor_hashes else c.last_visible_anchor_hashes end,
    shadow_last_safe_depth=case when p_mode='shadow' then p_last_safe_depth else c.shadow_last_safe_depth end,
    shadow_last_safe_anchor=case when p_mode='shadow' then p_last_safe_anchor else c.shadow_last_safe_anchor end,
    shadow_anchor_fingerprint=case when p_mode='shadow' then p_anchor_fingerprint else c.shadow_anchor_fingerprint end,
    shadow_visible_anchor_hashes=case when p_mode='shadow' then p_last_visible_anchor_hashes else c.shadow_visible_anchor_hashes end,
    last_run_id=p_run_id,last_reached_at=now(),last_verified_at=now(),last_instagram_version=p_last_instagram_version,
    status=p_status,end_reached=p_end_reached,invalidation_reason=null,
    lease_expires_at=v_expiry,lease_heartbeat_at=now(),
    lease_generation=case when v_reclaimed then c.lease_generation+1 else c.lease_generation end,
    optimistic_version=c.optimistic_version+1,updated_at=now()
  where c.id=v_row.id returning optimistic_version into v_new_version;
  insert into public.ig_target_followers_resume_checkpoint_events(
    checkpoint_id,account_id,target_id,run_id,event_type,mode,previous_optimistic_version,new_optimistic_version,
    previous_depth,new_depth,reason,metadata
  ) values (v_row.id,p_account_id,p_target_id,p_run_id,'committed',p_mode,v_row.optimistic_version,v_new_version,
    v_previous_depth,p_last_safe_depth,p_reason,jsonb_build_object('status',p_status,'end_reached',p_end_reached,
      'anchor_count',jsonb_array_length(p_last_visible_anchor_hashes),'lease_reclaimed',v_reclaimed));
  return jsonb_build_object('ok',true,'reason','committed','optimistic_version',v_new_version,
    'depth',p_last_safe_depth,'lease_expires_at',v_expiry,'lease_reclaimed',v_reclaimed);
end
$_$;




CREATE OR REPLACE FUNCTION "public"."complete_account_run_request"("p_request_id" "uuid", "p_worker_id" "text", "p_status" "text", "p_error_code" "text" DEFAULT NULL::"text", "p_error_message_safe" "text" DEFAULT NULL::"text") RETURNS "public"."account_run_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ declare v_worker_id text := left(regexp_replace(coalesce(nullif(trim(p_worker_id), ''), 'run-dispatcher'), '[^a-zA-Z0-9_.:-]', '_', 'g'), 160); v_status text := lower(coalesce(nullif(trim(p_status), ''), '')); v_row public.account_run_requests; begin if v_status not in ('completed', 'failed', 'blocked', 'canceled') then raise exception 'invalid_terminal_status' using errcode = '22023'; end if; update public.account_run_requests arr set status = v_status, completed_at = case when v_status in ('completed', 'failed', 'blocked') then now() else arr.completed_at end, canceled_at = case when v_status = 'canceled' then now() else arr.canceled_at end, error_code = nullif(trim(coalesce(p_error_code, '')), ''), error_message_safe = nullif(trim(coalesce(p_error_message_safe, '')), ''), lease_expires_at = null, updated_at = now() where arr.id = p_request_id and arr.claimed_by = v_worker_id and arr.status in ('claimed', 'starting', 'running') returning * into v_row; return v_row; end; $$;




CREATE OR REPLACE FUNCTION "public"."complete_dm_job"("p_job_id" "uuid", "p_final_status" "public"."dm_job_status", "p_skip_reason" "text" DEFAULT NULL::"text", "p_last_error" "text" DEFAULT NULL::"text", "p_increment_attempt" boolean DEFAULT false, "p_retry_delay_seconds" integer DEFAULT NULL::integer, "p_metadata_patch" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "public"."ig_dm_jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_job public.ig_dm_jobs;
  v_previous_job public.ig_dm_jobs;
  v_counter public.ig_account_dm_counters;
  v_counter_date date;
  v_should_increment boolean;
begin
  if p_final_status not in ('sent', 'skipped', 'failed', 'cancelled') then
    raise exception 'final_status must be sent, skipped, failed, or cancelled';
  end if;

  select *
  into v_previous_job
  from public.ig_dm_jobs
  where id = p_job_id
  for update;

  if not found then
    raise exception 'job not found: %', p_job_id;
  end if;

  update public.ig_dm_jobs
  set
    skip_reason = case when p_final_status = 'skipped' then p_skip_reason else skip_reason end,
    last_error = case when p_final_status in ('failed', 'skipped') then p_last_error else last_error end,
    attempts = case when p_increment_attempt then attempts + 1 else attempts end,
    next_retry_at = case
      when p_final_status = 'failed'
        and p_retry_delay_seconds is not null
        and attempts + case when p_increment_attempt then 1 else 0 end < max_attempts
        then now() + make_interval(secs => greatest(p_retry_delay_seconds, 0))
      else null
    end,
    status = case
      when p_final_status = 'failed'
        and p_retry_delay_seconds is not null
        and attempts + case when p_increment_attempt then 1 else 0 end < max_attempts
        then 'pending'::public.dm_job_status
      else p_final_status
    end,
    reserved_at = case
      when p_final_status = 'failed'
        and p_retry_delay_seconds is not null
        and attempts + case when p_increment_attempt then 1 else 0 end < max_attempts
        then null
      else reserved_at
    end,
    reserved_by = case
      when p_final_status = 'failed'
        and p_retry_delay_seconds is not null
        and attempts + case when p_increment_attempt then 1 else 0 end < max_attempts
        then null
      else reserved_by
    end,
    sent_at = case
      when p_final_status = 'sent' and status is distinct from 'sent'::public.dm_job_status then now()
      when p_final_status = 'sent' then coalesce(sent_at, now())
      else sent_at
    end,
    finished_at = case
      when p_final_status in ('sent', 'skipped', 'cancelled')
        then case
          when status is distinct from p_final_status then now()
          else coalesce(finished_at, now())
        end
      when p_final_status = 'failed'
        and (
          p_retry_delay_seconds is null
          or attempts + case when p_increment_attempt then 1 else 0 end >= max_attempts
        )
        then case
          when status is distinct from 'failed'::public.dm_job_status then now()
          else coalesce(finished_at, now())
        end
      else finished_at
    end,
    metadata = coalesce(metadata, '{}'::jsonb) || coalesce(p_metadata_patch, '{}'::jsonb),
    updated_at = now()
  where id = p_job_id
  returning * into v_job;

  if v_job.dm_type = 'welcome' then
    update public.ig_account_followers f
    set
      welcome_dm_status = case v_job.status
        when 'sent' then 'sent'::public.welcome_dm_status
        when 'skipped' then 'skipped'::public.welcome_dm_status
        when 'failed' then 'failed'::public.welcome_dm_status
        when 'pending' then f.welcome_dm_status
        else f.welcome_dm_status
      end,
      welcomed_at = case when v_job.status = 'sent' then coalesce(f.welcomed_at, now()) else f.welcomed_at end,
      skip_reason = case when v_job.status = 'skipped' then v_job.skip_reason else f.skip_reason end,
      last_error = case when v_job.status = 'failed' then v_job.last_error else f.last_error end,
      dm_thread_checked_at = coalesce(f.dm_thread_checked_at, now()),
      updated_at = now()
    where f.account_id = v_job.account_id
      and f.follower_username_normalized = v_job.recipient_username_normalized;
  end if;

  v_should_increment := v_job.status in ('sent', 'skipped', 'failed')
    and v_job.finished_at is not null
    and (
      v_previous_job.status is distinct from v_job.status
      or v_previous_job.finished_at is null
    );

  if v_should_increment then
    v_counter_date := (
      timezone(
        'Africa/Johannesburg',
        case when v_job.status = 'sent' then v_job.sent_at else v_job.finished_at end
      )
    )::date;
    v_counter := public.ensure_dm_counter_row(v_job.account_id, v_counter_date);

    update public.ig_account_dm_counters
    set
      welcome_sent_count = welcome_sent_count
        + case when v_job.dm_type = 'welcome' and v_job.status = 'sent' then 1 else 0 end,
      outreach_sent_count = outreach_sent_count
        + case when v_job.dm_type = 'outreach' and v_job.status = 'sent' then 1 else 0 end,
      total_dm_sent_count = total_dm_sent_count
        + case when v_job.status = 'sent' then 1 else 0 end,
      welcome_skipped_count = welcome_skipped_count
        + case when v_job.dm_type = 'welcome' and v_job.status = 'skipped' then 1 else 0 end,
      outreach_skipped_count = outreach_skipped_count
        + case when v_job.dm_type = 'outreach' and v_job.status = 'skipped' then 1 else 0 end,
      failed_count = failed_count
        + case when v_job.status = 'failed' then 1 else 0 end,
      updated_at = now()
    where id = v_counter.id;
  end if;

  return v_job;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."complete_scheduled_session_preflight"("p_preflight_id" "uuid", "p_status" "text", "p_reason_code" "text" DEFAULT NULL::"text", "p_checked_at" timestamp with time zone DEFAULT "now"(), "p_metadata_safe" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "public"."scheduled_session_preflights"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ declare v_row public.scheduled_session_preflights%rowtype; begin if p_status not in ('preflight_ready','preflight_blocked','preflight_expired','preflight_invalidated','preflight_lease_unavailable') then raise exception 'invalid_preflight_terminal_status'; end if; update public.scheduled_session_preflights set status = p_status, reason_code = p_reason_code, checked_at = coalesce(p_checked_at, now()), metadata_safe = metadata_safe || coalesce(p_metadata_safe, '{}'::jsonb), updated_at = now() where id = p_preflight_id and status in ('preflight_due', 'preflight_running') returning * into v_row; if not found then raise exception 'preflight_not_completable'; end if; return v_row; end; $$;




CREATE OR REPLACE FUNCTION "public"."consume_account_verification_code_for_worker"("p_action_id" "uuid" DEFAULT NULL::"uuid", "p_account_id" "uuid" DEFAULT NULL::"uuid", "p_run_id" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'vault'
    AS $$
declare
  v_metadata jsonb := coalesce(p_metadata, '{}'::jsonb);
  v_submission public.account_verification_code_submissions%rowtype;
  v_secret_id_text text;
  v_secret_id uuid;
  v_secret_value text;
  v_payload jsonb;
  v_code text;
  v_now timestamptz := now();
begin
  if auth.role() <> 'service_role' then
    raise exception 'service_role_required';
  end if;

  if p_action_id is null and p_account_id is null then
    raise exception 'action_id_or_account_id_required';
  end if;

  if jsonb_typeof(v_metadata) is distinct from 'object'
     or public.jsonb_has_forbidden_safe_metadata_key(v_metadata) then
    raise exception 'metadata_forbidden';
  end if;

  select avcs.*
    into v_submission
  from public.account_verification_code_submissions as avcs
  where avcs.status in ('code_submitted', 'ready_for_resume')
    and avcs.expires_at > v_now
    and (p_action_id is null or avcs.action_id = p_action_id)
    and (p_account_id is null or avcs.account_id = p_account_id)
  order by avcs.updated_at desc
  for update skip locked
  limit 1;

  if v_submission.id is null then
    return jsonb_build_object(
      'ok', false,
      'reason', 'verification_code_not_available',
      'action_id', p_action_id,
      'account_id', p_account_id
    );
  end if;

  if v_submission.attempts_count >= v_submission.max_attempts then
    update public.account_verification_code_submissions
    set status = 'failed', updated_at = v_now
    where id = v_submission.id;
    return jsonb_build_object(
      'ok', false,
      'reason', 'verification_code_attempts_exhausted',
      'action_id', v_submission.action_id,
      'account_id', v_submission.account_id
    );
  end if;

  if coalesce(v_submission.secret_ref, '') = '' then
    return jsonb_build_object(
      'ok', false,
      'reason', 'verification_code_secret_missing',
      'action_id', v_submission.action_id,
      'account_id', v_submission.account_id
    );
  end if;

  v_secret_id_text := btrim(substr(v_submission.secret_ref, length('supabase_vault://') + 1));
  v_secret_id := v_secret_id_text::uuid;

  select ds.decrypted_secret
    into v_secret_value
  from vault.decrypted_secrets ds
  where ds.id = v_secret_id
  limit 1;

  if coalesce(v_secret_value, '') = '' then
    return jsonb_build_object(
      'ok', false,
      'reason', 'verification_code_secret_empty',
      'action_id', v_submission.action_id,
      'account_id', v_submission.account_id
    );
  end if;

  begin
    v_payload := v_secret_value::jsonb;
    v_code := btrim(coalesce(v_payload ->> 'verification_code', ''));
  exception
    when others then
      v_code := btrim(v_secret_value);
  end;

  if v_code = '' then
    return jsonb_build_object(
      'ok', false,
      'reason', 'verification_code_payload_invalid',
      'action_id', v_submission.action_id,
      'account_id', v_submission.account_id
    );
  end if;

  perform public.neutralize_ephemeral_verification_code_vault_secret(v_submission.secret_ref);

  update public.account_verification_code_submissions
  set
    updated_at = v_now,
    status = 'consumed',
    consumed_at = v_now,
    consumed_run_id = nullif(trim(coalesce(p_run_id, '')), ''),
    secret_ref = null,
    metadata_safe = coalesce(metadata_safe, '{}'::jsonb) || v_metadata
  where id = v_submission.id;

  return jsonb_build_object(
    'ok', true,
    'reason', 'consumed',
    'action_id', v_submission.action_id,
    'account_id', v_submission.account_id,
    'submission_id', v_submission.id,
    'verification_code', v_code
  );
end;
$$;




COMMENT ON FUNCTION "public"."consume_account_verification_code_for_worker"("p_action_id" "uuid", "p_account_id" "uuid", "p_run_id" "text", "p_metadata" "jsonb") IS 'Service-role-only RPC that reads and neutralizes one ephemeral verification code for worker resume. Callers must never log the response.';



CREATE TABLE IF NOT EXISTS "public"."client_provisioning_slot_reservations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "client_id" "uuid" NOT NULL,
    "client_instagram_account_id" "uuid" NOT NULL,
    "ig_account_id" "uuid" NOT NULL,
    "assignment_id" "uuid" NOT NULL,
    "device_id" "uuid" NOT NULL,
    "app_instance_id" "uuid" NOT NULL,
    "expected_package" "text" DEFAULT ''::"text" NOT NULL,
    "window_start_utc" timestamp with time zone NOT NULL,
    "window_end_utc" timestamp with time zone NOT NULL,
    "expires_at" timestamp with time zone NOT NULL,
    "status" "text" DEFAULT 'reserved'::"text" NOT NULL,
    "reservation_source" "text" DEFAULT 'client_connect'::"text" NOT NULL,
    "assisted_connect_requested_at" timestamp with time zone,
    "dedupe_key" "text" NOT NULL,
    "safe_metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    CONSTRAINT "client_provisioning_slot_reservations_dedupe_nonempty" CHECK (("char_length"(TRIM(BOTH FROM "dedupe_key")) > 0)),
    CONSTRAINT "client_provisioning_slot_reservations_expires_check" CHECK (("expires_at" >= "window_end_utc")),
    CONSTRAINT "client_provisioning_slot_reservations_metadata_object_check" CHECK (("jsonb_typeof"("safe_metadata") = 'object'::"text")),
    CONSTRAINT "client_provisioning_slot_reservations_status_check" CHECK (("status" = ANY (ARRAY['reserved'::"text", 'window_open'::"text", 'assisted_requested'::"text", 'consumed'::"text", 'expired'::"text", 'cancelled'::"text", 'invalidated'::"text"]))),
    CONSTRAINT "client_provisioning_slot_reservations_window_order_check" CHECK (("window_end_utc" > "window_start_utc"))
);




CREATE OR REPLACE FUNCTION "public"."consume_client_provisioning_slot_reservation"("p_reservation_id" "uuid", "p_ig_account_id" "uuid") RETURNS "public"."client_provisioning_slot_reservations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ declare v_row public.client_provisioning_slot_reservations; begin update public.client_provisioning_slot_reservations set status = 'consumed', updated_at = now() where id = p_reservation_id and ig_account_id = p_ig_account_id and status in ('reserved', 'window_open', 'assisted_requested') returning * into v_row; if not found then raise exception 'provisioning_slot_reservation_not_consumable' using errcode = 'P0001'; end if; return v_row; end; $$;




CREATE OR REPLACE FUNCTION "public"."consume_resume_authorization_and_create_request_v2"("p_authorization_id" "uuid", "p_worker_id" "text", "p_device_id" "uuid", "p_metadata_safe" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_auth public.incident_resume_authorizations%rowtype;
  v_incident public.account_incidents%rowtype;
  v_plan public.account_session_resume_plans%rowtype;
  v_request public.account_run_requests%rowtype;
  v_plan_error text;
begin
  select * into v_auth
  from public.incident_resume_authorizations
  where id = p_authorization_id
  for update;

  if v_auth.id is null then
    raise exception 'resume_authorization_missing' using errcode = '22023';
  end if;
  if v_auth.status = 'consumed' and v_auth.consumed_by_request_id is not null then
    return jsonb_build_object(
      'request_id', v_auth.consumed_by_request_id,
      'authorization_id', v_auth.id,
      'idempotent', true
    );
  end if;
  if v_auth.status <> 'armed' then
    raise exception 'resume_authorization_consumed' using errcode = '40001';
  end if;
  if v_auth.test then
    raise exception 'test_authorization_excluded' using errcode = '22023';
  end if;
  if v_auth.scheduled_window_start is null or v_auth.scheduled_window_end is null
     or not (v_auth.scheduled_window_start <= now() and now() < v_auth.scheduled_window_end) then
    raise exception 'resume_authorization_expired' using errcode = '22023';
  end if;

  select * into v_incident from public.account_incidents
  where id = v_auth.incident_id and account_id = v_auth.account_id
  for share;
  if v_incident.id is null or v_incident.status <> 'resolved' then
    raise exception 'resume_incident_not_resolved' using errcode = '22023';
  end if;

  select * into v_plan from public.account_session_resume_plans
  where id = v_auth.resume_plan_id
    and account_id = v_auth.account_id
    and run_id = v_auth.run_id
  for update;
  if v_plan.id is null
     or v_plan.resume_state <> 'awaiting_human_resume_authorization' then
    raise exception 'resume_plan_not_recoverable' using errcode = '22023';
  end if;

  if p_metadata_safe ->> 'incident_id' <> v_auth.incident_id::text
     or p_metadata_safe ->> 'authorization_id' <> v_auth.id::text
     or p_metadata_safe -> 'resume_plan' ->> 'account_id' <> v_auth.account_id::text then
    raise exception 'resume_phase_plan_identity_mismatch' using errcode = '22023';
  end if;
  v_plan_error := public.auto_restart_phase_plan_v2_error(p_metadata_safe -> 'resume_plan');
  if v_plan_error is not null then
    raise exception '%', v_plan_error using errcode = '22023';
  end if;

  if p_device_id is not null and not exists (
    select 1 from public.auto_restart_device_locks l
    where l.device_id = p_device_id
      and l.account_id = v_auth.account_id
      and l.worker_id = p_worker_id
      and l.lease_expires_at > now()
    for update
  ) then
    raise exception 'resume_device_lock_missing' using errcode = '40001';
  end if;

  update public.incident_resume_authorizations
  set status = 'consumed', consumed_at = now(), consume_error = null,
      frozen_phase_plan = p_metadata_safe -> 'resume_plan', updated_at = now()
  where id = v_auth.id;

  v_request := public.create_account_run_request(
    p_account_id => v_auth.account_id,
    p_requested_by => null,
    p_actor_type => 'system',
    p_source_surface => 'auto_restart_tick',
    p_requested_run_type => 'account_session',
    p_idempotency_key => 'resume-auth:' || v_auth.id::text || ':g' || v_auth.retry_generation::text,
    p_priority => 0,
    p_metadata_safe => p_metadata_safe
  );

  update public.incident_resume_authorizations
  set consumed_by_request_id = v_request.id, updated_at = now()
  where id = v_auth.id;

  update public.account_session_resume_plans
  set resume_state = 'resume_requested', plan = coalesce(plan, '{}'::jsonb) || jsonb_build_object(
        'frozen_phase_plan', p_metadata_safe -> 'resume_plan',
        'resume_request_id', v_request.id,
        'retry_generation', v_auth.retry_generation
      ), last_updated_at = now()
  where id = v_plan.id;

  update public.account_incidents
  set metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
        'recovery', coalesce(metadata -> 'recovery', '{}'::jsonb) || jsonb_build_object(
          'state', 'resume_requested', 'resume_request_id', v_request.id,
          'authorization_id', v_auth.id, 'retry_generation', v_auth.retry_generation,
          'updated_at', now()
        )
      ), updated_at = now()
  where id = v_incident.id;

  if p_device_id is not null then
    update public.auto_restart_device_locks
    set request_id = v_request.id, updated_at = now()
    where device_id = p_device_id and worker_id = p_worker_id;
  end if;

  return jsonb_build_object(
    'request_id', v_request.id,
    'authorization_id', v_auth.id,
    'retry_generation', v_auth.retry_generation,
    'idempotent', false
  );
end
$$;




CREATE OR REPLACE FUNCTION "public"."consume_resume_authorization_and_create_request_v3"("p_authorization_id" "uuid", "p_worker_id" "text", "p_device_id" "uuid", "p_metadata_safe" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_auth public.incident_resume_authorizations%rowtype;
  v_incident public.account_incidents%rowtype;
  v_hold public.instagram_account_restriction_holds%rowtype;
  v_plan jsonb := p_metadata_safe -> 'resume_plan';
begin
  if coalesce(auth.jwt() ->> 'role', '') <> 'service_role' then
    raise exception 'service_role_required' using errcode = '42501';
  end if;

  select * into v_auth
  from public.incident_resume_authorizations
  where id = p_authorization_id
  for update;
  if v_auth.id is null then
    raise exception 'resume_authorization_missing' using errcode = '22023';
  end if;

  if coalesce((v_plan ->> 'restriction_preflight_only')::boolean, false) then
    select * into v_incident
    from public.account_incidents
    where id = v_auth.incident_id and account_id = v_auth.account_id
    for share;
    if v_incident.id is null
       or v_incident.status <> 'resolved'
       or v_incident.incident_type <> 'instagram_account_restriction' then
      raise exception 'restriction_preflight_not_authorized' using errcode = '22023';
    end if;
    if p_metadata_safe ->> 'restriction_preflight_only' <> 'true'
       or v_plan ->> 'incident_id' <> v_auth.incident_id::text
       or v_plan ->> 'authorization_id' <> v_auth.id::text
       or public.auto_restart_phase_plan_v2_error(v_plan) is not null then
      raise exception 'restriction_preflight_contract_invalid' using errcode = '22023';
    end if;

    select * into v_hold
    from public.instagram_account_restriction_holds
    where account_id = v_auth.account_id
      and incident_id = v_auth.incident_id
      and status = 'verification_required'
    for update;
    if v_hold.id is null then
      raise exception 'restriction_preflight_not_authorized' using errcode = '22023';
    end if;
  end if;

  return public.consume_resume_authorization_and_create_request_v2(
    p_authorization_id,
    p_worker_id,
    p_device_id,
    p_metadata_safe
  );
end
$$;




COMMENT ON FUNCTION "public"."consume_resume_authorization_and_create_request_v3"("p_authorization_id" "uuid", "p_worker_id" "text", "p_device_id" "uuid", "p_metadata_safe" "jsonb") IS 'Atomically validates a normal human resume or one strict zero-business-action Instagram restriction preflight before request creation.';



CREATE OR REPLACE FUNCTION "public"."create_account_run_request"("p_account_id" "uuid", "p_requested_by" "uuid" DEFAULT NULL::"uuid", "p_actor_type" "text" DEFAULT 'admin'::"text", "p_source_surface" "text" DEFAULT 'instagram_dashboard'::"text", "p_requested_run_type" "text" DEFAULT 'account_session'::"text", "p_idempotency_key" "text" DEFAULT NULL::"text", "p_priority" integer DEFAULT 0, "p_metadata_safe" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "public"."account_run_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_actor_type text := lower(coalesce(nullif(trim(p_actor_type), ''), 'admin'));
  v_source_surface text := coalesce(nullif(trim(p_source_surface), ''), 'instagram_dashboard');
  v_requested_run_type text := lower(coalesce(nullif(trim(p_requested_run_type), ''), 'account_session'));
  v_idempotency_key text := coalesce(
    nullif(trim(p_idempotency_key), ''),
    'dashboard:' || p_account_id::text || ':' || gen_random_uuid()::text
  );
  v_metadata jsonb := coalesce(p_metadata_safe, '{}'::jsonb);
  v_existing public.account_run_requests;
  v_row public.account_run_requests;
  v_assignment public.account_assignments;
  v_app_instance public.phone_app_instances;
  v_parent_binding jsonb;
  v_resume_action_id text;
  v_parent_request_id text;
  v_scheduler_enabled boolean;
begin
  if p_account_id is null then
    raise exception 'account_id_required' using errcode = '22023';
  end if;

  if v_actor_type not in ('admin', 'assistant', 'ops', 'system', 'internal', 'client') then
    raise exception 'invalid_actor_type' using errcode = '22023';
  end if;

  if not public.run_control_metadata_is_safe(v_metadata) then
    raise exception 'metadata_forbidden_key' using errcode = '22023';
  end if;

  if v_requested_run_type = 'login_email_code_resume' then
    v_resume_action_id := coalesce(
      nullif(trim(v_metadata ->> 'action_id'), ''),
      nullif(trim(v_metadata ->> 'verification_action_id'), '')
    );
    if v_resume_action_id is null then
      raise exception 'login_resume_action_id_required' using errcode = '22023';
    end if;
  end if;

  select *
    into v_existing
  from public.account_run_requests arr
  where arr.idempotency_key = v_idempotency_key
  limit 1;

  if found then
    return v_existing;
  end if;

  if v_source_surface in ('auto_restart_tick', 'instagram_schedule_session_cron') then
    select s.auto_restart_enabled
      into v_scheduler_enabled
    from public.auto_restart_settings s
    where s.id = 'global'
    for share;

    if not coalesce(v_scheduler_enabled, false) then
      raise exception 'scheduler_disabled' using errcode = '22023';
    end if;
  end if;

  if v_requested_run_type in ('login_provisioning', 'login_email_code_resume') then
    select aa.*
      into v_assignment
    from public.account_assignments aa
    where aa.account_id = p_account_id
      and aa.status in ('reserved', 'active')
    order by aa.created_at desc
    limit 1
    for share;

    if v_assignment.id is null then
      raise exception 'login_assignment_binding_missing' using errcode = '22023';
    end if;
    if v_assignment.app_instance_id is null then
      raise exception 'login_app_instance_binding_missing' using errcode = '22023';
    end if;

    select pai.*
      into v_app_instance
    from public.phone_app_instances pai
    where pai.id = v_assignment.app_instance_id
    for share;

    if v_app_instance.id is null then
      raise exception 'login_app_instance_binding_missing' using errcode = '22023';
    end if;
    if v_app_instance.device_id <> v_assignment.device_id then
      raise exception 'login_app_instance_device_mismatch' using errcode = '22023';
    end if;
    if nullif(trim(v_app_instance.package_name), '') is null
       or v_app_instance.package_name !~ '^[A-Za-z0-9_.]+$' then
      raise exception 'login_package_binding_missing' using errcode = '22023';
    end if;
    if not v_app_instance.is_launchable
       or not v_app_instance.usable_for_auto_login
       or v_app_instance.status not in ('available', 'active', 'occupied', 'reserved') then
      raise exception 'login_app_instance_unavailable' using errcode = '22023';
    end if;
    if v_app_instance.current_account_id is not null
       and v_app_instance.current_account_id <> p_account_id then
      raise exception 'login_app_instance_account_mismatch' using errcode = '22023';
    end if;

    -- Reject caller-provided routing that disagrees with the canonical rows.
    if nullif(trim(v_metadata ->> 'assignment_id'), '') is not null
       and v_metadata ->> 'assignment_id' <> v_assignment.id::text then
      raise exception 'login_assignment_binding_mismatch' using errcode = '22023';
    end if;
    if nullif(trim(v_metadata ->> 'device_id'), '') is not null
       and v_metadata ->> 'device_id' <> v_assignment.device_id::text then
      raise exception 'login_device_binding_mismatch' using errcode = '22023';
    end if;
    if nullif(trim(v_metadata ->> 'app_instance_id'), '') is not null
       and v_metadata ->> 'app_instance_id' <> v_app_instance.id::text then
      raise exception 'login_app_instance_binding_mismatch' using errcode = '22023';
    end if;
    if nullif(trim(v_metadata ->> 'package_name'), '') is not null
       and v_metadata ->> 'package_name' <> v_app_instance.package_name then
      raise exception 'login_package_binding_mismatch' using errcode = '22023';
    end if;
    if v_metadata ? 'clone_index' then
      if coalesce(v_metadata ->> 'clone_index', '') !~ '^[0-9]+$'
         or (v_metadata ->> 'clone_index')::integer <> v_app_instance.instance_index then
        raise exception 'login_clone_index_binding_mismatch' using errcode = '22023';
      end if;
    end if;

    v_metadata := v_metadata || jsonb_build_object(
      'binding_version', 'auto_login_app_instance_v1',
      'assignment_id', v_assignment.id,
      'device_id', v_assignment.device_id,
      'app_instance_id', v_app_instance.id,
      'package_name', v_app_instance.package_name,
      'clone_index', v_app_instance.instance_index
    );

    -- A verification-code resume must remain on the exact parent binding.
    if v_requested_run_type = 'login_email_code_resume' then
      v_parent_request_id := nullif(trim(v_metadata ->> 'parent_request_id'), '');
      if v_parent_request_id is not null then
        select arr.metadata_safe
          into v_parent_binding
        from public.account_run_requests arr
        where arr.id::text = v_parent_request_id
          and arr.account_id = p_account_id
          and arr.requested_run_type = 'login_provisioning'
        limit 1;

        if v_parent_binding is null
           or v_parent_binding ->> 'binding_version' <> 'auto_login_app_instance_v1'
           or nullif(trim(v_parent_binding ->> 'assignment_id'), '') is null
           or nullif(trim(v_parent_binding ->> 'device_id'), '') is null
           or nullif(trim(v_parent_binding ->> 'app_instance_id'), '') is null
           or nullif(trim(v_parent_binding ->> 'package_name'), '') is null
           or not (v_parent_binding ? 'clone_index') then
          raise exception 'login_parent_binding_missing' using errcode = '22023';
        end if;
        if v_parent_binding ->> 'assignment_id' <> v_metadata ->> 'assignment_id'
           or v_parent_binding ->> 'device_id' <> v_metadata ->> 'device_id'
           or v_parent_binding ->> 'app_instance_id' <> v_metadata ->> 'app_instance_id'
           or v_parent_binding ->> 'package_name' <> v_metadata ->> 'package_name'
           or (v_parent_binding ->> 'clone_index')::integer <> (v_metadata ->> 'clone_index')::integer then
          raise exception 'login_parent_binding_changed' using errcode = '22023';
        end if;
      end if;
    end if;
  end if;

  if v_requested_run_type not in ('login_provisioning', 'login_email_code_resume')
     and public.account_has_active_ig_run(p_account_id) then
    raise exception 'account_already_running' using errcode = '22023';
  end if;

  if exists (
    select 1
    from public.account_run_requests arr
    where arr.account_id = p_account_id
      and arr.status in ('queued', 'claimed', 'starting', 'running')
  ) then
    raise exception 'account_run_already_requested' using errcode = '22023';
  end if;

  insert into public.account_run_requests (
    account_id,
    requested_by,
    actor_type,
    source_surface,
    requested_run_type,
    status,
    priority,
    idempotency_key,
    metadata_safe
  )
  values (
    p_account_id,
    p_requested_by,
    v_actor_type,
    v_source_surface,
    v_requested_run_type,
    'queued',
    coalesce(p_priority, 0),
    v_idempotency_key,
    v_metadata
  )
  returning * into v_row;

  return v_row;
end;
$_$;




COMMENT ON FUNCTION "public"."create_account_run_request"("p_account_id" "uuid", "p_requested_by" "uuid", "p_actor_type" "text", "p_source_surface" "text", "p_requested_run_type" "text", "p_idempotency_key" "text", "p_priority" integer, "p_metadata_safe" "jsonb") IS 'Run Control enqueue RPC. actor_type client is audit-only for dashboard client Connect; execute remains service_role-only.';



CREATE OR REPLACE FUNCTION "public"."create_credential_dashboard_action"("p_account_id" "uuid", "p_action_type" "text" DEFAULT 'update_instagram_password'::"text", "p_safe_client_message" "text" DEFAULT NULL::"text", "p_admin_message" "text" DEFAULT NULL::"text", "p_action_deep_link" "text" DEFAULT NULL::"text", "p_severity" "text" DEFAULT 'warning'::"text", "p_requires_client_action" boolean DEFAULT true, "p_blocking_campaign" boolean DEFAULT false, "p_actor_type" "text" DEFAULT 'backend'::"text", "p_actor_id" "text" DEFAULT NULL::"text", "p_metadata_safe" "jsonb" DEFAULT '{}'::"jsonb") RETURNS TABLE("action_id" "uuid", "account_id" "uuid", "action_type" "text", "status" "text", "severity" "text", "requires_client_action" boolean, "blocking_campaign" boolean, "safe_client_message" "text", "action_deep_link" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_action_type text := lower(coalesce(nullif(trim(p_action_type), ''), 'update_instagram_password'));
  v_actor_type text := lower(coalesce(nullif(trim(p_actor_type), ''), 'backend'));
  v_metadata_safe jsonb := coalesce(p_metadata_safe, '{}'::jsonb);
  v_title text;
  v_label text;
  v_dedupe_key text;
  v_action public.account_dashboard_actions;
begin
  if auth.role() <> 'service_role' then
    raise exception 'service_role_required'
      using errcode = '42501';
  end if;

  if p_account_id is null then
    raise exception 'account_id_required'
      using errcode = '22023';
  end if;

  if v_action_type not in (
    'submit_instagram_credentials',
    'update_instagram_password',
    'complete_two_factor',
    'resolve_checkpoint',
    'review_login_failure',
    'review_account_mismatch',
    'review_credentials'
  ) then
    raise exception 'invalid_credential_action_type'
      using errcode = '22023';
  end if;

  if v_actor_type not in ('admin', 'client', 'system', 'migration', 'backend') then
    raise exception 'invalid_actor_type'
      using errcode = '22023';
  end if;

  if jsonb_typeof(v_metadata_safe) is distinct from 'object'
    or public.jsonb_has_forbidden_safe_metadata_key(v_metadata_safe)
  then
    raise exception 'metadata_safe_forbidden'
      using errcode = '22023';
  end if;

  v_title := case v_action_type
    when 'submit_instagram_credentials' then 'Submit Instagram credentials'
    when 'update_instagram_password' then 'Update Instagram password'
    when 'complete_two_factor' then 'Complete Instagram two-factor challenge'
    when 'resolve_checkpoint' then 'Resolve Instagram checkpoint'
    when 'review_login_failure' then 'Review Instagram login failure'
    when 'review_account_mismatch' then 'Review Instagram account mismatch'
    else 'Review Instagram credentials'
  end;

  v_label := case v_action_type
    when 'submit_instagram_credentials' then 'Submit credentials'
    when 'update_instagram_password' then 'Update password'
    when 'complete_two_factor' then 'Complete 2FA'
    when 'resolve_checkpoint' then 'Resolve checkpoint'
    else 'Review'
  end;

  v_dedupe_key := 'account:' || p_account_id::text || ':credential_action:' || v_action_type;

  v_action := public.upsert_account_dashboard_action(
    p_account_id := p_account_id,
    p_action_type := v_action_type,
    p_title := v_title,
    p_dedupe_key := v_dedupe_key,
    p_status := 'pending',
    p_severity := p_severity,
    p_audience := 'client',
    p_requires_client_action := p_requires_client_action,
    p_blocking_campaign := p_blocking_campaign,
    p_safe_client_message := p_safe_client_message,
    p_admin_message := p_admin_message,
    p_action_label := v_label,
    p_action_deep_link := p_action_deep_link,
    p_metadata := v_metadata_safe
  );

  update public.account_dashboard_actions ada
  set
    created_by_actor_type = v_actor_type,
    created_by_actor_id = nullif(trim(coalesce(p_actor_id, '')), ''),
    metadata_safe = v_metadata_safe
  where ada.id = v_action.id
  returning ada.* into v_action;

  return query
    select
      v_action.id,
      v_action.account_id,
      v_action.action_type,
      v_action.status,
      v_action.severity,
      v_action.requires_client_action,
      v_action.blocking_campaign,
      v_action.safe_client_message,
      v_action.action_deep_link,
      v_action.created_at,
      v_action.updated_at;
end;
$$;




COMMENT ON FUNCTION "public"."create_credential_dashboard_action"("p_account_id" "uuid", "p_action_type" "text", "p_safe_client_message" "text", "p_admin_message" "text", "p_action_deep_link" "text", "p_severity" "text", "p_requires_client_action" boolean, "p_blocking_campaign" boolean, "p_actor_type" "text", "p_actor_id" "text", "p_metadata_safe" "jsonb") IS 'Credential Secure Pipeline V1 service-role skeleton for safe credential-related dashboard actions. Does not create raw update links or tokens.';



CREATE OR REPLACE FUNCTION "public"."create_credential_update_request_metadata"("p_account_id" "uuid", "p_token_hash" "text", "p_expires_at" timestamp with time zone, "p_action_id" "uuid" DEFAULT NULL::"uuid", "p_created_by_actor_type" "text" DEFAULT 'backend'::"text", "p_created_by_actor_id" "text" DEFAULT NULL::"text", "p_delivery_status" "text" DEFAULT NULL::"text", "p_metadata_safe" "jsonb" DEFAULT '{}'::"jsonb") RETURNS TABLE("request_id" "uuid", "action_id" "uuid", "account_id" "uuid", "status" "text", "expires_at" timestamp with time zone, "created_at" timestamp with time zone)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor_type text := lower(coalesce(nullif(trim(p_created_by_actor_type), ''), 'backend'));
  v_token_hash text := nullif(trim(coalesce(p_token_hash, '')), '');
  v_metadata_safe jsonb := coalesce(p_metadata_safe, '{}'::jsonb);
  v_row public.credential_update_requests;
begin
  if auth.role() <> 'service_role' then
    raise exception 'service_role_required'
      using errcode = '42501';
  end if;

  if p_account_id is null then
    raise exception 'account_id_required'
      using errcode = '22023';
  end if;

  if v_token_hash is null or char_length(v_token_hash) < 32 then
    raise exception 'token_hash_required'
      using errcode = '22023';
  end if;

  if lower(v_token_hash) like 'bearer %' or lower(v_token_hash) like 'http%' then
    raise exception 'token_hash_must_not_be_raw_token'
      using errcode = '22023';
  end if;

  if p_expires_at is null or p_expires_at <= now() then
    raise exception 'expires_at_must_be_future'
      using errcode = '22023';
  end if;

  if v_actor_type not in ('admin', 'client', 'system', 'migration', 'backend') then
    raise exception 'invalid_actor_type'
      using errcode = '22023';
  end if;

  if jsonb_typeof(v_metadata_safe) is distinct from 'object'
    or public.jsonb_has_forbidden_safe_metadata_key(v_metadata_safe)
  then
    raise exception 'metadata_safe_forbidden'
      using errcode = '22023';
  end if;

  insert into public.credential_update_requests (
    action_id,
    account_id,
    token_hash,
    expires_at,
    status,
    created_by_actor_type,
    created_by_actor_id,
    delivery_status,
    metadata_safe
  )
  values (
    p_action_id,
    p_account_id,
    v_token_hash,
    p_expires_at,
    'pending',
    v_actor_type,
    nullif(trim(coalesce(p_created_by_actor_id, '')), ''),
    nullif(trim(coalesce(p_delivery_status, '')), ''),
    v_metadata_safe
  )
  returning * into v_row;

  return query
    select
      v_row.id,
      v_row.action_id,
      v_row.account_id,
      v_row.status,
      v_row.expires_at,
      v_row.created_at;
end;
$$;




COMMENT ON FUNCTION "public"."create_credential_update_request_metadata"("p_account_id" "uuid", "p_token_hash" "text", "p_expires_at" timestamp with time zone, "p_action_id" "uuid", "p_created_by_actor_type" "text", "p_created_by_actor_id" "text", "p_delivery_status" "text", "p_metadata_safe" "jsonb") IS 'Credential Secure Pipeline V1 service-role RPC for storing one-time credential update request metadata. Accepts token_hash only and never returns token_hash.';



CREATE OR REPLACE FUNCTION "public"."create_ephemeral_verification_code_vault_secret"("p_account_id" "uuid", "p_action_id" "uuid", "p_verification_code" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'vault'
    AS $_$
declare
  v_code text := btrim(coalesce(p_verification_code, ''));
  v_secret_id uuid;
  v_name text;
begin
  if auth.role() <> 'service_role' then
    raise exception 'service_role_required';
  end if;

  if p_account_id is null or p_action_id is null then
    raise exception 'account_id_and_action_id_required';
  end if;

  if v_code = '' or char_length(v_code) > 32 then
    raise exception 'verification_code_invalid';
  end if;

  if v_code !~ '^[A-Za-z0-9-]{4,32}$' then
    raise exception 'verification_code_format_invalid';
  end if;

  v_name := format(
    'phonefarm/instagram/%s/verification-code/%s/%s',
    p_account_id::text,
    p_action_id::text,
    encode(extensions.gen_random_bytes(6), 'hex')
  );

  v_secret_id := vault.create_secret(
    jsonb_build_object(
      'kind', 'instagram_email_verification_code',
      'account_id', p_account_id::text,
      'action_id', p_action_id::text,
      'verification_code', v_code
    )::text,
    v_name,
    'Ephemeral Instagram email verification code. Single-use, short TTL.'
  );

  return v_secret_id;
end;
$_$;




COMMENT ON FUNCTION "public"."create_ephemeral_verification_code_vault_secret"("p_account_id" "uuid", "p_action_id" "uuid", "p_verification_code" "text") IS 'Service-role-only helper that stores a short-lived Instagram email verification code in Vault. Uses schema-qualified pgcrypto randomness.';



CREATE OR REPLACE FUNCTION "public"."create_instagram_credentials_vault_secret"("p_secret_payload" "text", "p_secret_name" "text", "p_secret_description" "text") RETURNS "uuid"
    LANGUAGE "sql"
    SET "search_path" TO 'public', 'vault'
    AS $$
  select vault.create_secret(
    p_secret_payload,
    p_secret_name,
    coalesce(p_secret_description, '')
  );
$$;




COMMENT ON FUNCTION "public"."create_instagram_credentials_vault_secret"("p_secret_payload" "text", "p_secret_name" "text", "p_secret_description" "text") IS 'Entry 2D-2B service-role-only wrapper for creating a Supabase Vault secret from the credentials Edge Function.';



CREATE OR REPLACE FUNCTION "public"."create_schedule_session_pre_run_retry_v1"("p_account_id" "uuid", "p_assignment_id" "uuid", "p_window_starts_at" timestamp with time zone, "p_window_ends_at" timestamp with time zone, "p_base_idempotency_key" "text", "p_worker_id" "text", "p_device_timezone" "text" DEFAULT NULL::"text", "p_retry_limit" integer DEFAULT 1, "p_min_remaining_seconds" integer DEFAULT 600) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_now timestamptz := clock_timestamp();
  v_assignment public.account_assignments%rowtype;
  v_base public.account_run_requests%rowtype;
  v_retry public.account_run_requests%rowtype;
  v_contract jsonb;
  v_retry_count integer := 0;
  v_retry_ordinal integer;
  v_retry_limit integer := least(greatest(coalesce(p_retry_limit, 1), 1), 3);
  v_min_remaining integer := least(greatest(coalesce(p_min_remaining_seconds, 600), 60), 3600);
  v_retry_key text;
  v_decision_key text;
begin
  if p_account_id is null or p_assignment_id is null
     or p_window_starts_at is null or p_window_ends_at is null
     or nullif(trim(p_base_idempotency_key), '') is null then
    return jsonb_build_object('created', false, 'reason', 'scheduled_retry_not_needed');
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'schedule-session-retry-v1:' || p_assignment_id::text || ':' || p_window_starts_at::text, 0
  ));

  select * into v_assignment
  from public.account_assignments
  where id = p_assignment_id and account_id = p_account_id
    and status in ('reserved', 'active') and schedule_mode = 'scheduled'
    and assignment_type = 'full_cycle'
  for share;

  if v_assignment.id is null
     or v_assignment.starts_at is distinct from p_window_starts_at
     or v_assignment.ends_at is distinct from p_window_ends_at then
    return jsonb_build_object('created', false, 'reason', 'scheduled_retry_not_needed');
  end if;

  if v_now < p_window_starts_at
     or v_now >= p_window_ends_at
     or extract(epoch from (p_window_ends_at - v_now)) < v_min_remaining then
    v_decision_key := left(trim(p_base_idempotency_key) || ':decision:window-closed', 240);
    insert into public.account_package_runtime_contract_events (
      account_id, assignment_id, event_type, source, idempotency_key, details_safe
    ) values (
      p_account_id, p_assignment_id, 'scheduled_retry_window_closed', 'schedule_session_cron', v_decision_key,
      jsonb_build_object('window_starts_at', p_window_starts_at, 'window_ends_at', p_window_ends_at, 'minimum_remaining_seconds', v_min_remaining)
    ) on conflict (idempotency_key) where idempotency_key is not null do nothing;
    return jsonb_build_object('created', false, 'reason', 'scheduled_retry_window_closed');
  end if;

  select * into v_base
  from public.account_run_requests
  where account_id = p_account_id
    and idempotency_key = trim(p_base_idempotency_key)
    and source_surface = 'instagram_schedule_session_cron'
    and requested_run_type = 'account_session'
  for share;

  if v_base.id is null
     or v_base.status <> 'blocked'
     or v_base.error_code not in ('package_settings_incomplete', 'runtime_contract_not_ready')
     or v_base.run_id is not null then
    return jsonb_build_object('created', false, 'reason', 'scheduled_retry_not_needed');
  end if;

  insert into public.account_package_runtime_contract_events (
    account_id, assignment_id, request_id, event_type, source, idempotency_key, details_safe
  ) values (
    p_account_id, p_assignment_id, v_base.id, 'retryable_pre_run_block', 'schedule_session_cron',
    left(trim(p_base_idempotency_key) || ':decision:retryable', 240),
    jsonb_build_object('blocked_reason', v_base.error_code, 'run_created', false)
  ) on conflict (idempotency_key) where idempotency_key is not null do nothing;

  v_contract := public.account_package_runtime_contract_status(p_account_id);
  if not coalesce((v_contract ->> 'ok')::boolean, false) then
    return jsonb_build_object('created', false, 'reason', 'package_runtime_contract_blocked', 'contract_reason', v_contract ->> 'reason');
  end if;

  select count(*)::integer into v_retry_count
  from public.account_run_requests r
  where r.account_id = p_account_id
    and r.source_surface = 'instagram_schedule_session_cron'
    and r.metadata_safe ->> 'retry_of_request_id' = v_base.id::text;

  if v_retry_count >= v_retry_limit then
    insert into public.account_package_runtime_contract_events (
      account_id, assignment_id, request_id, event_type, source, idempotency_key, details_safe
    ) values (
      p_account_id, p_assignment_id, v_base.id, 'scheduled_retry_limit_reached', 'schedule_session_cron',
      left(trim(p_base_idempotency_key) || ':decision:limit:' || v_retry_limit::text, 240),
      jsonb_build_object('retry_count', v_retry_count, 'retry_limit', v_retry_limit)
    ) on conflict (idempotency_key) where idempotency_key is not null do nothing;
    return jsonb_build_object('created', false, 'reason', 'scheduled_retry_limit_reached', 'retry_count', v_retry_count, 'retry_limit', v_retry_limit);
  end if;

  if public.account_has_active_ig_run(p_account_id)
     or exists (select 1 from public.account_run_requests r where r.account_id = p_account_id and r.status in ('queued','claimed','starting','running'))
     or exists (select 1 from public.auto_restart_device_locks l where l.device_id = v_assignment.device_id and l.lease_expires_at > v_now)
     or exists (select 1 from public.ig_account_settings s where s.account_id = p_account_id and coalesce(s.manual_stop_requested, false)) then
    return jsonb_build_object('created', false, 'reason', 'scheduled_retry_not_needed');
  end if;

  v_retry_ordinal := v_retry_count + 1;
  v_retry_key := left(trim(p_base_idempotency_key) || ':retry:v1:' || v_retry_ordinal::text, 240);

  v_retry := public.create_account_run_request(
    p_account_id => p_account_id,
    p_requested_by => null,
    p_actor_type => 'system',
    p_source_surface => 'instagram_schedule_session_cron',
    p_requested_run_type => 'account_session',
    p_idempotency_key => v_retry_key,
    p_priority => 0,
    p_metadata_safe => jsonb_build_object(
      'source', 'schedule_session_cron', 'trigger', 'scheduler',
      'assignment_id', p_assignment_id, 'worker_id', coalesce(nullif(trim(p_worker_id), ''), 'schedule_session_cron'),
      'scheduled_session_at', p_window_starts_at, 'scheduled_session_ends_at', p_window_ends_at,
      'device_timezone', p_device_timezone,
      'retry_of_request_id', v_base.id, 'retry_reason', v_base.error_code,
      'schedule_retry_version', 1, 'schedule_retry_ordinal', v_retry_ordinal,
      'package_runtime_contract_status', 'ready'
    )
  );

  insert into public.account_package_runtime_contract_events (
    account_id, assignment_id, request_id, event_type, source, idempotency_key, details_safe
  ) values (
    p_account_id, p_assignment_id, v_retry.id, 'scheduled_retry_created', 'schedule_session_cron',
    left(v_retry_key || ':decision:created', 240),
    jsonb_build_object('retry_of_request_id', v_base.id, 'retry_request_id', v_retry.id, 'retry_ordinal', v_retry_ordinal, 'retry_reason', v_base.error_code)
  ) on conflict (idempotency_key) where idempotency_key is not null do nothing;

  return jsonb_build_object(
    'created', true, 'reason', 'scheduled_retry_created',
    'request_id', v_retry.id, 'status', v_retry.status,
    'idempotency_key', v_retry.idempotency_key,
    'retry_of_request_id', v_base.id, 'retry_ordinal', v_retry_ordinal, 'retry_limit', v_retry_limit
  );
end;
$$;




CREATE OR REPLACE FUNCTION "public"."dm_job_idempotency_key_outreach"("p_account_id" "uuid", "p_recipient_username" "text", "p_campaign_id" "uuid" DEFAULT NULL::"uuid") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case
    when p_campaign_id is null then format(
      'outreach:%s:%s',
      p_account_id::text,
      public.normalize_ig_username(p_recipient_username)
    )
    else format(
      'outreach:%s:%s:%s',
      p_account_id::text,
      p_campaign_id::text,
      public.normalize_ig_username(p_recipient_username)
    )
  end;
$$;




CREATE OR REPLACE FUNCTION "public"."dm_job_idempotency_key_welcome"("p_account_id" "uuid", "p_recipient_username" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select format('welcome:%s:%s', p_account_id::text, public.normalize_ig_username(p_recipient_username));
$$;




CREATE OR REPLACE FUNCTION "public"."enforce_assignment_package_runtime_contract"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if coalesce(current_setting('bmb.package_contract_reconcile', true), '') = 'on' then
    return new;
  end if;
  if new.status in ('pending', 'reserved', 'active') then
    begin
      perform public.reconcile_account_package_runtime_contract(new.account_id, 'assignment_trigger');
    exception when others then
      insert into public.account_package_runtime_contract_events (
        account_id, assignment_id, event_type, source, details_safe
      ) values (
        new.account_id, new.id, 'package_runtime_contract_blocked', 'assignment_trigger',
        jsonb_build_object('reason', case when sqlerrm in ('package_settings_incomplete','assignment_package_mismatch','app_instance_package_mismatch','clone_package_mismatch','runtime_profile_mismatch') then sqlerrm else 'contract_reconcile_failed' end)
      );
    end;
  end if;
  return new;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."enforce_auto_restart_phase_plan_v2"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_error text;
begin
  if new.source_surface = 'auto_restart_tick'
     and new.requested_run_type = 'account_session' then
    v_error := public.auto_restart_phase_plan_v2_error(new.metadata_safe -> 'resume_plan');
    if v_error is not null then
      raise exception '%', v_error using errcode = '22023';
    end if;
  end if;
  return new;
end
$$;




CREATE OR REPLACE FUNCTION "public"."enqueue_ig_social_profile_snapshot_job_guarded"("p_account_id" "uuid", "p_username_normalized" "text", "p_snapshot_local_date" "date", "p_account_timezone" "text", "p_timezone_source" "text", "p_source_trigger" "text", "p_idempotency_key" "text", "p_source_event_id" "text" DEFAULT NULL::"text", "p_source_run_id" "uuid" DEFAULT NULL::"uuid", "p_source_business_session_id" "uuid" DEFAULT NULL::"uuid", "p_explicit_admin_refresh" boolean DEFAULT false, "p_dry_run" boolean DEFAULT false, "p_now" timestamp with time zone DEFAULT "now"()) RETURNS TABLE("classification" "text", "reason" "text", "job_id" "uuid", "job_status" "text", "created" boolean, "provider_calls_new_job_max" integer, "existing_retry_provider_calls_max" integer, "retry_due" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_username text := lower(trim(leading '@' from trim(coalesce(p_username_normalized, ''))));
  v_current_username text;
  v_lifecycle text;
  v_latest_success_at timestamptz;
  v_active public.ig_social_profile_snapshot_jobs%rowtype;
  v_terminal public.ig_social_profile_snapshot_jobs%rowtype;
  v_inserted public.ig_social_profile_snapshot_jobs%rowtype;
begin
  if p_now is null then
    raise exception 'social_profile_snapshot_guard_now_required';
  end if;
  if v_username !~ '^[a-z0-9._]{1,30}$' then
    return query select 'terminal_suppressed', 'invalid_username', null::uuid, null::text, false, 0, 0, false;
    return;
  end if;
  if p_snapshot_local_date is null
     or nullif(trim(p_account_timezone), '') is null
     or p_timezone_source not in ('device_assignment', 'schedule', 'platform_default')
     or p_source_trigger not in ('session_end', 'daily_fallback', 'admin_manual_refresh', 'baseline_one_shot')
     or nullif(trim(p_idempotency_key), '') is null then
    raise exception 'social_profile_snapshot_guard_invalid_request';
  end if;

  select lower(trim(leading '@' from trim(account.username))),
         lower(coalesce(nullif(account.admin_lifecycle_status, ''), account.status, ''))
    into v_current_username, v_lifecycle
    from public.ig_accounts account
   where account.id = p_account_id;
  if not found then
    return query select 'terminal_suppressed', 'account_not_found', null::uuid, null::text, false, 0, 0, false;
    return;
  end if;
  if v_lifecycle <> 'active' then
    return query select 'terminal_suppressed', 'lifecycle_not_active', null::uuid, null::text, false, 0, 0, false;
    return;
  end if;
  if v_current_username <> v_username then
    return query select 'terminal_suppressed', 'current_username_mismatch', null::uuid, null::text, false, 0, 0, false;
    return;
  end if;

  if not p_dry_run then
    perform pg_advisory_xact_lock(hashtextextended(p_account_id::text || ':' || v_username, 0));
  end if;

  select snapshot.observed_at
    into v_latest_success_at
    from public.ig_account_social_profile_snapshots snapshot
   where snapshot.account_id = p_account_id
     and snapshot.username_normalized = v_username
     and snapshot.lookup_status = 'found'
     and snapshot.source_trigger <> 'legacy_import'
   order by snapshot.observed_at desc
   limit 1;

  if not p_explicit_admin_refresh
     and v_latest_success_at is not null
     and v_latest_success_at >= p_now - interval '36 hours' then
    return query select 'skipped_fresh', 'modern_snapshot_within_36h', null::uuid, null::text, false, 0, 0, false;
    return;
  end if;

  select job.*
    into v_active
    from public.ig_social_profile_snapshot_jobs job
   where job.account_id = p_account_id
     and job.username_normalized = v_username
     and job.status in ('queued', 'processing')
   order by case when job.status = 'processing' then 0 else 1 end, job.created_at desc
   limit 1;
  if found then
    if v_active.attempts >= 3 then
      return query select 'terminal_suppressed', 'retry_exhausted_existing_job', v_active.id, v_active.status,
        false, 0, 0, false;
    elsif v_active.status = 'queued' and v_active.attempts > 0 and v_active.available_at > p_now then
      return query select 'retryable_backoff', 'existing_retry_backoff', v_active.id, v_active.status,
        false, 0, 0, false;
    else
      return query select 'existing_job_pending',
        case when v_active.status = 'processing' then 'existing_job_processing' else 'existing_job_due' end,
        v_active.id, v_active.status, false, 0,
        case when v_active.status = 'queued' and v_active.available_at <= p_now and v_active.attempts < 3 then 1 else 0 end,
        v_active.status = 'queued' and v_active.available_at <= p_now and v_active.attempts < 3;
    end if;
    return;
  end if;

  if p_explicit_admin_refresh and exists (
    select 1
      from public.ig_social_profile_snapshot_jobs job
     where job.account_id = p_account_id
       and job.username_normalized = v_username
       and job.source_trigger = 'admin_manual_refresh'
       and job.created_at >= p_now - interval '6 hours'
  ) then
    return query select 'terminal_suppressed', 'admin_refresh_cooldown', null::uuid, null::text, false, 0, 0, false;
    return;
  end if;

  if not p_explicit_admin_refresh then
    select job.*
      into v_terminal
      from public.ig_social_profile_snapshot_jobs job
     where job.account_id = p_account_id
       and job.username_normalized = v_username
       and job.status = 'failed'
       and (
         job.last_error_code in ('not_found', 'invalid_username', 'profile_unavailable')
         or job.last_error_code like 'retry_exhausted:%'
       )
     order by job.updated_at desc, job.created_at desc
     limit 1;
    if found and (v_latest_success_at is null or v_terminal.updated_at > v_latest_success_at) then
      return query select 'terminal_suppressed', 'latest_terminal_failure_for_current_username',
        v_terminal.id, v_terminal.status, false, 0, 0, false;
      return;
    end if;
  end if;

  if p_dry_run then
    return query select 'enqueue_allowed',
      case when p_explicit_admin_refresh then 'explicit_admin_refresh' else 'automatic_collection_due' end,
      null::uuid, null::text, false, 1, 0, false;
    return;
  end if;

  begin
    insert into public.ig_social_profile_snapshot_jobs (
      account_id, username_normalized, snapshot_local_date, account_timezone, timezone_source,
      source_trigger, source_event_id, source_run_id, source_business_session_id,
      idempotency_key, status
    ) values (
      p_account_id, v_username, p_snapshot_local_date, trim(p_account_timezone), p_timezone_source,
      p_source_trigger, nullif(trim(p_source_event_id), ''), p_source_run_id, p_source_business_session_id,
      trim(p_idempotency_key), 'queued'
    )
    on conflict (account_id, idempotency_key) do nothing
    returning * into v_inserted;
  exception when unique_violation then
    v_inserted.id := null;
  end;

  if v_inserted.id is not null then
    return query select 'enqueued', 'automatic_collection_due', v_inserted.id, v_inserted.status, true, 1, 0, false;
    return;
  end if;

  select job.*
    into v_active
    from public.ig_social_profile_snapshot_jobs job
   where job.account_id = p_account_id
     and job.username_normalized = v_username
     and job.status in ('queued', 'processing')
   order by job.created_at desc
   limit 1;
  return query select 'existing_job_pending', 'concurrent_or_idempotent_enqueue',
    v_active.id, v_active.status, false, 0,
    case when v_active.status = 'queued' and v_active.available_at <= p_now and v_active.attempts < 3 then 1 else 0 end,
    v_active.status = 'queued' and v_active.available_at <= p_now and v_active.attempts < 3;
end;
$_$;




COMMENT ON FUNCTION "public"."enqueue_ig_social_profile_snapshot_job_guarded"("p_account_id" "uuid", "p_username_normalized" "text", "p_snapshot_local_date" "date", "p_account_timezone" "text", "p_timezone_source" "text", "p_source_trigger" "text", "p_idempotency_key" "text", "p_source_event_id" "text", "p_source_run_id" "uuid", "p_source_business_session_id" "uuid", "p_explicit_admin_refresh" boolean, "p_dry_run" boolean, "p_now" timestamp with time zone) IS 'Atomically classifies and optionally enqueues one social profile snapshot job without provider access.';



CREATE OR REPLACE FUNCTION "public"."enqueue_outreach_dm_job"("p_account_id" "uuid", "p_recipient_username" "text", "p_message_body" "text" DEFAULT NULL::"text", "p_template_id" "uuid" DEFAULT NULL::"uuid", "p_source" "public"."dm_job_source" DEFAULT 'manual'::"public"."dm_job_source", "p_campaign_id" "uuid" DEFAULT NULL::"uuid", "p_priority" integer DEFAULT 0, "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "public"."ig_dm_jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_username text := trim(p_recipient_username);
  v_settings public.ig_account_dm_settings;
  v_job public.ig_dm_jobs;
  v_key text;
  v_body text;
begin
  if v_username is null or char_length(v_username) = 0 then
    raise exception 'recipient_username must be non-empty';
  end if;

  select * into v_settings
  from public.ig_account_dm_settings
  where account_id = p_account_id;

  if not found or v_settings.outreach_enabled is distinct from true then
    return null;
  end if;

  v_body := nullif(trim(coalesce(p_message_body, '')), '');
  if v_body is null and p_template_id is not null then
    select t.body into v_body
    from public.ig_dm_templates t
    where t.id = p_template_id and t.account_id = p_account_id and t.active = true;
  end if;

  if v_body is null and v_settings.default_outreach_template_id is not null then
    select t.body into v_body
    from public.ig_dm_templates t
    where t.id = v_settings.default_outreach_template_id and t.active = true;
  end if;

  if v_body is null or char_length(v_body) = 0 then
    raise exception 'no outreach message_body or template for account %', p_account_id;
  end if;

  v_key := public.dm_job_idempotency_key_outreach(p_account_id, v_username, p_campaign_id);

  insert into public.ig_dm_jobs (
    account_id,
    dm_type,
    recipient_username,
    message_body,
    template_id,
    source,
    campaign_id,
    priority,
    status,
    idempotency_key,
    metadata
  )
  values (
    p_account_id,
    'outreach',
    v_username,
    v_body,
    p_template_id,
    coalesce(p_source, 'manual'::public.dm_job_source),
    p_campaign_id,
    coalesce(p_priority, 0),
    'pending',
    v_key,
    coalesce(p_metadata, '{}'::jsonb)
  )
  on conflict (idempotency_key) do nothing
  returning * into v_job;

  if v_job.id is null then
    select * into v_job from public.ig_dm_jobs where idempotency_key = v_key;
  end if;

  return v_job;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."enqueue_welcome_dm_job_if_eligible"("p_account_id" "uuid", "p_follower_username" "text", "p_source_scan_run_id" "uuid" DEFAULT NULL::"uuid", "p_message_body" "text" DEFAULT NULL::"text", "p_template_id" "uuid" DEFAULT NULL::"uuid", "p_priority" integer DEFAULT 10) RETURNS "public"."ig_dm_jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_username text := trim(p_follower_username);
  v_follower public.ig_account_followers;
  v_settings public.ig_account_dm_settings;
  v_template public.ig_dm_templates;
  v_job public.ig_dm_jobs;
  v_key text;
  v_body text;
  v_template_id uuid;
begin
  if v_username is null or char_length(v_username) = 0 then
    raise exception 'follower_username must be non-empty';
  end if;

  select * into v_settings
  from public.ig_account_dm_settings
  where account_id = p_account_id;

  if not found or v_settings.welcome_enabled is distinct from true then
    return null;
  end if;

  if v_settings.welcome_baseline_completed_at is null then
    return null;
  end if;

  v_template_id := coalesce(p_template_id, v_settings.welcome_template_id);
  if v_template_id is null then
    raise exception 'canonical welcome template is required for account %', p_account_id;
  end if;

  select * into v_template
  from public.ig_dm_templates
  where id = v_template_id
    and account_id = p_account_id
    and template_type = 'welcome'
    and active = true;

  if not found then
    raise exception 'canonical welcome template % is not active for account %', v_template_id, p_account_id;
  end if;

  if v_settings.welcome_template_id is not null
     and v_template_id is distinct from v_settings.welcome_template_id then
    raise exception 'welcome template % does not match account settings', v_template_id;
  end if;

  v_body := nullif(trim(coalesce(p_message_body, '')), '');
  if v_body is null then
    raise exception 'canonical rendered welcome message is required for account %', p_account_id;
  end if;

  select * into v_follower
  from public.ig_account_followers
  where account_id = p_account_id
    and follower_username_normalized = public.normalize_ig_username(v_username);

  if not found then
    v_follower := public.upsert_account_follower_seen(
      p_account_id,
      v_username,
      p_source_scan_run_id,
      false
    );
  end if;

  if v_follower.baseline_existing
     or v_follower.welcome_dm_status in (
       'not_eligible_baseline', 'sent', 'reserved', 'skipped', 'failed'
     ) then
    return null;
  end if;

  v_key := public.dm_job_idempotency_key_welcome(p_account_id, v_username);

  select * into v_job
  from public.ig_dm_jobs
  where idempotency_key = v_key
  for update;

  if found then
    if v_job.status = 'cancelled'
       and v_job.skip_reason = 'cleanup_full_cycle_minimum_extra_welcome_jobs'
       and v_job.sent_at is null
       and coalesce(v_job.attempts, 0) = 0
       and v_job.reserved_at is null
       and v_job.started_at is null
       and v_follower.welcome_dm_status = 'pending' then
      update public.ig_dm_jobs
      set status = 'pending',
          message_body = v_body,
          template_id = v_template_id,
          skip_reason = null,
          next_retry_at = null,
          reserved_at = null,
          reserved_by = null,
          started_at = null,
          finished_at = null,
          last_error = null,
          metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
            'reactivated_at', now(),
            'reactivation_reason', 'safe_unverified_scan_overflow_job',
            'previous_status', v_job.status,
            'previous_skip_reason', v_job.skip_reason,
            'previous_template_id', v_job.template_id,
            'canonical_template_id', v_template_id,
            'canonical_template_updated_at', v_template.updated_at,
            'source_scan_run_id', p_source_scan_run_id
          ),
          updated_at = now()
      where id = v_job.id
      returning * into v_job;
      return v_job;
    end if;

    if v_job.status = 'pending'
       and v_job.sent_at is null
       and coalesce(v_job.attempts, 0) = 0
       and v_job.reserved_at is null
       and v_job.started_at is null
       and v_job.finished_at is null
       and v_follower.welcome_dm_status = 'pending' then
      update public.ig_dm_jobs
      set message_body = v_body,
          template_id = v_template_id,
          metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
            'canonical_template_refreshed_at', now(),
            'canonical_template_refresh_reason', 'safe_unattempted_idempotent_reuse',
            'previous_template_id', v_job.template_id,
            'canonical_template_id', v_template_id,
            'canonical_template_updated_at', v_template.updated_at,
            'source_scan_run_id', p_source_scan_run_id
          ),
          updated_at = now()
      where id = v_job.id
        and (
          message_body is distinct from v_body
          or template_id is distinct from v_template_id
        )
      returning * into v_job;

      if v_job.id is null then
        select * into v_job
        from public.ig_dm_jobs
        where idempotency_key = v_key;
      end if;
      return v_job;
    end if;

    if v_job.status in ('sent', 'skipped', 'failed', 'cancelled') then
      return null;
    end if;
    return v_job;
  end if;

  insert into public.ig_dm_jobs (
    account_id,
    dm_type,
    recipient_username,
    message_body,
    template_id,
    source,
    priority,
    status,
    idempotency_key,
    metadata
  )
  values (
    p_account_id,
    'welcome',
    v_username,
    v_body,
    v_template_id,
    'welcome_scan',
    coalesce(p_priority, 10),
    'pending',
    v_key,
    jsonb_build_object(
      'source_scan_run_id', p_source_scan_run_id,
      'follower_id', v_follower.id,
      'canonical_template_id', v_template_id,
      'canonical_template_updated_at', v_template.updated_at
    )
  )
  on conflict (idempotency_key) do nothing
  returning * into v_job;

  if v_job.id is null then
    return null;
  end if;

  update public.ig_account_followers
  set welcome_dm_status = 'pending',
      updated_at = now()
  where id = v_follower.id
    and welcome_dm_status not in ('sent', 'reserved');

  return v_job;
end;
$$;




COMMENT ON FUNCTION "public"."enqueue_welcome_dm_job_if_eligible"("p_account_id" "uuid", "p_follower_username" "text", "p_source_scan_run_id" "uuid", "p_message_body" "text", "p_template_id" "uuid", "p_priority" integer) IS 'Welcome producer enqueue. Reuses only safe unattempted rows after refreshing them from the current canonical account template.';



CREATE TABLE IF NOT EXISTS "public"."ig_account_dm_counters" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "account_id" "uuid" NOT NULL,
    "counter_date" "date" DEFAULT ("timezone"('Africa/Johannesburg'::"text", "now"()))::"date" NOT NULL,
    "welcome_sent_count" integer DEFAULT 0 NOT NULL,
    "outreach_sent_count" integer DEFAULT 0 NOT NULL,
    "total_dm_sent_count" integer DEFAULT 0 NOT NULL,
    "welcome_skipped_count" integer DEFAULT 0 NOT NULL,
    "outreach_skipped_count" integer DEFAULT 0 NOT NULL,
    "failed_count" integer DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "ig_account_dm_counters_counts_nonnegative" CHECK ((("welcome_sent_count" >= 0) AND ("outreach_sent_count" >= 0) AND ("total_dm_sent_count" >= 0) AND ("welcome_skipped_count" >= 0) AND ("outreach_skipped_count" >= 0) AND ("failed_count" >= 0)))
);




CREATE OR REPLACE FUNCTION "public"."ensure_dm_counter_row"("p_account_id" "uuid", "p_counter_date" "date" DEFAULT ("timezone"('Africa/Johannesburg'::"text", "now"()))::"date") RETURNS "public"."ig_account_dm_counters"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_row public.ig_account_dm_counters;
begin
  insert into public.ig_account_dm_counters (account_id, counter_date)
  values (p_account_id, p_counter_date)
  on conflict (account_id, counter_date) do nothing;

  select *
  into v_row
  from public.ig_account_dm_counters
  where account_id = p_account_id
    and counter_date = p_counter_date;

  return v_row;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."evaluate_account_schedule_gate"("p_account_id" "uuid", "p_requested_run_type" "text" DEFAULT NULL::"text", "p_trigger" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_account_id uuid := p_account_id;
  v_requested_run_type text := nullif(lower(trim(p_requested_run_type)), '');
  v_trigger text := coalesce(nullif(lower(trim(p_trigger)), ''), 'auto');
  v_manual_trigger boolean := coalesce(nullif(lower(trim(p_trigger)), ''), 'auto') in ('manual', 'user', 'admin', 'client');
  v_assignment record;
  v_device record;
  v_now timestamptz := now();
  v_window_active boolean := false;
  v_phone_rest_active boolean := false;
  v_outreach_rest_reserved boolean := false;
  v_next_slot timestamptz;
  v_reason text := null;
  v_ok boolean := true;
  v_technical_run_types text[] := array[
    'check_login',
    'login_check',
    'login_provisioning',
    'login_email_code_resume',
    'reconnect_instagram',
    'credential_verification',
    'provisioning_only',
    'account_status_check'
  ];
  v_growth_run_types text[] := array[
    'account_session',
    'follow_session',
    'unfollow_session',
    'dm_welcome_session_send',
    'outreach_session',
    'target_discovery_session'
  ];
begin
  if v_account_id is null then
    return jsonb_build_object('ok', false, 'reason', 'assignment_missing');
  end if;

  select
    aa.id,
    aa.device_id,
    aa.clone_id,
    aa.app_instance_id,
    aa.assignment_type,
    aa.slot_kind,
    aa.schedule_mode,
    aa.status,
    aa.starts_at,
    aa.ends_at,
    aa.assignment_source
  into v_assignment
  from public.account_assignments aa
  where aa.account_id = v_account_id
    and aa.status in ('pending', 'reserved', 'active')
  order by aa.created_at desc
  limit 1;

  if v_assignment.id is null then
    return jsonb_build_object(
      'ok', false,
      'reason', 'assignment_missing',
      'window_active', false,
      'phone_rest_active', false,
      'next_eligible_starts_at', null,
      'trigger', v_trigger
    );
  end if;

  select pd.id, pd.name, pd.status, pd.timezone, pd.pool_type
  into v_device
  from public.phone_devices pd
  where pd.id = v_assignment.device_id;

  if v_device.id is null or v_device.status not in ('available', 'active', 'online', 'occupied') then
    return jsonb_build_object(
      'ok', false,
      'reason', 'device_unavailable',
      'assignment_id', v_assignment.id,
      'app_instance_id', v_assignment.app_instance_id,
      'schedule_mode', v_assignment.schedule_mode,
      'window_active', false,
      'phone_rest_active', false,
      'next_eligible_starts_at', null,
      'trigger', v_trigger
    );
  end if;

  if v_requested_run_type = any(v_technical_run_types) then
    return jsonb_build_object(
      'ok', true,
      'reason', case
        when v_assignment.schedule_mode = 'manual_only' then 'technical_run_allowed_manual_only'
        else 'technical_run_allowed_outside_campaign_window'
      end,
      'assignment_id', v_assignment.id,
      'clone_id', v_assignment.clone_id,
      'app_instance_id', v_assignment.app_instance_id,
      'assignment_type', v_assignment.assignment_type,
      'slot_kind', v_assignment.slot_kind,
      'schedule_mode', v_assignment.schedule_mode,
      'starts_at', v_assignment.starts_at,
      'ends_at', v_assignment.ends_at,
      'assignment_source', v_assignment.assignment_source,
      'device_id', v_assignment.device_id,
      'device_label', v_device.name,
      'device_timezone', v_device.timezone,
      'window_active', false,
      'phone_rest_active', false,
      'next_eligible_starts_at', null,
      'trigger', v_trigger
    );
  end if;

  if v_assignment.schedule_mode = 'manual_only' then
    return jsonb_build_object(
      'ok', v_manual_trigger,
      'reason', case
        when v_manual_trigger then 'manual_start_allowed_manual_only'
        else 'manual_only_requires_manual_trigger'
      end,
      'assignment_id', v_assignment.id,
      'clone_id', v_assignment.clone_id,
      'app_instance_id', v_assignment.app_instance_id,
      'assignment_type', v_assignment.assignment_type,
      'slot_kind', v_assignment.slot_kind,
      'schedule_mode', v_assignment.schedule_mode,
      'starts_at', null,
      'ends_at', null,
      'assignment_source', v_assignment.assignment_source,
      'device_id', v_assignment.device_id,
      'device_label', v_device.name,
      'device_timezone', v_device.timezone,
      'window_active', false,
      'phone_rest_active', false,
      'next_eligible_starts_at', null,
      'trigger', v_trigger
    );
  end if;

  if v_requested_run_type = 'account_session' and v_assignment.assignment_type = 'outreach_only' then
    return jsonb_build_object(
      'ok', false,
      'reason', 'assignment_profile_mismatch',
      'assignment_id', v_assignment.id,
      'app_instance_id', v_assignment.app_instance_id,
      'schedule_mode', v_assignment.schedule_mode,
      'window_active', false,
      'phone_rest_active', false,
      'next_eligible_starts_at', null,
      'trigger', v_trigger
    );
  end if;

  if exists (
    select 1
    from public.account_assignments aa
    where aa.device_id = v_assignment.device_id
      and aa.account_id <> v_account_id
      and aa.id <> v_assignment.id
      and aa.status in ('pending', 'reserved', 'active')
      and aa.schedule_mode = 'scheduled'
      and tstzrange(aa.starts_at, aa.ends_at, '[)') && tstzrange(v_assignment.starts_at, v_assignment.ends_at, '[)')
  ) then
    return jsonb_build_object(
      'ok', false,
      'reason', 'assignment_slot_conflict',
      'assignment_id', v_assignment.id,
      'app_instance_id', v_assignment.app_instance_id,
      'schedule_mode', v_assignment.schedule_mode,
      'window_active', false,
      'phone_rest_active', false,
      'next_eligible_starts_at', null,
      'trigger', v_trigger
    );
  end if;

  v_window_active := v_assignment.starts_at <= v_now and v_now < v_assignment.ends_at;
  v_phone_rest_active := public.slot_overlaps_phone_rest(
    v_assignment.device_id,
    v_now,
    v_now + interval '1 minute',
    coalesce(v_device.timezone, 'UTC')
  );
  v_outreach_rest_reserved := v_assignment.assignment_type = 'outreach_only'
    and public.slot_reserved_for_outreach_rest(
      v_assignment.device_id,
      ((extract(hour from (v_assignment.starts_at at time zone coalesce(v_device.timezone, 'UTC')))::integer * 60
        + extract(minute from (v_assignment.starts_at at time zone coalesce(v_device.timezone, 'UTC')))::integer) / 40) + 1
    );

  if v_phone_rest_active then
    v_ok := false;
    v_reason := 'phone_rest_active';
  elsif v_outreach_rest_reserved then
    v_ok := false;
    v_reason := 'outreach_rest_reserved';
  elsif not v_window_active and not v_manual_trigger then
    v_ok := false;
    v_reason := 'assignment_window_closed';
  end if;

  if not v_ok then
    select min(slot.starts_at)
    into v_next_slot
    from public.generate_assignment_slot_catalog(
      v_assignment.assignment_type,
      (v_now at time zone coalesce(v_device.timezone, 'UTC'))::date,
      coalesce(v_device.timezone, 'UTC')
    ) as slot
    where slot.starts_at > v_now
      and not exists (
        select 1
        from public.account_assignments aa
        where aa.device_id = v_assignment.device_id
          and aa.account_id <> v_account_id
          and aa.status in ('pending', 'reserved', 'active')
          and aa.schedule_mode = 'scheduled'
          and tstzrange(aa.starts_at, aa.ends_at, '[)') && tstzrange(slot.starts_at, slot.ends_at, '[)')
      )
      and not public.slot_overlaps_phone_rest(
        v_assignment.device_id,
        slot.starts_at,
        slot.ends_at,
        coalesce(v_device.timezone, 'UTC')
      )
      and not (
        v_assignment.assignment_type = 'outreach_only'
        and public.slot_reserved_for_outreach_rest(v_assignment.device_id, slot.slot_index)
      );
  end if;

  return jsonb_build_object(
    'ok', v_ok,
    'reason', coalesce(v_reason, case
      when v_manual_trigger and v_requested_run_type = any(v_growth_run_types) then 'manual_start_allowed_outside_campaign_window'
      else 'assignment_window_open'
    end),
    'assignment_id', v_assignment.id,
    'clone_id', v_assignment.clone_id,
    'app_instance_id', v_assignment.app_instance_id,
    'assignment_type', v_assignment.assignment_type,
    'slot_kind', v_assignment.slot_kind,
    'schedule_mode', v_assignment.schedule_mode,
    'starts_at', v_assignment.starts_at,
    'ends_at', v_assignment.ends_at,
    'assignment_source', v_assignment.assignment_source,
    'device_id', v_assignment.device_id,
    'device_label', v_device.name,
    'device_timezone', v_device.timezone,
    'window_active', v_window_active,
    'phone_rest_active', v_phone_rest_active,
    'next_eligible_starts_at', v_next_slot,
    'trigger', v_trigger
  );
end;
$$;




CREATE OR REPLACE FUNCTION "public"."expire_client_instagram_onboarding_sessions"("p_client_id" "uuid", "p_actor_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_count integer;
begin
  if not exists (
    select 1 from public.client_users cu
     where cu.client_id = p_client_id
       and cu.auth_user_id = p_actor_id
       and cu.status = 'active'
  ) then
    return 0;
  end if;

  update public.client_instagram_onboarding_sessions
     set status = 'expired', lease_owner = null, lease_expires_at = null, updated_at = now()
   where client_id = p_client_id
     and status in ('active', 'creating', 'failed_retryable')
     and expires_at <= now();
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."expire_client_provisioning_slot_reservations"("p_now" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ declare v_count integer := 0; begin update public.client_provisioning_slot_reservations set status = 'expired', updated_at = p_now where status in ('reserved', 'window_open', 'assisted_requested') and expires_at <= p_now; get diagnostics v_count = row_count; return jsonb_build_object('ok', true, 'expired_count', v_count); end; $$;




CREATE OR REPLACE FUNCTION "public"."finalize_auto_login_failure_v1"("p_request_id" "uuid", "p_worker_id" "text", "p_account_id" "uuid", "p_run_id" "uuid", "p_persisted_error_code" "text", "p_error_message_safe" "text", "p_internal_worker_reason" "text", "p_phase" "text", "p_exit_code" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_worker_id text := left(
    regexp_replace(coalesce(nullif(trim(p_worker_id), ''), 'run-dispatcher'), '[^a-zA-Z0-9_.:-]', '_', 'g'),
    160
  );
  v_error_code text := lower(trim(coalesce(p_persisted_error_code, '')));
  v_internal_reason text := lower(trim(coalesce(p_internal_worker_reason, '')));
  v_phase text := lower(trim(coalesce(p_phase, '')));
  v_message text := trim(coalesce(p_error_message_safe, ''));
  v_request public.account_run_requests;
  v_request_updated public.account_run_requests;
  v_run_status text;
begin
  if v_error_code !~ '^[a-z][a-z0-9_]{0,119}$'
     or v_error_code ~* '(token|secret|authorization|cookie|service_role|vault|password)' then
    raise exception 'unsafe_auto_login_error_code' using errcode = '22023';
  end if;
  if v_internal_reason !~ '^[a-z][a-z0-9_]{0,159}$' then
    raise exception 'invalid_internal_worker_reason' using errcode = '22023';
  end if;
  if v_phase !~ '^[a-z][a-z0-9_]{0,79}$' then
    raise exception 'invalid_auto_login_phase' using errcode = '22023';
  end if;
  if char_length(v_message) < 1
     or char_length(v_message) > 500
     or v_message ~* '(token|secret|authorization|cookie|service_role|vault|password)' then
    raise exception 'unsafe_auto_login_error_message' using errcode = '22023';
  end if;

  select arr.*
    into v_request
  from public.account_run_requests arr
  where arr.id = p_request_id
  for update;

  if v_request.id is null then
    raise exception 'auto_login_request_not_found' using errcode = 'P0002';
  end if;
  if v_request.account_id <> p_account_id
     or v_request.run_id is distinct from p_run_id
     or v_request.claimed_by is distinct from v_worker_id
     or v_request.requested_run_type not in ('login_provisioning', 'login_email_code_resume') then
    raise exception 'auto_login_terminalization_scope_mismatch' using errcode = '22023';
  end if;

  if v_request.status = 'failed' then
    return jsonb_build_object(
      'request_id', v_request.id,
      'request_status', v_request.status,
      'run_id', v_request.run_id,
      'persisted_error_code', v_request.error_code,
      'terminalized', false,
      'reason', 'already_terminal'
    );
  end if;
  if v_request.status not in ('claimed', 'starting', 'running') then
    raise exception 'auto_login_request_not_active' using errcode = '22023';
  end if;

  perform 1
  from public.ig_runs r
  where r.id = p_run_id
    and r.account_id = p_account_id
  for update;
  if not found then
    raise exception 'auto_login_run_scope_mismatch' using errcode = '22023';
  end if;

  insert into public.auto_login_internal_failure_details (
    request_id,
    run_id,
    account_id,
    internal_worker_reason,
    phase,
    exit_code,
    source
  ) values (
    p_request_id,
    p_run_id,
    p_account_id,
    v_internal_reason,
    v_phase,
    p_exit_code,
    'run_dispatcher'
  )
  on conflict (request_id) do update set
    run_id = excluded.run_id,
    account_id = excluded.account_id,
    internal_worker_reason = excluded.internal_worker_reason,
    phase = excluded.phase,
    exit_code = excluded.exit_code,
    updated_at = now();

  update public.ig_runs r
  set
    status = 'failed',
    finished_at = coalesce(r.finished_at, now()),
    completed_at = coalesce(r.completed_at, now()),
    updated_at = now(),
    performance_summary = coalesce(r.performance_summary, '{}'::jsonb) || jsonb_build_object(
      'domain', 'auto_login',
      'phase', v_phase,
      'reason_code', v_error_code,
      'exit_code', p_exit_code,
      'terminalization_contract', 'auto_login_failure_v1'
    )
  where r.id = p_run_id
    and r.account_id = p_account_id
    and r.status in ('queued', 'pending', 'in_progress', 'active', 'starting', 'running');

  select r.status into v_run_status
  from public.ig_runs r
  where r.id = p_run_id;
  if v_run_status <> 'failed' then
    raise exception 'auto_login_run_not_terminalized' using errcode = '22023';
  end if;

  update public.account_run_requests arr
  set
    status = 'failed',
    completed_at = coalesce(arr.completed_at, now()),
    error_code = v_error_code,
    error_message_safe = v_message,
    lease_expires_at = null,
    updated_at = now()
  where arr.id = p_request_id
    and arr.claimed_by = v_worker_id
    and arr.status in ('claimed', 'starting', 'running')
  returning * into v_request_updated;

  if v_request_updated.id is null then
    raise exception 'auto_login_request_not_terminalized' using errcode = '22023';
  end if;

  return jsonb_build_object(
    'request_id', v_request_updated.id,
    'request_status', v_request_updated.status,
    'run_id', v_request_updated.run_id,
    'run_status', v_run_status,
    'persisted_error_code', v_request_updated.error_code,
    'terminalized', true,
    'reason', 'terminalized'
  );
end;
$_$;




COMMENT ON FUNCTION "public"."finalize_auto_login_failure_v1"("p_request_id" "uuid", "p_worker_id" "text", "p_account_id" "uuid", "p_run_id" "uuid", "p_persisted_error_code" "text", "p_error_message_safe" "text", "p_internal_worker_reason" "text", "p_phase" "text", "p_exit_code" integer) IS 'Service-role-only atomic Auto Login failure terminalization. Exact internal reason is retained outside projectable request/run fields.';



CREATE OR REPLACE FUNCTION "public"."generate_assignment_slot_catalog"("p_assignment_type" "text", "p_slot_date" "date", "p_timezone" "text") RETURNS TABLE("slot_index" integer, "slot_kind" "text", "local_label" "text", "starts_at" timestamp with time zone, "ends_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
declare
  v_tz text := coalesce(nullif(trim(p_timezone), ''), 'UTC');
  v_day_start timestamptz;
  v_offset_minutes integer;
  v_slot_kind text;
begin
  if not public.is_valid_schedule_timezone(v_tz) then
    raise exception 'invalid_timezone';
  end if;

  v_slot_kind := public.resolve_assignment_slot_kind(p_assignment_type);
  if v_slot_kind is null then
    return;
  end if;

  v_day_start := (p_slot_date::timestamp at time zone v_tz);

  if p_assignment_type = 'full_cycle' then
    return query
    select *
    from (
      values
        (1, 'full_cycle_6h'::text, '00:00 - 06:00'::text, v_day_start + interval '0 hour', v_day_start + interval '6 hours'),
        (2, 'full_cycle_6h'::text, '06:00 - 12:00'::text, v_day_start + interval '6 hours', v_day_start + interval '12 hours'),
        (3, 'full_cycle_6h'::text, '12:00 - 18:00'::text, v_day_start + interval '12 hours', v_day_start + interval '18 hours'),
        (4, 'full_cycle_6h'::text, '18:00 - 00:00'::text, v_day_start + interval '18 hours', v_day_start + interval '24 hours')
    ) as slots(slot_index, slot_kind, local_label, starts_at, ends_at);
    return;
  end if;

  v_offset_minutes := 0;
  while v_offset_minutes < 24 * 60 loop
    slot_index := (v_offset_minutes / 40) + 1;
    slot_kind := 'outreach_40m';
    starts_at := v_day_start + make_interval(mins => v_offset_minutes);
    ends_at := v_day_start + make_interval(mins => v_offset_minutes + 40);
    local_label := to_char(starts_at at time zone v_tz, 'HH24:MI') || ' - ' || to_char(ends_at at time zone v_tz, 'HH24:MI');
    return next;
    v_offset_minutes := v_offset_minutes + 40;
  end loop;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."get_account_incidents_overview_v1"("p_filter" "text" DEFAULT 'open'::"text", "p_limit" integer DEFAULT 50, "p_cursor_last_seen_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_cursor_id" "uuid" DEFAULT NULL::"uuid", "p_search" "text" DEFAULT NULL::"text", "p_include_test" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
with latest_action as (
  select distinct on (a.incident_id)
    a.incident_id,
    a.id as action_id,
    a.status as action_status,
    a.blocking_campaign,
    a.created_at
  from public.account_dashboard_actions a
  where a.action_type = 'operator_review_required'
    and a.incident_id is not null
  order by a.incident_id, a.created_at desc, a.id desc
), base as (
  select
    i.*,
    la.action_id as operator_action_id,
    la.action_status as operator_action_status,
    coalesce(la.action_status in ('pending', 'acknowledged', 'pending_verification', 'code_submitted'), false)
      or coalesce(i.metadata #>> '{recovery,state}', '') in ('reintervention_required', 'resume_authorization_expired')
      as action_required_derived,
    (i.incident_type = 'system_test_incident' or lower(coalesce(i.metadata ->> 'test', 'false')) in ('true', '1', 'yes')) as is_test
  from public.account_incidents i
  left join latest_action la on la.incident_id = i.id
  where i.archived_at is null
), operational as (
  select * from base where not is_test
), filtered as (
  select *
  from base b
  where (p_include_test or not b.is_test)
    and (
      nullif(trim(coalesce(p_search, '')), '') is null
      or coalesce(b.account_username, '') ilike '%' || trim(p_search) || '%'
      or coalesce(b.reason, '') ilike '%' || trim(p_search) || '%'
      or coalesce(b.failure_reason, '') ilike '%' || trim(p_search) || '%'
      or b.incident_type ilike '%' || trim(p_search) || '%'
    )
    and case lower(coalesce(p_filter, 'open'))
      when 'action_required' then b.status in ('open', 'acknowledged') and b.action_required_derived
      when 'resolved' then b.status in ('resolved', 'ignored')
      when 'all' then true
      else b.status in ('open', 'acknowledged') and not b.action_required_derived
    end
), cursor_filtered as (
  select *
  from filtered f
  where p_cursor_last_seen_at is null
    or p_cursor_id is null
    or (f.last_seen_at, f.id) < (p_cursor_last_seen_at, p_cursor_id)
), page_plus_one as (
  select * from cursor_filtered
  order by last_seen_at desc, id desc
  limit least(100, greatest(1, coalesce(p_limit, 50))) + 1
), page_rows as (
  select * from page_plus_one
  order by last_seen_at desc, id desc
  limit least(100, greatest(1, coalesce(p_limit, 50)))
), last_row as (
  select last_seen_at, id from page_rows order by last_seen_at asc, id asc limit 1
), global_counters as (
  select
    count(*) filter (where status in ('open', 'acknowledged') and not action_required_derived) as open_count,
    count(*) filter (where status in ('open', 'acknowledged') and action_required_derived) as action_required_count,
    count(*) filter (where status in ('resolved', 'ignored')) as resolved_count,
    count(*) as total_count,
    count(*) filter (where exists (
      select 1 from public.account_incident_notifications n
      where n.incident_id = operational.id and n.status = 'failed'
    )) as delivery_degraded_count
  from operational
)
select jsonb_build_object(
  'rows', coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', r.id,
      'status', r.status,
      'severity', r.severity,
      'incident_type', r.incident_type,
      'reason', r.reason,
      'failure_reason', r.failure_reason,
      'action_required', r.action_required,
      'admin_message', r.admin_message,
      'account_id', r.account_id,
      'account_username', r.account_username,
      'run_id', r.run_id,
      'occurrence_count', r.occurrence_count,
      'first_seen_at', r.first_seen_at,
      'last_seen_at', r.last_seen_at,
      'resolved_at', r.resolved_at,
      'source', r.source,
      'metadata', r.metadata,
      'operator_action_id', r.operator_action_id,
      'operator_action_status', r.operator_action_status,
      'is_test', r.is_test
    ) order by r.last_seen_at desc, r.id desc) from page_rows r
  ), '[]'::jsonb),
  'filtered_total', (select count(*) from filtered),
  'has_more', (select count(*) from page_plus_one) > least(100, greatest(1, coalesce(p_limit, 50))),
  'next_cursor', case
    when (select count(*) from page_plus_one) > least(100, greatest(1, coalesce(p_limit, 50)))
    then (select jsonb_build_object('last_seen_at', last_seen_at, 'id', id) from last_row)
    else null
  end,
  'counters', (select jsonb_build_object(
    'open', open_count,
    'actionRequired', action_required_count,
    'resolved', resolved_count,
    'deliveryDegraded', delivery_degraded_count,
    'total', total_count
  ) from global_counters)
)
$$;




CREATE OR REPLACE FUNCTION "public"."get_account_protection_lists_for_run"("p_account_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select case
    when not exists (select 1 from public.ig_accounts a where a.id = p_account_id) then
      jsonb_build_object('ok', false, 'reason', 'account_not_found', 'account_id', p_account_id)
    else jsonb_build_object(
      'ok', true,
      'account_id', p_account_id,
      'source', 'account_protection_list_entries',
      'loaded_at', now(),
      'lists', jsonb_build_object(
        'interaction_blacklist', coalesce((
          select jsonb_agg(e.normalized_username order by e.normalized_username)
            from public.account_protection_list_entries e
           where e.account_id = p_account_id
             and e.list_kind = 'interaction_blacklist'
             and e.active
        ), '[]'::jsonb),
        'unfollow_whitelist', coalesce((
          select jsonb_agg(e.normalized_username order by e.normalized_username)
            from public.account_protection_list_entries e
           where e.account_id = p_account_id
             and e.list_kind = 'unfollow_whitelist'
             and e.active
        ), '[]'::jsonb)
      ),
      'versions', jsonb_build_object(
        'interaction_blacklist', coalesce((
          select v.version from public.account_protection_list_versions v
           where v.account_id = p_account_id and v.list_kind = 'interaction_blacklist'
        ), 0),
        'unfollow_whitelist', coalesce((
          select v.version from public.account_protection_list_versions v
           where v.account_id = p_account_id and v.list_kind = 'unfollow_whitelist'
        ), 0)
      )
    )
  end;
$$;




COMMENT ON FUNCTION "public"."get_account_protection_lists_for_run"("p_account_id" "uuid") IS 'Returns one immutable, account-scoped protection-list snapshot for one worker run or attempt. Service role only.';



CREATE TABLE IF NOT EXISTS "public"."operator_stop_suppressions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "account_id" "uuid" NOT NULL,
    "assignment_id" "uuid",
    "scheduled_window_start" timestamp with time zone NOT NULL,
    "scheduled_window_end" timestamp with time zone NOT NULL,
    "request_id" "uuid",
    "run_id" "uuid",
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "reason_code" "text" DEFAULT 'operator_stop_suppressed'::"text" NOT NULL,
    "suppressed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "expires_at" timestamp with time zone NOT NULL,
    "released_at" timestamp with time zone,
    "metadata_safe" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "operator_stop_suppressions_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'expired'::"text"])))
);




CREATE OR REPLACE FUNCTION "public"."get_active_operator_stop_suppression"("p_account_id" "uuid", "p_now" timestamp with time zone DEFAULT "now"()) RETURNS "public"."operator_stop_suppressions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ declare v_row public.operator_stop_suppressions%rowtype; begin update public.operator_stop_suppressions set status = 'expired', released_at = coalesce(released_at, now()), updated_at = now() where account_id = p_account_id and status = 'active' and expires_at <= p_now; select * into v_row from public.operator_stop_suppressions where account_id = p_account_id and status = 'active' and expires_at > p_now order by suppressed_at desc limit 1; return v_row; end; $$;




CREATE OR REPLACE FUNCTION "public"."get_activity_log_interaction_evidence_admin"("p_account_id" "uuid" DEFAULT NULL::"uuid", "p_search" "text" DEFAULT NULL::"text", "p_mode" "text" DEFAULT 'all'::"text", "p_period" "text" DEFAULT '7d'::"text", "p_limit" integer DEFAULT 100) RETURNS TABLE("source_record_id" "uuid", "evidence_source_table" "text", "account_id" "uuid", "client_id" "uuid", "client_account_username" "text", "ct_id" "uuid", "ct_username" "text", "interacted_username" "text", "action_type" "text", "action_status" "text", "occurred_at" timestamp with time zone, "run_id" "uuid", "request_id" "uuid", "safe_device_label" "text", "evidence_source" "text", "evidence_confidence" "text", "evidence_summary" "text", "metadata_safe" "jsonb")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select
    source_record_id,
    evidence_source_table,
    account_id,
    client_id,
    client_account_username,
    ct_id,
    ct_username,
    interacted_username,
    action_type,
    action_status,
    occurred_at,
    run_id,
    request_id,
    safe_device_label,
    evidence_source,
    evidence_confidence,
    evidence_summary,
    metadata_safe
  from public.activity_log_interaction_evidence_admin_v1 evidence
  where (p_account_id is null or evidence.account_id = p_account_id)
    and evidence.occurred_at >= now() - case lower(coalesce(nullif(trim(p_period), ''), '7d'))
      when '24h' then interval '24 hours'
      when '30d' then interval '30 days'
      else interval '7 days'
    end
    and (
      nullif(trim(coalesce(p_search, '')), '') is null
      or case lower(coalesce(nullif(trim(p_mode), ''), 'all'))
        when 'search_by_ct' then coalesce(evidence.ct_username, '') ilike '%' || trim(both '@' from p_search) || '%'
        when 'search_by_account' then coalesce(evidence.interacted_username, '') ilike '%' || trim(both '@' from p_search) || '%'
        else (
          coalesce(evidence.ct_username, '') ilike '%' || trim(both '@' from p_search) || '%'
          or coalesce(evidence.interacted_username, '') ilike '%' || trim(both '@' from p_search) || '%'
          or coalesce(evidence.client_account_username, '') ilike '%' || trim(both '@' from p_search) || '%'
        )
      end
    )
  order by evidence.occurred_at desc nulls last
  limit least(greatest(coalesce(p_limit, 100), 1), 500);
$$;




CREATE OR REPLACE FUNCTION "public"."get_admin_account_overview"("p_limit" integer DEFAULT 100, "p_offset" integer DEFAULT 0, "p_search" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text") RETURNS TABLE("account_id" "uuid", "client_id" "uuid", "client_name" "text", "username" "text", "email_display" "text", "admin_status" "text", "customer_status" "text", "subscription_status" "text", "package_label" "text", "entitlement_summary" "text"[], "credentials_configured" boolean, "credentials_status" "text", "reauth_required" boolean, "login_status" "text", "provisioning_status" "text", "onboarding_status" "text", "password_display" "text", "two_factor_display" "text", "last_7d_growth" numeric, "created_at" timestamp with time zone, "tags" "text"[], "invoice_status" "text", "pending_actions_count" integer, "blocking_campaign" boolean, "latest_incident_severity" "text", "last_safe_update" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_limit int := least(200, greatest(1, coalesce(p_limit, 100)));
  v_offset int := greatest(0, coalesce(p_offset, 0));
  v_search text := nullif(trim(coalesce(p_search, '')), '');
  v_status text := lower(nullif(trim(coalesce(p_status, '')), ''));
begin
  return query
  with latest_credentials as (
    select distinct on (ac.account_id)
      ac.account_id,
      ac.status,
      coalesce(ac.reauth_required, false) as reauth_required,
      ac.updated_at
    from public.account_credentials as ac
    where ac.provider = 'instagram'
    order by ac.account_id, ac.credentials_version desc, ac.updated_at desc
  ),
  subscription_agg as (
    select
      csa.account_id,
      case
        when bool_or(cs.status = 'active') then 'active'
        when bool_or(cs.status = 'paused') then 'paused'
        when bool_or(cs.status = 'cancelled') then 'cancelled'
        when bool_or(cs.status = 'expired') then 'expired'
        else 'unknown'
      end as subscription_status
    from public.client_subscription_accounts as csa
    join public.client_subscriptions as cs
      on cs.id = csa.subscription_id
    group by csa.account_id
  ),
  entitlement_agg as (
    select
      ce.account_id,
      array_remove(array_agg(distinct ce.feature_code order by ce.feature_code), null) as entitlement_summary
    from public.client_entitlements as ce
    where ce.active = true
    group by ce.account_id
  ),
  action_agg as (
    select
      ada.account_id,
      count(*) filter (where ada.status in ('pending', 'acknowledged', 'pending_verification'))::int
        as pending_actions_count,
      bool_or(ada.blocking_campaign and ada.status in ('pending', 'acknowledged', 'pending_verification'))
        as blocking_campaign,
      max(ada.updated_at) as latest_action_at
    from public.account_dashboard_actions as ada
    group by ada.account_id
  ),
  incident_ranked as (
    select
      ai.account_id,
      ai.severity,
      ai.updated_at,
      row_number() over (
        partition by ai.account_id
        order by
          case ai.severity
            when 'critical' then 4
            when 'error' then 3
            when 'warning' then 2
            when 'info' then 1
            else 0
          end desc,
          ai.last_seen_at desc,
          ai.updated_at desc
      ) as rn
    from public.account_incidents as ai
    where ai.status in ('open', 'acknowledged')
  ),
  incident_latest as (
    select
      ir.account_id,
      ir.severity as latest_incident_severity,
      ir.updated_at as latest_incident_at
    from incident_ranked as ir
    where ir.rn = 1
  ),
  action_metrics as (
    select
      ial.account_id,
      count(*) filter (
        where ial.created_at >= now() - interval '7 days'
          and coalesce(ial.status, '') in ('success', 'completed', 'ok')
      )::numeric as last_7d_growth,
      max(ial.created_at) as latest_log_at
    from public.ig_action_logs as ial
    group by ial.account_id
  ),
  rows as (
    select
      cia.account_id,
      cia.client_id,
      c.name as client_name,
      nullif(trim(coalesce(ia.username, cia.label)), '') as username,
      case
        when nullif(trim(ia.email), '') is null then null
        when position('@' in ia.email) <= 1 then '***'
        else left(split_part(ia.email, '@', 1), 1) || '***@' || split_part(ia.email, '@', 2)
      end as email_display,
      case
        when coalesce(ia.status, '') in ('cancelled', 'canceled') then 'cancelled'
        when coalesce(ia.status, '') = 'paused' or coalesce(cia.provisioning_status, '') = 'paused' then 'paused'
        when coalesce(ia.status, '') = 'unpaid' then 'unpaid'
        when coalesce(cia.login_status, '') = 'needs_2fa' then 'twofactor'
        when coalesce(cia.login_status, '') = 'failed' or coalesce(lc.reauth_required, false) then 'incorrect'
        when coalesce(cia.login_status, '') = 'checkpoint' then 'checking'
        when coalesce(cia.login_status, '') = 'connected'
          and coalesce(cia.provisioning_status, '') in ('ready', 'assigned', 'provisioning') then 'active'
        when coalesce(cia.onboarding_status, '') in ('pending', 'incomplete', 'credentials_required') then 'pending'
        when coalesce(cia.login_status, '') in ('unknown', '') then 'new'
        else 'unknown'
      end as admin_status,
      case
        when coalesce(c.status, '') in ('active', 'trial', 'paused', 'inactive') then c.status
        else 'unknown'
      end as customer_status,
      coalesce(sa.subscription_status, 'unknown') as subscription_status,
      aps.commercial_package_label as package_label,
      coalesce(ea.entitlement_summary, aps.entitlements, array[]::text[]) as entitlement_summary,
      (lc.account_id is not null and lc.status = 'active') as credentials_configured,
      coalesce(lc.status, case when lc.account_id is null then 'missing' else 'unknown' end) as credentials_status,
      coalesce(lc.reauth_required, false) as reauth_required,
      coalesce(cia.login_status, 'unknown') as login_status,
      cia.provisioning_status,
      cia.onboarding_status,
      case
        when lc.account_id is not null and lc.status = 'active' then 'configured'
        when lc.account_id is null then 'missing'
        else 'unknown'
      end as password_display,
      case
        when coalesce(cia.login_status, '') = 'needs_2fa' then 'required'
        else 'unknown'
      end as two_factor_display,
      am.last_7d_growth,
      coalesce(cia.created_at, ia.created_at) as created_at,
      array[]::text[] as tags,
      null::text as invoice_status,
      coalesce(aa.pending_actions_count, 0) as pending_actions_count,
      coalesce(aa.blocking_campaign, false) as blocking_campaign,
      il.latest_incident_severity,
      greatest(
        coalesce(cia.updated_at, '-infinity'::timestamptz),
        coalesce(ia.updated_at, '-infinity'::timestamptz),
        coalesce(lc.updated_at, '-infinity'::timestamptz),
        coalesce(aa.latest_action_at, '-infinity'::timestamptz),
        coalesce(il.latest_incident_at, '-infinity'::timestamptz),
        coalesce(am.latest_log_at, '-infinity'::timestamptz)
      ) as last_safe_update
    from public.client_instagram_accounts as cia
    left join public.ig_accounts as ia
      on ia.id = cia.account_id
    left join public.clients as c
      on c.id = cia.client_id
    left join latest_credentials as lc
      on lc.account_id = cia.account_id
    left join subscription_agg as sa
      on sa.account_id = cia.account_id
    left join public.account_package_summary as aps
      on aps.account_id = cia.account_id
    left join entitlement_agg as ea
      on ea.account_id = cia.account_id
    left join action_agg as aa
      on aa.account_id = cia.account_id
    left join incident_latest as il
      on il.account_id = cia.account_id
    left join action_metrics as am
      on am.account_id = cia.account_id
  )
  select
    rows.account_id,
    rows.client_id,
    rows.client_name,
    rows.username,
    rows.email_display,
    rows.admin_status,
    rows.customer_status,
    rows.subscription_status,
    rows.package_label,
    rows.entitlement_summary,
    rows.credentials_configured,
    rows.credentials_status,
    rows.reauth_required,
    rows.login_status,
    rows.provisioning_status,
    rows.onboarding_status,
    rows.password_display,
    rows.two_factor_display,
    rows.last_7d_growth,
    rows.created_at,
    rows.tags,
    rows.invoice_status,
    rows.pending_actions_count,
    rows.blocking_campaign,
    rows.latest_incident_severity,
    nullif(rows.last_safe_update, '-infinity'::timestamptz) as last_safe_update
  from rows
  where (v_search is null or (
      rows.username ilike '%' || v_search || '%'
      or rows.email_display ilike '%' || v_search || '%'
      or rows.client_name ilike '%' || v_search || '%'
    ))
    and (v_status is null or rows.admin_status = v_status)
  order by rows.created_at desc nulls last, rows.account_id
  limit v_limit
  offset v_offset;
end;
$$;




COMMENT ON FUNCTION "public"."get_admin_account_overview"("p_limit" integer, "p_offset" integer, "p_search" "text", "p_status" "text") IS 'Dashboard Foundation 1A service-role-only read projection for future Admin Manage. Returns safe account overview fields only; no credentials, secret refs, raw logs, device internals, webhooks, or screenshots.';



CREATE OR REPLACE FUNCTION "public"."get_admin_radar_overview"("p_limit" integer DEFAULT 100, "p_offset" integer DEFAULT 0, "p_search" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_health" "text" DEFAULT NULL::"text") RETURNS TABLE("account_id" "uuid", "username" "text", "email_display" "text", "health_status" "text", "health_reason" "text", "admin_status" "text", "password_display" "text", "two_factor_display" "text", "actions_2d" integer, "actions_7d" integer, "actions_30d" integer, "followers_gained_30d" integer, "followers_gained_90d" integer, "fbr_percent" numeric, "posts_30d" integer, "live_feed_not_updated_2d" boolean, "last_block_at" timestamp with time zone, "dashboard_activity_status" "text", "quick_rule_flags" "text"[], "special_care_active" boolean, "tags" "text"[])
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_limit int := least(200, greatest(1, coalesce(p_limit, 100)));
  v_offset int := greatest(0, coalesce(p_offset, 0));
  v_search text := nullif(trim(coalesce(p_search, '')), '');
  v_status text := lower(nullif(trim(coalesce(p_status, '')), ''));
  v_health text := lower(nullif(trim(coalesce(p_health, '')), ''));
begin
  return query
  with manage as (
    select *
    from public.get_admin_account_overview(
      p_limit := 200,
      p_offset := 0,
      p_search := null,
      p_status := null
    )
  ),
  action_metrics as (
    select
      ial.account_id,
      count(*) filter (where ial.created_at >= now() - interval '2 days')::int as actions_2d,
      count(*) filter (where ial.created_at >= now() - interval '7 days')::int as actions_7d,
      count(*) filter (where ial.created_at >= now() - interval '30 days')::int as actions_30d,
      max(ial.created_at) filter (
        where lower(coalesce(ial.message, '') || ' ' || coalesce(ial.status, '') || ' ' || coalesce(ial.action_type, ''))
          like '%block%'
      ) as last_block_at
    from public.ig_action_logs as ial
    group by ial.account_id
  ),
  followback_metrics as (
    select
      iiu.account_id,
      round(
        100.0 * count(*) filter (where iiu.is_following_back is true)
        / nullif(count(*) filter (where iiu.followed_by_bot is true or iiu.follow_requested_at is not null), 0),
        2
      ) as fbr_percent
    from public.ig_interacted_users as iiu
    where iiu.last_interaction_at >= now() - interval '90 days'
    group by iiu.account_id
  ),
  latest_event as (
    select
      re.account_id,
      max(re.created_at) as latest_runtime_event_at
    from public.runtime_events as re
    where re.account_id is not null
    group by re.account_id
  ),
  open_incidents as (
    select
      ai.account_id,
      bool_or(ai.severity in ('critical', 'error')) as has_problem_incident,
      bool_or(ai.severity = 'warning') as has_warning_incident,
      max(ai.reason) filter (where ai.severity in ('critical', 'error')) as problem_reason,
      max(ai.reason) filter (where ai.severity = 'warning') as warning_reason
    from public.account_incidents as ai
    where ai.status in ('open', 'acknowledged')
    group by ai.account_id
  ),
  rows as (
    select
      m.account_id,
      m.username,
      m.email_display,
      case
        when coalesce(oi.has_problem_incident, false)
          or m.blocking_campaign
          or m.admin_status in ('incorrect', 'temporary_block', 'need_targets')
          or m.login_status in ('failed', 'checkpoint') then 'problem'
        when coalesce(oi.has_warning_incident, false)
          or m.pending_actions_count > 0
          or m.reauth_required
          or m.admin_status in ('checking', 'pending', 'twofactor')
          or (m.admin_status = 'active' and le.latest_runtime_event_at is null) then 'monitor'
        when m.admin_status = 'active'
          and m.login_status = 'connected'
          and not m.blocking_campaign
          and m.pending_actions_count = 0 then 'ok'
        else 'unknown'
      end as health_status,
      case
        when coalesce(oi.has_problem_incident, false) then coalesce(oi.problem_reason, 'open_problem_incident')
        when m.blocking_campaign then 'blocking_dashboard_action'
        when m.admin_status in ('incorrect', 'temporary_block', 'need_targets') then 'admin_status_' || m.admin_status
        when m.login_status in ('failed', 'checkpoint') then 'login_status_' || m.login_status
        when coalesce(oi.has_warning_incident, false) then coalesce(oi.warning_reason, 'open_warning_incident')
        when m.pending_actions_count > 0 then 'pending_dashboard_action'
        when m.reauth_required then 'reauth_required'
        when m.admin_status = 'active' and le.latest_runtime_event_at is null then 'runtime_data_missing'
        when m.admin_status = 'active' and m.login_status = 'connected' then 'healthy_connected'
        else 'insufficient_data'
      end as health_reason,
      m.admin_status,
      m.password_display,
      m.two_factor_display,
      am.actions_2d,
      am.actions_7d,
      am.actions_30d,
      null::int as followers_gained_30d,
      null::int as followers_gained_90d,
      fm.fbr_percent,
      null::int as posts_30d,
      case
        when le.latest_runtime_event_at is null then null
        else le.latest_runtime_event_at < now() - interval '2 days'
      end as live_feed_not_updated_2d,
      am.last_block_at,
      case
        when m.blocking_campaign then 'blocking'
        when m.pending_actions_count > 0 then 'pending'
        when m.last_safe_update >= now() - interval '2 days' then 'recent'
        else 'none'
      end as dashboard_activity_status,
      array[]::text[] as quick_rule_flags,
      false as special_care_active,
      m.tags
    from manage as m
    left join action_metrics as am
      on am.account_id = m.account_id
    left join followback_metrics as fm
      on fm.account_id = m.account_id
    left join latest_event as le
      on le.account_id = m.account_id
    left join open_incidents as oi
      on oi.account_id = m.account_id
  )
  select
    rows.account_id,
    rows.username,
    rows.email_display,
    rows.health_status,
    rows.health_reason,
    rows.admin_status,
    rows.password_display,
    rows.two_factor_display,
    rows.actions_2d,
    rows.actions_7d,
    rows.actions_30d,
    rows.followers_gained_30d,
    rows.followers_gained_90d,
    rows.fbr_percent,
    rows.posts_30d,
    rows.live_feed_not_updated_2d,
    rows.last_block_at,
    rows.dashboard_activity_status,
    rows.quick_rule_flags,
    rows.special_care_active,
    rows.tags
  from rows
  where (v_search is null or (
      rows.username ilike '%' || v_search || '%'
      or rows.email_display ilike '%' || v_search || '%'
    ))
    and (v_status is null or rows.admin_status = v_status)
    and (v_health is null or rows.health_status = v_health)
  order by
    case rows.health_status
      when 'problem' then 1
      when 'monitor' then 2
      when 'unknown' then 3
      when 'ok' then 4
      else 5
    end,
    rows.username nulls last,
    rows.account_id
  limit v_limit
  offset v_offset;
end;
$$;




COMMENT ON FUNCTION "public"."get_admin_radar_overview"("p_limit" integer, "p_offset" integer, "p_search" "text", "p_status" "text", "p_health" "text") IS 'Dashboard Foundation 1A service-role-only read projection for future Admin Radar and Server Check. Health is derived from safe statuses/actions/incidents/runtime signals; no mutations or device controls.';



CREATE OR REPLACE FUNCTION "public"."get_target_followers_resume_checkpoint"("p_account_id" "uuid", "p_target_id" "uuid", "p_surface" "text" DEFAULT 'followers'::"text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select to_jsonb(c)
  from public.ig_target_followers_resume_checkpoints as c
  where c.account_id = p_account_id
    and c.target_id = p_target_id
    and c.surface = p_surface
  limit 1
$$;




CREATE OR REPLACE FUNCTION "public"."get_target_followers_resume_checkpoint_v3"("p_account_id" "uuid", "p_target_id" "uuid", "p_surface" "text" DEFAULT 'followers'::"text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select to_jsonb(c) from public.ig_target_followers_resume_checkpoints c
  where c.account_id = p_account_id and c.target_id = p_target_id and c.surface = p_surface limit 1
$$;




CREATE OR REPLACE FUNCTION "public"."get_valid_scheduled_session_preflight"("p_account_id" "uuid", "p_assignment_id" "uuid", "p_device_id" "uuid", "p_app_instance_id" "uuid", "p_expected_package" "text", "p_scheduled_window_start" timestamp with time zone, "p_scheduled_window_end" timestamp with time zone, "p_now" timestamp with time zone DEFAULT "now"()) RETURNS "public"."scheduled_session_preflights"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_row public.scheduled_session_preflights%rowtype;
begin
  select * into v_row
  from public.scheduled_session_preflights
  where account_id = p_account_id
    and assignment_id = p_assignment_id
    and device_id = p_device_id
    and app_instance_id = p_app_instance_id
    and expected_package = coalesce(p_expected_package, '')
    and scheduled_window_start = p_scheduled_window_start
    and scheduled_window_end = p_scheduled_window_end
    and status = 'preflight_ready'
    and business_action_deadline > p_now
  limit 1;
  return v_row;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
begin
  insert into public.profiles (id, email, full_name)
  values (
    new.id,
    new.email,
    coalesce(new.raw_user_meta_data ->> 'full_name', '')
  );
  return new;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."handoff_preflight_device_lock_to_request"("p_device_id" "uuid", "p_preflight_request_id" "uuid", "p_scheduler_request_id" "uuid", "p_new_worker_id" "text", "p_lease_seconds" integer DEFAULT 900) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ declare v_transfer jsonb; begin v_transfer := public.auto_restart_transfer_device_lock(p_device_id, p_preflight_request_id, p_new_worker_id, p_lease_seconds); if coalesce((v_transfer->>'ok')::boolean, false) is not true then return v_transfer; end if; update public.auto_restart_device_locks set request_id = p_scheduler_request_id, owner_kind = 'scheduler', operation_phase = 'queued', reason = 'scheduler_run', updated_at = now() where device_id = p_device_id and request_id = p_preflight_request_id; return jsonb_build_object('ok', true, 'transferred', true, 'request_id', p_scheduler_request_id); end; $$;




CREATE OR REPLACE FUNCTION "public"."increment_ig_target_follows_sent_p1c"("p_target_id" "uuid", "p_account_id" "uuid" DEFAULT NULL::"uuid", "p_last_successful_candidate_at" timestamp with time zone DEFAULT "now"()) RETURNS TABLE("follows_sent_count" integer, "followback_ratio" numeric)
    LANGUAGE "plpgsql"
    AS $$
begin
  return query
  update public.ig_targets as target
  set
    follows_sent_count = target.follows_sent_count + 1,
    last_successful_candidate_at = p_last_successful_candidate_at,
    last_used_at = p_last_successful_candidate_at,
    metrics_updated_at = p_last_successful_candidate_at,
    updated_at = p_last_successful_candidate_at
  where target.id = p_target_id
    and (p_account_id is null or target.account_id = p_account_id)
  returning target.follows_sent_count, target.followback_ratio;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."initialize_account_warmup_on_package_activation"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_started_at timestamptz;
begin
  if new.status <> 'active' or new.ends_at is not null then
    return new;
  end if;

  v_started_at := coalesce(new.starts_at, new.created_at, now());

  insert into public.account_warmup_settings (
    account_id,
    warmup_enabled,
    package_started_at,
    warmup_profile_code,
    day_1_follow_cap,
    day_2_follow_cap,
    day_3_follow_cap,
    day_4_plus_follow_cap,
    status,
    updated_at
  ) values (
    new.account_id,
    true,
    v_started_at,
    'follow_default_v1',
    10,
    20,
    40,
    null,
    'active',
    now()
  )
  on conflict (account_id) do update
    set package_started_at = excluded.package_started_at,
        status = 'active',
        updated_at = now()
    where account_warmup_settings.package_started_at is null;

  return new;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."instagram_credential_cleanup_reason_allowed"("p_reason" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  select lower(coalesce(nullif(btrim(p_reason), ''), '')) in (
    'smoke_cleanup',
    'failed_ingestion_cleanup',
    'explicit_credential_revoke',
    'security_revoke',
    'permanent_account_delete',
    'test_onboarding_rollback'
  );
$$;




COMMENT ON FUNCTION "public"."instagram_credential_cleanup_reason_allowed"("p_reason" "text") IS 'Patch 2C-1 reason guard for credential cleanup. Restorable lifecycle states such as archive/trash/paused are intentionally not valid cleanup reasons.';



CREATE OR REPLACE FUNCTION "public"."invalidate_target_followers_resume_checkpoint"("p_account_id" "uuid", "p_target_id" "uuid", "p_surface" "text", "p_run_id" "uuid", "p_expected_version" bigint, "p_reason" "text", "p_status" "text" DEFAULT 'stale'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_row public.ig_target_followers_resume_checkpoints%rowtype;
  v_new_version bigint;
begin
  if p_account_id is null
     or p_target_id is null
     or p_run_id is null
     or p_expected_version is null
     or p_surface <> 'followers'
     or p_status not in ('stale', 'reset_required', 'invalidated')
     or p_reason !~ '^[a-z0-9_:-]{1,120}$' then
    return jsonb_build_object('ok', false, 'reason', 'invalid_invalidation_input');
  end if;
  select * into v_row from public.ig_target_followers_resume_checkpoints c
  where c.account_id = p_account_id and c.target_id = p_target_id and c.surface = p_surface
  for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'checkpoint_missing');
  end if;
  if v_row.optimistic_version <> p_expected_version then
    return jsonb_build_object('ok', false, 'reason', 'optimistic_version_conflict', 'optimistic_version', v_row.optimistic_version);
  end if;
  update public.ig_target_followers_resume_checkpoints c
  set status = p_status,
      invalidation_reason = p_reason,
      lease_owner_run_id = null,
      lease_mode = null,
      lease_expires_at = null,
      last_run_id = p_run_id,
      optimistic_version = c.optimistic_version + 1,
      updated_at = now()
  where c.id = v_row.id
  returning c.optimistic_version into v_new_version;
  insert into public.ig_target_followers_resume_checkpoint_events (
    checkpoint_id, account_id, target_id, run_id, event_type,
    previous_optimistic_version, new_optimistic_version,
    previous_depth, new_depth, reason
  ) values (
    v_row.id, p_account_id, p_target_id, p_run_id, 'invalidated',
    v_row.optimistic_version, v_new_version,
    greatest(v_row.last_safe_depth, v_row.shadow_last_safe_depth),
    greatest(v_row.last_safe_depth, v_row.shadow_last_safe_depth), p_reason
  );
  return jsonb_build_object('ok', true, 'reason', 'invalidated', 'optimistic_version', v_new_version, 'status', p_status);
end
$_$;




CREATE OR REPLACE FUNCTION "public"."is_account_run_request_cancel_requested"("p_request_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ select exists (select 1 from public.account_run_requests arr where arr.id = p_request_id and (arr.cancel_requested_at is not null or arr.status = 'canceled')); $$;




CREATE OR REPLACE FUNCTION "public"."is_customer_member"("target_customer_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE
    AS $$
  select exists (
    select 1
    from public.customer_members cm
    where cm.customer_id = target_customer_id
      and cm.profile_id = auth.uid()
  );
$$;




CREATE OR REPLACE FUNCTION "public"."is_open_assignment_status"("p_status" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select coalesce(p_status, '') in ('pending', 'reserved', 'active');
$$;




CREATE OR REPLACE FUNCTION "public"."is_terminal_assignment_status"("p_status" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select coalesce(p_status, '') in ('released', 'canceled', 'expired', 'archived');
$$;




CREATE OR REPLACE FUNCTION "public"."is_valid_schedule_timezone"("p_timezone" "text") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  select exists (
    select 1
    from pg_catalog.pg_timezone_names
    where name = nullif(trim(p_timezone), '')
  );
$$;




CREATE OR REPLACE FUNCTION "public"."link_account_run_request_run"("p_request_id" "uuid", "p_worker_id" "text", "p_run_id" "uuid") RETURNS "public"."account_run_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ declare v_worker_id text := left(regexp_replace(coalesce(nullif(trim(p_worker_id), ''), 'run-dispatcher'), '[^a-zA-Z0-9_.:-]', '_', 'g'), 160); v_row public.account_run_requests; begin if p_run_id is null then raise exception 'run_id_required' using errcode = '22023'; end if; update public.account_run_requests arr set status = 'running', run_id = p_run_id, started_at = coalesce(arr.started_at, now()), lease_expires_at = greatest(coalesce(arr.lease_expires_at, now()), now() + interval '5 minutes'), updated_at = now() where arr.id = p_request_id and arr.status in ('claimed', 'starting') and arr.claimed_by = v_worker_id returning * into v_row; return v_row; end; $$;




CREATE OR REPLACE FUNCTION "public"."list_available_assignment_slots"("p_account_id" "uuid", "p_device_id" "uuid" DEFAULT NULL::"uuid", "p_assignment_type" "text" DEFAULT NULL::"text", "p_slot_date" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_account_id uuid := p_account_id;
  v_device_id uuid := p_device_id;
  v_assignment_type text := coalesce(
    nullif(trim(p_assignment_type), ''),
    public.resolve_account_schedule_assignment_type(p_account_id)
  );
  v_subscription_account_id uuid;
  v_device_timezone text := 'UTC';
  v_device_status text;
  v_device_pool_type text;
  v_slot_date date;
  v_slot_kind text;
  v_current_assignment record;
  v_slot record;
  v_slots jsonb := '[]'::jsonb;
  v_available boolean;
  v_reason text;
  v_occupied_by text;
  v_occupant record;
  v_app_instance_summary jsonb := '{}'::jsonb;
begin
  if v_account_id is null then
    raise exception 'missing_account_id';
  end if;

  if v_assignment_type is null then
    return jsonb_build_object(
      'ok', false,
      'reason', 'subscription_not_active',
      'slots', '[]'::jsonb
    );
  end if;

  v_slot_kind := public.resolve_assignment_slot_kind(v_assignment_type);

  select csa.id
  into v_subscription_account_id
  from public.client_subscription_accounts csa
  join public.client_subscriptions cs on cs.id = csa.subscription_id
  where csa.account_id = v_account_id
    and csa.status = 'active'
    and cs.status = 'active'
    and cs.subscription_type = v_assignment_type
  order by cs.starts_at desc, cs.created_at desc
  limit 1;

  select
    aa.id,
    aa.device_id,
    aa.clone_id,
    aa.app_instance_id,
    aa.assignment_type,
    aa.slot_kind,
    aa.schedule_mode,
    aa.status,
    aa.starts_at,
    aa.ends_at,
    aa.assignment_source
  into v_current_assignment
  from public.account_assignments aa
  where aa.account_id = v_account_id
    and aa.status in ('pending', 'reserved', 'active')
  order by aa.created_at desc
  limit 1;

  if v_device_id is null then
    v_device_id := v_current_assignment.device_id;
  end if;

  if v_device_id is null then
    select pd.id
    into v_device_id
    from public.phone_devices pd
    where pd.status in ('available', 'active')
      and pd.pool_type in (v_assignment_type, 'shared')
    order by pd.created_at asc
    limit 1;
  end if;

  if v_device_id is null then
    return jsonb_build_object(
      'ok', false,
      'reason', 'device_unavailable',
      'assignment_type', v_assignment_type,
      'slot_kind', v_slot_kind,
      'slots', '[]'::jsonb
    );
  end if;

  select pd.timezone, pd.status, pd.pool_type
  into v_device_timezone, v_device_status, v_device_pool_type
  from public.phone_devices pd
  where pd.id = v_device_id;

  if v_device_timezone is null then
    return jsonb_build_object(
      'ok', false,
      'reason', 'device_unavailable',
      'assignment_type', v_assignment_type,
      'slot_kind', v_slot_kind,
      'slots', '[]'::jsonb
    );
  end if;

  if v_device_status not in ('available', 'active') then
    return jsonb_build_object(
      'ok', false,
      'reason', 'device_unavailable',
      'assignment_type', v_assignment_type,
      'slot_kind', v_slot_kind,
      'device_id', v_device_id,
      'device_timezone', v_device_timezone,
      'slots', '[]'::jsonb
    );
  end if;

  if v_device_pool_type <> 'shared' and v_device_pool_type <> v_assignment_type then
    return jsonb_build_object(
      'ok', false,
      'reason', 'outside_policy',
      'assignment_type', v_assignment_type,
      'slot_kind', v_slot_kind,
      'device_id', v_device_id,
      'device_timezone', v_device_timezone,
      'slots', '[]'::jsonb
    );
  end if;

  select jsonb_build_object(
    'total', count(*),
    'available', count(*) filter (
      where pai.status = 'available'
        and pai.usable_for_auto_login
        and pai.is_launchable
        and pai.current_account_id is null
    ),
    'occupied', count(*) filter (where pai.status = 'occupied' or pai.current_account_id is not null),
    'disabled', count(*) filter (where pai.status = 'disabled'),
    'unknown', count(*) filter (where pai.status = 'unknown'),
    'primary_app', count(*) filter (where pai.instance_type = 'primary_app'),
    'clones', count(*) filter (where pai.instance_type = 'clone')
  )
  into v_app_instance_summary
  from public.phone_app_instances pai
  where pai.device_id = v_device_id;

  v_slot_date := coalesce(
    p_slot_date,
    (now() at time zone v_device_timezone)::date
  );

  for v_slot in
    select *
    from public.generate_assignment_slot_catalog(v_assignment_type, v_slot_date, v_device_timezone)
    order by slot_index
  loop
    v_available := true;
    v_reason := null;
    v_occupied_by := null;

    select
      aa.account_id,
      ia.username
    into v_occupant
    from public.account_assignments aa
    left join public.ig_accounts ia on ia.id = aa.account_id
    where aa.device_id = v_device_id
      and aa.status in ('pending', 'reserved', 'active')
      and aa.schedule_mode = 'scheduled'
      and aa.account_id <> v_account_id
      and tstzrange(aa.starts_at, aa.ends_at, '[)') && tstzrange(v_slot.starts_at, v_slot.ends_at, '[)')
    order by aa.created_at desc
    limit 1;

    if found then
      v_available := false;
      v_reason := 'occupied';
      v_occupied_by := coalesce(nullif(trim(v_occupant.username), ''), 'assigned account');
    elsif not exists (
      select 1
      from public.phone_app_instances pai
      where pai.device_id = v_device_id
        and pai.status = 'available'
        and pai.usable_for_auto_login
        and pai.is_launchable
        and pai.current_account_id is null
        and not exists (
          select 1
          from public.account_assignments aa
          where aa.app_instance_id = pai.id
            and aa.status in ('pending', 'reserved', 'active')
            and aa.schedule_mode = 'scheduled'
            and tstzrange(aa.starts_at, aa.ends_at, '[)') && tstzrange(v_slot.starts_at, v_slot.ends_at, '[)')
        )
    ) then
      v_available := false;
      v_reason := 'no_app_instance_available';
    elsif public.slot_overlaps_phone_rest(v_device_id, v_slot.starts_at, v_slot.ends_at, v_device_timezone) then
      v_available := false;
      v_reason := 'phone_rest';
    elsif v_assignment_type = 'outreach_only'
      and public.slot_reserved_for_outreach_rest(v_device_id, v_slot.slot_index) then
      v_available := false;
      v_reason := 'outreach_rest_reserved';
    elsif v_current_assignment.id is not null
      and v_current_assignment.schedule_mode = 'scheduled'
      and v_current_assignment.starts_at = v_slot.starts_at
      and v_current_assignment.ends_at = v_slot.ends_at then
      v_available := true;
      v_reason := 'current';
    end if;

    v_slots := v_slots || jsonb_build_array(
      jsonb_build_object(
        'slot_index', v_slot.slot_index,
        'slot_kind', v_slot.slot_kind,
        'slot_kind_label', case when v_slot.slot_kind in ('outreach_short', 'outreach_40m') then 'outreach_40m' else v_slot.slot_kind end,
        'local_label', v_slot.local_label,
        'starts_at', v_slot.starts_at,
        'ends_at', v_slot.ends_at,
        'available', v_available,
        'reason', v_reason,
        'occupied_by', v_occupied_by
      )
    );
  end loop;

  return jsonb_build_object(
    'ok', true,
    'account_id', v_account_id,
    'device_id', v_device_id,
    'assignment_type', v_assignment_type,
    'slot_kind', v_slot_kind,
    'slot_date', v_slot_date,
    'device_timezone', v_device_timezone,
    'app_instance_availability', coalesce(v_app_instance_summary, '{}'::jsonb),
    'current_assignment', case
      when v_current_assignment.id is null then null
      else jsonb_build_object(
        'assignment_id', v_current_assignment.id,
        'device_id', v_current_assignment.device_id,
        'clone_id', v_current_assignment.clone_id,
        'app_instance_id', v_current_assignment.app_instance_id,
        'assignment_type', v_current_assignment.assignment_type,
        'slot_kind', v_current_assignment.slot_kind,
        'schedule_mode', v_current_assignment.schedule_mode,
        'status', v_current_assignment.status,
        'starts_at', v_current_assignment.starts_at,
        'ends_at', v_current_assignment.ends_at,
        'assignment_source', v_current_assignment.assignment_source
      )
    end,
    'slots', v_slots
  );
end;
$$;




COMMENT ON FUNCTION "public"."list_available_assignment_slots"("p_account_id" "uuid", "p_device_id" "uuid", "p_assignment_type" "text", "p_slot_date" "date") IS 'Returns phone-local slot catalog with availability, occupied reason, and explicit fixed-blackout blocking. Does not create default rest slots.';



CREATE OR REPLACE FUNCTION "public"."mark_account_run_request_starting"("p_request_id" "uuid", "p_worker_id" "text") RETURNS "public"."account_run_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ declare v_worker_id text := left(regexp_replace(coalesce(nullif(trim(p_worker_id), ''), 'run-dispatcher'), '[^a-zA-Z0-9_.:-]', '_', 'g'), 160); v_row public.account_run_requests; begin update public.account_run_requests arr set status = 'starting', lease_expires_at = greatest(coalesce(arr.lease_expires_at, now()), now() + interval '2 minutes'), updated_at = now() where arr.id = p_request_id and arr.status = 'claimed' and arr.claimed_by = v_worker_id and (arr.lease_expires_at is null or arr.lease_expires_at > now()) and arr.cancel_requested_at is null returning * into v_row; return v_row; end; $$;




CREATE OR REPLACE FUNCTION "public"."mark_client_provisioning_assisted_requested"("p_reservation_id" "uuid", "p_ig_account_id" "uuid") RETURNS "public"."client_provisioning_slot_reservations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ declare v_row public.client_provisioning_slot_reservations; begin update public.client_provisioning_slot_reservations set status = 'assisted_requested', assisted_connect_requested_at = coalesce(assisted_connect_requested_at, now()), updated_at = now() where id = p_reservation_id and ig_account_id = p_ig_account_id and status in ('reserved', 'window_open', 'assisted_requested') returning * into v_row; if not found then raise exception 'provisioning_slot_reservation_not_assistable' using errcode = 'P0001'; end if; return v_row; end; $$;




CREATE OR REPLACE FUNCTION "public"."mark_dm_job_running"("p_job_id" "uuid") RETURNS "public"."ig_dm_jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_job public.ig_dm_jobs;
begin
  update public.ig_dm_jobs
  set
    status = 'running',
    started_at = coalesce(started_at, now()),
    updated_at = now()
  where id = p_job_id
    and status in ('reserved', 'pending')
  returning * into v_job;

  return v_job;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."mark_instagram_restriction_preflight_required_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if new.incident_type <> 'instagram_account_restriction' then
    return new;
  end if;
  update public.instagram_account_restriction_holds
  set status = 'verification_required',
      human_resolved_at = coalesce(new.resolved_at, now()),
      verification_required_at = now(),
      metadata_safe = coalesce(metadata_safe, '{}'::jsonb)
        || jsonb_build_object('incident_resolved_but_physical_preflight_pending', true),
      updated_at = now()
  where incident_id = new.id and status = 'active';
  return new;
end
$$;




CREATE OR REPLACE FUNCTION "public"."match_documents"("query_embedding" "public"."vector", "match_count" integer, "filter" "jsonb" DEFAULT '{}'::"jsonb") RETURNS TABLE("id" bigint, "content" "text", "metadata" "jsonb", "similarity" double precision)
    LANGUAGE "sql"
    AS $$
  select
    documents.id,
    documents.content,
    documents.metadata,
    1 - (documents.embedding <=> query_embedding) as similarity
  from public.documents
  where documents.metadata @> filter
  order by documents.embedding <=> query_embedding
  limit match_count;
$$;




CREATE OR REPLACE FUNCTION "public"."match_documents"("query_embedding" "public"."vector", "match_count" integer DEFAULT 5, "filter_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("id" bigint, "user_id" "uuid", "source_name" "text", "content" "text", "metadata" "jsonb", "similarity" double precision)
    LANGUAGE "sql" STABLE
    AS $$
  select
    d.id,
    d.user_id,
    d.source_name,
    d.content,
    d.metadata,
    1 - (d.embedding <=> query_embedding) as similarity
  from public.documents d
  where
    d.embedding is not null
    and (filter_user_id is null or d.user_id = filter_user_id)
  order by d.embedding <=> query_embedding
  limit match_count;
$$;




CREATE OR REPLACE FUNCTION "public"."materialize_client_email_outbox_candidate_v1"("p_account_id" "uuid", "p_client_id" "uuid", "p_category" "text", "p_operation" "text", "p_parent_episode_key" "text", "p_started_at" timestamp with time zone, "p_source_action_id" "uuid" DEFAULT NULL::"uuid", "p_eligible_target_count_at_start" integer DEFAULT NULL::integer, "p_recipient_email" "text" DEFAULT NULL::"text", "p_idempotency_key" "text" DEFAULT NULL::"text", "p_trigger" "text" DEFAULT NULL::"text", "p_reminder_index" smallint DEFAULT NULL::smallint, "p_template_id" "uuid" DEFAULT NULL::"uuid", "p_template_version" integer DEFAULT NULL::integer, "p_snapshot_subject" "text" DEFAULT NULL::"text", "p_snapshot_body_text" "text" DEFAULT NULL::"text", "p_snapshot_body_html" "text" DEFAULT NULL::"text", "p_from_email" "text" DEFAULT NULL::"text", "p_from_email_snapshot" "text" DEFAULT NULL::"text", "p_support_email_snapshot" "text" DEFAULT NULL::"text", "p_parent_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_parent_id uuid;
  v_parent_created boolean := false;
  v_parent_kind text;
  v_parent_status text;
  v_intent_id uuid;
  v_intent_created boolean := false;
  v_existing_intent public.client_email_send_intents%rowtype;
  v_reminder_index smallint;
  v_is_create_intent boolean;
begin
  v_is_create_intent := p_operation in (
    'create_lifecycle_initial_intent',
    'create_needs_more_initial_intent',
    'create_needs_more_reminder_intent'
  );

  if p_account_id is null or p_client_id is null then
    return jsonb_build_object('ok', false, 'code', 'missing_account_or_client');
  end if;

  if p_category not in (
    'account_paused',
    'account_canceled',
    'needs_assistance',
    'needs_more_target_accounts'
  ) then
    return jsonb_build_object('ok', false, 'code', 'invalid_category');
  end if;

  if p_parent_episode_key is null or btrim(p_parent_episode_key) = '' then
    return jsonb_build_object('ok', false, 'code', 'missing_parent_episode_key');
  end if;

  if p_started_at is null then
    return jsonb_build_object('ok', false, 'code', 'missing_started_at');
  end if;

  perform pg_advisory_xact_lock(
    hashtext('client_email_materialize'),
    hashtext(p_account_id::text)
  );

  if not exists (
    select 1
    from public.client_instagram_accounts cia
    where cia.account_id = p_account_id
      and cia.client_id = p_client_id
  ) then
    return jsonb_build_object('ok', false, 'code', 'client_email_account_client_ownership_mismatch');
  end if;

  v_reminder_index := coalesce(p_reminder_index, 0);

  if p_category = 'needs_more_target_accounts' then
    v_parent_kind := 'sequence';

    if p_operation not in (
      'open_needs_more_sequence',
      'create_needs_more_initial_intent',
      'create_needs_more_reminder_intent'
    ) then
      return jsonb_build_object('ok', false, 'code', 'invalid_operation');
    end if;

    if p_operation = 'create_needs_more_initial_intent' and v_reminder_index <> 0 then
      if v_is_create_intent then
        raise exception using
          errcode = 'P0001',
          message = 'client_email_needs_more_initial_index_required';
      end if;
      return jsonb_build_object('ok', false, 'code', 'needs_more_initial_index_required');
    end if;

    if p_operation = 'create_needs_more_reminder_intent'
       and (v_reminder_index < 1 or v_reminder_index > 5) then
      if v_is_create_intent then
        raise exception using
          errcode = 'P0001',
          message = 'client_email_needs_more_reminder_index_out_of_range';
      end if;
      return jsonb_build_object('ok', false, 'code', 'needs_more_reminder_index_out_of_range');
    end if;
  else
    v_parent_kind := 'lifecycle_episode';

    if p_operation not in (
      'open_lifecycle_episode',
      'create_lifecycle_initial_intent'
    ) then
      return jsonb_build_object('ok', false, 'code', 'invalid_operation');
    end if;

    if v_reminder_index <> 0 then
      if v_is_create_intent then
        raise exception using
          errcode = 'P0001',
          message = 'client_email_lifecycle_initial_index_required';
      end if;
      return jsonb_build_object('ok', false, 'code', 'lifecycle_initial_index_required');
    end if;
  end if;

  if v_is_create_intent then
    if p_idempotency_key is null or btrim(p_idempotency_key) = '' then
      raise exception using
        errcode = 'P0001',
        message = 'client_email_missing_idempotency_key';
    end if;

    select *
      into v_existing_intent
    from public.client_email_send_intents i
    where i.idempotency_key = p_idempotency_key
    limit 1;

    if found then
      if v_existing_intent.account_id is distinct from p_account_id
         or v_existing_intent.client_id is distinct from p_client_id
         or v_existing_intent.intent_kind is distinct from 'client'
         or v_existing_intent.category is distinct from p_category
         or v_existing_intent.trigger is distinct from p_trigger
         or v_existing_intent.reminder_index is distinct from v_reminder_index then
        raise exception 'client_email_idempotency_identity_conflict'
          using errcode = '23514';
      end if;

      if p_category = 'needs_more_target_accounts' then
        if v_existing_intent.sequence_id is null then
          raise exception 'client_email_idempotency_identity_conflict'
            using errcode = '23514';
        end if;
        v_parent_id := v_existing_intent.sequence_id;
      else
        if v_existing_intent.lifecycle_episode_id is null then
          raise exception 'client_email_idempotency_identity_conflict'
            using errcode = '23514';
        end if;
        v_parent_id := v_existing_intent.lifecycle_episode_id;
      end if;

      return jsonb_build_object(
        'ok', true,
        'parent', jsonb_build_object(
          'id', v_parent_id,
          'kind', v_parent_kind,
          'created', false
        ),
        'intent', jsonb_build_object(
          'id', v_existing_intent.id,
          'created', false,
          'status', v_existing_intent.status,
          'idempotency_key', v_existing_intent.idempotency_key
        )
      );
    end if;

    if p_from_email is null
       or btrim(p_from_email) = ''
       or p_from_email_snapshot is null
       or btrim(p_from_email_snapshot) = ''
    then
      raise exception using
        errcode = 'P0001',
        message = 'client_email_from_email_snapshot_missing';
    end if;

    if btrim(p_from_email) is distinct from btrim(p_from_email_snapshot) then
      raise exception using
        errcode = 'P0001',
        message = 'client_email_from_email_snapshot_mismatch';
    end if;

    if p_recipient_email is null or btrim(p_recipient_email) = '' then
      raise exception using
        errcode = 'P0001',
        message = 'client_email_missing_recipient_email';
    end if;

    if p_trigger is null
       or btrim(p_trigger) = ''
       or p_template_id is null
       or p_template_version is null
       or p_snapshot_subject is null
       or btrim(p_snapshot_subject) = ''
       or p_snapshot_body_text is null
       or btrim(p_snapshot_body_text) = ''
       or p_snapshot_body_html is null
       or btrim(p_snapshot_body_html) = ''
       or p_support_email_snapshot is null
       or btrim(p_support_email_snapshot) = '' then
      raise exception using
        errcode = 'P0001',
        message = 'client_email_missing_intent_snapshot_fields';
    end if;

    if p_operation = 'create_needs_more_reminder_intent' then
      if p_parent_id is null then
        raise exception using
          errcode = 'P0001',
          message = 'client_email_needs_more_active_sequence_required';
      end if;

      select s.id, s.status
        into v_parent_id, v_parent_status
      from public.client_email_needs_more_targets_sequences s
      where s.id = p_parent_id
        and s.account_id = p_account_id
        and s.client_id = p_client_id
        and s.status = 'active'
      limit 1;

      if v_parent_id is null then
        raise exception using
          errcode = 'P0001',
          message = 'client_email_needs_more_active_sequence_required';
      end if;

      if exists (
        select 1
        from public.client_email_needs_more_targets_sequences s
        where s.episode_key = p_parent_episode_key
          and s.status <> 'active'
      ) then
        raise exception using
          errcode = 'P0001',
          message = 'client_email_parent_episode_not_reopenable';
      end if;
    end if;
  end if;

  if p_category = 'needs_more_target_accounts' then
    if p_operation = 'create_needs_more_reminder_intent' then
      null;
    elsif p_parent_id is not null then
      select s.id, s.status
        into v_parent_id, v_parent_status
      from public.client_email_needs_more_targets_sequences s
      where s.id = p_parent_id
        and s.account_id = p_account_id
        and s.client_id = p_client_id
      limit 1;

      if v_parent_id is null then
        if v_is_create_intent then
          raise exception using
            errcode = 'P0001',
            message = 'client_email_parent_id_not_found';
        end if;
        return jsonb_build_object('ok', false, 'code', 'parent_id_not_found');
      end if;

      if v_parent_status <> 'active' then
        if v_is_create_intent then
          raise exception using
            errcode = 'P0001',
            message = 'client_email_parent_episode_not_reopenable';
        end if;
        return jsonb_build_object('ok', false, 'code', 'parent_episode_not_reopenable');
      end if;
    else
      select s.id, s.status
        into v_parent_id, v_parent_status
      from public.client_email_needs_more_targets_sequences s
      where s.account_id = p_account_id
        and s.status = 'active'
      limit 1;

      if v_parent_id is not null then
        null;
      else
        if exists (
          select 1
          from public.client_email_needs_more_targets_sequences s
          where s.episode_key = p_parent_episode_key
            and s.status <> 'active'
        ) then
          if v_is_create_intent then
            raise exception using
              errcode = 'P0001',
              message = 'client_email_parent_episode_not_reopenable';
          end if;
          return jsonb_build_object('ok', false, 'code', 'parent_episode_not_reopenable');
        end if;

        insert into public.client_email_needs_more_targets_sequences (
          account_id,
          client_id,
          source_action_id,
          status,
          eligible_target_count_at_start,
          threshold_at_start,
          started_at,
          episode_key
        )
        values (
          p_account_id,
          p_client_id,
          p_source_action_id,
          'active',
          coalesce(p_eligible_target_count_at_start, 0),
          5,
          p_started_at,
          p_parent_episode_key
        )
        on conflict (episode_key) do nothing
        returning id into v_parent_id;

        if v_parent_id is not null then
          v_parent_created := true;
        else
          select s.id, s.status
            into v_parent_id, v_parent_status
          from public.client_email_needs_more_targets_sequences s
          where s.episode_key = p_parent_episode_key
          limit 1;

          if v_parent_status is distinct from 'active' then
            if v_is_create_intent then
              raise exception using
                errcode = 'P0001',
                message = 'client_email_parent_episode_not_reopenable';
            end if;
            return jsonb_build_object('ok', false, 'code', 'parent_episode_not_reopenable');
          end if;
        end if;
      end if;
    end if;
  else
    if p_parent_id is not null then
      select e.id, e.status
        into v_parent_id, v_parent_status
      from public.client_email_lifecycle_episodes e
      where e.id = p_parent_id
        and e.account_id = p_account_id
        and e.client_id = p_client_id
        and e.category = p_category
      limit 1;

      if v_parent_id is null then
        if v_is_create_intent then
          raise exception using
            errcode = 'P0001',
            message = 'client_email_parent_id_not_found';
        end if;
        return jsonb_build_object('ok', false, 'code', 'parent_id_not_found');
      end if;

      if v_parent_status <> 'active' then
        if v_is_create_intent then
          raise exception using
            errcode = 'P0001',
            message = 'client_email_parent_episode_not_reopenable';
        end if;
        return jsonb_build_object('ok', false, 'code', 'parent_episode_not_reopenable');
      end if;
    else
      select e.id, e.status
        into v_parent_id, v_parent_status
      from public.client_email_lifecycle_episodes e
      where e.account_id = p_account_id
          and e.category = p_category
          and e.status = 'active'
      limit 1;

      if v_parent_id is null then
        if exists (
          select 1
          from public.client_email_lifecycle_episodes e
          where e.episode_key = p_parent_episode_key
            and e.status <> 'active'
        ) then
          if v_is_create_intent then
            raise exception using
              errcode = 'P0001',
              message = 'client_email_parent_episode_not_reopenable';
          end if;
          return jsonb_build_object('ok', false, 'code', 'parent_episode_not_reopenable');
        end if;

        insert into public.client_email_lifecycle_episodes (
          account_id,
          client_id,
          category,
          source_action_id,
          status,
          started_at,
          episode_key
        )
        values (
          p_account_id,
          p_client_id,
          p_category,
          p_source_action_id,
          'active',
          p_started_at,
          p_parent_episode_key
        )
        on conflict (episode_key) do nothing
        returning id into v_parent_id;

        if v_parent_id is not null then
          v_parent_created := true;
        else
          select e.id, e.status
            into v_parent_id, v_parent_status
          from public.client_email_lifecycle_episodes e
          where e.episode_key = p_parent_episode_key
          limit 1;

          if v_parent_status is distinct from 'active' then
            if v_is_create_intent then
              raise exception using
                errcode = 'P0001',
                message = 'client_email_parent_episode_not_reopenable';
            end if;
            return jsonb_build_object('ok', false, 'code', 'parent_episode_not_reopenable');
          end if;
        end if;
      end if;
    end if;
  end if;

  if v_parent_id is null then
    if v_is_create_intent then
      raise exception using
        errcode = 'P0001',
        message = 'client_email_parent_create_failed';
    end if;
    return jsonb_build_object('ok', false, 'code', 'parent_create_failed');
  end if;

  if p_operation in ('open_lifecycle_episode', 'open_needs_more_sequence') then
    return jsonb_build_object(
      'ok', true,
      'parent', jsonb_build_object(
        'id', v_parent_id,
        'kind', v_parent_kind,
        'created', v_parent_created
      ),
      'intent', null
    );
  end if;

  if p_category = 'needs_more_target_accounts' then
    insert into public.client_email_send_intents (
      category,
      client_id,
      account_id,
      recipient_email,
      from_email,
      trigger,
      reminder_index,
      template_id,
      template_version,
      snapshot_subject,
      snapshot_body_text,
      snapshot_body_html,
      idempotency_key,
      status,
      intent_kind,
      sequence_id,
      lifecycle_episode_id,
      from_email_snapshot,
      support_email_snapshot
    )
    values (
      p_category,
      p_client_id,
      p_account_id,
      btrim(p_recipient_email),
      btrim(p_from_email),
      p_trigger,
      v_reminder_index,
      p_template_id,
      p_template_version,
      p_snapshot_subject,
      p_snapshot_body_text,
      p_snapshot_body_html,
      p_idempotency_key,
      'pending',
      'client',
      v_parent_id,
      null,
      btrim(p_from_email_snapshot),
      btrim(p_support_email_snapshot)
    )
    on conflict (idempotency_key) do nothing
    returning id into v_intent_id;
  else
    insert into public.client_email_send_intents (
      category,
      client_id,
      account_id,
      recipient_email,
      from_email,
      trigger,
      reminder_index,
      template_id,
      template_version,
      snapshot_subject,
      snapshot_body_text,
      snapshot_body_html,
      idempotency_key,
      status,
      intent_kind,
      sequence_id,
      lifecycle_episode_id,
      from_email_snapshot,
      support_email_snapshot
    )
    values (
      p_category,
      p_client_id,
      p_account_id,
      btrim(p_recipient_email),
      btrim(p_from_email),
      p_trigger,
      v_reminder_index,
      p_template_id,
      p_template_version,
      p_snapshot_subject,
      p_snapshot_body_text,
      p_snapshot_body_html,
      p_idempotency_key,
      'pending',
      'client',
      null,
      v_parent_id,
      btrim(p_from_email_snapshot),
      btrim(p_from_email_snapshot),
      btrim(p_support_email_snapshot)
    )
    on conflict (idempotency_key) do nothing
    returning id into v_intent_id;
  end if;

  v_intent_created := v_intent_id is not null;

  if v_intent_id is null then
    select *
      into v_existing_intent
    from public.client_email_send_intents i
    where i.idempotency_key = p_idempotency_key
    limit 1;

    if not found then
      raise exception using
        errcode = 'P0001',
        message = 'client_email_intent_create_failed';
    end if;

    if v_existing_intent.account_id is distinct from p_account_id
       or v_existing_intent.client_id is distinct from p_client_id
       or v_existing_intent.intent_kind is distinct from 'client'
       or v_existing_intent.category is distinct from p_category
       or v_existing_intent.trigger is distinct from p_trigger
       or v_existing_intent.reminder_index is distinct from v_reminder_index
       or (
         p_category = 'needs_more_target_accounts'
         and v_existing_intent.sequence_id is distinct from v_parent_id
       )
       or (
         p_category <> 'needs_more_target_accounts'
         and v_existing_intent.lifecycle_episode_id is distinct from v_parent_id
       ) then
      raise exception 'client_email_idempotency_identity_conflict'
        using errcode = '23514';
    end if;

    v_intent_id := v_existing_intent.id;
  end if;

  return jsonb_build_object(
    'ok', true,
    'parent', jsonb_build_object(
      'id', v_parent_id,
      'kind', v_parent_kind,
      'created', v_parent_created
    ),
    'intent', jsonb_build_object(
      'id', v_intent_id,
      'created', v_intent_created,
      'status', 'pending',
      'idempotency_key', p_idempotency_key
    )
  );
end;
$$;




COMMENT ON FUNCTION "public"."materialize_client_email_outbox_candidate_v1"("p_account_id" "uuid", "p_client_id" "uuid", "p_category" "text", "p_operation" "text", "p_parent_episode_key" "text", "p_started_at" timestamp with time zone, "p_source_action_id" "uuid", "p_eligible_target_count_at_start" integer, "p_recipient_email" "text", "p_idempotency_key" "text", "p_trigger" "text", "p_reminder_index" smallint, "p_template_id" "uuid", "p_template_version" integer, "p_snapshot_subject" "text", "p_snapshot_body_text" "text", "p_snapshot_body_html" "text", "p_from_email" "text", "p_from_email_snapshot" "text", "p_support_email_snapshot" "text", "p_parent_id" "uuid") IS 'Server-only transactional materialize for client email outbox. Create-intent operations validate recipient/snapshots before parent writes and raise on business failures to prevent orphan parents.';



CREATE OR REPLACE FUNCTION "public"."mutate_account_protection_list"("p_account_id" "uuid", "p_list_kind" "text", "p_operation" "text", "p_items" "text"[], "p_add_items" "text"[], "p_remove_items" "text"[], "p_source_surface" "text", "p_actor_auth_user_id" "uuid", "p_request_id" "text", "p_idempotency_key" "text", "p_expected_version" bigint, "p_request_fingerprint" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $_$
declare
  v_current_version bigint;
  v_new_version bigint;
  v_current_items text[];
  v_desired_items text[];
  v_updated_at timestamptz;
  v_existing_event public.account_protection_list_events%rowtype;
  v_action text;
  v_event_username text;
  v_reactivated boolean := false;
  v_changed boolean;
  v_account_status text;
  v_account_lifecycle text;
  v_account_archived_at timestamptz;
  v_account_trashed_at timestamptz;
begin
  if p_list_kind not in ('interaction_blacklist', 'unfollow_whitelist') then
    return jsonb_build_object('ok', false, 'error', 'invalid_list_kind');
  end if;
  if p_operation not in ('replace', 'patch', 'delete') then
    return jsonb_build_object('ok', false, 'error', 'invalid_operation');
  end if;
  if p_expected_version is null or p_expected_version < 0 then
    return jsonb_build_object('ok', false, 'error', 'invalid_expected_version');
  end if;
  if p_idempotency_key is null or char_length(p_idempotency_key) not between 1 and 200 then
    return jsonb_build_object('ok', false, 'error', 'invalid_idempotency_key');
  end if;
  if p_request_fingerprint is null or p_request_fingerprint !~ '^[a-f0-9]{64}$' then
    return jsonb_build_object('ok', false, 'error', 'invalid_request_fingerprint');
  end if;
  if p_source_surface is null or char_length(btrim(p_source_surface)) not between 1 and 64 then
    return jsonb_build_object('ok', false, 'error', 'invalid_source_surface');
  end if;
  if cardinality(coalesce(p_items, '{}'::text[])) > 1000
    or cardinality(coalesce(p_add_items, '{}'::text[])) > 1000
    or cardinality(coalesce(p_remove_items, '{}'::text[])) > 1000 then
    return jsonb_build_object('ok', false, 'error', 'too_many_items');
  end if;
  if exists (
    select 1
    from unnest(
      coalesce(p_items, '{}'::text[])
      || coalesce(p_add_items, '{}'::text[])
      || coalesce(p_remove_items, '{}'::text[])
    ) as candidate(username)
    where username is null
      or username <> lower(username)
      or username <> btrim(username)
      or char_length(username) not between 1 and 30
      or username !~ '^[a-z0-9._]+$'
      or username ~ '^\.'
      or username ~ '\.$'
      or username ~ '\.\.'
      or username ~ '://'
      or username ~ '/'
      or username ~ '^@'
  ) then
    return jsonb_build_object('ok', false, 'error', 'invalid_username');
  end if;

  select
    lower(coalesce(status, '')),
    lower(coalesce(admin_lifecycle_status, '')),
    archived_at,
    trashed_at
  into
    v_account_status,
    v_account_lifecycle,
    v_account_archived_at,
    v_account_trashed_at
  from public.ig_accounts
  where id = p_account_id
  for share;

  if not found then
    return jsonb_build_object('ok', false, 'error', 'account_not_found');
  end if;
  if v_account_archived_at is not null
    or v_account_trashed_at is not null
    or v_account_status in ('archived', 'trashed', 'cancelled', 'canceled', 'deleted')
    or v_account_lifecycle in ('archived', 'trashed', 'cancelled', 'canceled', 'deleted') then
    return jsonb_build_object('ok', false, 'error', 'account_lifecycle_conflict');
  end if;

  insert into public.account_protection_list_versions (account_id, list_kind, version)
  values (p_account_id, p_list_kind, 0)
  on conflict (account_id, list_kind) do nothing;

  select version
    into v_current_version
  from public.account_protection_list_versions
  where account_id = p_account_id and list_kind = p_list_kind
  for update;

  select *
    into v_existing_event
  from public.account_protection_list_events
  where account_id = p_account_id
    and list_kind = p_list_kind
    and idempotency_key = p_idempotency_key;

  select coalesce(array_agg(normalized_username order by normalized_username), '{}'::text[])
    into v_current_items
  from public.account_protection_list_entries
  where account_id = p_account_id and list_kind = p_list_kind and active;

  if v_existing_event.id is not null then
    if v_existing_event.metadata_safe ->> 'request_fingerprint' <> p_request_fingerprint then
      return jsonb_build_object(
        'ok', false,
        'error', 'idempotency_conflict',
        'version', v_current_version
      );
    end if;
    select updated_at into v_updated_at
    from public.account_protection_list_versions
    where account_id = p_account_id and list_kind = p_list_kind;
    return jsonb_build_object(
      'ok', true,
      'replayed', true,
      'items', to_jsonb(v_current_items),
      'size', cardinality(v_current_items),
      'version', v_current_version,
      'mutation_version', v_existing_event.new_version,
      'updated_at', v_updated_at
    );
  end if;

  if v_current_version <> p_expected_version then
    return jsonb_build_object(
      'ok', false,
      'error', 'version_conflict',
      'version', v_current_version
    );
  end if;

  if p_operation = 'replace' then
    select coalesce(array_agg(username order by username), '{}'::text[])
      into v_desired_items
    from (select distinct unnest(coalesce(p_items, '{}'::text[])) as username) desired;
  elsif p_operation = 'patch' then
    select coalesce(array_agg(username order by username), '{}'::text[])
      into v_desired_items
    from (
      select distinct username
      from unnest(v_current_items || coalesce(p_add_items, '{}'::text[])) as added(username)
      where username <> all(coalesce(p_remove_items, '{}'::text[]))
    ) desired;
  else
    select coalesce(array_agg(username order by username), '{}'::text[])
      into v_desired_items
    from unnest(v_current_items) as current_item(username)
    where username <> all(coalesce(p_remove_items, '{}'::text[]));
  end if;

  v_changed := v_current_items is distinct from v_desired_items;
  v_new_version := v_current_version + case when v_changed then 1 else 0 end;
  v_updated_at := now();

  if v_changed then
    if p_operation = 'patch' and cardinality(coalesce(p_add_items, '{}'::text[])) = 1 then
      select exists (
        select 1 from public.account_protection_list_entries
        where account_id = p_account_id
          and list_kind = p_list_kind
          and normalized_username = p_add_items[1]
          and not active
      ) into v_reactivated;
    end if;

    update public.account_protection_list_entries
    set active = false,
        source_surface = p_source_surface,
        updated_by_auth_user_id = p_actor_auth_user_id,
        version = v_new_version,
        updated_at = v_updated_at
    where account_id = p_account_id
      and list_kind = p_list_kind
      and active
      and normalized_username <> all(v_desired_items);

    insert into public.account_protection_list_entries (
      account_id,
      list_kind,
      normalized_username,
      active,
      source_surface,
      created_by_auth_user_id,
      updated_by_auth_user_id,
      version,
      created_at,
      updated_at
    )
    select
      p_account_id,
      p_list_kind,
      username,
      true,
      p_source_surface,
      p_actor_auth_user_id,
      p_actor_auth_user_id,
      v_new_version,
      v_updated_at,
      v_updated_at
    from unnest(v_desired_items) as desired(username)
    on conflict (account_id, list_kind, normalized_username)
    do update set
      active = true,
      source_surface = excluded.source_surface,
      updated_by_auth_user_id = excluded.updated_by_auth_user_id,
      version = excluded.version,
      updated_at = excluded.updated_at
    where not account_protection_list_entries.active;

    update public.account_protection_list_versions
    set version = v_new_version, updated_at = v_updated_at
    where account_id = p_account_id and list_kind = p_list_kind;
  else
    select updated_at into v_updated_at
    from public.account_protection_list_versions
    where account_id = p_account_id and list_kind = p_list_kind;
  end if;

  if p_operation = 'replace' then
    v_action := case when cardinality(v_desired_items) = 0 then 'clear' else 'replace' end;
  elsif p_operation = 'delete' then
    v_action := 'remove';
  elsif cardinality(coalesce(p_add_items, '{}'::text[])) > 0
    and cardinality(coalesce(p_remove_items, '{}'::text[])) = 0 then
    v_action := case when v_reactivated then 'reactivate' else 'add' end;
  elsif cardinality(coalesce(p_add_items, '{}'::text[])) = 0
    and cardinality(coalesce(p_remove_items, '{}'::text[])) > 0 then
    v_action := 'remove';
  else
    v_action := 'replace';
  end if;

  if p_operation = 'delete' and cardinality(coalesce(p_remove_items, '{}'::text[])) = 1 then
    v_event_username := p_remove_items[1];
  elsif p_operation = 'patch'
    and cardinality(coalesce(p_add_items, '{}'::text[])) + cardinality(coalesce(p_remove_items, '{}'::text[])) = 1 then
    v_event_username := coalesce(p_add_items[1], p_remove_items[1]);
  end if;

  insert into public.account_protection_list_events (
    account_id,
    list_kind,
    normalized_username,
    action,
    source_surface,
    actor_auth_user_id,
    request_id,
    idempotency_key,
    previous_version,
    new_version,
    metadata_safe
  ) values (
    p_account_id,
    p_list_kind,
    v_event_username,
    v_action,
    p_source_surface,
    p_actor_auth_user_id,
    p_request_id,
    p_idempotency_key,
    v_current_version,
    v_new_version,
    jsonb_build_object(
      'operation', p_operation,
      'add_count', cardinality(coalesce(p_add_items, '{}'::text[])),
      'remove_count', cardinality(coalesce(p_remove_items, '{}'::text[])),
      'item_count', cardinality(v_desired_items),
      'changed', v_changed,
      'request_fingerprint', p_request_fingerprint
    )
  );

  return jsonb_build_object(
    'ok', true,
    'replayed', false,
    'items', to_jsonb(v_desired_items),
    'size', cardinality(v_desired_items),
    'version', v_new_version,
    'mutation_version', v_new_version,
    'updated_at', v_updated_at
  );
end;
$_$;




CREATE OR REPLACE FUNCTION "public"."neutralize_ephemeral_verification_code_vault_secret"("p_secret_ref" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'vault'
    AS $_$
declare
  v_secret_ref text := btrim(coalesce(p_secret_ref, ''));
  v_secret_id_text text;
  v_secret_id uuid;
begin
  if auth.role() <> 'service_role' then
    raise exception 'service_role_required';
  end if;

  if v_secret_ref = '' or left(v_secret_ref, length('supabase_vault://')) <> 'supabase_vault://' then
    return jsonb_build_object('ok', false, 'reason', 'invalid_secret_ref');
  end if;

  v_secret_id_text := btrim(substr(v_secret_ref, length('supabase_vault://') + 1));
  if v_secret_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    return jsonb_build_object('ok', false, 'reason', 'vault_secret_id_invalid');
  end if;

  v_secret_id := v_secret_id_text::uuid;

  perform vault.update_secret(
    v_secret_id,
    jsonb_build_object('neutralized', true)::text,
    format('neutralized/instagram/verification-code/%s', v_secret_id::text),
    'Ephemeral Instagram verification code neutralized after consumption.'
  );

  return jsonb_build_object('ok', true, 'reason', 'neutralized');
exception
  when others then
    return jsonb_build_object('ok', false, 'reason', 'vault_neutralization_failed');
end;
$_$;




CREATE OR REPLACE FUNCTION "public"."normalize_assignment_slot_kind"("p_slot_kind" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case
    when p_slot_kind = 'outreach_40m' then 'outreach_short'
    else p_slot_kind
  end;
$$;




CREATE OR REPLACE FUNCTION "public"."normalize_ig_username"("p_username" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select lower(trim(p_username));
$$;




CREATE OR REPLACE FUNCTION "public"."persist_verified_follow_success_v1"("p_action_id" "uuid", "p_account_id" "uuid", "p_run_id" "uuid", "p_request_id" "uuid", "p_candidate_username" "text", "p_source_target_id" "uuid" DEFAULT NULL::"uuid", "p_source_ct_username" "text" DEFAULT NULL::"text", "p_followed_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_follow_state_after" "text" DEFAULT NULL::"text", "p_settings_revision_expected" "text" DEFAULT NULL::"text", "p_verification_method" "text" DEFAULT NULL::"text", "p_metadata_safe" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $_$
declare
  v_username text := lower(ltrim(trim(coalesce(p_candidate_username, '')), '@'));
  v_source_username text := lower(ltrim(trim(coalesce(p_source_ct_username, '')), '@'));
  v_follow_state text := lower(trim(coalesce(p_follow_state_after, '')));
  v_verification_method text := lower(trim(coalesce(p_verification_method, '')));
  v_metadata jsonb := coalesce(p_metadata_safe, '{}'::jsonb);
  v_followed_at timestamptz := p_followed_at;
  v_expected_revision timestamptz;
  v_settings public.ig_account_unfollow_settings;
  v_request public.account_run_requests;
  v_run public.ig_runs;
  v_target public.ig_targets;
  v_event public.ig_interaction_events;
  v_interaction public.ig_interacted_users;
  v_interaction_count integer := 0;
  v_event_inserted boolean := false;
  v_eligible_unfollow_at timestamptz;
  v_counter_applied boolean := false;
  v_counter_status text := 'not_applicable';
  v_invariants jsonb := jsonb_build_array(
    'account_request_run_consistent',
    'canonical_username_confirmed',
    'settings_locked_revision_match',
    'interaction_persisted',
    'audit_persisted',
    'counter_applied_or_not_applicable'
  );
begin
  if p_action_id is null or p_account_id is null or p_run_id is null or p_request_id is null then
    raise exception 'follow_persistence_identity_required' using errcode = '22023';
  end if;
  if v_username = '' or v_username !~ '^[a-z0-9._]{1,30}$' then
    raise exception 'follow_persistence_username_invalid' using errcode = '22023';
  end if;
  if v_followed_at is null or v_followed_at > now() + interval '5 minutes' then
    raise exception 'follow_persistence_followed_at_invalid' using errcode = '22023';
  end if;
  if v_follow_state <> 'following' then
    raise exception 'follow_persistence_state_not_verified' using errcode = '22023';
  end if;
  if v_verification_method = '' or char_length(v_verification_method) > 120 then
    raise exception 'follow_persistence_verification_method_invalid' using errcode = '22023';
  end if;
  if jsonb_typeof(v_metadata) is distinct from 'object'
     or pg_column_size(v_metadata) > 8192
     or public.jsonb_has_forbidden_safe_metadata_key(v_metadata) then
    raise exception 'follow_persistence_metadata_unsafe' using errcode = '22023';
  end if;
  begin
    v_expected_revision := nullif(trim(coalesce(p_settings_revision_expected, '')), '')::timestamptz;
  exception when others then
    raise exception 'follow_persistence_settings_revision_invalid' using errcode = '22023';
  end;
  if v_expected_revision is null then
    raise exception 'follow_persistence_settings_revision_required' using errcode = '22023';
  end if;

  select arr.* into v_request
  from public.account_run_requests as arr
  where arr.id = p_request_id
  for share;
  if v_request.id is null
     or v_request.account_id is distinct from p_account_id
     or v_request.run_id is distinct from p_run_id then
    raise exception 'follow_persistence_request_run_mismatch' using errcode = '22023';
  end if;

  select r.* into v_run
  from public.ig_runs as r
  where r.id = p_run_id
  for share;
  if v_run.id is null or v_run.account_id is distinct from p_account_id then
    raise exception 'follow_persistence_run_account_mismatch' using errcode = '22023';
  end if;

  if p_source_target_id is not null then
    select t.* into v_target
    from public.ig_targets as t
    where t.id = p_source_target_id
    for update;
    if v_target.id is null or v_target.account_id is distinct from p_account_id then
      raise exception 'follow_persistence_target_account_mismatch' using errcode = '22023';
    end if;
    if v_source_username <> '' and v_source_username not in (
      lower(ltrim(trim(coalesce(v_target.target_username, '')), '@')),
      lower(ltrim(trim(coalesce(v_target.normalized_username, '')), '@')),
      lower(ltrim(trim(coalesce(v_target.canonical_username, '')), '@'))
    ) then
      raise exception 'follow_persistence_target_username_mismatch' using errcode = '22023';
    end if;
  end if;

  insert into public.ig_interaction_events (
    id, account_id, run_id, username, source_profile,
    event_type, event_status, event_reason, event_at, payload,
    target_id, ct_id, source_target_id, source_target_username, request_id,
    interaction_type, interaction_status, evidence_source,
    evidence_confidence, evidence_summary, metadata_safe
  ) values (
    p_action_id, p_account_id, p_run_id, v_username, nullif(v_source_username, ''),
    'follow_verified_persisted_v1', 'processing', null, v_followed_at,
    jsonb_build_object('contract_version', 'follow_persistence_v1'),
    p_source_target_id, p_source_target_id, p_source_target_id, nullif(v_source_username, ''), p_request_id,
    'follow', 'processing', 'worker_follow_state_exact',
    'high', 'Exact Following state verified before transactional persistence.', v_metadata
  )
  on conflict (id) do nothing
  returning * into v_event;
  v_event_inserted := v_event.id is not null;

  if not v_event_inserted then
    select e.* into v_event
    from public.ig_interaction_events as e
    where e.id = p_action_id
    for update;
    if v_event.id is null
       or v_event.account_id is distinct from p_account_id
       or v_event.run_id is distinct from p_run_id
       or v_event.request_id is distinct from p_request_id
       or lower(v_event.username) <> v_username
       or v_event.source_target_id is distinct from p_source_target_id
       or v_event.event_type <> 'follow_verified_persisted_v1' then
      raise exception 'follow_persistence_action_id_conflict' using errcode = '23505';
    end if;
    if v_event.event_status = 'success'
       and coalesce((v_event.payload ->> 'follow_persisted')::boolean, false)
       and coalesce((v_event.payload ->> 'audit_persisted')::boolean, false)
       and coalesce((v_event.payload ->> 'counter_applied')::boolean, false)
       and coalesce((v_event.payload ->> 'settings_revision_match')::boolean, false) then
      return jsonb_build_object(
        'ok', true,
        'status', 'idempotent_replay',
        'action_id', p_action_id,
        'interaction_id', v_event.payload ->> 'interaction_id',
        'follow_persisted', true,
        'eligible_unfollow_at', v_event.payload ->> 'eligible_unfollow_at',
        'audit_persisted', true,
        'counter_applied', true,
        'settings_revision_match', true,
        'invariants_confirmed', coalesce(v_event.payload -> 'invariants_confirmed', v_invariants),
        'failure_reason', null
      );
    end if;
    raise exception 'follow_persistence_existing_action_incomplete' using errcode = '40001';
  end if;

  select s.* into v_settings
  from public.ig_account_unfollow_settings as s
  where s.account_id = p_account_id
  for update;
  if v_settings.account_id is null then
    raise exception 'follow_persistence_unfollow_settings_missing' using errcode = 'P0002';
  end if;
  if v_settings.updated_at is distinct from v_expected_revision then
    raise exception 'follow_persistence_settings_revision_mismatch' using errcode = '40001';
  end if;
  v_eligible_unfollow_at := v_followed_at + make_interval(days => v_settings.unfollow_after_days);

  select count(*) into v_interaction_count
  from public.ig_interacted_users as iu
  where iu.account_id = p_account_id and lower(iu.username) = v_username;
  if v_interaction_count > 1 then
    raise exception 'follow_persistence_casefold_ambiguous' using errcode = '23505';
  end if;

  select iu.* into v_interaction
  from public.ig_interacted_users as iu
  where iu.account_id = p_account_id and lower(iu.username) = v_username
  for update;

  if v_interaction.id is not null
     and v_interaction.unfollowed_at is null
     and coalesce(v_interaction.interaction_lifecycle_state, '') = 'active_following' then
    raise exception 'follow_persistence_active_interaction_exists' using errcode = '23505';
  end if;

  if v_interaction.id is null then
    insert into public.ig_interacted_users (
      account_id, run_id, username, source_profile, interaction_type,
      follow_status, was_successful, followed_at, last_interaction_at,
      payload, first_source_profile, last_source_profile, first_run_id, last_run_id,
      followed_by_bot, eligible_unfollow_at, interaction_lifecycle_state,
      ct_id, source_target_id, source_target_username, request_id,
      interaction_status, evidence_source, evidence_confidence,
      evidence_summary, metadata_safe
    ) values (
      p_account_id, p_run_id, v_username, nullif(v_source_username, ''), 'follow',
      'following', true, v_followed_at, v_followed_at,
      jsonb_build_object('follow_state_after', 'following', 'action_id', p_action_id),
      nullif(v_source_username, ''), nullif(v_source_username, ''), p_run_id, p_run_id,
      true, v_eligible_unfollow_at, 'active_following',
      p_source_target_id, p_source_target_id, nullif(v_source_username, ''), p_request_id,
      'success', 'worker_follow_state_exact', 'high',
      'Exact Following state verified before transactional persistence.', v_metadata
    ) returning * into v_interaction;
  else
    update public.ig_interacted_users as iu set
      run_id = p_run_id,
      username = v_username,
      source_profile = nullif(v_source_username, ''),
      interaction_type = 'follow',
      follow_status = 'following',
      was_successful = true,
      followed_at = v_followed_at,
      unfollowed_at = null,
      last_interaction_at = v_followed_at,
      updated_at = now(),
      payload = jsonb_build_object('follow_state_after', 'following', 'action_id', p_action_id),
      first_source_profile = coalesce(iu.first_source_profile, nullif(v_source_username, '')),
      last_source_profile = nullif(v_source_username, ''),
      first_run_id = coalesce(iu.first_run_id, p_run_id),
      last_run_id = p_run_id,
      followed_by_bot = true,
      eligible_unfollow_at = v_eligible_unfollow_at,
      unfollow_mode_applied = null,
      unfollow_result = null,
      unfollow_attempts = 0,
      last_unfollow_attempt_at = null,
      unfollow_skip_reason = null,
      interaction_lifecycle_state = 'active_following',
      ct_id = p_source_target_id,
      source_target_id = p_source_target_id,
      source_target_username = nullif(v_source_username, ''),
      request_id = p_request_id,
      interaction_status = 'success',
      evidence_source = 'worker_follow_state_exact',
      evidence_confidence = 'high',
      evidence_summary = 'Exact Following state verified before transactional persistence.',
      metadata_safe = v_metadata
    where iu.id = v_interaction.id
    returning * into v_interaction;
  end if;

  if p_source_target_id is not null then
    update public.ig_targets as t set
      follows_sent_count = coalesce(t.follows_sent_count, 0) + 1,
      last_successful_candidate_at = v_followed_at,
      last_action_at = v_followed_at,
      last_used_at = v_followed_at,
      metrics_updated_at = now(),
      updated_at = now()
    where t.id = p_source_target_id and t.account_id = p_account_id;
    if not found then
      raise exception 'follow_persistence_target_counter_failed' using errcode = 'P0002';
    end if;
    v_counter_status := 'applied';
  end if;
  v_counter_applied := true;

  update public.ig_interaction_events as e set
    event_status = 'success',
    interaction_status = 'success',
    event_reason = null,
    payload = jsonb_build_object(
      'contract_version', 'follow_persistence_v1',
      'interaction_id', v_interaction.id,
      'follow_persisted', true,
      'eligible_unfollow_at', v_eligible_unfollow_at,
      'audit_persisted', true,
      'counter_applied', v_counter_applied,
      'counter_status', v_counter_status,
      'settings_revision_match', true,
      'settings_revision', v_settings.updated_at,
      'verification_method', v_verification_method,
      'invariants_confirmed', v_invariants
    ),
    metadata_safe = v_metadata
  where e.id = p_action_id
  returning * into v_event;

  return jsonb_build_object(
    'ok', true,
    'status', 'created',
    'action_id', p_action_id,
    'interaction_id', v_interaction.id,
    'follow_persisted', true,
    'eligible_unfollow_at', v_eligible_unfollow_at,
    'audit_persisted', true,
    'counter_applied', true,
    'settings_revision_match', true,
    'invariants_confirmed', v_invariants,
    'failure_reason', null
  );
end;
$_$;




COMMENT ON FUNCTION "public"."persist_verified_follow_success_v1"("p_action_id" "uuid", "p_account_id" "uuid", "p_run_id" "uuid", "p_request_id" "uuid", "p_candidate_username" "text", "p_source_target_id" "uuid", "p_source_ct_username" "text", "p_followed_at" timestamp with time zone, "p_follow_state_after" "text", "p_settings_revision_expected" "text", "p_verification_method" "text", "p_metadata_safe" "jsonb") IS 'Atomically persists one exact Following verification, its J+N eligibility, source counter, and idempotent audit event.';



CREATE OR REPLACE FUNCTION "public"."read_instagram_credentials_vault_secret"("p_secret_ref" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'vault'
    AS $_$
declare
  v_secret_ref text := btrim(coalesce(p_secret_ref, ''));
  v_secret_id_text text;
  v_secret_id uuid;
  v_secret_value text;
begin
  if v_secret_ref = '' then
    return jsonb_build_object(
      'ok', false,
      'reason', 'invalid_secret_ref',
      'secret_provider', 'supabase_vault',
      'safe_ref_label', 'supabase_vault://[REDACTED]'
    );
  end if;

  if left(v_secret_ref, length('supabase_vault://')) <> 'supabase_vault://' then
    return jsonb_build_object(
      'ok', false,
      'reason', 'unsupported_secret_ref_provider',
      'secret_provider', 'supabase_vault',
      'safe_ref_label', 'supabase_vault://[REDACTED]'
    );
  end if;

  v_secret_id_text := btrim(substr(v_secret_ref, length('supabase_vault://') + 1));
  if v_secret_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    return jsonb_build_object(
      'ok', false,
      'reason', 'vault_secret_id_invalid',
      'secret_provider', 'supabase_vault',
      'safe_ref_label', 'supabase_vault://[REDACTED]'
    );
  end if;

  v_secret_id := v_secret_id_text::uuid;

  select ds.decrypted_secret
    into v_secret_value
  from vault.decrypted_secrets ds
  where ds.id = v_secret_id
  limit 1;

  if not found then
    return jsonb_build_object(
      'ok', false,
      'reason', 'vault_secret_not_found',
      'secret_provider', 'supabase_vault',
      'safe_ref_label', 'supabase_vault://[REDACTED]'
    );
  end if;

  if coalesce(v_secret_value, '') = '' then
    return jsonb_build_object(
      'ok', false,
      'reason', 'vault_secret_empty',
      'secret_provider', 'supabase_vault',
      'safe_ref_label', 'supabase_vault://[REDACTED]'
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'secret_value', v_secret_value,
    'secret_provider', 'supabase_vault',
    'safe_ref_label', 'supabase_vault://[REDACTED]'
  );
exception
  when others then
    return jsonb_build_object(
      'ok', false,
      'reason', 'vault_read_failed',
      'secret_provider', 'supabase_vault',
      'safe_ref_label', 'supabase_vault://[REDACTED]'
    );
end;
$_$;




COMMENT ON FUNCTION "public"."read_instagram_credentials_vault_secret"("p_secret_ref" "text") IS 'Entry 2E-5H-2 service-role-only Supabase Vault read helper for worker-side Instagram credentials. Returns a minimal safe envelope; callers must never log raw responses.';



CREATE OR REPLACE FUNCTION "public"."reclaim_stale_account_run_requests"("p_worker_id" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ declare v_count integer := 0; v_reclaimed integer := 0; begin update public.account_run_requests arr set status = 'queued', claimed_by = null, claimed_at = null, lease_expires_at = null, updated_at = now() where arr.status in ('claimed', 'starting') and arr.run_id is null and arr.lease_expires_at is not null and arr.lease_expires_at <= now() and arr.cancel_requested_at is null; get diagnostics v_reclaimed = row_count; v_count := v_count + v_reclaimed; update public.account_run_requests arr set status = 'failed', completed_at = now(), error_code = 'stale_claim_timeout', error_message_safe = 'Dispatcher claim lease expired before run linked.', lease_expires_at = null, updated_at = now() where arr.status = 'running' and arr.run_id is null and arr.lease_expires_at is not null and arr.lease_expires_at <= now() and arr.cancel_requested_at is null; get diagnostics v_reclaimed = row_count; v_count := v_count + v_reclaimed; return v_count; end; $$;




CREATE OR REPLACE FUNCTION "public"."reconcile_account_package_runtime_contract"("p_account_id" "uuid", "p_source" "text" DEFAULT 'canonical_reconcile'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_result jsonb;
  v_limits jsonb;
  v_previous_guard text := coalesce(current_setting('bmb.package_contract_reconcile', true), '');
begin
  perform set_config('bmb.package_contract_reconcile', 'on', true);
  v_result := public.reconcile_account_package_runtime_contract_legacy_limit_restore_v1(
    p_account_id,
    p_source
  );
  v_limits := public.apply_account_follow_limit_provenance_v1(p_account_id);
  perform set_config('bmb.package_contract_reconcile', v_previous_guard, true);
  return coalesce(v_result, '{}'::jsonb)
    || jsonb_build_object('follow_limit_provenance', v_limits);
exception when others then
  perform set_config('bmb.package_contract_reconcile', v_previous_guard, true);
  raise;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."reconcile_account_package_runtime_contract_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_account_id uuid;
begin
  if coalesce(current_setting('bmb.package_contract_reconcile', true), '') = 'on' then
    return new;
  end if;
  v_account_id := case
    when tg_table_name = 'client_account_entitlements' then coalesce(new.account_id, old.account_id)
    else new.account_id
  end;
  if v_account_id is null then return new; end if;
  begin
    perform public.reconcile_account_package_runtime_contract(v_account_id, tg_table_name || '_trigger');
  exception when others then
    insert into public.account_package_runtime_contract_events (
      account_id, event_type, source, details_safe
    ) values (
      v_account_id, 'package_runtime_contract_blocked', tg_table_name || '_trigger',
      jsonb_build_object('reason', case when sqlerrm in ('package_settings_incomplete','assignment_package_mismatch','app_instance_package_mismatch','clone_package_mismatch','runtime_profile_mismatch') then sqlerrm else 'contract_reconcile_failed' end)
    );
  end;
  return new;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."reconcile_account_package_runtime_contract_exact_v1"("p_account_id" "uuid", "p_source" "text" DEFAULT 'canonical_reconcile'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_package public.commercial_packages%rowtype;
  v_runtime public.commercial_package_runtime_settings%rowtype;
  v_account_package public.account_commercial_packages%rowtype;
  v_assignment public.account_assignments%rowtype;
  v_instance public.phone_app_instances%rowtype;
  v_subscription_type text;
  v_expected_clone_mode text;
  v_outreach_enabled boolean := false;
  v_outreach_day integer := 0;
  v_outreach_session integer := 0;
  v_welcome_day integer := 0;
  v_welcome_session integer := 0;
  v_settings_count integer := 0;
begin
  if p_account_id is null then
    raise exception 'package_settings_incomplete';
  end if;

  select acp.* into v_account_package
  from public.account_commercial_packages acp
  where acp.account_id = p_account_id
    and acp.status = 'active'
    and (acp.ends_at is null or acp.ends_at > now())
  order by acp.starts_at desc, acp.created_at desc
  limit 1
  for update;

  if v_account_package.id is null then
    raise exception 'package_settings_incomplete';
  end if;

  select cp.* into v_package
  from public.commercial_packages cp
  where cp.code = v_account_package.package_code
    and cp.active = true;

  if v_package.code is null
     or v_package.default_follow_day_cap is null
     or v_package.default_follow_session_cap is null
     or v_package.default_unfollow_day_cap is null
     or v_package.default_unfollow_session_cap is null then
    raise exception 'package_settings_incomplete';
  end if;

  select prs.* into v_runtime
  from public.commercial_package_runtime_settings prs
  where prs.package_code = v_package.code;
  if v_runtime.package_code is null then
    raise exception 'package_settings_incomplete';
  end if;

  if not exists (
    select 1
    from public.client_account_entitlements cae
    where cae.account_id = p_account_id
      and cae.status = 'entitlement_consumed'
      and cae.commercial_package_code = v_account_package.package_code
  ) then
    raise exception 'package_settings_incomplete';
  end if;

  select aa.* into v_assignment
  from public.account_assignments aa
  where aa.account_id = p_account_id
    and aa.status in ('pending', 'reserved', 'active')
  order by aa.updated_at desc, aa.created_at desc
  limit 1
  for update;

  if v_assignment.id is null
     or v_assignment.device_id is null
     or v_assignment.app_instance_id is null then
    raise exception 'assignment_package_mismatch';
  end if;

  select pai.* into v_instance
  from public.phone_app_instances pai
  where pai.id = v_assignment.app_instance_id
  for update;

  if v_instance.id is null
     or v_instance.device_id <> v_assignment.device_id
     or nullif(trim(v_instance.package_name), '') is null
     or not coalesce(v_instance.is_launchable, false)
     or not coalesce(v_instance.usable_for_auto_login, false) then
    raise exception 'app_instance_package_mismatch';
  end if;

  select cs.subscription_type into v_subscription_type
  from public.client_subscription_accounts csa
  join public.client_subscriptions cs on cs.id = csa.subscription_id
  where csa.account_id = p_account_id
    and csa.status = 'active'
    and cs.status = 'active'
  order by cs.starts_at desc, cs.created_at desc
  limit 1;

  if nullif(trim(v_subscription_type), '') is null
     or v_assignment.assignment_type is distinct from v_subscription_type then
    raise exception 'runtime_profile_mismatch';
  end if;

  v_expected_clone_mode := case
    when v_instance.instance_type = 'primary_app' or coalesce(v_instance.instance_index, 0) = 0 then 'off'
    else 'clone_' || v_instance.instance_index::text
  end;

  select count(*) into v_settings_count
  from public.ig_account_settings s
  where s.account_id = p_account_id
    and s.likes_per_follow_min is not null
    and s.likes_per_follow_max is not null
    and s.total_likes_limit is not null;

  if v_settings_count <> 1 then
    raise exception 'package_settings_incomplete';
  end if;

  select exists (
    select 1
    from public.client_account_entitlements cae
    where cae.account_id = p_account_id
      and cae.status = 'entitlement_consumed'
      and (
        nullif(trim(cae.outreach_addon_key), '') is not null
        or nullif(trim(cae.outreach_variant), '') is not null
        or nullif(trim(cae.backend_addon_code), '') is not null
      )
  ) into v_outreach_enabled;

  if v_outreach_enabled then
    select coalesce(cp.default_outreach_day_cap, 0)
    into v_outreach_day
    from public.commercial_packages cp
    where cp.code = 'outreach_standalone' and cp.active = true;
    if coalesce(v_outreach_day, 0) <= 0 then
      raise exception 'package_settings_incomplete';
    end if;
    v_outreach_session := least(v_outreach_day, v_runtime.outreach_per_session_limit);
  end if;

  v_welcome_day := case
    when coalesce(v_package.default_welcome_enabled, false)
      then coalesce(v_package.default_welcome_day_cap, 0)
    else 0
  end;
  v_welcome_session := least(v_welcome_day, v_runtime.welcome_per_session_limit);

  update public.ig_accounts
  set clone_mode = v_expected_clone_mode,
      device_name = (select coalesce(pd.name, pd.device_name) from public.phone_devices pd where pd.id = v_assignment.device_id),
      updated_at = now()
  where id = p_account_id;

  update public.ig_account_settings
  set app_package = v_instance.package_name,
      clone_mode = v_expected_clone_mode,
      cloned_app_mode = v_expected_clone_mode <> 'off',
      follow_enabled = v_subscription_type = 'full_cycle',
      like_enabled = v_subscription_type = 'full_cycle',
      unfollow_enabled = v_subscription_type = 'full_cycle',
      welcome_dm_enabled = v_subscription_type = 'full_cycle' and coalesce(v_package.default_welcome_enabled, false),
      cold_dm_enabled = v_outreach_enabled,
      max_actions_per_day = v_package.default_follow_day_cap,
      follow_limit = v_package.default_follow_session_cap,
      max_follow_per_run = v_package.default_follow_session_cap,
      total_unfollows_limit = v_package.default_unfollow_day_cap,
      likes_per_follow_min = v_runtime.likes_per_follow_min,
      likes_per_follow_max = v_runtime.likes_per_follow_max,
      total_likes_limit = v_runtime.likes_per_day_limit,
      warmup_mode = v_runtime.warmup_enabled,
      updated_at = now()
  where account_id = p_account_id;

  if not found then
    raise exception 'package_settings_incomplete';
  end if;

  insert into public.account_follow_source_settings (
    account_id, max_follows_per_target_per_run, max_targets_per_run, updated_at, updated_by, metadata
  ) values (
    p_account_id, v_runtime.max_follows_per_target_per_run, v_runtime.max_targets_per_run,
    now(), coalesce(nullif(trim(p_source), ''), 'canonical_reconcile'),
    jsonb_build_object('source', 'canonical_package_runtime_contract', 'package_code', v_package.code)
  )
  on conflict (account_id) do update
  set max_follows_per_target_per_run = excluded.max_follows_per_target_per_run,
      max_targets_per_run = excluded.max_targets_per_run,
      updated_at = excluded.updated_at,
      updated_by = excluded.updated_by,
      metadata = coalesce(public.account_follow_source_settings.metadata, '{}'::jsonb) || excluded.metadata;

  insert into public.ig_account_unfollow_settings (
    account_id, unfollow_enabled, unfollow_after_days, unfollow_mode,
    unfollow_per_session_limit, unfollow_per_day_limit, runtime_cap_mode,
    runtime_safety_cap, package_default_snapshot, updated_at
  ) values (
    p_account_id, v_subscription_type = 'full_cycle', v_runtime.unfollow_after_days, 'unfollow',
    v_package.default_unfollow_session_cap, v_package.default_unfollow_day_cap,
    'prod_normal', null,
    jsonb_build_object(
      'source', 'commercial_packages',
      'package_code', v_package.code,
      'unfollow_day', v_package.default_unfollow_day_cap,
      'unfollow_session', v_package.default_unfollow_session_cap
    ),
    now()
  )
  on conflict (account_id) do update
  set unfollow_enabled = excluded.unfollow_enabled,
      unfollow_after_days = excluded.unfollow_after_days,
      unfollow_per_session_limit = excluded.unfollow_per_session_limit,
      unfollow_per_day_limit = excluded.unfollow_per_day_limit,
      runtime_cap_mode = excluded.runtime_cap_mode,
      runtime_safety_cap = excluded.runtime_safety_cap,
      package_default_snapshot = excluded.package_default_snapshot,
      updated_at = excluded.updated_at;

  insert into public.account_warmup_settings (
    account_id, warmup_enabled, package_started_at, warmup_profile_code,
    day_1_follow_cap, day_2_follow_cap, day_3_follow_cap, day_4_plus_follow_cap,
    status, updated_at
  ) values (
    p_account_id, v_runtime.warmup_enabled, v_account_package.starts_at,
    v_runtime.warmup_profile_code, v_runtime.warmup_day_1_cap,
    v_runtime.warmup_day_2_cap, v_runtime.warmup_day_3_cap,
    v_package.default_follow_day_cap, 'active', now()
  )
  on conflict (account_id) do update
  set warmup_enabled = excluded.warmup_enabled,
      package_started_at = excluded.package_started_at,
      warmup_profile_code = excluded.warmup_profile_code,
      day_1_follow_cap = excluded.day_1_follow_cap,
      day_2_follow_cap = excluded.day_2_follow_cap,
      day_3_follow_cap = excluded.day_3_follow_cap,
      day_4_plus_follow_cap = excluded.day_4_plus_follow_cap,
      status = excluded.status,
      updated_at = excluded.updated_at;

  insert into public.ig_account_dm_settings (
    account_id, welcome_enabled, outreach_enabled,
    welcome_per_session_limit, welcome_per_day_limit,
    outreach_per_session_limit, outreach_per_day_limit,
    total_dm_per_day_limit, updated_at
  ) values (
    p_account_id,
    v_subscription_type = 'full_cycle' and coalesce(v_package.default_welcome_enabled, false),
    v_outreach_enabled,
    v_welcome_session, v_welcome_day,
    v_outreach_session, v_outreach_day,
    v_welcome_day + v_outreach_day,
    now()
  )
  on conflict (account_id) do update
  set welcome_enabled = excluded.welcome_enabled,
      outreach_enabled = excluded.outreach_enabled,
      welcome_per_session_limit = excluded.welcome_per_session_limit,
      welcome_per_day_limit = excluded.welcome_per_day_limit,
      outreach_per_session_limit = excluded.outreach_per_session_limit,
      outreach_per_day_limit = excluded.outreach_per_day_limit,
      total_dm_per_day_limit = excluded.total_dm_per_day_limit,
      updated_at = excluded.updated_at;

  return jsonb_build_object(
    'ok', true,
    'reason', 'package_runtime_contract_reconciled',
    'account_id', p_account_id,
    'commercial_package_code', v_package.code,
    'runtime_profile', v_subscription_type,
    'assignment_id', v_assignment.id,
    'device_id', v_assignment.device_id,
    'app_instance_id', v_instance.id,
    'clone_mode', v_expected_clone_mode,
    'android_package_name', v_instance.package_name,
    'source', coalesce(nullif(trim(p_source), ''), 'canonical_reconcile')
  );
end;
$$;




CREATE OR REPLACE FUNCTION "public"."reconcile_account_package_runtime_contract_legacy_limit_restore"("p_account_id" "uuid", "p_source" "text" DEFAULT 'canonical_reconcile'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_source text := coalesce(nullif(trim(p_source), ''), 'canonical_reconcile');
  v_previous_guard text := coalesce(current_setting('bmb.package_contract_reconcile', true), '');
  v_before_status jsonb;
  v_after_status jsonb;
  v_account public.ig_accounts%rowtype;
  v_assignment public.account_assignments%rowtype;
  v_package_caps jsonb;
  v_package_follow_day integer;
  v_package_follow_session integer;
  v_package_unfollow_day integer;
  v_package_unfollow_session integer;
  v_follow_day integer;
  v_follow_session integer;
  v_follow_run integer;
  v_unfollow_day integer;
  v_unfollow_session integer;
  v_welcome_day integer;
  v_welcome_session integer;
  v_outreach_day integer;
  v_outreach_session integer;
  v_total_dm_day integer;
  v_result jsonb;
  v_changed_fields jsonb := '{}'::jsonb;
begin
  if p_account_id is null then
    raise exception 'package_settings_incomplete';
  end if;

  select * into v_account from public.ig_accounts where id = p_account_id for update;
  if v_account.id is null then
    raise exception 'package_settings_incomplete';
  end if;
  if v_account.status in ('archived', 'trashed')
     or v_account.archived_at is not null
     or v_account.trashed_at is not null then
    return jsonb_build_object('ok', true, 'reason', 'account_archived_skipped', 'account_id', p_account_id, 'source', v_source, 'changed', false);
  end if;

  v_before_status := public.account_package_runtime_contract_status(p_account_id);
  if coalesce((v_before_status ->> 'ok')::boolean, false) then
    return jsonb_build_object('ok', true, 'reason', 'package_runtime_contract_already_compliant', 'account_id', p_account_id, 'source', v_source, 'changed', false, 'contract', v_before_status);
  end if;

  select aa.* into v_assignment
  from public.account_assignments aa
  where aa.account_id = p_account_id and aa.status in ('pending', 'reserved', 'active')
  order by aa.updated_at desc, aa.created_at desc limit 1 for update;

  select aps.package_caps into v_package_caps
  from public.account_package_summary aps where aps.account_id = p_account_id;
  v_package_follow_day := coalesce((v_package_caps ->> 'follow_day')::integer, 0);
  v_package_follow_session := coalesce((v_package_caps ->> 'follow_session')::integer, 0);
  v_package_unfollow_day := coalesce((v_package_caps ->> 'unfollow_day')::integer, 0);
  v_package_unfollow_session := coalesce((v_package_caps ->> 'unfollow_session')::integer, 0);
  if least(v_package_follow_day, v_package_follow_session, v_package_unfollow_day, v_package_unfollow_session) <= 0 then
    raise exception 'package_settings_incomplete';
  end if;

  select s.max_actions_per_day, s.follow_limit, s.max_follow_per_run
  into v_follow_day, v_follow_session, v_follow_run
  from public.ig_account_settings s
  where s.account_id = p_account_id
  order by s.updated_at desc nulls last, s.created_at desc nulls last limit 1;

  select u.unfollow_per_day_limit, u.unfollow_per_session_limit
  into v_unfollow_day, v_unfollow_session
  from public.ig_account_unfollow_settings u where u.account_id = p_account_id;

  select d.welcome_per_day_limit, d.welcome_per_session_limit,
         d.outreach_per_day_limit, d.outreach_per_session_limit,
         d.total_dm_per_day_limit
  into v_welcome_day, v_welcome_session, v_outreach_day, v_outreach_session,
       v_total_dm_day
  from public.ig_account_dm_settings d where d.account_id = p_account_id;

  -- A missing legacy settings row can be initialized safely from schema
  -- defaults; the exact materializer below fills every contract field.
  if not exists (select 1 from public.ig_account_settings where account_id = p_account_id) then
    insert into public.ig_account_settings (account_id) values (p_account_id);
    v_changed_fields := v_changed_fields || jsonb_build_object('ig_account_settings', 'LEGACY_DEFAULT_MISSING');
  end if;

  perform set_config('bmb.package_contract_reconcile', 'on', true);
  if v_before_status ->> 'entitlement_source' = 'legacy_active_subscription_package' then
    v_result := public.reconcile_legacy_account_assignment_binding_v1(p_account_id, v_source);
  else
    v_result := public.reconcile_account_package_runtime_contract_exact_v1(p_account_id, v_source);
  end if;

  -- Restore only explicit positive lower account overrides. Above-package,
  -- zero and null values stay corrected to the package materializer value.
  update public.ig_account_settings s
  set max_actions_per_day = case when v_follow_day between 1 and v_package_follow_day then v_follow_day else s.max_actions_per_day end,
      follow_limit = case when v_follow_session between 1 and v_package_follow_session then v_follow_session else s.follow_limit end,
      max_follow_per_run = case
        when v_follow_run between 1 and least(v_package_follow_session,
             case when v_follow_session between 1 and v_package_follow_session then v_follow_session else s.follow_limit end)
          then v_follow_run
        else least(s.max_follow_per_run, s.follow_limit)
      end,
      updated_at = case
        when (s.max_actions_per_day, s.follow_limit, s.max_follow_per_run) is distinct from (
          case when v_follow_day between 1 and v_package_follow_day then v_follow_day else s.max_actions_per_day end,
          case when v_follow_session between 1 and v_package_follow_session then v_follow_session else s.follow_limit end,
          case
            when v_follow_run between 1 and least(v_package_follow_session,
                 case when v_follow_session between 1 and v_package_follow_session then v_follow_session else s.follow_limit end)
              then v_follow_run
            else least(s.max_follow_per_run, s.follow_limit)
          end
        ) then now() else s.updated_at end
  where s.account_id = p_account_id;

  update public.ig_account_unfollow_settings u
  set unfollow_per_day_limit = case when v_unfollow_day between 1 and v_package_unfollow_day then v_unfollow_day else u.unfollow_per_day_limit end,
      unfollow_per_session_limit = case when v_unfollow_session between 1 and v_package_unfollow_session then v_unfollow_session else u.unfollow_per_session_limit end,
      updated_at = case
        when (u.unfollow_per_day_limit, u.unfollow_per_session_limit) is distinct from (
          case when v_unfollow_day between 1 and v_package_unfollow_day then v_unfollow_day else u.unfollow_per_day_limit end,
          case when v_unfollow_session between 1 and v_package_unfollow_session then v_unfollow_session else u.unfollow_per_session_limit end
        ) then now() else u.updated_at end
  where u.account_id = p_account_id;

  -- DM values are inherited at provisioning, but explicit positive lower caps
  -- remain safe. Disabled domains remain zeroed by the exact materializer.
  update public.ig_account_dm_settings d
  set welcome_per_day_limit = case when d.welcome_enabled and v_welcome_day between 1 and d.welcome_per_day_limit then v_welcome_day else d.welcome_per_day_limit end,
      welcome_per_session_limit = case when d.welcome_enabled and v_welcome_session between 1 and least(d.welcome_per_session_limit, d.welcome_per_day_limit) then v_welcome_session else d.welcome_per_session_limit end,
      outreach_per_day_limit = case when d.outreach_enabled and v_outreach_day between 1 and d.outreach_per_day_limit then v_outreach_day else d.outreach_per_day_limit end,
      outreach_per_session_limit = case when d.outreach_enabled and v_outreach_session between 1 and least(d.outreach_per_session_limit, d.outreach_per_day_limit) then v_outreach_session else d.outreach_per_session_limit end,
      updated_at = now()
  where d.account_id = p_account_id;

  -- Compute the combined ceiling from the restored domain caps, then preserve a
  -- positive lower combined override when one existed before reconciliation.
  update public.ig_account_dm_settings d
  set total_dm_per_day_limit = case
        when v_total_dm_day between 1 and
          ((case when d.welcome_enabled then d.welcome_per_day_limit else 0 end) +
           (case when d.outreach_enabled then d.outreach_per_day_limit else 0 end))
          then v_total_dm_day
        else
          (case when d.welcome_enabled then d.welcome_per_day_limit else 0 end) +
          (case when d.outreach_enabled then d.outreach_per_day_limit else 0 end)
      end,
      updated_at = case
        when d.total_dm_per_day_limit is distinct from case
          when v_total_dm_day between 1 and
            ((case when d.welcome_enabled then d.welcome_per_day_limit else 0 end) +
             (case when d.outreach_enabled then d.outreach_per_day_limit else 0 end))
            then v_total_dm_day
          else
            (case when d.welcome_enabled then d.welcome_per_day_limit else 0 end) +
            (case when d.outreach_enabled then d.outreach_per_day_limit else 0 end)
        end then now() else d.updated_at end
  where d.account_id = p_account_id;

  perform set_config('bmb.package_contract_reconcile', v_previous_guard, true);
  v_after_status := public.account_package_runtime_contract_status(p_account_id);
  if not coalesce((v_after_status ->> 'ok')::boolean, false) then
    raise exception '%', coalesce(v_after_status ->> 'reason', 'package_settings_incomplete');
  end if;

  insert into public.account_package_runtime_contract_events (
    account_id, assignment_id, event_type, source, idempotency_key, details_safe
  ) values (
    p_account_id, v_assignment.id, 'package_runtime_contract_reconciled', v_source,
    left('contract-reconcile:' || p_account_id::text || ':' || coalesce(v_assignment.id::text, 'none') || ':' || v_source, 205)
      || ':' || md5(v_after_status::text),
    jsonb_build_object(
      'before_reason', v_before_status ->> 'reason',
      'after_reason', v_after_status ->> 'reason',
      'commercial_package_code', v_after_status ->> 'commercial_package_code',
      'override_policy', 'positive_account_override_lte_package',
      'missing_fields', v_changed_fields
    )
  ) on conflict (idempotency_key) where idempotency_key is not null do nothing;

  return jsonb_build_object(
    'ok', true, 'reason', 'package_runtime_contract_reconciled',
    'account_id', p_account_id, 'source', v_source, 'changed', true,
    'contract', v_after_status, 'materializer', v_result
  );
exception when others then
  perform set_config('bmb.package_contract_reconcile', v_previous_guard, true);
  raise;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."reconcile_legacy_account_assignment_binding_v1"("p_account_id" "uuid", "p_source" "text" DEFAULT 'canonical_reconcile'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_account_package public.account_commercial_packages%rowtype;
  v_assignment public.account_assignments%rowtype;
  v_instance public.phone_app_instances%rowtype;
  v_subscription_type text;
  v_expected_clone_mode text;
begin
  select acp.* into v_account_package
  from public.account_commercial_packages acp
  where acp.account_id = p_account_id
    and acp.status = 'active'
    and (acp.ends_at is null or acp.ends_at > now())
  order by acp.starts_at desc, acp.created_at desc
  limit 1
  for update;

  if v_account_package.id is null
     or exists (
       select 1
       from public.client_account_entitlements cae
       where cae.account_id = p_account_id
         and cae.status = 'entitlement_consumed'
     ) then
    raise exception 'legacy_package_contract_not_applicable';
  end if;

  select cs.subscription_type into v_subscription_type
  from public.client_subscription_accounts csa
  join public.client_subscriptions cs on cs.id = csa.subscription_id
  where csa.account_id = p_account_id
    and csa.status = 'active'
    and cs.status = 'active'
  order by cs.starts_at desc, cs.created_at desc
  limit 1;

  select aa.* into v_assignment
  from public.account_assignments aa
  where aa.account_id = p_account_id
    and aa.status in ('pending', 'reserved', 'active')
  order by aa.updated_at desc, aa.created_at desc
  limit 1
  for update;

  if v_subscription_type is null
     or v_assignment.id is null
     or v_assignment.device_id is null
     or v_assignment.app_instance_id is null
     or v_assignment.assignment_type is distinct from v_subscription_type then
    raise exception 'runtime_profile_mismatch';
  end if;

  select pai.* into v_instance
  from public.phone_app_instances pai
  where pai.id = v_assignment.app_instance_id
  for update;

  if v_instance.id is null
     or v_instance.device_id is distinct from v_assignment.device_id
     or nullif(trim(v_instance.package_name), '') is null
     or not coalesce(v_instance.is_launchable, false)
     or not coalesce(v_instance.usable_for_auto_login, false) then
    raise exception 'app_instance_package_mismatch';
  end if;

  v_expected_clone_mode := case
    when v_instance.instance_type = 'primary_app' or coalesce(v_instance.instance_index, 0) = 0 then 'off'
    else 'clone_' || v_instance.instance_index::text
  end;

  update public.ig_accounts
  set clone_mode = v_expected_clone_mode,
      device_name = (
        select coalesce(pd.name, pd.device_name)
        from public.phone_devices pd
        where pd.id = v_assignment.device_id
      ),
      updated_at = now()
  where id = p_account_id;

  update public.ig_account_settings
  set app_package = v_instance.package_name,
      clone_mode = v_expected_clone_mode,
      cloned_app_mode = v_expected_clone_mode <> 'off',
      updated_at = now()
  where account_id = p_account_id;

  if not found then
    raise exception 'package_settings_incomplete';
  end if;

  return jsonb_build_object(
    'ok', true,
    'reason', 'legacy_assignment_package_binding_reconciled',
    'account_id', p_account_id,
    'commercial_package_code', v_account_package.package_code,
    'runtime_profile', v_subscription_type,
    'assignment_id', v_assignment.id,
    'app_instance_id', v_instance.id,
    'clone_mode', v_expected_clone_mode,
    'android_package_name', v_instance.package_name,
    'source', coalesce(nullif(trim(p_source), ''), 'canonical_reconcile')
  );
end;
$$;




CREATE OR REPLACE FUNCTION "public"."reconcile_resolved_incident_resume_windows_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_row record;
  v_assignment public.account_assignments%rowtype;
  v_authorization_id uuid;
  v_count integer := 0;
begin
  for v_row in
    select i.id as incident_id, i.account_id, i.run_id, i.incident_type,
           i.reason, i.failure_reason, p.id as resume_plan_id,
           coalesce(p.test, false) as test
    from public.account_incidents i
    join lateral (
      select rp.* from public.account_session_resume_plans rp
      where rp.account_id = i.account_id and rp.run_id = i.run_id
        and rp.resume_state = 'awaiting_human_resume_authorization'
      order by rp.last_updated_at desc nulls last, rp.created_at desc
      limit 1
    ) p on true
    where i.status = 'resolved'
      and not exists (
        select 1 from public.incident_resume_authorizations a
        where a.incident_id = i.id and a.status = 'armed'
      )
    for update of i skip locked
  loop
    select aa.* into v_assignment
    from public.account_assignments aa
    where aa.account_id = v_row.account_id
      and aa.status in ('reserved','active')
      and aa.starts_at <= now() and now() < aa.ends_at
      and coalesce(aa.schedule_mode, '') <> 'manual_only'
    order by aa.starts_at desc
    limit 1;
    if v_assignment.id is null then continue; end if;

    v_authorization_id := null;
    insert into public.incident_resume_authorizations (
      incident_id, account_id, run_id, resume_plan_id, resume_window_key,
      scheduled_window_start, scheduled_window_end, status, armed_source,
      metadata_safe, test
    ) values (
      v_row.incident_id, v_row.account_id, v_row.run_id, v_row.resume_plan_id,
      v_row.account_id::text || ':' || v_assignment.starts_at::text,
      v_assignment.starts_at, v_assignment.ends_at, 'armed',
      'resolved_incident_reconciliation',
      jsonb_build_object(
        'incident_type', v_row.incident_type,
        'reason_code', coalesce(v_row.reason, v_row.failure_reason),
        'generic_resolved_incident_rule', true
      ), v_row.test
    ) on conflict do nothing returning id into v_authorization_id;

    if v_authorization_id is not null then
      update public.account_session_resume_plans
      set assignment_id = v_assignment.id, device_id = v_assignment.device_id,
          app_instance_id = v_assignment.app_instance_id,
          scheduled_window_start = v_assignment.starts_at,
          scheduled_window_end = v_assignment.ends_at,
          resume_window_key = v_row.account_id::text || ':' || v_assignment.starts_at::text,
          last_updated_at = now()
      where id = v_row.resume_plan_id;
      update public.account_incidents
      set metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
            'recovery', coalesce(metadata -> 'recovery', '{}'::jsonb) || jsonb_build_object(
              'state', 'ready_to_resume', 'authorization_id', v_authorization_id,
              'source', 'resolved_incident_reconciliation', 'updated_at', now()
            )
          ), updated_at = now()
      where id = v_row.incident_id;
      v_count := v_count + 1;
    end if;
  end loop;
  return jsonb_build_object('armed_count', v_count);
end
$$;




CREATE OR REPLACE FUNCTION "public"."reconcile_stale_device_ui_leases"("p_grace_seconds" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_now timestamptz := now();
  v_cutoff timestamptz := v_now - make_interval(secs => greatest(p_grace_seconds, 0));
  v_row public.auto_restart_device_locks%rowtype;
  v_reconciled integer := 0;
  v_skipped_active integer := 0;
begin
  for v_row in
    select *
    from public.auto_restart_device_locks
    where lease_expires_at <= v_cutoff
    for update
  loop
    if v_row.request_id is not null and exists (
      select 1 from public.account_run_requests r
      where r.id = v_row.request_id
        and r.status in ('queued', 'claimed', 'starting', 'running')
    ) then
      v_skipped_active := v_skipped_active + 1;
      continue;
    end if;

    if v_row.run_id is not null and exists (
      select 1 from public.ig_runs g
      where g.id = v_row.run_id
        and g.status in ('running', 'pending', 'starting', 'queued', 'in_progress', 'active')
    ) then
      v_skipped_active := v_skipped_active + 1;
      continue;
    end if;

    perform public._device_ui_lease_audit(
      v_row.lease_id, v_row.device_id, 'stale_reconciled', v_row.owner_kind, v_row.worker_id,
      v_row.request_id, v_row.run_id, 'lease_expired'
    );
    delete from public.auto_restart_device_locks where device_id = v_row.device_id;
    v_reconciled := v_reconciled + 1;
  end loop;

  return jsonb_build_object(
    'ok', true,
    'reconciled', v_reconciled,
    'skipped_active', v_skipped_active
  );
end;
$$;




CREATE OR REPLACE FUNCTION "public"."record_instagram_credential_ingestion"("p_account_id" "uuid", "p_provider" "text" DEFAULT 'instagram'::"text", "p_secret_ref" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT 'configured'::"text", "p_source" "text" DEFAULT 'unknown'::"text", "p_actor_type" "text" DEFAULT 'backend'::"text", "p_actor_id" "text" DEFAULT NULL::"text", "p_metadata_safe" "jsonb" DEFAULT '{}'::"jsonb") RETURNS TABLE("account_id" "uuid", "provider" "text", "credentials_version" integer, "status" "text", "last_updated_at" timestamp with time zone)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_provider text := lower(coalesce(nullif(trim(p_provider), ''), 'instagram'));
  v_status text := lower(coalesce(nullif(trim(p_status), ''), 'configured'));
  v_source text := lower(coalesce(nullif(trim(p_source), ''), 'unknown'));
  v_actor_type text := lower(coalesce(nullif(trim(p_actor_type), ''), 'backend'));
  v_secret_ref text := nullif(trim(coalesce(p_secret_ref, '')), '');
  v_metadata_safe jsonb := coalesce(p_metadata_safe, '{}'::jsonb);
  v_existing public.account_credentials%rowtype;
  v_next_version integer := 1;
  v_now timestamptz := now();
begin
  if auth.role() <> 'service_role' then
    raise exception 'service_role_required'
      using errcode = '42501';
  end if;

  if p_account_id is null then
    raise exception 'account_id_required'
      using errcode = '22023';
  end if;

  if v_provider <> 'instagram' then
    raise exception 'provider_not_supported'
      using errcode = '22023';
  end if;

  if v_status not in ('missing', 'configured', 'reauth_required', 'update_needed', 'revoked', 'unknown') then
    raise exception 'invalid_credential_status'
      using errcode = '22023';
  end if;

  if v_source not in ('add_profile', 'secure_update_link', 'admin_backend', 'migration', 'unknown') then
    raise exception 'invalid_credential_source'
      using errcode = '22023';
  end if;

  if v_actor_type not in ('admin', 'client', 'system', 'migration', 'backend') then
    raise exception 'invalid_actor_type'
      using errcode = '22023';
  end if;

  if jsonb_typeof(v_metadata_safe) is distinct from 'object'
    or public.jsonb_has_forbidden_safe_metadata_key(v_metadata_safe)
  then
    raise exception 'metadata_safe_forbidden'
      using errcode = '22023';
  end if;

  select *
    into v_existing
  from public.account_credentials ac
  where ac.account_id = p_account_id
    and ac.provider = v_provider
  order by ac.credentials_version desc, ac.updated_at desc
  limit 1
  for update;

  if found then
    v_next_version := v_existing.credentials_version
      + case
          when v_existing.status is distinct from v_status then 1
          when v_secret_ref is not null and v_existing.secret_ref is distinct from v_secret_ref then 1
          else 0
        end;

    update public.account_credentials ac
    set
      status = v_status,
      secret_ref = coalesce(v_secret_ref, ac.secret_ref),
      secret_provider = case
        when v_secret_ref is not null and ac.secret_provider is null then 'supabase_vault'
        else ac.secret_provider
      end,
      credentials_version = v_next_version,
      last_updated_at = v_now,
      updated_by_actor_type = v_actor_type,
      updated_by_actor_id = nullif(trim(coalesce(p_actor_id, '')), ''),
      source = v_source,
      metadata_safe = v_metadata_safe,
      updated_at = v_now,
      reauth_required = v_status in ('reauth_required', 'update_needed'),
      reauth_reason = case
        when v_status = 'reauth_required' then coalesce(ac.reauth_reason, 'credential_reauth_required')
        when v_status = 'update_needed' then coalesce(ac.reauth_reason, 'credential_update_needed')
        else null
      end
    where ac.id = v_existing.id;
  else
    insert into public.account_credentials (
      account_id,
      provider,
      secret_ref,
      secret_provider,
      credentials_version,
      status,
      last_updated_at,
      updated_by_actor_type,
      updated_by_actor_id,
      source,
      metadata_safe,
      reauth_required,
      reauth_reason
    )
    values (
      p_account_id,
      v_provider,
      v_secret_ref,
      case when v_secret_ref is not null then 'supabase_vault' else null end,
      1,
      v_status,
      v_now,
      v_actor_type,
      nullif(trim(coalesce(p_actor_id, '')), ''),
      v_source,
      v_metadata_safe,
      v_status in ('reauth_required', 'update_needed'),
      case
        when v_status = 'reauth_required' then 'credential_reauth_required'
        when v_status = 'update_needed' then 'credential_update_needed'
        else null
      end
    );
  end if;

  return query
    select
      ac.account_id,
      ac.provider,
      ac.credentials_version,
      ac.status,
      ac.last_updated_at
    from public.account_credentials ac
    where ac.account_id = p_account_id
      and ac.provider = v_provider
    order by ac.credentials_version desc, ac.updated_at desc
    limit 1;
end;
$$;




COMMENT ON FUNCTION "public"."record_instagram_credential_ingestion"("p_account_id" "uuid", "p_provider" "text", "p_secret_ref" "text", "p_status" "text", "p_source" "text", "p_actor_type" "text", "p_actor_id" "text", "p_metadata_safe" "jsonb") IS 'Credential Secure Pipeline V1 service-role RPC for safe credential metadata ingestion. Does not accept password input and never returns secret_ref.';



