CREATE OR REPLACE FUNCTION "public"."release_dm_job_after_dry_run"("p_job_id" "uuid", "p_thread_state" "text", "p_sendable" boolean, "p_skip_reason_candidate" "text" DEFAULT NULL::"text", "p_metadata_patch" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "public"."ig_dm_jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_job public.ig_dm_jobs;
  v_now timestamptz := now();
  v_meta jsonb;
begin
  if p_job_id is null then
    raise exception 'job_id is required';
  end if;

  select * into v_job
  from public.ig_dm_jobs
  where id = p_job_id;

  if not found then
    raise exception 'job not found: %', p_job_id;
  end if;

  if v_job.status not in ('running', 'reserved') then
    raise exception 'job % must be running or reserved to release after dry-run (status=%)',
      p_job_id, v_job.status;
  end if;

  v_meta := coalesce(v_job.metadata, '{}'::jsonb)
    || jsonb_build_object(
      'dry_run_passed_at', v_now,
      'dry_run_started_at', v_job.started_at,
      'thread_state', coalesce(nullif(trim(p_thread_state), ''), 'unknown'),
      'sendable', coalesce(p_sendable, false),
      'skip_reason_candidate', nullif(trim(coalesce(p_skip_reason_candidate, '')), '')
    )
    || coalesce(p_metadata_patch, '{}'::jsonb);

  update public.ig_dm_jobs
  set
    status = 'pending'::public.dm_job_status,
    reserved_at = null,
    reserved_by = null,
    started_at = null,
    metadata = v_meta,
    updated_at = v_now
  where id = p_job_id
  returning * into v_job;

  return v_job;
end;
$$;




COMMENT ON FUNCTION "public"."release_dm_job_after_dry_run"("p_job_id" "uuid", "p_thread_state" "text", "p_sendable" boolean, "p_skip_reason_candidate" "text", "p_metadata_patch" "jsonb") IS 'V4.3-B dry-run finalize: pending + dry_run metadata; clears reservation and started_at (audit in metadata.dry_run_started_at).';



CREATE OR REPLACE FUNCTION "public"."release_instagram_action_restriction_hold_v1"("p_account_id" "uuid", "p_incident_id" "uuid", "p_preflight_run_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_hold public.instagram_account_restriction_holds%rowtype;
  v_incident public.account_incidents%rowtype;
  v_restored_status text;
begin
  if coalesce(auth.jwt() ->> 'role', '') <> 'service_role' then
    raise exception 'service_role_required' using errcode = '42501';
  end if;

  select * into v_hold
  from public.instagram_account_restriction_holds
  where account_id = p_account_id
    and incident_id = p_incident_id
  for update;
  if v_hold.id is null then
    return jsonb_build_object('ok', false, 'reason', 'restriction_hold_missing');
  end if;
  if v_hold.status = 'cleared' then
    return jsonb_build_object('ok', true, 'idempotent', true, 'hold_id', v_hold.id, 'hold_status', v_hold.status);
  end if;
  if v_hold.status <> 'verification_required' then
    return jsonb_build_object('ok', false, 'reason', 'restriction_preflight_not_authorized', 'hold_status', v_hold.status);
  end if;

  select * into v_incident
  from public.account_incidents
  where id = p_incident_id and account_id = p_account_id
  for share;
  if v_incident.id is null or v_incident.status <> 'resolved' then
    return jsonb_build_object('ok', false, 'reason', 'restriction_incident_not_resolved');
  end if;

  update public.instagram_account_restriction_holds
  set status = 'cleared',
      verified_cleared_at = now(),
      verified_by_run_id = p_preflight_run_id,
      metadata_safe = coalesce(metadata_safe, '{}'::jsonb)
        || jsonb_build_object(
          'physical_preflight_passed', true,
          'physical_preflight_run_id', p_preflight_run_id,
          'hold_released_at', now()
        ),
      updated_at = now()
  where id = v_hold.id
  returning * into v_hold;

  v_restored_status := coalesce(nullif(v_hold.previous_admin_lifecycle_status, ''), 'active');
  if v_restored_status <> 'paused'
     and not exists (
       select 1 from public.instagram_account_restriction_holds h
       where h.account_id = p_account_id
         and h.id <> v_hold.id
         and h.status in ('active', 'verification_required')
     ) then
    update public.ig_accounts
    set admin_lifecycle_status = v_restored_status, updated_at = now()
    where id = p_account_id and admin_lifecycle_status = 'paused';
  end if;

  return jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'hold_id', v_hold.id,
    'hold_status', v_hold.status,
    'restored_admin_lifecycle_status', v_restored_status,
    'physical_preflight_passed', true
  );
end
$$;




CREATE OR REPLACE FUNCTION "public"."release_schedule_capacity_on_account_admin_lifecycle"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_reason text;
  v_commercial_state text;
begin
  if old.admin_lifecycle_status is not distinct from new.admin_lifecycle_status then
    return new;
  end if;

  if new.admin_lifecycle_status in ('paused', 'needs_assistance') then
    perform public.audit_schedule_capacity_event(
      'schedule_capacity_release_skipped',
      new.id,
      null,
      null,
      case
        when new.admin_lifecycle_status = 'paused' then 'account_paused_keep_assignment'
        else 'account_needs_assistance_keep_assignment'
      end,
      jsonb_build_object(
        'source', 'ig_accounts_admin_lifecycle_trigger',
        'old_admin_lifecycle_status', old.admin_lifecycle_status,
        'new_admin_lifecycle_status', new.admin_lifecycle_status
      )
    );
    return new;
  end if;

  if new.admin_lifecycle_status not in ('cancelled') then
    return new;
  end if;

  select commercial_state into v_commercial_state
  from public.commercial_account_lifecycle_states
  where account_id = new.id
  limit 1;

  if v_commercial_state in ('cancel_requested', 'action_required', 'cancelled') then
    perform public.audit_schedule_capacity_event(
      'schedule_capacity_release_skipped',
      new.id,
      null,
      null,
      'commercial_lifecycle_release_owner',
      jsonb_build_object(
        'source', 'ig_accounts_admin_lifecycle_trigger',
        'commercial_state', v_commercial_state,
        'old_admin_lifecycle_status', old.admin_lifecycle_status,
        'new_admin_lifecycle_status', new.admin_lifecycle_status
      )
    );
    return new;
  end if;

  v_reason := 'account_cancelled_release';

  perform public.release_account_schedule_capacity(
    new.id,
    v_reason,
    'ig_accounts_admin_lifecycle_trigger',
    null
  );

  return new;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."release_target_auto_archive_low_fbr_scheduler_lock"("worker_id" "text" DEFAULT 'target_auto_archive_low_fbr_cron'::"text") RETURNS boolean
    LANGUAGE "plpgsql"
