CREATE OR REPLACE FUNCTION "public"."release_target_followers_resume_checkpoint_v3"("p_account_id" "uuid", "p_target_id" "uuid", "p_surface" "text", "p_run_id" "uuid", "p_mode" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_row public.ig_target_followers_resume_checkpoints%rowtype; v_new_version bigint;
begin
  select * into v_row from public.ig_target_followers_resume_checkpoints c
  where c.account_id=p_account_id and c.target_id=p_target_id and c.surface=p_surface for update;
  if not found then return jsonb_build_object('ok',false,'reason','checkpoint_missing'); end if;
  if v_row.lease_owner_run_id is null then return jsonb_build_object('ok',true,'reason','already_released','optimistic_version',v_row.optimistic_version); end if;
  if v_row.lease_owner_run_id <> p_run_id or v_row.lease_mode <> p_mode then
    return jsonb_build_object('ok',false,'reason','lease_owner_mismatch','optimistic_version',v_row.optimistic_version);
  end if;
  update public.ig_target_followers_resume_checkpoints c set lease_owner_run_id=null,lease_mode=null,
    lease_expires_at=null,lease_heartbeat_at=null,optimistic_version=c.optimistic_version+1,updated_at=now()
  where c.id=v_row.id returning optimistic_version into v_new_version;
  insert into public.ig_target_followers_resume_checkpoint_events(
    checkpoint_id,account_id,target_id,run_id,event_type,mode,previous_optimistic_version,new_optimistic_version,
    previous_depth,new_depth,reason
  ) values (v_row.id,p_account_id,p_target_id,p_run_id,'released',p_mode,v_row.optimistic_version,v_new_version,
    case when p_mode='enforce' then v_row.last_safe_depth else v_row.shadow_last_safe_depth end,
    case when p_mode='enforce' then v_row.last_safe_depth else v_row.shadow_last_safe_depth end,'lease_released');
  return jsonb_build_object('ok',true,'reason','released','optimistic_version',v_new_version);
end
$$;




CREATE OR REPLACE FUNCTION "public"."renew_device_ui_lease"("p_device_id" "uuid", "p_worker_id" "text", "p_request_id" "uuid", "p_lease_seconds" integer DEFAULT 900) RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select public.auto_restart_renew_device_lock(
    p_device_id, p_worker_id, p_request_id, p_lease_seconds
  );
$$;




CREATE OR REPLACE FUNCTION "public"."renew_target_followers_resume_checkpoint_v3"("p_account_id" "uuid", "p_target_id" "uuid", "p_surface" "text", "p_run_id" "uuid", "p_mode" "text", "p_expected_version" bigint, "p_lease_seconds" integer DEFAULT 3600) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_row public.ig_target_followers_resume_checkpoints%rowtype;
  v_new_version bigint;
  v_expiry timestamptz;
  v_reclaimed boolean;
begin
  if p_lease_seconds not between 300 and 7200 or p_expected_version is null then
    return jsonb_build_object('ok', false, 'reason', 'invalid_renew_input');
  end if;
  select * into v_row from public.ig_target_followers_resume_checkpoints c
  where c.account_id=p_account_id and c.target_id=p_target_id and c.surface=p_surface for update;
  if not found then return jsonb_build_object('ok', false, 'reason', 'checkpoint_missing'); end if;
  if v_row.optimistic_version <> p_expected_version then
    return jsonb_build_object('ok', false, 'reason', 'optimistic_version_conflict', 'optimistic_version', v_row.optimistic_version);
  end if;
  if v_row.lease_owner_run_id <> p_run_id or v_row.lease_mode <> p_mode then
    return jsonb_build_object('ok', false, 'reason', 'lease_owner_mismatch', 'optimistic_version', v_row.optimistic_version);
  end if;
  v_reclaimed := v_row.lease_expires_at is null or v_row.lease_expires_at <= now();
  v_expiry := now() + make_interval(secs => p_lease_seconds);
  update public.ig_target_followers_resume_checkpoints c
  set lease_expires_at=v_expiry, lease_heartbeat_at=now(),
      lease_generation=case when v_reclaimed then c.lease_generation+1 else c.lease_generation end,
      optimistic_version=c.optimistic_version+1, updated_at=now()
  where c.id=v_row.id returning optimistic_version into v_new_version;
  insert into public.ig_target_followers_resume_checkpoint_events(
    checkpoint_id,account_id,target_id,run_id,event_type,mode,previous_optimistic_version,new_optimistic_version,
    previous_depth,new_depth,reason
  ) values (v_row.id,p_account_id,p_target_id,p_run_id,case when v_reclaimed then 'reclaimed' else 'renewed' end,p_mode,
    v_row.optimistic_version,v_new_version,
    case when p_mode='enforce' then v_row.last_safe_depth else v_row.shadow_last_safe_depth end,
    case when p_mode='enforce' then v_row.last_safe_depth else v_row.shadow_last_safe_depth end,
    case when v_reclaimed then 'lease_reclaimed_same_run' else 'lease_renewed' end);
  return jsonb_build_object('ok',true,'reason',case when v_reclaimed then 'reclaimed' else 'renewed' end,
    'optimistic_version',v_new_version,'lease_expires_at',v_expiry);
end
$$;




CREATE OR REPLACE FUNCTION "public"."reserve_client_provisioning_slot"("p_client_id" "uuid", "p_client_instagram_account_id" "uuid", "p_ig_account_id" "uuid", "p_assignment_id" "uuid", "p_device_id" "uuid", "p_app_instance_id" "uuid", "p_expected_package" "text", "p_window_start_utc" timestamp with time zone, "p_reservation_source" "text" DEFAULT 'client_connect'::"text", "p_dedupe_key" "text" DEFAULT NULL::"text", "p_safe_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "public"."client_provisioning_slot_reservations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ declare v_existing public.client_provisioning_slot_reservations; v_dedupe text; v_window_end timestamptz; v_row public.client_provisioning_slot_reservations; begin perform public.expire_client_provisioning_slot_reservations(now()); select * into v_existing from public.client_provisioning_slot_reservations r where r.client_instagram_account_id = p_client_instagram_account_id and r.status in ('reserved', 'window_open', 'assisted_requested') order by r.created_at desc limit 1; if found then return v_existing; end if; v_dedupe := coalesce(nullif(trim(p_dedupe_key), ''), format('client_provisioning:%s', p_client_instagram_account_id)); v_window_end := p_window_start_utc + interval '30 minutes'; insert into public.client_provisioning_slot_reservations (client_id, client_instagram_account_id, ig_account_id, assignment_id, device_id, app_instance_id, expected_package, window_start_utc, window_end_utc, expires_at, status, reservation_source, dedupe_key, safe_metadata) values (p_client_id, p_client_instagram_account_id, p_ig_account_id, p_assignment_id, p_device_id, p_app_instance_id, coalesce(p_expected_package, ''), p_window_start_utc, v_window_end, v_window_end, case when p_window_start_utc <= now() then 'window_open' else 'reserved' end, coalesce(nullif(trim(p_reservation_source), ''), 'client_connect'), v_dedupe, coalesce(p_safe_metadata, '{}'::jsonb)) returning * into v_row; return v_row; exception when exclusion_violation then raise exception 'provisioning_slot_device_overlap' using errcode = 'P0001'; when unique_violation then select * into v_existing from public.client_provisioning_slot_reservations r where r.client_instagram_account_id = p_client_instagram_account_id and r.status in ('reserved', 'window_open', 'assisted_requested') order by r.created_at desc limit 1; if found then return v_existing; end if; raise; end; $$;




CREATE OR REPLACE FUNCTION "public"."reset_target_followers_resume_checkpoint"("p_account_id" "uuid", "p_target_id" "uuid", "p_surface" "text", "p_run_id" "uuid", "p_expected_version" bigint, "p_reason" "text", "p_reset_shadow" boolean DEFAULT true, "p_reset_enforce" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_row public.ig_target_followers_resume_checkpoints%rowtype;
  v_new_version bigint;
begin
  if p_account_id is null
     or p_target_id is null
     or p_run_id is null
     or p_expected_version is null
     or p_surface <> 'followers'
     or not (p_reset_shadow or p_reset_enforce)
     or p_reason !~ '^[a-z0-9_:-]{1,120}$' then
    return jsonb_build_object('ok', false, 'reason', 'invalid_reset_input');
  end if;
  select * into v_row from public.ig_target_followers_resume_checkpoints c
  where c.account_id = p_account_id and c.target_id = p_target_id and c.surface = p_surface
  for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'checkpoint_missing');
  end if;
  if v_row.optimistic_version <> p_expected_version then
    return jsonb_build_object('ok', false, 'reason', 'optimistic_version_conflict', 'optimistic_version', v_row.optimistic_version);
  end if;
  update public.ig_target_followers_resume_checkpoints c
  set last_safe_depth = case when p_reset_enforce then 0 else c.last_safe_depth end,
      last_safe_anchor = case when p_reset_enforce then null else c.last_safe_anchor end,
      anchor_fingerprint = case when p_reset_enforce then null else c.anchor_fingerprint end,
      last_visible_anchor_hashes = case when p_reset_enforce then '[]'::jsonb else c.last_visible_anchor_hashes end,
      shadow_last_safe_depth = case when p_reset_shadow then 0 else c.shadow_last_safe_depth end,
      shadow_last_safe_anchor = case when p_reset_shadow then null else c.shadow_last_safe_anchor end,
      shadow_anchor_fingerprint = case when p_reset_shadow then null else c.shadow_anchor_fingerprint end,
      shadow_visible_anchor_hashes = case when p_reset_shadow then '[]'::jsonb else c.shadow_visible_anchor_hashes end,
      status = 'active',
      invalidation_reason = null,
      lease_owner_run_id = null,
      lease_mode = null,
      lease_expires_at = null,
      last_run_id = p_run_id,
      optimistic_version = c.optimistic_version + 1,
      updated_at = now()
  where c.id = v_row.id
  returning c.optimistic_version into v_new_version;
  insert into public.ig_target_followers_resume_checkpoint_events (
    checkpoint_id, account_id, target_id, run_id, event_type,
    previous_optimistic_version, new_optimistic_version,
    previous_depth, new_depth, reason, metadata
  ) values (
    v_row.id, p_account_id, p_target_id, p_run_id, 'reset',
    v_row.optimistic_version, v_new_version,
    greatest(v_row.last_safe_depth, v_row.shadow_last_safe_depth),
    greatest(
      case when p_reset_enforce then 0 else v_row.last_safe_depth end,
      case when p_reset_shadow then 0 else v_row.shadow_last_safe_depth end
    ),
    p_reason,
    jsonb_build_object('reset_shadow', p_reset_shadow, 'reset_enforce', p_reset_enforce)
  );
  return jsonb_build_object('ok', true, 'reason', 'reset', 'optimistic_version', v_new_version);
end
$_$;




CREATE OR REPLACE FUNCTION "public"."resolve_account_schedule_assignment_type"("p_account_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
declare
  v_package_code text;
  v_has_full_cycle boolean := false;
  v_has_outreach_only boolean := false;
begin
  if p_account_id is null then
    return null;
  end if;

  select acp.package_code
  into v_package_code
  from public.account_commercial_packages acp
  where acp.account_id = p_account_id
    and acp.status = 'active'
    and acp.starts_at <= now()
    and (acp.ends_at is null or acp.ends_at > now())
  order by acp.starts_at desc, acp.created_at desc
  limit 1;

  select exists (
    select 1
    from public.client_subscription_accounts csa
    join public.client_subscriptions cs on cs.id = csa.subscription_id
    where csa.account_id = p_account_id
      and csa.status = 'active'
      and cs.status = 'active'
      and cs.subscription_type = 'full_cycle'
  ) into v_has_full_cycle;

  select exists (
    select 1
    from public.client_subscription_accounts csa
    join public.client_subscriptions cs on cs.id = csa.subscription_id
    where csa.account_id = p_account_id
      and csa.status = 'active'
      and cs.status = 'active'
      and cs.subscription_type = 'outreach_only'
  ) into v_has_outreach_only;

  if v_package_code = 'outreach_standalone' and v_has_outreach_only then
    return 'outreach_only';
  end if;

  if v_has_full_cycle then
    return 'full_cycle';
  end if;

  if v_has_outreach_only then
    return 'outreach_only';
  end if;

  return null;
end;
$$;




COMMENT ON FUNCTION "public"."resolve_account_schedule_assignment_type"("p_account_id" "uuid") IS 'Resolves the primary Schedule assignment_type for an account. full_cycle wins over outreach_only add-on subscriptions; Outreach entitlement/add-on does not override full_cycle.';



CREATE OR REPLACE FUNCTION "public"."resolve_assignment_slot_kind"("p_assignment_type" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case
    when p_assignment_type = 'full_cycle' then 'full_cycle_6h'
    when p_assignment_type = 'outreach_only' then 'outreach_40m'
    else null
  end;
$$;




CREATE OR REPLACE FUNCTION "public"."resolve_linked_incident_from_dashboard_action_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if new.incident_id is null
     or new.status <> 'resolved'
     or old.status = 'resolved'
     or new.action_type not in ('operator_review_required', 'review_auto_restart_hard_stop') then
    return new;
  end if;

  new.blocking_campaign := false;
  new.requires_client_action := false;
  new.resolved_at := coalesce(new.resolved_at, now());

  update public.account_incidents
  set status = 'resolved',
      resolved_at = coalesce(resolved_at, new.resolved_at),
      resolution_reason = coalesce(resolution_reason, 'linked_operator_review_resolved'),
      resolution_note = coalesce(resolution_note, 'Resolved from linked operator review.'),
      updated_at = now()
  where id = new.incident_id
    and status in ('open', 'acknowledged', 'investigating');
  return new;
end
$$;




CREATE OR REPLACE FUNCTION "public"."resolve_welcome_template_missing_incidents_v1"("p_account_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_incident record;
  v_count integer := 0;
begin
  for v_incident in
    select id, lifecycle_version
      from public.account_incidents
     where account_id = p_account_id
       and incident_type = 'account_configuration_failure'
       and reason = 'welcome_template_missing'
       and status in ('open','acknowledged')
     for update
  loop
    perform public.transition_account_incident_human_review_v1(
      v_incident.id,
      'resolve',
      v_incident.lifecycle_version,
      'system',
      null,
      'system',
      'Welcome configuration revalidated by Scheduler.',
      'configuration_corrected',
      'welcome-template-resolved:' || v_incident.id::text || ':' || v_incident.lifecycle_version::text,
      null,
      null
    );
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."resolve_whatsapp_context"("p_phone_number_id" "text", "p_patient_phone" "text") RETURNS TABLE("customer_id" "uuid", "customer_name" "text", "customer_slug" "text", "customer_plan" "text", "customer_status" "text", "customer_phone_number_id" "text", "customer_waba_id" "text", "opening_hours" "text", "address" "text", "booking_link" "text", "patient_id" "uuid", "patient_external_id" "text", "patient_name" "text", "patient_phone_number" "text", "patient_wa_id" "text", "patient_age" integer, "patient_gender" "text", "patient_dob" "date")
    LANGUAGE "sql"
    AS $$
  select
    c.id as customer_id,
    c.name as customer_name,
    c.slug as customer_slug,
    c.plan as customer_plan,
    c.status as customer_status,
    c.whatsapp_phone_number_id as customer_phone_number_id,
    c.whatsapp_business_account_id as customer_waba_id,
    c.opening_hours as opening_hours,
    c.address as address,
    c.booking_link as booking_link,
    p.id as patient_id,
    p.external_patient_id as patient_external_id,
    p.full_name as patient_name,
    p.phone_number as patient_phone_number,
    p.wa_id as patient_wa_id,
    p.age as patient_age,
    p.gender as patient_gender,
    p.date_of_birth as patient_dob
  from patients p
  join customers c
    on c.id = p.customer_id
  where c.whatsapp_phone_number_id = p_phone_number_id
    and p.wa_id = p_patient_phone
  limit 1;
$$;




CREATE OR REPLACE FUNCTION "public"."resolve_whatsapp_customer_context"("p_phone_number_id" "text") RETURNS TABLE("customer_id" "uuid", "customer_name" "text", "customer_slug" "text", "customer_plan" "text", "customer_status" "text", "customer_phone_number_id" "text", "customer_waba_id" "text", "opening_hours" "text", "address" "text", "booking_link" "text", "office_visit_text" "text")
    LANGUAGE "sql"
    AS $$
  select
    c.id as customer_id,
    c.name as customer_name,
    c.slug as customer_slug,
    c.plan as customer_plan,
    c.status as customer_status,
    c.whatsapp_phone_number_id as customer_phone_number_id,
    c.whatsapp_business_account_id as customer_waba_id,
    c.opening_hours as opening_hours,
    c.address as address,
    c.booking_link as booking_link,
    c.office_visit_text as office_visit_text
  from customers c
  where c.whatsapp_phone_number_id = p_phone_number_id
  limit 1;
$$;




CREATE OR REPLACE FUNCTION "public"."restart_client_instagram_onboarding"("p_previous_session_id" "uuid", "p_client_id" "uuid", "p_actor_id" "uuid", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_previous public.client_instagram_onboarding_sessions%rowtype;
  v_existing public.client_instagram_onboarding_sessions%rowtype;
  v_new_id uuid;
begin
  perform pg_advisory_xact_lock(hashtextextended(
    'client_instagram_onboarding:restart:' || p_previous_session_id::text,
    0
  ));
  perform pg_advisory_xact_lock(hashtextextended(
    'client_instagram_onboarding:idempotency:' || p_client_id::text || ':' || p_idempotency_key::text,
    0
  ));

  if not exists (
    select 1 from public.client_users cu
     where cu.client_id = p_client_id
       and cu.auth_user_id = p_actor_id
       and cu.status = 'active'
       and cu.role in ('owner', 'admin', 'assistant')
  ) then
    return jsonb_build_object('ok', false, 'reason', 'client_access_denied');
  end if;

  select * into v_previous
    from public.client_instagram_onboarding_sessions
   where id = p_previous_session_id and client_id = p_client_id
   for update;
  if not found or v_previous.status not in ('expired', 'abandoned') then
    return jsonb_build_object('ok', false, 'reason', 'restart_not_allowed');
  end if;
  if v_previous.account_id is null then
    return jsonb_build_object('ok', false, 'reason', 'account_not_created');
  end if;

  select * into v_existing
    from public.client_instagram_onboarding_sessions
   where client_id = p_client_id
     and idempotency_key = p_idempotency_key
   for update;
  if found then
    if v_existing.account_id = v_previous.account_id
       and v_existing.entitlement_id = v_previous.entitlement_id then
      return jsonb_build_object(
        'ok', true,
        'already_restarted', true,
        'session_id', v_existing.id,
        'account_id', v_existing.account_id
      );
    end if;
    return jsonb_build_object('ok', false, 'reason', 'restart_idempotency_mismatch');
  end if;

  select * into v_existing
    from public.client_instagram_onboarding_sessions
   where client_id = p_client_id
     and status in ('active', 'creating')
     and (account_id = v_previous.account_id or entitlement_id = v_previous.entitlement_id)
   order by created_at desc
   limit 1
   for update;
  if found then
    return jsonb_build_object(
      'ok', true,
      'already_restarted', true,
      'session_id', v_existing.id,
      'account_id', v_existing.account_id
    );
  end if;

  insert into public.client_instagram_onboarding_sessions (
    client_id, entitlement_id, account_id, created_by, idempotency_key,
    requested_username, package_code, status, current_step,
    public_analysis, targeting_criteria, expires_at, last_progress_at
  ) values (
    p_client_id, v_previous.entitlement_id, v_previous.account_id, p_actor_id, p_idempotency_key,
    v_previous.requested_username, v_previous.package_code, 'active', v_previous.current_step,
    v_previous.public_analysis, v_previous.targeting_criteria, now() + interval '7 days', now()
  ) returning id into v_new_id;

  insert into public.commercial_checkout_audit_events (
    entitlement_id, event_type, client_id, payload
  ) values (
    v_previous.entitlement_id,
    'client_instagram_onboarding_restarted',
    p_client_id,
    jsonb_build_object(
      'previous_session_id', p_previous_session_id,
      'onboarding_session_id', v_new_id,
      'account_id', v_previous.account_id,
      'entitlement_reconsumed', false,
      'credentials_replayed', false
    )
  );

  return jsonb_build_object('ok', true, 'session_id', v_new_id, 'account_id', v_previous.account_id);
end;
$$;




COMMENT ON FUNCTION "public"."restart_client_instagram_onboarding"("p_previous_session_id" "uuid", "p_client_id" "uuid", "p_actor_id" "uuid", "p_idempotency_key" "uuid") IS 'Starts a new resumable session after explicit abandonment or expiry without recreating the account or consuming entitlement twice.';



CREATE OR REPLACE FUNCTION "public"."restaurant_find_overlapping_reservations"("p_location_id" "uuid", "p_start" timestamp with time zone, "p_end" timestamp with time zone) RETURNS TABLE("reservation_id" "uuid", "assigned_table_id" "uuid", "assigned_combination_id" "uuid", "party_size" integer, "status" "public"."restaurant_reservation_status")
    LANGUAGE "sql"
    AS $$
  select
    r.id as reservation_id,
    r.assigned_table_id,
    r.assigned_combination_id,
    r.party_size,
    r.status
  from public.restaurant_reservations r
  where r.location_id = p_location_id
    and r.status in ('pending', 'confirmed')
    and tstzrange(r.reservation_start, r.reservation_end, '[)')
        && tstzrange(p_start, p_end, '[)');
$$;




CREATE OR REPLACE FUNCTION "public"."restaurant_match_knowledge_chunks"("query_embedding" "public"."vector", "filter_tenant_id" "uuid", "filter_location_id" "uuid" DEFAULT NULL::"uuid", "match_count" integer DEFAULT 5) RETURNS TABLE("id" "uuid", "document_id" "uuid", "chunk_text" "text", "metadata" "jsonb", "similarity" double precision)
    LANGUAGE "sql"
    AS $$
  select
    kc.id,
    kc.document_id,
    kc.chunk_text,
    kc.metadata,
    1 - (kc.embedding <=> query_embedding) as similarity
  from public.restaurant_knowledge_chunks kc
  where kc.tenant_id = filter_tenant_id
    and kc.status = 'active'
    and (
      filter_location_id is null
      or kc.location_id = filter_location_id
      or kc.location_id is null
    )
  order by kc.embedding <=> query_embedding
  limit match_count;
$$;




CREATE OR REPLACE FUNCTION "public"."restaurant_set_updated_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  new.updated_at = now();
  return new;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."restore_prebusiness_resume_retry_credits_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_row record;
  v_assignment public.account_assignments%rowtype;
  v_count integer := 0;
begin
  for v_row in
    select a.*, q.run_id as retry_run_id, q.updated_at as request_updated_at
    from public.incident_resume_authorizations a
    join public.account_run_requests q on q.id = a.consumed_by_request_id
    join public.ig_runs r on r.id = q.run_id
    join public.account_incidents i on i.id = a.incident_id
    where a.status = 'consumed'
      and a.test is false
      and i.status = 'resolved'
      and q.status in ('failed','canceled')
      and (
        q.error_code = 'phase_plan_unknown'
        or r.error_message = 'phase_plan_unknown'
        or r.performance_summary ->> 'reason' = 'phase_plan_unknown'
        or r.performance_summary ->> 'root_failure_code' = 'phase_plan_unknown'
        or r.performance_summary ->> 'restart_block_reason' = 'phase_plan_unknown'
        or r.performance_summary #>> '{admin_reliability_snapshot,restart_block_reason}' = 'phase_plan_unknown'
      )
      and coalesce(r.total_follow, 0) = 0
      and coalesce(r.total_like, 0) = 0
      and coalesce(r.total_dm, 0) = 0
      and coalesce((r.performance_summary #>> '{unfollow,verified_unfollows}')::integer, 0) = 0
      and coalesce((r.performance_summary #>> '{session_counters,successful_interactions}')::integer, 0) = 0
      and not exists (
        select 1 from public.ig_action_logs l
        where l.run_id = r.id
          and l.status in ('success','completed','verified','persisted')
          and l.action_type in ('follow','unfollow','like','dm','welcome_dm','outreach_dm')
      )
      and not exists (
        select 1 from public.account_run_requests newer
        where newer.account_id = a.account_id
          and newer.created_at > q.created_at
          and newer.status in ('queued','claimed','starting','running')
      )
    order by q.updated_at
    for update of a skip locked
  loop
    select aa.* into v_assignment
    from public.account_assignments aa
    where aa.account_id = v_row.account_id
      and aa.status in ('reserved','active')
      and aa.starts_at <= now() and now() < aa.ends_at
      and coalesce(aa.schedule_mode, '') <> 'manual_only'
    order by aa.starts_at desc
    limit 1;
    if v_assignment.id is null then
      continue;
    end if;

    update public.incident_resume_authorizations
    set status = 'armed', retry_generation = retry_generation + 1,
        retry_credit_restored_at = now(),
        retry_credit_restore_reason = 'phase_plan_unknown_zero_business_actions',
        scheduled_window_start = v_assignment.starts_at,
        scheduled_window_end = v_assignment.ends_at,
        resume_window_key = account_id::text || ':' || v_assignment.starts_at::text,
        consumed_at = null, consumed_by_request_id = null, consume_error = null,
        frozen_phase_plan = null, armed_at = now(), updated_at = now()
    where id = v_row.id and status = 'consumed';
    if not found then continue; end if;

    update public.account_session_resume_plans
    set assignment_id = v_assignment.id, device_id = v_assignment.device_id,
        app_instance_id = v_assignment.app_instance_id,
        scheduled_window_start = v_assignment.starts_at,
        scheduled_window_end = v_assignment.ends_at,
        resume_window_key = v_row.account_id::text || ':' || v_assignment.starts_at::text,
        resume_state = 'awaiting_human_resume_authorization',
        restart_allowed = true,
        restart_block_reason = 'retry_credit_restored_prebusiness',
        last_updated_at = now()
    where id = v_row.resume_plan_id;

    update public.account_incidents
    set metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
          'recovery', coalesce(metadata -> 'recovery', '{}'::jsonb) || jsonb_build_object(
            'state', 'ready_to_resume',
            'reason', 'phase_plan_unknown_zero_business_actions',
            'authorization_id', v_row.id,
            'retry_generation', v_row.retry_generation + 1,
            'updated_at', now()
          )
        ), updated_at = now()
    where id = v_row.incident_id and status = 'resolved';
    v_count := v_count + 1;
  end loop;
  return jsonb_build_object('restored_count', v_count);
end
$$;




CREATE TABLE IF NOT EXISTS "public"."account_dashboard_actions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "account_id" "uuid" NOT NULL,
    "client_id" "uuid",
    "incident_id" "uuid",
    "action_type" "text" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "severity" "text" DEFAULT 'warning'::"text" NOT NULL,
    "audience" "text" DEFAULT 'client'::"text" NOT NULL,
    "requires_client_action" boolean DEFAULT true NOT NULL,
    "blocking_campaign" boolean DEFAULT false NOT NULL,
    "title" "text" NOT NULL,
    "safe_client_message" "text",
    "assistant_message" "text",
    "admin_message" "text",
    "action_label" "text",
    "action_deep_link" "text",
    "dedupe_key" "text" NOT NULL,
    "resolved_at" timestamp with time zone,
    "dismissed_at" timestamp with time zone,
    "acknowledged_at" timestamp with time zone,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_by_actor_type" "text",
    "created_by_actor_id" "text",
    "metadata_safe" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    CONSTRAINT "account_dashboard_actions_action_type_nonempty" CHECK (("char_length"(TRIM(BOTH FROM "action_type")) > 0)),
    CONSTRAINT "account_dashboard_actions_audience_check" CHECK (("audience" = ANY (ARRAY['client'::"text", 'admin'::"text", 'assistant'::"text", 'ops'::"text"]))),
    CONSTRAINT "account_dashboard_actions_created_actor_type_check" CHECK ((("created_by_actor_type" IS NULL) OR ("created_by_actor_type" = ANY (ARRAY['admin'::"text", 'client'::"text", 'system'::"text", 'migration'::"text", 'backend'::"text"])))),
    CONSTRAINT "account_dashboard_actions_dedupe_key_nonempty" CHECK (("char_length"(TRIM(BOTH FROM "dedupe_key")) > 0)),
    CONSTRAINT "account_dashboard_actions_metadata_object_check" CHECK (("jsonb_typeof"("metadata") = 'object'::"text")),
    CONSTRAINT "account_dashboard_actions_metadata_safe_check" CHECK ((("jsonb_typeof"("metadata_safe") = 'object'::"text") AND (NOT "public"."jsonb_has_forbidden_safe_metadata_key"("metadata_safe")))),
    CONSTRAINT "account_dashboard_actions_severity_check" CHECK (("severity" = ANY (ARRAY['info'::"text", 'warning'::"text", 'error'::"text", 'critical'::"text"]))),
    CONSTRAINT "account_dashboard_actions_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'acknowledged'::"text", 'pending_verification'::"text", 'code_submitted'::"text", 'resolved'::"text", 'dismissed'::"text", 'ignored'::"text"]))),
    CONSTRAINT "account_dashboard_actions_title_nonempty" CHECK (("char_length"(TRIM(BOTH FROM "title")) > 0))
);




COMMENT ON TABLE "public"."account_dashboard_actions" IS 'Entry 2D-4A dashboard action center. UI task/action state for client/admin/assistant dashboards; not Slack/Discord delivery audit.';



COMMENT ON COLUMN "public"."account_dashboard_actions"."incident_id" IS 'Optional link to account_incidents. Incidents remain the operational source; dashboard actions are the UI task projection.';



COMMENT ON COLUMN "public"."account_dashboard_actions"."action_type" IS 'Stable action type such as update_instagram_password, complete_two_factor, add_targets, or review_dm_template.';



COMMENT ON COLUMN "public"."account_dashboard_actions"."status" IS 'Dashboard action lifecycle: pending, acknowledged, pending_verification, resolved, dismissed, or ignored.';



COMMENT ON COLUMN "public"."account_dashboard_actions"."audience" IS 'Primary audience for the action: client, admin, assistant, or ops. Future safe APIs must filter fields by audience.';



COMMENT ON COLUMN "public"."account_dashboard_actions"."requires_client_action" IS 'True when the client must perform an action, e.g. update password, submit credentials, complete 2FA, or add targets.';



COMMENT ON COLUMN "public"."account_dashboard_actions"."blocking_campaign" IS 'True when the action should block or pause campaign activity and may require a priority dashboard modal.';



COMMENT ON COLUMN "public"."account_dashboard_actions"."action_deep_link" IS 'Safe dashboard app route to the correct form or panel. Never store external secret URLs, webhook URLs, or Vault references here.';



COMMENT ON COLUMN "public"."account_dashboard_actions"."metadata" IS 'Safe metadata only. Never store passwords, raw secrets, secret_ref, Vault payloads, webhook URLs, service-role data, raw XML, screenshots, tokens, or cookies.';



COMMENT ON COLUMN "public"."account_dashboard_actions"."metadata_safe" IS 'Credential pipeline safe metadata. Never store password, token, secret_ref, raw request body, raw logs/XML, screenshots, or device internals.';



CREATE OR REPLACE FUNCTION "public"."review_operator_dashboard_action"("p_action_id" "uuid", "p_account_id" "uuid", "p_actor_id" "uuid", "p_source" "text" DEFAULT 'admin_dashboard'::"text", "p_note" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "public"."account_dashboard_actions"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_action public.account_dashboard_actions;
  v_transitioned public.account_dashboard_actions;
  v_source text := lower(coalesce(nullif(trim(p_source), ''), 'admin_dashboard'));
  v_note text := nullif(trim(coalesce(p_note, '')), '');
  v_metadata jsonb := coalesce(p_metadata, '{}'::jsonb);
  v_reviewed_at timestamptz := now();
begin
  if p_action_id is null or p_account_id is null or p_actor_id is null then
    raise exception 'operator_review_identity_required' using errcode = '22023';
  end if;

  if v_source not in ('admin_dashboard', 'botapp_relay') then
    raise exception 'operator_review_source_invalid' using errcode = '22023';
  end if;

  if v_note is not null and char_length(v_note) > 500 then
    raise exception 'operator_review_note_too_long' using errcode = '22023';
  end if;

  if jsonb_typeof(v_metadata) is distinct from 'object' then
    raise exception 'operator_review_metadata_invalid' using errcode = '22023';
  end if;

  select ada.* into v_action
  from public.account_dashboard_actions as ada
  where ada.id = p_action_id and ada.account_id = p_account_id
  for update;

  if v_action.id is null then
    raise exception 'dashboard_action_not_found' using errcode = 'P0002';
  end if;
  if v_action.action_type <> 'operator_review_required' then
    raise exception 'dashboard_action_not_operator_review' using errcode = '22023';
  end if;
  if v_action.status not in ('pending', 'acknowledged', 'pending_verification', 'code_submitted') then
    raise exception 'dashboard_action_not_reviewable' using errcode = '22023';
  end if;

  select transitioned.* into v_transitioned
  from public.transition_account_dashboard_action(
    p_action_id,
    'resolved',
    'admin',
    p_actor_id,
    'operator_marked_reviewed',
    v_metadata || jsonb_strip_nulls(jsonb_build_object(
      'review_status', 'reviewed',
      'reviewed_by', p_actor_id::text,
      'reviewed_at', v_reviewed_at,
      'review_source', v_source,
      'review_note', v_note,
      'operator_review_completed', true,
      'keep_action_active_until_readiness_ok', false
    ))
  ) as transitioned;

  update public.account_dashboard_actions as ada
  set blocking_campaign = false,
      requires_client_action = false,
      updated_at = v_reviewed_at
  where ada.id = p_action_id
  returning ada.* into v_transitioned;

  insert into public.ig_action_logs (
    account_id, run_id, target_username, action_type, status, message, payload, created_at
  ) values (
    p_account_id, null, null, 'dashboard_action_reviewed', 'success',
    'operator_review_action_resolved',
    jsonb_build_object(
      'actor_type', 'admin',
      'actor_id', p_actor_id,
      'source', v_source,
      'dashboard_action_id', p_action_id,
      'dashboard_action_type', 'operator_review_required',
      'review_status', 'reviewed',
      'reviewed_at', v_reviewed_at,
      'note_present', v_note is not null
    ),
    v_reviewed_at
  );

  return v_transitioned;
end;
$$;




COMMENT ON FUNCTION "public"."review_operator_dashboard_action"("p_action_id" "uuid", "p_account_id" "uuid", "p_actor_id" "uuid", "p_source" "text", "p_note" "text", "p_metadata" "jsonb") IS 'Atomically resolves one operator_review_required action, clears its campaign block, and records the authenticated operator audit without changing the linked incident.';



CREATE OR REPLACE FUNCTION "public"."revoke_instagram_account_credentials"("p_account_id" "uuid", "p_provider" "text" DEFAULT 'instagram'::"text", "p_reason" "text" DEFAULT 'explicit_credential_revoke'::"text", "p_request_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_provider text := lower(coalesce(nullif(btrim(p_provider), ''), 'instagram'));
  v_reason text := lower(coalesce(nullif(btrim(p_reason), ''), 'explicit_credential_revoke'));
  v_request_id text := nullif(btrim(coalesce(p_request_id, '')), '');
  v_now timestamptz := now();
  v_found_count integer := 0;
  v_revoked_count integer := 0;
  v_already_revoked_count integer := 0;
  v_vault_attempted_count integer := 0;
  v_vault_neutralized_count integer := 0;
  v_vault_not_found_count integer := 0;
  v_vault_failed_count integer := 0;
  v_vault_status text := 'not_applicable';
  v_cleanup jsonb;
  v_secret_ref text;
begin
  if auth.role() <> 'service_role' then
    raise exception 'service_role_required'
      using errcode = '42501';
  end if;

  if p_account_id is null then
    raise exception 'account_id_required'
      using errcode = '22023';
  end if;

  if v_provider <> 'instagram' then
    raise exception 'provider_not_supported'
      using errcode = '22023';
  end if;

  if not public.instagram_credential_cleanup_reason_allowed(v_reason) then
    raise exception 'cleanup_reason_not_allowed'
      using errcode = '22023';
  end if;

  if v_request_id is not null and v_request_id !~ '^[a-zA-Z0-9._:-]{1,120}$' then
    raise exception 'request_id_invalid'
      using errcode = '22023';
  end if;

  select count(*),
         count(*) filter (where status = 'revoked'),
         count(*) filter (where status <> 'revoked')
    into v_found_count, v_already_revoked_count, v_revoked_count
  from public.account_credentials ac
  where ac.account_id = p_account_id
    and ac.provider = v_provider;

  for v_secret_ref in
    select distinct ac.secret_ref
    from public.account_credentials ac
    where ac.account_id = p_account_id
      and ac.provider = v_provider
      and ac.secret_ref is not null
      and ac.secret_ref like 'supabase_vault://%'
  loop
    v_cleanup := public.revoke_instagram_credentials_vault_secret(
      v_secret_ref,
      v_reason,
      v_request_id
    );
    v_vault_attempted_count := v_vault_attempted_count + 1;

    if v_cleanup->>'vault_cleanup_status' = 'neutralized' then
      v_vault_neutralized_count := v_vault_neutralized_count + 1;
    elsif v_cleanup->>'vault_cleanup_status' = 'not_found' then
      v_vault_not_found_count := v_vault_not_found_count + 1;
    else
      v_vault_failed_count := v_vault_failed_count + 1;
    end if;
  end loop;

  update public.account_credentials ac
     set status = 'revoked',
         revoked_at = coalesce(ac.revoked_at, v_now),
         reauth_required = true,
         reauth_reason = v_reason,
         last_updated_at = v_now,
         updated_at = v_now,
         updated_by_actor_type = 'backend',
         source = coalesce(nullif(ac.source, ''), 'unknown'),
         metadata_safe = coalesce(ac.metadata_safe, '{}'::jsonb)
           || jsonb_strip_nulls(jsonb_build_object(
             'action', 'revoke',
             'source', coalesce(nullif(ac.source, ''), 'unknown'),
             'revoke_reason', v_reason,
             'request_id', v_request_id,
             'credential_cleanup', true
           ))
   where ac.account_id = p_account_id
     and ac.provider = v_provider
     and ac.status <> 'revoked';

  if v_vault_attempted_count = 0 then
    v_vault_status := 'not_applicable';
  elsif v_vault_failed_count > 0 then
    v_vault_status := 'partial_failed';
  elsif v_vault_neutralized_count > 0 and v_vault_not_found_count > 0 then
    v_vault_status := 'partial_neutralized';
  elsif v_vault_neutralized_count > 0 then
    v_vault_status := 'neutralized';
  else
    v_vault_status := 'not_found';
  end if;

  return jsonb_build_object(
    'ok', true,
    'account_id', p_account_id,
    'provider', v_provider,
    'credentials_found', v_found_count > 0,
    'credentials_revoked', v_revoked_count,
    'credentials_already_revoked', v_already_revoked_count,
    'vault_cleanup_attempted', v_vault_attempted_count > 0,
    'vault_cleanup_status', v_vault_status,
    'vault_cleanup_attempted_count', v_vault_attempted_count,
    'vault_cleanup_neutralized_count', v_vault_neutralized_count,
    'vault_cleanup_not_found_count', v_vault_not_found_count,
    'vault_cleanup_failed_count', v_vault_failed_count
  );
end;
$_$;




COMMENT ON FUNCTION "public"."revoke_instagram_account_credentials"("p_account_id" "uuid", "p_provider" "text", "p_reason" "text", "p_request_id" "text") IS 'Patch 2C-1 service-role-only helper that revokes Instagram credential metadata and neutralizes linked Vault secrets when possible. Valid reasons exclude archive/trash/restore lifecycle states.';



CREATE OR REPLACE FUNCTION "public"."revoke_instagram_credentials_vault_secret"("p_secret_ref" "text", "p_reason" "text" DEFAULT 'explicit_credential_revoke'::"text", "p_request_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'vault'
    AS $_$
declare
  v_secret_ref text := btrim(coalesce(p_secret_ref, ''));
  v_reason text := lower(coalesce(nullif(btrim(p_reason), ''), 'explicit_credential_revoke'));
  v_request_id text := nullif(btrim(coalesce(p_request_id, '')), '');
  v_secret_id_text text;
  v_secret_id uuid;
  v_secret_exists boolean := false;
  v_neutral_payload text;
begin
  if auth.role() <> 'service_role' then
    raise exception 'service_role_required'
      using errcode = '42501';
  end if;

  if not public.instagram_credential_cleanup_reason_allowed(v_reason) then
    raise exception 'cleanup_reason_not_allowed'
      using errcode = '22023';
  end if;

  if v_request_id is not null and v_request_id !~ '^[a-zA-Z0-9._:-]{1,120}$' then
    raise exception 'request_id_invalid'
      using errcode = '22023';
  end if;

  if left(v_secret_ref, length('supabase_vault://')) <> 'supabase_vault://' then
    raise exception 'vault_secret_ref_invalid'
      using errcode = '22023';
  end if;

  v_secret_id_text := btrim(substr(v_secret_ref, length('supabase_vault://') + 1));
  if v_secret_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    raise exception 'vault_secret_ref_invalid'
      using errcode = '22023';
  end if;
  v_secret_id := v_secret_id_text::uuid;

  select exists (
    select 1
    from vault.secrets s
    where s.id = v_secret_id
  )
    into v_secret_exists;

  if not v_secret_exists then
    return jsonb_build_object(
      'ok', true,
      'vault_cleanup_attempted', true,
      'vault_cleanup_status', 'not_found',
      'safe_ref_label', 'supabase_vault://[REDACTED]'
    );
  end if;

  v_neutral_payload := jsonb_strip_nulls(jsonb_build_object(
    'revoked', true,
    'revoked_at', now(),
    'reason', v_reason,
    'request_id', v_request_id,
    'secret_value_removed', true
  ))::text;

  perform vault.update_secret(
    v_secret_id,
    v_neutral_payload,
    'revoked/instagram/credential/' || v_secret_id::text,
    'Revoked Instagram credential secret; value neutralized by Patch 2C-1.',
    null
  );

  return jsonb_build_object(
    'ok', true,
    'vault_cleanup_attempted', true,
    'vault_cleanup_status', 'neutralized',
    'safe_ref_label', 'supabase_vault://[REDACTED]'
  );
exception
  when others then
    if sqlstate in ('22023', '42501') then
      raise;
    end if;

    return jsonb_build_object(
      'ok', false,
      'vault_cleanup_attempted', true,
      'vault_cleanup_status', 'failed',
      'safe_ref_label', 'supabase_vault://[REDACTED]'
    );
end;
$_$;




COMMENT ON FUNCTION "public"."revoke_instagram_credentials_vault_secret"("p_secret_ref" "text", "p_reason" "text", "p_request_id" "text") IS 'Patch 2C-1 service-role-only helper that neutralizes a Supabase Vault Instagram credential secret with a unique revoked name. Valid reasons exclude restorable lifecycle states.';



CREATE OR REPLACE FUNCTION "public"."rls_auto_enable"() RETURNS "event_trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$$;




CREATE OR REPLACE FUNCTION "public"."rollback_test_instagram_onboarding_v1"("p_account_id" "uuid", "p_tenant_id" "uuid", "p_entitlement_id" "uuid", "p_expected_username" "text", "p_expected_checkout_id" "uuid", "p_expected_package" "text", "p_reason" "text", "p_request_id" "text", "p_idempotency_key" "text", "p_dry_run" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $_$
declare
  v_now timestamptz := now();
  v_expected_username text := lower(btrim(coalesce(p_expected_username, '')));
  v_expected_package text := lower(btrim(coalesce(p_expected_package, '')));
  v_reason text := lower(btrim(coalesce(p_reason, '')));
  v_request_id text := btrim(coalesce(p_request_id, ''));
  v_idempotency_key text := btrim(coalesce(p_idempotency_key, ''));
  v_idempotency_hash text;
  v_fingerprint text;
  v_existing_audit public.test_instagram_onboarding_rollbacks%rowtype;
  v_account public.ig_accounts%rowtype;
  v_link public.client_instagram_accounts%rowtype;
  v_entitlement public.client_account_entitlements%rowtype;
  v_checkout public.commercial_checkout_sessions%rowtype;
  v_assignment public.account_assignments%rowtype;
  v_instance public.phone_app_instances%rowtype;
  v_heartbeat public.device_heartbeats%rowtype;
  v_audit_id uuid := gen_random_uuid();
  v_tombstone_username text;
  v_actor_role text := coalesce(auth.role(), 'unknown');
  v_active_requests integer := 0;
  v_active_runs integer := 0;
  v_active_locks integer := 0;
  v_active_auto_login integer := 0;
  v_active_dependencies integer := 0;
  v_other_tenant_accounts integer := 0;
  v_existing_reserved integer := 0;
  v_assignment_count integer := 0;
  v_counts jsonb := '{}'::jsonb;
  v_planned jsonb := '{}'::jsonb;
  v_changed jsonb := '{}'::jsonb;
  v_before jsonb := '{}'::jsonb;
  v_after jsonb := '{}'::jsonb;
  v_credential_result jsonb := '{}'::jsonb;
  v_release_result jsonb := '{}'::jsonb;
  v_rows integer := 0;
  v_count integer := 0;
  v_previous_version bigint;
  v_new_version bigint;
  v_kind text;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'service_role_required' using errcode = '42501';
  end if;

  if p_account_id is null or p_tenant_id is null or p_entitlement_id is null
     or p_expected_checkout_id is null or v_expected_username = ''
     or v_expected_package = '' or v_reason = '' or v_request_id = ''
     or v_idempotency_key = '' or p_dry_run is null then
    return jsonb_build_object('ok', false, 'reason', 'required_parameter_missing', 'dry_run', p_dry_run);
  end if;
  if v_request_id !~ '^[A-Za-z0-9._:-]{1,120}$' then
    return jsonb_build_object('ok', false, 'reason', 'request_id_invalid', 'dry_run', p_dry_run);
  end if;
  if v_idempotency_key !~ '^[A-Za-z0-9._:-]{8,200}$' then
    return jsonb_build_object('ok', false, 'reason', 'idempotency_key_invalid', 'dry_run', p_dry_run);
  end if;
  if v_reason !~ '^[a-z0-9_:-]{3,120}$' then
    return jsonb_build_object('ok', false, 'reason', 'rollback_reason_invalid', 'dry_run', p_dry_run);
  end if;

  v_idempotency_hash := encode(digest(v_idempotency_key, 'sha256'), 'hex');
  v_fingerprint := encode(digest(concat_ws('|',
    p_account_id::text, p_tenant_id::text, p_entitlement_id::text,
    v_expected_username, p_expected_checkout_id::text, v_expected_package,
    v_reason, v_request_id
  ), 'sha256'), 'hex');

  perform pg_advisory_xact_lock(hashtextextended('rollback_test_instagram_onboarding_v1:' || p_account_id::text, 0));
  perform pg_advisory_xact_lock(hashtextextended('rollback_test_instagram_onboarding_v1:' || v_idempotency_hash, 0));

  select * into v_existing_audit
  from public.test_instagram_onboarding_rollbacks
  where idempotency_key_hash = v_idempotency_hash;
  if found then
    if v_existing_audit.input_fingerprint <> v_fingerprint then
      return jsonb_build_object(
        'ok', false,
        'reason', 'idempotency_fingerprint_mismatch',
        'dry_run', p_dry_run,
        'idempotency_key_prefix', left(v_idempotency_hash, 12)
      );
    end if;
    return jsonb_build_object(
      'ok', true,
      'reason', 'already_rolled_back',
      'dry_run', false,
      'account_id', v_existing_audit.account_id,
      'tenant_id', v_existing_audit.tenant_id,
      'entitlement_id', v_existing_audit.entitlement_id,
      'audit_id', v_existing_audit.id,
      'records_changed', v_existing_audit.records_changed,
      'completed_at', v_existing_audit.completed_at
    );
  end if;

  select * into v_account from public.ig_accounts where id = p_account_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'account_not_found', 'dry_run', p_dry_run);
  end if;
  if lower(btrim(v_account.username)) <> v_expected_username then
    return jsonb_build_object('ok', false, 'reason', 'username_mismatch', 'dry_run', p_dry_run);
  end if;
  if v_account.admin_lifecycle_status <> 'active'
     or v_account.status = 'rolled_back_test_onboarding' then
    return jsonb_build_object('ok', false, 'reason', 'account_not_active_for_rollback', 'dry_run', p_dry_run);
  end if;

  select * into v_link
  from public.client_instagram_accounts
  where account_id = p_account_id and client_id = p_tenant_id and active = true
  for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'tenant_or_active_ownership_mismatch', 'dry_run', p_dry_run);
  end if;

  select * into v_entitlement
  from public.client_account_entitlements
  where id = p_entitlement_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'entitlement_not_found', 'dry_run', p_dry_run);
  end if;
  if v_entitlement.client_id <> p_tenant_id
     or v_entitlement.account_id is distinct from p_account_id
     or v_entitlement.status <> 'entitlement_consumed' then
    return jsonb_build_object('ok', false, 'reason', 'entitlement_ownership_or_status_mismatch', 'dry_run', p_dry_run);
  end if;
  if lower(coalesce(v_entitlement.commercial_package_code, '')) <> v_expected_package
     or lower(coalesce(v_entitlement.plan_key, '')) <> v_expected_package then
    return jsonb_build_object('ok', false, 'reason', 'package_mismatch', 'dry_run', p_dry_run);
  end if;
  if v_entitlement.checkout_session_id <> p_expected_checkout_id then
    return jsonb_build_object('ok', false, 'reason', 'checkout_mismatch', 'dry_run', p_dry_run);
  end if;

  select * into v_checkout
  from public.commercial_checkout_sessions
  where id = p_expected_checkout_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'checkout_not_found', 'dry_run', p_dry_run);
  end if;
  if v_checkout.client_id is distinct from p_tenant_id
     or v_checkout.status <> 'checkout_activated_test'
     or lower(coalesce(v_checkout.plan_key, '')) <> v_expected_package then
    return jsonb_build_object('ok', false, 'reason', 'checkout_not_test_or_package_mismatch', 'dry_run', p_dry_run);
  end if;

  select count(*) into v_existing_reserved
  from public.client_account_entitlements e
  where e.client_id = p_tenant_id and e.status = 'entitlement_reserved' and e.id <> p_entitlement_id;
  if v_existing_reserved <> 0 then
    return jsonb_build_object('ok', false, 'reason', 'tenant_reserved_entitlement_conflict', 'dry_run', p_dry_run, 'count', v_existing_reserved);
  end if;

  select count(*) into v_other_tenant_accounts
  from public.client_instagram_accounts cia
  where cia.client_id = p_tenant_id and cia.active = true and cia.account_id <> p_account_id;
  if v_other_tenant_accounts <> 2 then
    return jsonb_build_object('ok', false, 'reason', 'tenant_other_account_count_mismatch', 'dry_run', p_dry_run, 'count', v_other_tenant_accounts);
  end if;

  select count(*) into v_assignment_count
  from public.account_assignments aa
  where aa.account_id = p_account_id and aa.status in ('pending', 'reserved', 'active');
  if v_assignment_count <> 1 then
    return jsonb_build_object('ok', false, 'reason', 'open_assignment_count_mismatch', 'dry_run', p_dry_run, 'count', v_assignment_count);
  end if;
  select * into v_assignment
  from public.account_assignments aa
  where aa.account_id = p_account_id and aa.status in ('pending', 'reserved', 'active')
  for update;
  if v_assignment.app_instance_id is null then
    return jsonb_build_object('ok', false, 'reason', 'assignment_app_instance_missing', 'dry_run', p_dry_run);
  end if;
  select * into v_instance from public.phone_app_instances where id = v_assignment.app_instance_id for update;
  if not found or v_instance.current_account_id is distinct from p_account_id or v_instance.status <> 'occupied' then
    return jsonb_build_object('ok', false, 'reason', 'assignment_instance_occupant_mismatch', 'dry_run', p_dry_run);
  end if;
  select * into v_heartbeat from public.device_heartbeats where device_id = v_assignment.device_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'device_heartbeat_missing', 'dry_run', p_dry_run);
  end if;
  if v_heartbeat.current_account_id is not null
     or v_heartbeat.current_assignment_id is not null
     or v_heartbeat.current_clone_id is not null then
    return jsonb_build_object('ok', false, 'reason', 'device_runtime_occupancy_active', 'dry_run', p_dry_run);
  end if;

  select count(*) into v_active_requests
  from public.account_run_requests r
  where r.account_id = p_account_id
    and r.status in ('pending', 'queued', 'claimed', 'starting', 'running', 'in_progress');
  select count(*) into v_active_auto_login
  from public.account_run_requests r
  where r.account_id = p_account_id
    and lower(r.requested_run_type) like '%login%'
    and r.status in ('pending', 'queued', 'claimed', 'starting', 'running', 'in_progress');
  select count(*) into v_active_runs
  from public.ig_runs r
  where r.account_id = p_account_id
    and r.status in ('pending', 'queued', 'starting', 'running', 'in_progress', 'active');
  select count(*) into v_active_locks
  from public.auto_restart_device_locks l
  where (l.account_id = p_account_id or l.device_id = v_assignment.device_id or l.app_instance_id = v_assignment.app_instance_id)
    and l.lease_expires_at > v_now
    and l.release_reason is null;
  if v_active_requests <> 0 then
    return jsonb_build_object('ok', false, 'reason', 'active_request_guard', 'dry_run', p_dry_run, 'count', v_active_requests);
  end if;
  if v_active_runs <> 0 then
    return jsonb_build_object('ok', false, 'reason', 'active_run_guard', 'dry_run', p_dry_run, 'count', v_active_runs);
  end if;
  if v_active_locks <> 0 then
    return jsonb_build_object('ok', false, 'reason', 'active_lock_guard', 'dry_run', p_dry_run, 'count', v_active_locks);
  end if;
  if v_active_auto_login <> 0 then
    return jsonb_build_object('ok', false, 'reason', 'active_auto_login_guard', 'dry_run', p_dry_run, 'count', v_active_auto_login);
  end if;

  select
    (select count(*) from public.live_view_sessions s where s.account_id = p_account_id and s.status in ('pending', 'starting', 'active', 'running'))
    + (select count(*) from public.ig_dm_jobs j where j.account_id = p_account_id and j.status::text in ('claimed', 'processing', 'running', 'in_progress', 'sending'))
    + (select count(*) from public.ig_social_profile_snapshot_jobs j where j.account_id = p_account_id and j.status in ('claimed', 'processing', 'running', 'in_progress'))
    + (select count(*) from public.ct_target_verification_jobs j where j.account_id = p_account_id and j.status = 'processing')
    + (select count(*) from public.credential_update_requests r where r.account_id = p_account_id and r.status in ('pending', 'active', 'processing'))
    + (select count(*) from public.account_verification_code_submissions s where s.account_id = p_account_id and s.status in ('pending', 'active', 'processing'))
    + (select count(*) from public.incident_resume_authorizations a where a.account_id = p_account_id and a.status in ('armed', 'active', 'pending'))
    + (select count(*) from public.scheduled_session_preflights s where s.account_id = p_account_id and s.status in ('pending', 'claimed', 'running', 'active'))
  into v_active_dependencies;
  if v_active_dependencies <> 0 then
    return jsonb_build_object('ok', false, 'reason', 'active_dependent_entity_guard', 'dry_run', p_dry_run, 'count', v_active_dependencies);
  end if;

  v_counts := jsonb_build_object(
    'credential_records', (select count(*) from public.account_credentials c where c.account_id = p_account_id and c.provider = 'instagram'),
    'ownership_client_links', (select count(*) from public.client_instagram_accounts c where c.account_id = p_account_id and c.active = true),
    'subscription_account_links', (select count(*) from public.client_subscription_accounts c where c.account_id = p_account_id and c.status = 'active'),
    'settings_rows',
      (select count(*) from public.ig_account_settings s where s.account_id = p_account_id)
      + (select count(*) from public.ig_account_dm_settings s where s.account_id = p_account_id)
      + (select count(*) from public.ig_account_unfollow_settings s where s.account_id = p_account_id)
      + (select count(*) from public.ig_account_follow_settings s where s.account_id = p_account_id)
      + (select count(*) from public.account_follow_source_settings s where s.account_id = p_account_id)
      + (select count(*) from public.account_warmup_settings s where s.account_id = p_account_id),
    'filters_rows', (select count(*) from public.ig_account_filters s where s.account_id = p_account_id),
    'targets_total', (select count(*) from public.ig_targets t where t.account_id = p_account_id),
    'targets_active', (select count(*) from public.ig_targets t where t.account_id = p_account_id and t.archived_at is null and t.deleted_at is null),
    'ct_audit_events_historical', (select count(*) from public.ct_target_audit_events e where e.account_id = p_account_id),
    'verification_jobs_total', (select count(*) from public.ct_target_verification_jobs j where j.account_id = p_account_id),
    'verification_jobs_nonhistorical', (select count(*) from public.ct_target_verification_jobs j where j.account_id = p_account_id and j.status in ('pending', 'processing', 'retry_scheduled')),
    'protection_entries_total', (select count(*) from public.account_protection_list_entries e where e.account_id = p_account_id),
    'protection_entries_active', (select count(*) from public.account_protection_list_entries e where e.account_id = p_account_id and e.active),
    'protection_versions_historical', (select count(*) from public.account_protection_list_versions e where e.account_id = p_account_id),
    'protection_events_historical', (select count(*) from public.account_protection_list_events e where e.account_id = p_account_id),
    'onboarding_sessions_total', (select count(*) from public.client_instagram_onboarding_sessions s where s.account_id = p_account_id),
    'onboarding_sessions_active', (select count(*) from public.client_instagram_onboarding_sessions s where s.account_id = p_account_id and s.status in ('creating', 'active')),
    'dashboard_actions_nonhistorical', (select count(*) from public.account_dashboard_actions a where a.account_id = p_account_id and a.status in ('pending', 'acknowledged', 'pending_verification', 'code_submitted')),
    'historical_requests', (select count(*) from public.account_run_requests r where r.account_id = p_account_id),
    'historical_runs', (select count(*) from public.ig_runs r where r.account_id = p_account_id),
    'historical_action_logs', (select count(*) from public.ig_action_logs l where l.account_id = p_account_id),
    'historical_incidents', (select count(*) from public.account_incidents i where i.account_id = p_account_id),
    'active_requests', v_active_requests,
    'active_runs', v_active_runs,
    'active_locks', v_active_locks,
    'active_auto_login', v_active_auto_login,
    'other_tenant_accounts', v_other_tenant_accounts
  );
  v_planned := jsonb_build_object(
    'ig_accounts', 1,
    'client_instagram_accounts', 1,
    'client_subscription_accounts', (select count(*) from public.client_subscription_accounts c where c.account_id = p_account_id and c.status = 'active'),
    'account_commercial_packages', (select count(*) from public.account_commercial_packages c where c.account_id = p_account_id and c.status = 'active'),
    'account_credentials', (select count(*) from public.account_credentials c where c.account_id = p_account_id and c.provider = 'instagram' and c.status <> 'revoked'),
    'account_assignments', 1,
    'phone_app_instances', 1,
    'settings_deleted', v_counts->'settings_rows',
    'filters_deleted', v_counts->'filters_rows',
    'targets_archived', v_counts->'targets_active',
    'verification_jobs_deleted', v_counts->'verification_jobs_nonhistorical',
    'protection_entries_disabled', v_counts->'protection_entries_active',
    'onboarding_sessions_abandoned', v_counts->'onboarding_sessions_active',
    'dashboard_actions_resolved', v_counts->'dashboard_actions_nonhistorical',
    'client_account_entitlements', 1,
    'account_incidents', 1,
    'test_instagram_onboarding_rollbacks', 1,
    'commercial_checkout_audit_events', 1
  );
  v_before := jsonb_build_object(
    'account_status', v_account.status,
    'admin_lifecycle_status', v_account.admin_lifecycle_status,
    'username', v_account.username,
    'entitlement_status', v_entitlement.status,
    'assignment_status', v_assignment.status,
    'app_instance_status', v_instance.status,
    'client_link_active', v_link.active
  );

  if p_dry_run then
    return jsonb_build_object(
      'ok', true,
      'reason', 'dry_run_pass',
      'dry_run', true,
      'account_id', p_account_id,
      'tenant_id', p_tenant_id,
      'entitlement_id', p_entitlement_id,
      'assignment_id', v_assignment.id,
      'app_instance_id', v_instance.id,
      'idempotency_key_prefix', left(v_idempotency_hash, 12),
      'guards', jsonb_build_object(
        'account_exact', true, 'username_exact', true, 'tenant_exact', true,
        'entitlement_exact', true, 'checkout_test_exact', true, 'package_exact', true,
        'entitlement_consumed_by_account', true, 'zero_active_requests', true,
        'zero_active_runs', true, 'zero_active_locks', true, 'zero_auto_login', true,
        'device_idle', true, 'assignment_occupant_exact', true,
        'zero_active_dependencies', true, 'two_other_tenant_accounts_untouched', true,
        'idempotency_fingerprint_available', true
      ),
      'counts', v_counts,
      'historical_rows_preserved', jsonb_build_object(
        'requests', v_counts->'historical_requests', 'runs', v_counts->'historical_runs',
        'action_logs', v_counts->'historical_action_logs', 'incidents', v_counts->'historical_incidents',
        'ct_audit_events', v_counts->'ct_audit_events_historical',
        'protection_events', v_counts->'protection_events_historical'
      ),
      'planned_mutations', v_planned
    );
  end if;

  begin
    v_credential_result := public.revoke_instagram_account_credentials(
      p_account_id, 'instagram', 'test_onboarding_rollback', v_request_id
    );
    if coalesce((v_credential_result->>'ok')::boolean, false) is not true
       or coalesce(v_credential_result->>'vault_cleanup_status', '') not in ('neutralized', 'not_found', 'not_applicable', 'partial_neutralized') then
      raise exception 'credential_or_vault_revoke_failed';
    end if;

    v_release_result := public.release_account_schedule_capacity(
      p_account_id, 'test_onboarding_rollback', 'test_onboarding_rollback_v1', auth.uid()
    );
    if coalesce((v_release_result->>'ok')::boolean, false) is not true then
      raise exception 'assignment_release_failed';
    end if;
    if exists (select 1 from public.account_assignments a where a.id = v_assignment.id and a.status in ('pending', 'reserved', 'active')) then
      raise exception 'assignment_still_open_after_release';
    end if;
    if exists (select 1 from public.phone_app_instances i where i.id = v_instance.id and (i.status <> 'available' or i.current_account_id is not null)) then
      raise exception 'app_instance_still_occupied_after_release';
    end if;

    update public.client_subscription_accounts
       set status = 'removed', updated_at = v_now
     where account_id = p_account_id and status = 'active';
    get diagnostics v_rows = row_count;
    v_changed := v_changed || jsonb_build_object('client_subscription_accounts_removed', v_rows);

    update public.account_commercial_packages
       set status = 'rolled_back_test_onboarding', ends_at = coalesce(ends_at, v_now), updated_at = v_now,
           metadata_safe = coalesce(metadata_safe, '{}'::jsonb) || jsonb_build_object('rollback_request_id', v_request_id, 'source', 'test_onboarding_rollback_v1')
     where account_id = p_account_id and status = 'active';
    get diagnostics v_rows = row_count;
    v_changed := v_changed || jsonb_build_object('account_commercial_packages_rolled_back', v_rows);

    update public.account_commercial_addons
       set status = 'rolled_back_test_onboarding', ends_at = coalesce(ends_at, v_now), updated_at = v_now,
           metadata_safe = coalesce(metadata_safe, '{}'::jsonb) || jsonb_build_object('rollback_request_id', v_request_id, 'source', 'test_onboarding_rollback_v1')
     where account_id = p_account_id and status = 'active';
    get diagnostics v_rows = row_count;
    v_changed := v_changed || jsonb_build_object('account_commercial_addons_rolled_back', v_rows);

    delete from public.ig_account_settings where account_id = p_account_id;
    get diagnostics v_rows = row_count;
    v_changed := v_changed || jsonb_build_object('ig_account_settings_deleted', v_rows);
    delete from public.ig_account_dm_settings where account_id = p_account_id;
    get diagnostics v_rows = row_count;
    v_changed := v_changed || jsonb_build_object('ig_account_dm_settings_deleted', v_rows);
    delete from public.ig_account_unfollow_settings where account_id = p_account_id;
    get diagnostics v_rows = row_count;
    v_changed := v_changed || jsonb_build_object('ig_account_unfollow_settings_deleted', v_rows);
    delete from public.ig_account_follow_settings where account_id = p_account_id;
    get diagnostics v_rows = row_count;
    v_changed := v_changed || jsonb_build_object('ig_account_follow_settings_deleted', v_rows);
    delete from public.account_follow_source_settings where account_id = p_account_id;
    get diagnostics v_rows = row_count;
    v_changed := v_changed || jsonb_build_object('account_follow_source_settings_deleted', v_rows);
    delete from public.account_warmup_settings where account_id = p_account_id;
    get diagnostics v_rows = row_count;
    v_changed := v_changed || jsonb_build_object('account_warmup_settings_deleted', v_rows);
    delete from public.ig_account_filters where account_id = p_account_id;
    get diagnostics v_rows = row_count;
    v_changed := v_changed || jsonb_build_object('ig_account_filters_deleted', v_rows);

    update public.ig_dm_templates set active = false, updated_at = v_now
     where account_id = p_account_id and active = true;
    get diagnostics v_rows = row_count;
    v_changed := v_changed || jsonb_build_object('ig_dm_templates_disabled', v_rows);
    update public.client_entitlements set active = false, updated_at = v_now
     where account_id = p_account_id and active = true;
    get diagnostics v_rows = row_count;
    v_changed := v_changed || jsonb_build_object('client_entitlements_disabled', v_rows);

    update public.ig_targets
       set status = 'archived', archived_at = coalesce(archived_at, v_now),
           archive_reason = 'test_onboarding_rollback', updated_at = v_now,
           metadata_safe = coalesce(metadata_safe, '{}'::jsonb) || jsonb_build_object('rollback_request_id', v_request_id, 'source', 'test_onboarding_rollback_v1')
     where account_id = p_account_id and archived_at is null and deleted_at is null;
    get diagnostics v_rows = row_count;
    v_changed := v_changed || jsonb_build_object('ig_targets_archived', v_rows);

    delete from public.ct_target_verification_jobs
     where account_id = p_account_id and status in ('pending', 'processing', 'retry_scheduled');
    get diagnostics v_rows = row_count;
    v_changed := v_changed || jsonb_build_object('ct_target_verification_jobs_deleted', v_rows);

    for v_kind in
      select distinct e.list_kind from public.account_protection_list_entries e
      where e.account_id = p_account_id and e.active = true
    loop
      select coalesce(v.version, 0) into v_previous_version
      from public.account_protection_list_versions v
      where v.account_id = p_account_id and v.list_kind = v_kind
      for update;
      v_previous_version := coalesce(v_previous_version, 0);
      v_new_version := v_previous_version + 1;
      insert into public.account_protection_list_versions(account_id, list_kind, version, updated_at)
      values (p_account_id, v_kind, v_new_version, v_now)
      on conflict (account_id, list_kind) do update set version = excluded.version, updated_at = excluded.updated_at;
      update public.account_protection_list_entries
         set active = false, version = v_new_version, updated_at = v_now, updated_by_auth_user_id = auth.uid()
       where account_id = p_account_id and list_kind = v_kind and active = true;
      get diagnostics v_rows = row_count;
      v_count := v_count + v_rows;
      insert into public.account_protection_list_events(
        account_id, list_kind, normalized_username, action, source_surface,
        actor_auth_user_id, request_id, idempotency_key, previous_version,
        new_version, metadata_safe, created_at
      ) values (
        p_account_id, v_kind, null, 'clear', 'test_onboarding_rollback_v1',
        auth.uid(), v_request_id, left(v_idempotency_hash, 64), v_previous_version,
        v_new_version, jsonb_build_object('entries_disabled', v_rows, 'reason', v_reason), v_now
      );
    end loop;
    v_changed := v_changed || jsonb_build_object('protection_entries_disabled', v_count);

    update public.client_instagram_onboarding_sessions
       set status = 'abandoned', abandoned_at = coalesce(abandoned_at, v_now),
           lease_owner = null, lease_expires_at = null,
           failure_reason = 'test_onboarding_rollback', updated_at = v_now
     where account_id = p_account_id and status in ('creating', 'active');
    get diagnostics v_rows = row_count;
    v_changed := v_changed || jsonb_build_object('onboarding_sessions_abandoned', v_rows);

    update public.account_dashboard_actions
       set status = 'resolved', resolved_at = coalesce(resolved_at, v_now), updated_at = v_now,
           metadata_safe = coalesce(metadata_safe, '{}'::jsonb) || jsonb_build_object('resolution_reason', 'test_onboarding_rollback', 'rollback_request_id', v_request_id)
     where account_id = p_account_id and status in ('pending', 'acknowledged', 'pending_verification', 'code_submitted');
    get diagnostics v_rows = row_count;
    v_changed := v_changed || jsonb_build_object('dashboard_actions_resolved', v_rows);
    update public.client_account_notifications
       set status = 'resolved', resolved_at = coalesce(resolved_at, v_now)
     where account_id = p_account_id and status = 'active';
    get diagnostics v_rows = row_count;
    v_changed := v_changed || jsonb_build_object('client_notifications_resolved', v_rows);

    update public.client_instagram_accounts
       set active = false,
           onboarding_status = 'blocked', provisioning_status = 'paused', login_status = 'logged_out',
           onboarding_rollback_at = v_now, onboarding_rollback_id = v_audit_id, updated_at = v_now
     where id = v_link.id and active = true;
    get diagnostics v_rows = row_count;
    if v_rows <> 1 then raise exception 'client_link_tombstone_failed'; end if;
    v_changed := v_changed || jsonb_build_object('client_instagram_accounts_tombstoned', v_rows);

    update public.client_account_entitlements
       set status = 'entitlement_reserved', account_id = null, consumed_at = null, updated_at = v_now,
           metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
             'rollback_reason', v_reason, 'rolled_back_account_id', p_account_id,
             'rolled_back_at', v_now, 'rollback_request_id', v_request_id,
             'source', 'test_onboarding_rollback_v1'
           )
     where id = p_entitlement_id and status = 'entitlement_consumed' and account_id = p_account_id;
    get diagnostics v_rows = row_count;
    if v_rows <> 1 then raise exception 'entitlement_reset_failed'; end if;
    v_changed := v_changed || jsonb_build_object('client_account_entitlements_reset', v_rows);

    update public.account_incidents
       set status = 'resolved', resolved_at = coalesce(resolved_at, v_now),
           resolution_reason = 'test_onboarding_rolled_back_after_package_runtime_fix',
           resolution_note = 'Resolved by transactionally audited Test onboarding rollback after package/runtime correction.',
           updated_at = v_now
     where account_id = p_account_id and incident_type = 'login_package_mismatch' and status <> 'resolved';
    get diagnostics v_rows = row_count;
    if v_rows <> 1 then raise exception 'login_package_mismatch_incident_resolution_failed'; end if;
    v_changed := v_changed || jsonb_build_object('login_package_mismatch_incidents_resolved', v_rows);

    v_tombstone_username := 'rb_test_' || left(replace(p_account_id::text, '-', ''), 20);
    update public.ig_accounts
       set username = v_tombstone_username,
           status = 'rolled_back_test_onboarding', admin_lifecycle_status = 'cancelled',
           email = null, password = null, device_id = null,
           username_verification_status = 'unknown',
           username_verification_reason = 'test_onboarding_rollback',
           updated_at = v_now
     where id = p_account_id and lower(btrim(username)) = v_expected_username;
    get diagnostics v_rows = row_count;
    if v_rows <> 1 then raise exception 'account_tombstone_failed'; end if;
    v_changed := v_changed || jsonb_build_object('ig_accounts_tombstoned', v_rows);

    v_changed := v_changed || jsonb_build_object(
      'account_credentials_revoked', coalesce((v_credential_result->>'credentials_revoked')::integer, 0),
      'account_assignments_released', coalesce((v_release_result->>'released_count')::integer, 0),
      'phone_app_instances_released', coalesce((v_release_result->>'app_instances_released_count')::integer, 0)
    );
    v_after := jsonb_build_object(
      'account_status', 'rolled_back_test_onboarding',
      'admin_lifecycle_status', 'cancelled',
      'username', v_tombstone_username,
      'entitlement_status', 'entitlement_reserved',
      'assignment_status', 'released',
      'app_instance_status', 'available',
      'client_link_active', false,
      'vault_cleanup_status', v_credential_result->>'vault_cleanup_status'
    );

    insert into public.commercial_checkout_audit_events(
      checkout_session_id, entitlement_id, event_type, actor_email, client_id, payload, created_at
    ) values (
      p_expected_checkout_id, p_entitlement_id, 'test_instagram_onboarding_rolled_back', null, p_tenant_id,
      jsonb_build_object(
        'account_id', p_account_id, 'request_id', v_request_id,
        'reason', v_reason, 'source', 'test_onboarding_rollback_v1',
        'audit_id', v_audit_id
      ), v_now
    );
    v_changed := v_changed || jsonb_build_object('commercial_checkout_audit_events_inserted', 1);

    insert into public.test_instagram_onboarding_rollbacks(
      id, account_id, tenant_id, entitlement_id, checkout_id,
      expected_username, expected_package, request_id, idempotency_key_hash,
      idempotency_key_prefix, input_fingerprint, reason, actor_id, actor_role,
      counts_before, records_changed, before_status, after_status, result,
      created_at, completed_at
    ) values (
      v_audit_id, p_account_id, p_tenant_id, p_entitlement_id, p_expected_checkout_id,
      v_expected_username, v_expected_package, v_request_id, v_idempotency_hash,
      left(v_idempotency_hash, 12), v_fingerprint, v_reason, auth.uid(), v_actor_role,
      v_counts, v_changed, v_before, v_after, 'completed', v_now, v_now
    );
  exception when others then
    return jsonb_build_object(
      'ok', false,
      'reason', 'transaction_failed',
      'error_code', sqlstate,
      'error_safe', left(sqlerrm, 160),
      'dry_run', false,
      'account_id', p_account_id
    );
  end;

  return jsonb_build_object(
    'ok', true,
    'reason', 'rolled_back',
    'dry_run', false,
    'account_id', p_account_id,
    'tenant_id', p_tenant_id,
    'entitlement_id', p_entitlement_id,
    'assignment_id', v_assignment.id,
    'app_instance_id', v_instance.id,
    'audit_id', v_audit_id,
    'tombstone_username', v_tombstone_username,
    'credential_revocation', v_credential_result,
    'assignment_release', v_release_result,
    'records_changed', v_changed,
    'history_preserved', true,
    'ready_to_restart_onboarding', true
  );
end;
$_$;




COMMENT ON FUNCTION "public"."rollback_test_instagram_onboarding_v1"("p_account_id" "uuid", "p_tenant_id" "uuid", "p_entitlement_id" "uuid", "p_expected_username" "text", "p_expected_checkout_id" "uuid", "p_expected_package" "text", "p_reason" "text", "p_request_id" "text", "p_idempotency_key" "text", "p_dry_run" boolean) IS 'Service-role-only, Test-checkout-only transactional logical rollback. Dry-run defaults true and never mutates.';



CREATE TABLE IF NOT EXISTS "public"."account_credentials" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "account_id" "uuid" NOT NULL,
    "client_id" "uuid",
    "provider" "text" DEFAULT 'instagram'::"text" NOT NULL,
    "username_at_submission" "text",
    "secret_ref" "text",
    "secret_provider" "text",
    "credentials_version" integer DEFAULT 1 NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "last_submitted_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "last_rotated_at" timestamp with time zone,
    "reauth_required" boolean DEFAULT false NOT NULL,
    "reauth_reason" "text",
    "submitted_by" "uuid",
    "submitted_via" "text",
    "revoked_at" timestamp with time zone,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "last_updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_by_actor_type" "text",
    "updated_by_actor_id" "text",
    "source" "text",
    "metadata_safe" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    CONSTRAINT "account_credentials_actor_type_check" CHECK ((("updated_by_actor_type" IS NULL) OR ("updated_by_actor_type" = ANY (ARRAY['admin'::"text", 'client'::"text", 'system'::"text", 'migration'::"text", 'backend'::"text"])))),
    CONSTRAINT "account_credentials_credentials_version_positive" CHECK (("credentials_version" >= 1)),
    CONSTRAINT "account_credentials_metadata_object_check" CHECK (("jsonb_typeof"("metadata") = 'object'::"text")),
    CONSTRAINT "account_credentials_metadata_safe_check" CHECK ((("jsonb_typeof"("metadata_safe") = 'object'::"text") AND (NOT "public"."jsonb_has_forbidden_safe_metadata_key"("metadata_safe")))),
    CONSTRAINT "account_credentials_provider_check" CHECK (("provider" = 'instagram'::"text")),
    CONSTRAINT "account_credentials_reauth_reason_nonempty" CHECK ((("reauth_reason" IS NULL) OR ("char_length"(TRIM(BOTH FROM "reauth_reason")) > 0))),
    CONSTRAINT "account_credentials_secret_provider_nonempty" CHECK (("char_length"(TRIM(BOTH FROM "secret_provider")) > 0)),
    CONSTRAINT "account_credentials_secret_ref_nonempty" CHECK (("char_length"(TRIM(BOTH FROM "secret_ref")) > 0)),
    CONSTRAINT "account_credentials_source_check" CHECK ((("source" IS NULL) OR ("source" = ANY (ARRAY['add_profile'::"text", 'secure_update_link'::"text", 'admin_backend'::"text", 'migration'::"text", 'unknown'::"text"])))),
    CONSTRAINT "account_credentials_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'superseded'::"text", 'revoked'::"text", 'missing'::"text", 'configured'::"text", 'reauth_required'::"text", 'update_needed'::"text", 'unknown'::"text"]))),
    CONSTRAINT "account_credentials_submitted_via_check" CHECK ((("submitted_via" IS NULL) OR ("submitted_via" = ANY (ARRAY['client_dashboard'::"text", 'admin_dashboard'::"text", 'api'::"text", 'system'::"text", 'migration'::"text", 'add_profile'::"text", 'secure_update_link'::"text", 'admin_backend'::"text", 'unknown'::"text"])))),
    CONSTRAINT "account_credentials_username_nonempty" CHECK ((("username_at_submission" IS NULL) OR ("char_length"(TRIM(BOTH FROM "username_at_submission")) > 0)))
);




COMMENT ON TABLE "public"."account_credentials" IS 'Entry 2D-1 metadata-only credential registry. Stores secret_ref/secret_provider only; never store raw passwords, encrypted passwords, tokens, cookies, or vault payloads.';



COMMENT ON COLUMN "public"."account_credentials"."secret_ref" IS 'Reference to a future vault/KMS/secret manager entry. This is not the secret value and must not be client-readable.';



COMMENT ON COLUMN "public"."account_credentials"."secret_provider" IS 'Identifier for the future secret backend, for example supabase_vault, aws_secrets_manager, 1password, or local_ops_vault.';



COMMENT ON COLUMN "public"."account_credentials"."credentials_version" IS 'Monotonic safe credential metadata version. Increment on future submit/update/rotation APIs.';



COMMENT ON COLUMN "public"."account_credentials"."metadata" IS 'Safe metadata only. Never store passwords, raw secrets, tokens, cookies, recovery codes, screenshots, raw XML, or client-visible device internals.';



COMMENT ON COLUMN "public"."account_credentials"."last_updated_at" IS 'Credential Secure Pipeline V1 safe metadata update timestamp. Does not imply a password read.';



COMMENT ON COLUMN "public"."account_credentials"."updated_by_actor_type" IS 'Safe actor type for metadata updates: admin, client, system, migration, or backend.';



COMMENT ON COLUMN "public"."account_credentials"."updated_by_actor_id" IS 'Safe actor identifier supplied by backend/API. Never store password, token, or secret material here.';



COMMENT ON COLUMN "public"."account_credentials"."source" IS 'Safe ingestion source: add_profile, secure_update_link, admin_backend, migration, or unknown.';



COMMENT ON COLUMN "public"."account_credentials"."metadata_safe" IS 'Safe metadata only. Forbidden keys include password, token, secret_ref, raw request body, raw logs/XML, screenshots, and device internals.';



CREATE OR REPLACE FUNCTION "public"."rotate_instagram_account_credentials"("p_account_id" "uuid", "p_client_id" "uuid", "p_username_at_submission" "text", "p_secret_ref" "text", "p_secret_provider" "text", "p_credentials_version" integer, "p_action" "text", "p_external_request_id" "text", "p_request_id" "text", "p_submitted_by" "uuid", "p_submitted_via" "text") RETURNS "public"."account_credentials"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_next_version integer;
  v_row public.account_credentials;
  v_metadata jsonb;
  v_metadata_safe jsonb;
  v_submitted_via text := lower(coalesce(nullif(trim(p_submitted_via), ''), 'unknown'));
  v_source text := 'unknown';
  v_actor_type text := 'backend';
begin
  if auth.role() <> 'service_role' then
    raise exception 'service_role_required';
  end if;

  if p_account_id is null then
    raise exception 'account_id_required';
  end if;

  if p_secret_ref is null or char_length(trim(p_secret_ref)) = 0 then
    raise exception 'secret_ref_required';
  end if;

  if p_secret_provider <> 'supabase_vault' then
    raise exception 'secret_provider_not_supported';
  end if;

  if p_credentials_version is null or p_credentials_version < 1 then
    raise exception 'credentials_version_required';
  end if;

  if p_action not in ('submit', 'update_password') then
    raise exception 'action_not_supported';
  end if;

  if v_submitted_via not in (
    'client_dashboard',
    'admin_dashboard',
    'api',
    'system',
    'migration',
    'add_profile',
    'secure_update_link',
    'admin_backend',
    'unknown'
  ) then
    raise exception 'submitted_via_not_supported';
  end if;

  v_source := case v_submitted_via
    when 'add_profile' then 'add_profile'
    when 'secure_update_link' then 'secure_update_link'
    when 'admin_backend' then 'admin_backend'
    when 'migration' then 'migration'
    else 'unknown'
  end;

  v_actor_type := case v_submitted_via
    when 'client_dashboard' then 'client'
    when 'migration' then 'migration'
    when 'system' then 'system'
    else 'backend'
  end;

  select coalesce(max(credentials_version), 0) + 1
    into v_next_version
  from public.account_credentials
  where account_id = p_account_id
    and provider = 'instagram';

  if v_next_version <> p_credentials_version then
    raise exception 'credentials_version_conflict';
  end if;

  update public.account_credentials
     set status = 'superseded',
         updated_at = now()
   where account_id = p_account_id
     and provider = 'instagram'
     and status = 'active';

  v_metadata := jsonb_build_object(
    'action', p_action,
    'request_id', nullif(trim(coalesce(p_request_id, '')), ''),
    'vault_secret_created', true
  );

  v_metadata_safe := jsonb_build_object(
    'source', v_source,
    'action', p_action,
    'request_id', nullif(trim(coalesce(p_request_id, '')), ''),
    'submitted_via', v_submitted_via,
    'vault_secret_created', true
  );

  if nullif(trim(coalesce(p_external_request_id, '')), '') is not null then
    v_metadata := v_metadata || jsonb_build_object(
      'external_request_id',
      left(trim(p_external_request_id), 120)
    );
    v_metadata_safe := v_metadata_safe || jsonb_build_object(
      'external_request_id',
      left(trim(p_external_request_id), 120)
    );
  end if;

  if public.jsonb_has_forbidden_safe_metadata_key(v_metadata_safe) then
    raise exception 'metadata_safe_forbidden';
  end if;

  insert into public.account_credentials (
    account_id,
    client_id,
    provider,
    username_at_submission,
    secret_ref,
    secret_provider,
    credentials_version,
    status,
    last_submitted_at,
    last_rotated_at,
    reauth_required,
    reauth_reason,
    submitted_by,
    submitted_via,
    metadata,
    last_updated_at,
    updated_by_actor_type,
    updated_by_actor_id,
    source,
    metadata_safe
  )
  values (
    p_account_id,
    p_client_id,
    'instagram',
    nullif(trim(coalesce(p_username_at_submission, '')), ''),
    trim(p_secret_ref),
    p_secret_provider,
    v_next_version,
    'active',
    now(),
    case when p_action = 'update_password' then now() else null end,
    true,
    'awaiting_login_verification',
    p_submitted_by,
    v_submitted_via,
    v_metadata,
    now(),
    v_actor_type,
    case when p_submitted_by is not null then p_submitted_by::text else null end,
    v_source,
    v_metadata_safe
  )
  returning * into v_row;

  return v_row;
end;
$$;




COMMENT ON FUNCTION "public"."rotate_instagram_account_credentials"("p_account_id" "uuid", "p_client_id" "uuid", "p_username_at_submission" "text", "p_secret_ref" "text", "p_secret_provider" "text", "p_credentials_version" integer, "p_action" "text", "p_external_request_id" "text", "p_request_id" "text", "p_submitted_by" "uuid", "p_submitted_via" "text") IS 'Patch 2A service-role-only metadata rotation after the Edge Function stores the password in Vault. Writes active credential metadata and safe source/actor fields; never accepts raw password material.';



CREATE OR REPLACE FUNCTION "public"."run_incident_retention_cleanup_v1"("p_batch_size" integer DEFAULT NULL::integer, "p_dry_run" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_policy public.incident_retention_policies%rowtype;
  v_run_id uuid;
  v_batch integer;
  v_examined integer := 0;
  v_archived integer := 0;
  v_deleted integer := 0;
  v_deliveries integer := 0;
begin
  select * into strict v_policy
  from public.incident_retention_policies
  where policy_key = 'default';
  v_batch := least(1000, greatest(1, coalesce(p_batch_size, v_policy.cleanup_batch_size)));

  insert into public.incident_cleanup_runs(policy_version, batch_size, dry_run)
  values (v_policy.policy_version, v_batch, p_dry_run)
  returning id into v_run_id;

  begin
    if not pg_try_advisory_xact_lock(hashtextextended('incident_retention_cleanup_v1', 0)) then
      update public.incident_cleanup_runs
      set status = 'skipped_locked', completed_at = now(), metadata = '{"reason":"advisory_lock_busy"}'::jsonb
      where id = v_run_id;
      return jsonb_build_object('ok', true, 'status', 'skipped_locked', 'run_id', v_run_id);
    end if;

    if not v_policy.enabled then
      update public.incident_cleanup_runs
      set status = 'disabled', completed_at = now()
      where id = v_run_id;
      return jsonb_build_object('ok', true, 'status', 'disabled', 'run_id', v_run_id);
    end if;

    select count(*) into v_examined
    from (
      select i.id
      from public.account_incidents i
      where i.status in ('resolved', 'ignored')
        and i.archived_at is null
        and i.legal_hold = false
        and i.purge_after <= now()
        and not exists (
          select 1 from public.account_dashboard_actions a
          where a.incident_id = i.id
            and a.status in ('pending', 'acknowledged', 'pending_verification', 'code_submitted')
        )
      order by i.purge_after, i.id
      limit v_batch
    ) candidates;

    if not p_dry_run then
      with candidates as (
        select i.id
        from public.account_incidents i
        where i.status in ('resolved', 'ignored')
          and i.archived_at is null
          and i.legal_hold = false
          and i.purge_after <= now()
          and not exists (
            select 1 from public.account_dashboard_actions a
            where a.incident_id = i.id
              and a.status in ('pending', 'acknowledged', 'pending_verification', 'code_submitted')
          )
        order by i.purge_after, i.id
        for update skip locked
        limit v_batch
      ), archived as (
        update public.account_incidents i
        set archived_at = now(), updated_at = now(), retention_policy_version = v_policy.policy_version
        from candidates c
        where i.id = c.id
        returning i.id
      ) select count(*) into v_archived from archived;

      with candidates as (
        select n.id
        from public.account_incident_notifications n
        join public.account_incidents i on i.id = n.incident_id
        where n.created_at < now() - make_interval(days => v_policy.delivery_log_days)
          and (i.status in ('resolved', 'ignored') or i.archived_at is not null)
          and not exists (
            select 1 from public.account_dashboard_actions a
            where a.incident_id = i.id
              and a.status in ('pending', 'acknowledged', 'pending_verification', 'code_submitted')
          )
        order by n.created_at, n.id
        for update of n skip locked
        limit v_batch
      ), deleted as (
        delete from public.account_incident_notifications n
        using candidates c where n.id = c.id returning n.id
      ) select count(*) into v_deliveries from deleted;

      with candidates as (
        select i.id
        from public.account_incidents i
        where i.archived_at < now() - make_interval(days => v_policy.physical_delete_grace_days)
          and i.legal_hold = false
          and i.run_id is null
          and i.source_event_id is null
          and coalesce(i.metadata ->> 'run_request_id', '') = ''
          and not exists (select 1 from public.account_dashboard_actions a where a.incident_id = i.id)
        order by i.archived_at, i.id
        for update skip locked
        limit v_batch
      ), deleted as (
        delete from public.account_incidents i
        using candidates c where i.id = c.id returning i.id
      ) select count(*) into v_deleted from deleted;
    end if;

    update public.incident_cleanup_runs
    set completed_at = now(), status = 'completed', rows_examined = v_examined,
        incidents_archived = v_archived, incidents_deleted = v_deleted,
        deliveries_deleted = v_deliveries
    where id = v_run_id;
  exception when others then
    update public.incident_cleanup_runs
    set completed_at = now(), status = 'failed', rows_examined = v_examined,
        incidents_archived = v_archived, incidents_deleted = v_deleted,
        deliveries_deleted = v_deliveries,
        errors = jsonb_build_array(jsonb_build_object('sqlstate', sqlstate, 'message', left(sqlerrm, 240)))
    where id = v_run_id;
  end;

  return (select jsonb_build_object(
    'ok', status = 'completed', 'status', status, 'run_id', id,
    'policy_version', policy_version, 'batch_size', batch_size,
    'dry_run', dry_run, 'rows_examined', rows_examined,
    'incidents_archived', incidents_archived, 'incidents_deleted', incidents_deleted,
    'deliveries_deleted', deliveries_deleted, 'errors', errors
  ) from public.incident_cleanup_runs where id = v_run_id);
end
$$;




CREATE OR REPLACE FUNCTION "public"."save_account_follow_settings_v1"("p_account_id" "uuid", "p_actor_id" "uuid", "p_idempotency_key" "text", "p_warmup_enabled" boolean, "p_day_1_follow_cap" integer, "p_day_2_follow_cap" integer, "p_day_3_follow_cap" integer, "p_day_4_plus_follow_cap" integer, "p_admin_day_cap" integer, "p_admin_session_cap" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_package_cap integer;
  v_before jsonb;
  v_after jsonb;
  v_started_at timestamptz;
begin
  if coalesce(trim(p_idempotency_key), '') = '' then
    raise exception 'idempotency_key_required';
  end if;

  select (package_caps ->> 'follow_day')::integer
    into v_package_cap
    from public.account_package_summary
   where account_id = p_account_id;
  if v_package_cap is null or v_package_cap < 1 then
    raise exception 'package_follow_cap_unavailable';
  end if;
  if p_day_1_follow_cap not between 0 and 10
     or p_day_2_follow_cap not between 0 and 20
     or p_day_3_follow_cap not between 0 and 40
     or p_day_4_plus_follow_cap not between 0 and v_package_cap
     or p_admin_day_cap < 0
     or p_admin_session_cap < 0 then
    raise exception 'invalid_follow_cap';
  end if;

  if exists (
    select 1 from public.ig_action_logs
     where account_id = p_account_id
       and action_type = 'follow_warmup_settings_saved'
       and payload ->> 'idempotency_key' = p_idempotency_key
  ) then
    return jsonb_build_object('changed', false, 'idempotent', true);
  end if;

  select package_started_at into v_started_at
    from public.account_warmup_settings
   where account_id = p_account_id
   for update;
  select jsonb_build_object(
    'warmup', to_jsonb(w),
    'admin_day_cap', s.max_actions_per_day,
    'admin_session_cap', s.follow_limit
  ) into v_before
    from public.ig_account_settings s
    left join public.account_warmup_settings w on w.account_id = s.account_id
   where s.account_id = p_account_id;

  insert into public.account_warmup_settings (
    account_id, warmup_enabled, warmup_profile_code, day_1_follow_cap,
    day_2_follow_cap, day_3_follow_cap, day_4_plus_follow_cap,
    package_started_at, status, updated_at
  ) values (
    p_account_id, p_warmup_enabled, 'follow_default_v1', p_day_1_follow_cap,
    p_day_2_follow_cap, p_day_3_follow_cap, p_day_4_plus_follow_cap,
    v_started_at, case when v_started_at is null then 'pending_package_start' else 'active' end, now()
  ) on conflict (account_id) do update set
    warmup_enabled = excluded.warmup_enabled,
    day_1_follow_cap = excluded.day_1_follow_cap,
    day_2_follow_cap = excluded.day_2_follow_cap,
    day_3_follow_cap = excluded.day_3_follow_cap,
    day_4_plus_follow_cap = excluded.day_4_plus_follow_cap,
    updated_at = now();

  update public.ig_account_settings
     set max_actions_per_day = p_admin_day_cap,
         follow_limit = p_admin_session_cap,
         updated_at = now()
   where account_id = p_account_id;
  if not found then
    raise exception 'account_settings_missing';
  end if;

  select jsonb_build_object(
    'warmup', to_jsonb(w),
    'admin_day_cap', s.max_actions_per_day,
    'admin_session_cap', s.follow_limit
  ) into v_after
    from public.ig_account_settings s
    join public.account_warmup_settings w on w.account_id = s.account_id
   where s.account_id = p_account_id;

  insert into public.ig_action_logs(account_id, action_type, status, message, payload)
  values (p_account_id, 'follow_warmup_settings_saved', 'success',
    'Follow and warmup settings saved transactionally.',
    jsonb_build_object('actor_type','admin','actor_id',p_actor_id,'source_surface','admin_dashboard',
      'domain','follow_warmup','idempotency_key',p_idempotency_key,'before',coalesce(v_before,'{}'::jsonb),'after',v_after));
  return jsonb_build_object('changed', true, 'idempotent', false, 'data', v_after);
end;
$$;




CREATE OR REPLACE FUNCTION "public"."save_account_unfollow_settings_v1"("p_account_id" "uuid", "p_actor_id" "uuid", "p_idempotency_key" "text", "p_unfollow_enabled" boolean, "p_unfollow_mode" "text", "p_unfollow_per_session_limit" integer, "p_unfollow_per_day_limit" integer, "p_unfollow_after_days" integer, "p_runtime_cap_mode" "text", "p_runtime_safety_cap" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_before jsonb;
  v_after jsonb;
begin
  if coalesce(trim(p_idempotency_key), '') = '' then raise exception 'idempotency_key_required'; end if;
  if p_unfollow_mode not in ('unfollow','unfollow-any')
     or p_runtime_cap_mode not in ('prod_normal','mini_run','incident_safety')
     or p_unfollow_per_session_limit < 0 or p_unfollow_per_day_limit < 0
     or p_unfollow_after_days < 0
     or (p_runtime_cap_mode <> 'prod_normal' and coalesce(p_runtime_safety_cap, 0) < 1) then
    raise exception 'invalid_unfollow_settings';
  end if;
  if exists (
    select 1 from public.ig_action_logs
     where account_id = p_account_id
       and action_type = 'unfollow_domain_settings_saved'
       and payload ->> 'idempotency_key' = p_idempotency_key
  ) then
    return jsonb_build_object('changed', false, 'idempotent', true);
  end if;

  select to_jsonb(u) into v_before from public.ig_account_unfollow_settings u
   where account_id = p_account_id for update;
  insert into public.ig_account_unfollow_settings (
    account_id, unfollow_enabled, unfollow_mode, unfollow_per_session_limit,
    unfollow_per_day_limit, unfollow_after_days, runtime_cap_mode,
    runtime_safety_cap, updated_at
  ) values (
    p_account_id, p_unfollow_enabled, p_unfollow_mode, p_unfollow_per_session_limit,
    p_unfollow_per_day_limit, p_unfollow_after_days, p_runtime_cap_mode,
    case when p_runtime_cap_mode = 'prod_normal' then null else p_runtime_safety_cap end, now()
  ) on conflict (account_id) do update set
    unfollow_enabled = excluded.unfollow_enabled,
    unfollow_mode = excluded.unfollow_mode,
    unfollow_per_session_limit = excluded.unfollow_per_session_limit,
    unfollow_per_day_limit = excluded.unfollow_per_day_limit,
    unfollow_after_days = excluded.unfollow_after_days,
    runtime_cap_mode = excluded.runtime_cap_mode,
    runtime_safety_cap = excluded.runtime_safety_cap,
    updated_at = now();
  select to_jsonb(u) into v_after from public.ig_account_unfollow_settings u where account_id = p_account_id;
  insert into public.ig_action_logs(account_id, action_type, status, message, payload)
  values (p_account_id, 'unfollow_domain_settings_saved', 'success',
    'Unfollow settings saved transactionally.',
    jsonb_build_object('actor_type','admin','actor_id',p_actor_id,'source_surface','admin_dashboard',
      'domain','unfollow','idempotency_key',p_idempotency_key,'before',coalesce(v_before,'{}'::jsonb),'after',v_after));
  return jsonb_build_object('changed', true, 'idempotent', false, 'data', v_after);
end;
$$;




CREATE OR REPLACE FUNCTION "public"."save_client_instagram_onboarding_protection_lists"("p_session_id" "uuid", "p_client_id" "uuid", "p_actor_id" "uuid", "p_mode" "text", "p_unfollow_items" "text"[], "p_blacklist_items" "text"[], "p_unfollow_expected_version" bigint, "p_blacklist_expected_version" bigint, "p_request_id" "text", "p_idempotency_key" "text", "p_unfollow_fingerprint" "text", "p_blacklist_fingerprint" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_session public.client_instagram_onboarding_sessions%rowtype;
  v_unfollow jsonb := '{}'::jsonb;
  v_blacklist jsonb := '{}'::jsonb;
  v_failure jsonb := '{}'::jsonb;
begin
  if p_mode not in ('save', 'skip') then
    return jsonb_build_object('ok', false, 'error', 'protection_lists_mode_invalid');
  end if;
  if p_idempotency_key is null or char_length(p_idempotency_key) not between 1 and 200 then
    return jsonb_build_object('ok', false, 'error', 'invalid_idempotency_key');
  end if;
  if not exists (
    select 1
      from public.client_users cu
      join public.clients c on c.id = cu.client_id and c.status = 'active'
     where cu.client_id = p_client_id
       and cu.auth_user_id = p_actor_id
       and cu.status = 'active'
       and cu.role in ('owner', 'admin', 'assistant')
  ) then
    return jsonb_build_object('ok', false, 'error', 'client_access_denied');
  end if;

  select * into v_session
    from public.client_instagram_onboarding_sessions
   where id = p_session_id and client_id = p_client_id
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'onboarding_not_found');
  end if;
  if v_session.status in ('active', 'creating', 'failed_retryable')
     and v_session.expires_at <= now() then
    update public.client_instagram_onboarding_sessions
       set status = 'expired', lease_owner = null, lease_expires_at = null, updated_at = now()
     where id = p_session_id;
    return jsonb_build_object('ok', false, 'error', 'onboarding_expired');
  end if;
  if v_session.status in ('expired', 'abandoned', 'completed') then
    return jsonb_build_object('ok', false, 'error', 'onboarding_terminal');
  end if;
  if v_session.account_id is null then
    return jsonb_build_object('ok', false, 'error', 'account_not_created');
  end if;
  if v_session.current_step not in ('protection_lists', 'targeting') then
    return jsonb_build_object('ok', false, 'error', 'protection_lists_step_invalid');
  end if;

  begin
    if p_mode = 'save' then
      v_unfollow := public.mutate_account_protection_list(
        v_session.account_id, 'unfollow_whitelist', 'replace',
        coalesce(p_unfollow_items, '{}'::text[]), '{}'::text[], '{}'::text[],
        'client_onboarding', p_actor_id, p_request_id, p_idempotency_key,
        p_unfollow_expected_version, p_unfollow_fingerprint
      );
      if v_unfollow->>'ok' <> 'true' then
        v_failure := v_unfollow || jsonb_build_object('failed_list_kind', 'unfollow_whitelist');
        raise exception using errcode = 'P0001', message = 'rollback_protection_lists';
      end if;

      v_blacklist := public.mutate_account_protection_list(
        v_session.account_id, 'interaction_blacklist', 'replace',
        coalesce(p_blacklist_items, '{}'::text[]), '{}'::text[], '{}'::text[],
        'client_onboarding', p_actor_id, p_request_id, p_idempotency_key,
        p_blacklist_expected_version, p_blacklist_fingerprint
      );
      if v_blacklist->>'ok' <> 'true' then
        v_failure := v_blacklist || jsonb_build_object('failed_list_kind', 'interaction_blacklist');
        raise exception using errcode = 'P0001', message = 'rollback_protection_lists';
      end if;

      update public.client_instagram_onboarding_sessions
         set status = 'active', current_step = 'targeting', protection_lists_skipped_at = null,
             last_progress_at = now(), expires_at = now() + interval '7 days', updated_at = now()
       where id = p_session_id;
    else
      update public.client_instagram_onboarding_sessions
         set status = 'active', current_step = 'targeting',
             protection_lists_skipped_at = coalesce(protection_lists_skipped_at, now()),
             last_progress_at = now(), expires_at = now() + interval '7 days', updated_at = now()
       where id = p_session_id;
    end if;
  exception
    when sqlstate 'P0001' then
      return v_failure || jsonb_build_object('ok', false, 'rolled_back', true);
    when others then
      return jsonb_build_object('ok', false, 'error', 'protection_lists_transaction_failed', 'rolled_back', true);
  end;

  return jsonb_build_object(
    'ok', true,
    'status', 'active',
    'current_step', 'targeting',
    'mode', p_mode,
    'unfollow_whitelist', case when p_mode = 'save' then v_unfollow else null end,
    'interaction_blacklist', case when p_mode = 'save' then v_blacklist else null end
  );
end;
$$;




COMMENT ON FUNCTION "public"."save_client_instagram_onboarding_protection_lists"("p_session_id" "uuid", "p_client_id" "uuid", "p_actor_id" "uuid", "p_mode" "text", "p_unfollow_items" "text"[], "p_blacklist_items" "text"[], "p_unfollow_expected_version" bigint, "p_blacklist_expected_version" bigint, "p_request_id" "text", "p_idempotency_key" "text", "p_unfollow_fingerprint" "text", "p_blacklist_fingerprint" "text") IS 'Atomically saves both canonical account protection lists and advances onboarding, or records an explicit skip without list writes.';



CREATE OR REPLACE FUNCTION "public"."set_account_follow_limit_override_v1"("p_account_id" "uuid", "p_follow_day_cap" integer, "p_follow_session_cap" integer, "p_source" "text" DEFAULT 'admin'::"text", "p_source_surface" "text" DEFAULT 'instagram_dashboard_settings'::"text", "p_updated_by" "uuid" DEFAULT NULL::"uuid", "p_reason" "text" DEFAULT 'explicit_settings_save'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_package_day integer;
  v_package_session integer;
  v_source text := case when p_source in ('admin','support') then p_source else 'admin' end;
  v_result jsonb;
begin
  select
    nullif(aps.package_caps ->> 'follow_day', '')::integer,
    nullif(aps.package_caps ->> 'follow_session', '')::integer
  into v_package_day, v_package_session
  from public.account_package_summary aps
  where aps.account_id = p_account_id;

  if coalesce(v_package_day, 0) <= 0 or coalesce(v_package_session, 0) <= 0 then
    raise exception 'package_settings_incomplete' using errcode = '22023';
  end if;
  if p_follow_day_cap not between 1 and v_package_day
     or p_follow_session_cap not between 1 and v_package_session then
    raise exception 'follow_cap_outside_package' using errcode = '22023';
  end if;

  if p_follow_day_cap = v_package_day and p_follow_session_cap = v_package_session then
    delete from public.ig_account_follow_limit_overrides where account_id = p_account_id;
  else
    insert into public.ig_account_follow_limit_overrides (
      account_id,
      classification,
      follow_day_cap_override,
      follow_session_cap_override,
      max_follow_per_run_legacy,
      source,
      source_surface,
      updated_by,
      reason,
      updated_at
    ) values (
      p_account_id,
      'explicit',
      p_follow_day_cap,
      p_follow_session_cap,
      p_follow_session_cap,
      v_source,
      nullif(trim(p_source_surface), ''),
      p_updated_by,
      nullif(trim(p_reason), ''),
      now()
    )
    on conflict (account_id) do update
    set classification = 'explicit',
        follow_day_cap_override = excluded.follow_day_cap_override,
        follow_session_cap_override = excluded.follow_session_cap_override,
        max_follow_per_run_legacy = excluded.max_follow_per_run_legacy,
        source = excluded.source,
        source_surface = excluded.source_surface,
        updated_by = excluded.updated_by,
        reason = excluded.reason,
        updated_at = excluded.updated_at;
  end if;

  v_result := public.apply_account_follow_limit_provenance_v1(p_account_id);
  return v_result || jsonb_build_object(
    'override_active', p_follow_day_cap <> v_package_day or p_follow_session_cap <> v_package_session
  );
end;
$$;




CREATE OR REPLACE FUNCTION "public"."set_account_incident_retention_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_policy public.incident_retention_policies%rowtype;
  v_days integer;
begin
  select * into v_policy
  from public.incident_retention_policies
  where policy_key = 'default';

  if new.legal_hold then
    new.retention_class := 'legal_audit';
    new.purge_after := null;
  elsif new.severity = 'critical' then
    new.retention_class := 'critical';
  elsif new.severity = 'info' and coalesce(new.action_required, '') = '' then
    new.retention_class := 'technical_nonblocking';
  else
    new.retention_class := 'normal';
  end if;

  if new.status in ('resolved', 'ignored') and not new.legal_hold then
    v_days := case new.retention_class
      when 'critical' then v_policy.critical_resolved_days
      when 'technical_nonblocking' then v_policy.technical_nonblocking_days
      else v_policy.normal_resolved_days
    end;
    new.retention_policy_version := v_policy.policy_version;
    new.purge_after := coalesce(new.resolved_at, now()) + make_interval(days => v_days);
  elsif new.status in ('open', 'acknowledged') then
    new.archived_at := null;
    new.purge_after := null;
    new.retention_policy_version := v_policy.policy_version;
  end if;
  return new;
end
$$;




