CREATE OR REPLACE FUNCTION "public"."slot_overlaps_phone_rest"("p_device_id" "uuid", "p_starts_at" timestamp with time zone, "p_ends_at" timestamp with time zone, "p_timezone" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
declare
  v_window record;
  v_tz text := coalesce(nullif(trim(p_timezone), ''), 'UTC');
  v_slot_start_local timestamp;
  v_slot_end_local timestamp;
  v_rest_start_local timestamp;
  v_rest_end_local timestamp;
  v_day date;
begin
  if not public.is_valid_schedule_timezone(v_tz) then
    raise exception 'invalid_timezone';
  end if;

  for v_window in
    select
      prw.rest_type,
      prw.weekday,
      prw.rest_date,
      prw.starts_at_local,
      prw.ends_at_local,
      prw.timezone
    from public.phone_rest_windows prw
    where prw.device_id = p_device_id
      and prw.status = 'active'
  loop
    if not public.is_valid_schedule_timezone(v_window.timezone) then
      raise exception 'invalid_timezone';
    end if;

    v_slot_start_local := p_starts_at at time zone v_window.timezone;
    v_slot_end_local := p_ends_at at time zone v_window.timezone;

    if v_slot_end_local <= v_slot_start_local then
      v_slot_end_local := v_slot_end_local + interval '1 day';
    end if;

    for v_day in
      select generate_series(
        (v_slot_start_local::date - 1),
        v_slot_end_local::date,
        interval '1 day'
      )::date
    loop
      if v_window.rest_type = 'weekly'
         and v_window.weekday <> extract(dow from v_day)::integer then
        continue;
      end if;

      if v_window.rest_type = 'one_off'
         and v_window.rest_date <> v_day then
        continue;
      end if;

      v_rest_start_local := v_day + v_window.starts_at_local;
      v_rest_end_local := v_day + v_window.ends_at_local;
      if v_rest_end_local <= v_rest_start_local then
        v_rest_end_local := v_rest_end_local + interval '1 day';
      end if;

      if tsrange(v_slot_start_local, v_slot_end_local, '[)')
         && tsrange(v_rest_start_local, v_rest_end_local, '[)') then
        return true;
      end if;
    end loop;
  end loop;

  return false;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."slot_reserved_for_outreach_rest"("p_device_id" "uuid", "p_slot_index" integer) RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.device_outreach_rest_policies policy
    where policy.device_id = p_device_id
      and policy.status = 'active'
      and p_slot_index = any(policy.reserved_slot_indexes)
  );
$$;




CREATE OR REPLACE FUNCTION "public"."stamp_assignment_release_metadata"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  if public.is_open_assignment_status(old.status)
     and public.is_terminal_assignment_status(new.status)
     and public.account_has_active_runtime_session(old.account_id) then
    raise exception 'assignment_terminal_update_blocked_active_run';
  end if;

  if public.is_open_assignment_status(old.status)
     and public.is_terminal_assignment_status(new.status)
     and new.released_at is null then
    new.released_at := now();
  end if;

  return new;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."submit_account_verification_code"("p_action_id" "uuid", "p_account_id" "uuid", "p_verification_code" "text", "p_actor_type" "text" DEFAULT 'client'::"text", "p_actor_id" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb", "p_ttl_minutes" integer DEFAULT 15) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_actor_type text := lower(coalesce(nullif(trim(p_actor_type), ''), 'client'));
  v_metadata jsonb := coalesce(p_metadata, '{}'::jsonb);
  v_code text := btrim(coalesce(p_verification_code, ''));
  v_action public.account_dashboard_actions%rowtype;
  v_submission public.account_verification_code_submissions%rowtype;
  v_secret_id uuid;
  v_secret_ref text;
  v_expires_at timestamptz;
  v_now timestamptz := now();
begin
  if auth.role() <> 'service_role' then
    raise exception 'service_role_required';
  end if;

  if p_action_id is null or p_account_id is null then
    raise exception 'action_id_and_account_id_required';
  end if;

  if v_code = '' or char_length(v_code) > 32 or v_code !~ '^[A-Za-z0-9-]{4,32}$' then
    raise exception 'verification_code_invalid';
  end if;

  if jsonb_typeof(v_metadata) is distinct from 'object'
     or public.jsonb_has_forbidden_safe_metadata_key(v_metadata) then
    raise exception 'metadata_forbidden';
  end if;

  select ada.*
    into v_action
  from public.account_dashboard_actions as ada
  where ada.id = p_action_id
    and ada.account_id = p_account_id
  for update;

  if v_action.id is null then
    raise exception 'dashboard_action_not_found';
  end if;

  if v_action.action_type <> 'enter_email_verification_code' then
    raise exception 'dashboard_action_type_invalid';
  end if;

  if v_action.status not in ('pending', 'acknowledged', 'pending_verification', 'code_submitted') then
    raise exception 'dashboard_action_not_active';
  end if;

  v_expires_at := v_now + make_interval(mins => greatest(5, least(coalesce(p_ttl_minutes, 15), 60)));

  v_secret_id := public.create_ephemeral_verification_code_vault_secret(
    p_account_id,
    p_action_id,
    v_code
  );
  v_secret_ref := format('supabase_vault://%s', v_secret_id::text);

  select avcs.*
    into v_submission
  from public.account_verification_code_submissions as avcs
  where avcs.action_id = p_action_id
  order by avcs.created_at desc
  limit 1
  for update;

  if v_submission.id is null or v_submission.status in ('consumed', 'expired', 'failed') then
    insert into public.account_verification_code_submissions (
      action_id,
      account_id,
      status,
      secret_ref,
      expires_at,
      metadata_safe
    )
    values (
      p_action_id,
      p_account_id,
      'code_submitted',
      v_secret_ref,
      v_expires_at,
      v_metadata || jsonb_build_object(
        'source', 'submit_account_verification_code',
        'actor_type', v_actor_type,
        'actor_id', nullif(trim(coalesce(p_actor_id, '')), '')
      )
    )
    returning * into v_submission;
  else
    if v_submission.secret_ref is not null then
      perform public.neutralize_ephemeral_verification_code_vault_secret(v_submission.secret_ref);
    end if;

    update public.account_verification_code_submissions as avcs
    set
      updated_at = v_now,
      status = 'code_submitted',
      secret_ref = v_secret_ref,
      expires_at = v_expires_at,
      consumed_at = null,
      consumed_run_id = null,
      attempts_count = avcs.attempts_count + 1,
      metadata_safe = coalesce(avcs.metadata_safe, '{}'::jsonb) || v_metadata
    where avcs.id = v_submission.id
    returning * into v_submission;
  end if;

  update public.account_dashboard_actions as ada
  set
    updated_at = v_now,
    status = 'code_submitted',
    metadata = coalesce(ada.metadata, '{}'::jsonb) || jsonb_strip_nulls(
      jsonb_build_object(
        'verification_code_submitted_at', v_now,
        'verification_code_expires_at', v_expires_at,
        'verification_submission_id', v_submission.id::text
      )
    )
  where ada.id = p_action_id;

  return jsonb_build_object(
    'ok', true,
    'action_id', p_action_id,
    'account_id', p_account_id,
    'status', 'code_submitted',
    'submission_id', v_submission.id,
    'expires_at', v_expires_at,
    'message', 'Verification code stored securely and ready for worker resume.'
  );
end;
$_$;




COMMENT ON FUNCTION "public"."submit_account_verification_code"("p_action_id" "uuid", "p_account_id" "uuid", "p_verification_code" "text", "p_actor_type" "text", "p_actor_id" "text", "p_metadata" "jsonb", "p_ttl_minutes" integer) IS 'Service-role-only RPC to store an ephemeral Instagram email verification code linked to a dashboard action. Never returns the code.';



CREATE OR REPLACE FUNCTION "public"."sync_account_dashboard_actions_from_status"("p_account_id" "uuid", "p_actor_type" "text" DEFAULT 'system'::"text", "p_reason" "text" DEFAULT NULL::"text", "p_external_request_id" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor_type text := lower(coalesce(nullif(trim(p_actor_type), ''), 'system'));
  v_transition_actor_type text;
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
  v_external_request_id text := nullif(trim(coalesce(p_external_request_id, '')), '');
  v_metadata jsonb := coalesce(p_metadata, '{}'::jsonb);
  v_client_id uuid;
  v_login_status text;
  v_provisioning_status text;
  v_onboarding_status text;
  v_credential_id uuid;
  v_reauth_required boolean := false;
  v_reauth_reason text;
  v_credentials_configured boolean := false;
  v_action public.account_dashboard_actions;
  v_active_action record;
  v_actions_upserted jsonb := '[]'::jsonb;
  v_actions_resolved jsonb := '[]'::jsonb;
  v_sync_metadata jsonb;
begin
  if p_account_id is null then
    raise exception 'account_id_required'
      using errcode = '22023';
  end if;

  if v_actor_type not in ('client', 'admin', 'assistant', 'ops', 'internal', 'system', 'worker', 'provisioner') then
    raise exception 'invalid_status_actor_type'
      using errcode = '22023';
  end if;

  v_transition_actor_type := case
    when v_actor_type in ('worker', 'provisioner') then 'system'
    else v_actor_type
  end;

  if v_reason is not null and char_length(v_reason) > 500 then
    raise exception 'reason too long'
      using errcode = '22023';
  end if;

  if jsonb_typeof(v_metadata) is distinct from 'object' then
    raise exception 'metadata must be a json object'
      using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_object_keys(v_metadata) as k(key)
    where lower(k.key) in (
      'password',
      'secret',
      'secret_ref',
      'raw_secret',
      'token',
      'cookie',
      'webhook',
      'webhook_url',
      'vault',
      'service_role',
      'authorization',
      'bearer',
      'raw_xml',
      'xml',
      'screenshot',
      'device_udid',
      'adb_serial'
    )
  ) then
    raise exception 'metadata contains a forbidden key'
      using errcode = '22023';
  end if;

  select cia.client_id, cia.login_status, cia.provisioning_status, cia.onboarding_status
    into v_client_id, v_login_status, v_provisioning_status, v_onboarding_status
  from public.client_instagram_accounts as cia
  where cia.account_id = p_account_id;

  if v_client_id is null then
    raise exception 'client_instagram_account_not_found'
      using errcode = 'P0002';
  end if;

  select ac.id, ac.reauth_required, ac.reauth_reason
    into v_credential_id, v_reauth_required, v_reauth_reason
  from public.account_credentials as ac
  where ac.account_id = p_account_id
    and ac.provider = 'instagram'
    and ac.status = 'active'
  order by ac.credentials_version desc
  limit 1;

  v_credentials_configured := v_credential_id is not null;
  v_reauth_required := coalesce(v_reauth_required, false);

  v_sync_metadata := v_metadata || jsonb_strip_nulls(
    jsonb_build_object(
      'source', 'status_sync',
      'actor_type', v_actor_type,
      'reason', v_reason,
      'external_request_id', v_external_request_id,
      'login_status', v_login_status,
      'provisioning_status', v_provisioning_status,
      'onboarding_status', v_onboarding_status
    )
  );

  if not v_credentials_configured then
    v_action := public.upsert_account_dashboard_action(
      p_account_id := p_account_id,
      p_client_id := v_client_id,
      p_action_type := 'submit_instagram_credentials',
      p_status := 'pending',
      p_severity := 'warning',
      p_audience := 'client',
      p_requires_client_action := true,
      p_blocking_campaign := true,
      p_title := 'Connexion Instagram requise',
      p_safe_client_message := 'Merci de connecter votre compte Instagram pour continuer la campagne.',
      p_action_label := 'Connecter Instagram',
      p_action_deep_link := '/accounts/' || p_account_id::text || '/connect-instagram',
      p_dedupe_key := 'account:' || p_account_id::text || ':dashboard_action:submit_instagram_credentials',
      p_metadata := v_sync_metadata
    );
    v_actions_upserted := v_actions_upserted || jsonb_build_array(
      jsonb_build_object('id', v_action.id, 'action_type', v_action.action_type, 'status', v_action.status)
    );
  elsif v_reauth_required then
    v_action := public.upsert_account_dashboard_action(
      p_account_id := p_account_id,
      p_client_id := v_client_id,
      p_action_type := 'update_instagram_password',
      p_status := 'pending',
      p_severity := 'warning',
      p_audience := 'client',
      p_requires_client_action := true,
      p_blocking_campaign := true,
      p_title := 'Mot de passe Instagram requis',
      p_safe_client_message := 'Merci de mettre à jour votre mot de passe Instagram pour continuer.',
      p_action_label := 'Mettre à jour le mot de passe',
      p_action_deep_link := '/accounts/' || p_account_id::text || '/credentials#password',
      p_dedupe_key := 'account:' || p_account_id::text || ':dashboard_action:update_instagram_password',
      p_metadata := v_sync_metadata
    );
    v_actions_upserted := v_actions_upserted || jsonb_build_array(
      jsonb_build_object('id', v_action.id, 'action_type', v_action.action_type, 'status', v_action.status)
    );
  end if;

  if v_credentials_configured then
    if v_login_status = 'needs_2fa' then
      v_action := public.upsert_account_dashboard_action(
        p_account_id := p_account_id,
        p_client_id := v_client_id,
        p_action_type := 'complete_two_factor',
        p_status := 'pending',
        p_severity := 'warning',
        p_audience := 'client',
        p_requires_client_action := true,
        p_blocking_campaign := true,
        p_title := 'Authentification à deux facteurs requise',
        p_safe_client_message := 'Instagram demande une validation à deux facteurs pour continuer.',
        p_action_label := 'Compléter la 2FA',
        p_action_deep_link := '/accounts/' || p_account_id::text || '/connect-instagram#2fa',
        p_dedupe_key := 'account:' || p_account_id::text || ':dashboard_action:complete_two_factor',
        p_metadata := v_sync_metadata
      );
      v_actions_upserted := v_actions_upserted || jsonb_build_array(
        jsonb_build_object('id', v_action.id, 'action_type', v_action.action_type, 'status', v_action.status)
      );
    elsif v_login_status = 'checkpoint' then
      v_action := public.upsert_account_dashboard_action(
        p_account_id := p_account_id,
        p_client_id := v_client_id,
        p_action_type := 'resolve_checkpoint',
        p_status := 'pending',
        p_severity := 'warning',
        p_audience := 'client',
        p_requires_client_action := true,
        p_blocking_campaign := true,
        p_title := 'Vérification Instagram requise',
        p_safe_client_message := 'Instagram demande une vérification de sécurité pour continuer.',
        p_action_label := 'Résoudre la vérification',
        p_action_deep_link := '/accounts/' || p_account_id::text || '/connect-instagram#checkpoint',
        p_dedupe_key := 'account:' || p_account_id::text || ':dashboard_action:resolve_checkpoint',
        p_metadata := v_sync_metadata
      );
      v_actions_upserted := v_actions_upserted || jsonb_build_array(
        jsonb_build_object('id', v_action.id, 'action_type', v_action.action_type, 'status', v_action.status)
      );
    elsif v_login_status = 'failed' then
      v_action := public.upsert_account_dashboard_action(
        p_account_id := p_account_id,
        p_client_id := v_client_id,
        p_action_type := 'review_login_failure',
        p_status := 'pending',
        p_severity := 'error',
        p_audience := 'client',
        p_requires_client_action := true,
        p_blocking_campaign := true,
        p_title := 'Connexion Instagram échouée',
        p_safe_client_message := 'La connexion Instagram a échoué. Merci de vérifier les informations de connexion.',
        p_action_label := 'Vérifier la connexion',
        p_action_deep_link := '/accounts/' || p_account_id::text || '/connect-instagram',
        p_dedupe_key := 'account:' || p_account_id::text || ':dashboard_action:review_login_failure',
        p_metadata := v_sync_metadata
      );
      v_actions_upserted := v_actions_upserted || jsonb_build_array(
        jsonb_build_object('id', v_action.id, 'action_type', v_action.action_type, 'status', v_action.status)
      );
    elsif v_login_status = 'mismatch' then
      v_action := public.upsert_account_dashboard_action(
        p_account_id := p_account_id,
        p_client_id := v_client_id,
        p_action_type := 'review_account_mismatch',
        p_status := 'pending',
        p_severity := 'critical',
        p_audience := 'admin',
        p_requires_client_action := false,
        p_blocking_campaign := true,
        p_title := 'Compte Instagram incohérent',
        p_safe_client_message := null,
        p_admin_message := 'Le compte connecté ne correspond pas au compte attendu. Vérification admin requise.',
        p_action_label := 'Examiner le compte',
        p_action_deep_link := '/admin/accounts/' || p_account_id::text || '/identity',
        p_dedupe_key := 'account:' || p_account_id::text || ':dashboard_action:review_account_mismatch',
        p_metadata := v_sync_metadata
      );
      v_actions_upserted := v_actions_upserted || jsonb_build_array(
        jsonb_build_object('id', v_action.id, 'action_type', v_action.action_type, 'status', v_action.status)
      );
    elsif v_login_status = 'logged_out' then
      v_action := public.upsert_account_dashboard_action(
        p_account_id := p_account_id,
        p_client_id := v_client_id,
        p_action_type := 'reconnect_instagram',
        p_status := 'pending',
        p_severity := 'warning',
        p_audience := 'client',
        p_requires_client_action := true,
        p_blocking_campaign := true,
        p_title := 'Reconnexion Instagram requise',
        p_safe_client_message := 'Votre compte Instagram semble déconnecté. Merci de reconnecter votre compte.',
        p_action_label := 'Reconnecter Instagram',
        p_action_deep_link := '/accounts/' || p_account_id::text || '/connect-instagram',
        p_dedupe_key := 'account:' || p_account_id::text || ':dashboard_action:reconnect_instagram',
        p_metadata := v_sync_metadata
      );
      v_actions_upserted := v_actions_upserted || jsonb_build_array(
        jsonb_build_object('id', v_action.id, 'action_type', v_action.action_type, 'status', v_action.status)
      );
    elsif v_login_status = 'connected' and not v_reauth_required then
      for v_active_action in
        select ada.id, ada.action_type
        from public.account_dashboard_actions as ada
        where ada.account_id = p_account_id
          and ada.status in ('pending', 'acknowledged', 'pending_verification')
          and ada.action_type in (
            'submit_instagram_credentials',
            'update_instagram_password',
            'reconnect_instagram',
            'complete_two_factor',
            'resolve_checkpoint',
            'review_login_failure'
          )
        order by ada.created_at asc
      loop
        v_action := public.transition_account_dashboard_action(
          v_active_action.id,
          'resolved',
          v_transition_actor_type,
          null,
          coalesce(v_reason, 'login_connected'),
          v_sync_metadata
        );
        v_actions_resolved := v_actions_resolved || jsonb_build_array(
          jsonb_build_object('id', v_action.id, 'action_type', v_action.action_type, 'status', v_action.status)
        );
      end loop;
    elsif v_login_status in ('verification_pending')
          or v_provisioning_status = 'login_verification_pending' then
      -- Generic verification only: keep existing credential actions; do not
      -- create new 2FA/checkpoint/login-failure actions from status sync alone.
      null;
    end if;
  end if;

  return jsonb_build_object(
    'ok', true,
    'account_id', p_account_id,
    'login_status', v_login_status,
    'provisioning_status', v_provisioning_status,
    'onboarding_status', v_onboarding_status,
    'credentials_configured', v_credentials_configured,
    'reauth_required', v_reauth_required,
    'reauth_reason', v_reauth_reason,
    'actions_upserted', v_actions_upserted,
    'actions_resolved', v_actions_resolved
  );
end;
$$;




COMMENT ON FUNCTION "public"."sync_account_dashboard_actions_from_status"("p_account_id" "uuid", "p_actor_type" "text", "p_reason" "text", "p_external_request_id" "text", "p_metadata" "jsonb") IS 'Entry 2E-2A service-role RPC that derives safe account_dashboard_actions from client_instagram_accounts and active account_credentials status. Explicit login_status values (needs_2fa, checkpoint, failed, mismatch, logged_out, connected) take priority over generic verification_pending states.';



CREATE OR REPLACE FUNCTION "public"."sync_account_incident_dashboard_action"("p_incident_id" "uuid", "p_actor_type" "text" DEFAULT 'system'::"text", "p_reason" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor_type text := lower(coalesce(nullif(trim(p_actor_type), ''), 'system'));
  v_transition_actor_type text;
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
  v_metadata jsonb := coalesce(p_metadata, '{}'::jsonb);
  v_incident public.account_incidents%rowtype;
  v_incident_metadata jsonb := '{}'::jsonb;
  v_action_type text;
  v_action_title text;
  v_action_label text;
  v_action_deep_link text;
  v_action_dedupe_key text;
  v_action public.account_dashboard_actions;
  v_existing_action public.account_dashboard_actions%rowtype;
  v_dashboard_action_id uuid;
  v_login_status text;
  v_sync_metadata jsonb;
  v_transition_status text;
begin
  if p_incident_id is null then
    return jsonb_build_object(
      'ok', false,
      'action', 'skipped',
      'reason', 'incident_id_required'
    );
  end if;

  if v_actor_type not in ('client', 'admin', 'assistant', 'ops', 'internal', 'system', 'worker', 'provisioner') then
    raise exception 'invalid_incident_dashboard_action_actor_type'
      using errcode = '22023';
  end if;

  v_transition_actor_type := case
    when v_actor_type in ('worker', 'provisioner') then 'system'
    else v_actor_type
  end;

  if v_reason is not null and char_length(v_reason) > 500 then
    raise exception 'reason too long'
      using errcode = '22023';
  end if;

  if jsonb_typeof(v_metadata) is distinct from 'object' then
    raise exception 'metadata must be a json object'
      using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_object_keys(v_metadata) as k(key)
    where lower(k.key) in (
      'password',
      'secret',
      'secret_ref',
      'raw_secret',
      'token',
      'cookie',
      'webhook',
      'webhook_url',
      'vault',
      'service_role',
      'authorization',
      'bearer',
      'adb_serial',
      'device_udid',
      'raw_xml',
      'xml',
      'screenshot',
      'session_cookie'
    )
  ) then
    raise exception 'metadata contains a forbidden key'
      using errcode = '22023';
  end if;

  select ai.*
    into v_incident
  from public.account_incidents as ai
  where ai.id = p_incident_id
  for update;

  if v_incident.id is null then
    return jsonb_build_object(
      'ok', false,
      'incident_id', p_incident_id,
      'action', 'skipped',
      'reason', 'incident_not_found'
    );
  end if;

  if v_incident.account_id is null then
    return jsonb_build_object(
      'ok', true,
      'incident_id', v_incident.id,
      'incident_type', v_incident.incident_type,
      'incident_status', v_incident.status,
      'action', 'skipped',
      'reason', 'missing_account_id'
    );
  end if;

  if v_incident.incident_type = 'active_instagram_account_mismatch' then
    v_action_type := 'review_account_mismatch';
    v_action_title := 'Compte Instagram incohérent';
    v_action_label := 'Examiner le compte';
    v_action_deep_link := '/admin/accounts/' || v_incident.account_id::text || '/identity';
    v_action_dedupe_key := 'account:' || v_incident.account_id::text || ':dashboard_action:review_account_mismatch';
  else
    return jsonb_build_object(
      'ok', true,
      'incident_id', v_incident.id,
      'incident_type', v_incident.incident_type,
      'incident_status', v_incident.status,
      'action', 'skipped',
      'reason', 'unsupported_incident_type'
    );
  end if;

  v_incident_metadata := coalesce(v_incident.metadata, '{}'::jsonb);
  v_sync_metadata := v_metadata || jsonb_strip_nulls(
    jsonb_build_object(
      'source', 'account_incident',
      'incident_id', v_incident.id::text,
      'incident_type', v_incident.incident_type,
      'incident_status', v_incident.status,
      'incident_severity', v_incident.severity,
      'occurrence_count', v_incident.occurrence_count,
      'run_id', coalesce(v_incident.run_id::text, v_incident_metadata ->> 'run_id'),
      'stage', v_incident_metadata ->> 'stage',
      'run_type', v_incident_metadata ->> 'run_type',
      'expected_account_username', v_incident_metadata ->> 'expected_account_username',
      'actual_username', coalesce(
        v_incident_metadata ->> 'actual_username',
        v_incident_metadata ->> 'actual_logged_in_username'
      ),
      'verification_method', v_incident_metadata ->> 'verification_method',
      'identity_evidence', v_incident_metadata ->> 'identity_evidence',
      'guard_reason', coalesce(v_incident_metadata ->> 'guard_reason', v_incident.failure_reason)
    )
  );

  if v_incident.status in ('open', 'acknowledged') then
    v_action := public.upsert_account_dashboard_action(
      p_account_id := v_incident.account_id,
      p_client_id := v_incident.client_id,
      p_incident_id := v_incident.id,
      p_action_type := v_action_type,
      p_status := 'pending',
      p_severity := 'critical',
      p_audience := 'admin',
      p_requires_client_action := false,
      p_blocking_campaign := true,
      p_title := v_action_title,
      p_safe_client_message := null,
      p_assistant_message := v_incident.assistant_message,
      p_admin_message := coalesce(
        nullif(trim(v_incident.admin_message), ''),
        'Le compte connecté ne correspond pas au compte attendu. Vérification admin requise.'
      ),
      p_action_label := v_action_label,
      p_action_deep_link := v_action_deep_link,
      p_dedupe_key := v_action_dedupe_key,
      p_metadata := v_sync_metadata
    );

    return jsonb_build_object(
      'ok', true,
      'incident_id', v_incident.id,
      'incident_type', v_incident.incident_type,
      'incident_status', v_incident.status,
      'action', 'upserted',
      'dashboard_action_id', v_action.id,
      'action_type', v_action.action_type,
      'reason', 'incident_open'
    );
  end if;

  if v_incident.status in ('resolved', 'ignored') then
    select cia.login_status
      into v_login_status
    from public.client_instagram_accounts as cia
    where cia.account_id = v_incident.account_id;

    if v_incident.incident_type = 'active_instagram_account_mismatch'
       and v_login_status = 'mismatch' then
      return jsonb_build_object(
        'ok', true,
        'incident_id', v_incident.id,
        'incident_type', v_incident.incident_type,
        'incident_status', v_incident.status,
        'action', 'skipped',
        'action_type', v_action_type,
        'reason', 'status_still_mismatch'
      );
    end if;

    select ada.*
      into v_existing_action
    from public.account_dashboard_actions as ada
    where ada.account_id = v_incident.account_id
      and ada.action_type = v_action_type
      and ada.status in ('pending', 'acknowledged', 'pending_verification')
      and (
        ada.incident_id = v_incident.id
        or ada.metadata ->> 'incident_id' = v_incident.id::text
      )
    order by ada.created_at desc
    limit 1
    for update;

    if v_existing_action.id is null then
      return jsonb_build_object(
        'ok', true,
        'incident_id', v_incident.id,
        'incident_type', v_incident.incident_type,
        'incident_status', v_incident.status,
        'action', 'skipped',
        'action_type', v_action_type,
        'reason', 'dashboard_action_not_found'
      );
    end if;

    v_transition_status := case
      when v_incident.status = 'ignored' then 'ignored'
      else 'resolved'
    end;

    v_action := public.transition_account_dashboard_action(
      v_existing_action.id,
      v_transition_status,
      v_transition_actor_type,
      null,
      coalesce(v_reason, 'incident_' || v_incident.status),
      v_sync_metadata
    );

    return jsonb_build_object(
      'ok', true,
      'incident_id', v_incident.id,
      'incident_type', v_incident.incident_type,
      'incident_status', v_incident.status,
      'action', v_transition_status,
      'dashboard_action_id', v_action.id,
      'action_type', v_action.action_type,
      'reason', 'incident_' || v_incident.status
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'incident_id', v_incident.id,
    'incident_type', v_incident.incident_type,
    'incident_status', v_incident.status,
    'action', 'skipped',
    'reason', 'unsupported_incident_status'
  );
end;
$$;




COMMENT ON FUNCTION "public"."sync_account_incident_dashboard_action"("p_incident_id" "uuid", "p_actor_type" "text", "p_reason" "text", "p_metadata" "jsonb") IS 'Entry 2F-1 service-role RPC that projects supported account_incidents into account_dashboard_actions using action-level dedupe. V1 supports active_instagram_account_mismatch -> review_account_mismatch only.';



CREATE OR REPLACE FUNCTION "public"."sync_app_instance_after_assignment_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_old_open boolean := false;
  v_new_open boolean := false;
  v_reason text := 'manual_assignment_release';
  v_instance_released boolean := false;
begin
  if tg_op = 'UPDATE' then
    v_old_open := public.is_open_assignment_status(old.status);
  end if;
  v_new_open := public.is_open_assignment_status(new.status);

  if v_new_open and new.app_instance_id is not null then
    update public.phone_app_instances pai
    set status = 'occupied',
        current_account_id = new.account_id,
        updated_at = now()
    where pai.id = new.app_instance_id
      and pai.status <> 'disabled';
  end if;

  if tg_op = 'UPDATE'
     and old.app_instance_id is not null
     and (
       (v_old_open and not v_new_open)
       or old.app_instance_id is distinct from new.app_instance_id
     ) then
    if public.account_has_active_runtime_session(old.account_id) then
      perform public.audit_schedule_capacity_event(
        'schedule_capacity_release_skipped',
        old.account_id,
        old.id,
        old.app_instance_id,
        'active_session_guard',
        jsonb_build_object(
          'source', 'account_assignments_trigger',
          'old_status', old.status,
          'new_status', new.status
        )
      );
      return new;
    end if;

    v_reason := case
      when old.app_instance_id is distinct from new.app_instance_id then 'reassignment_release_old_instance'
      when new.status = 'canceled' then 'assignment_canceled_release'
      when new.status = 'archived' then 'account_archived_release'
      when new.status = 'expired' then 'assignment_expired_release'
      else 'manual_assignment_release'
    end;

    v_instance_released := public.release_app_instance_if_unused(
      old.app_instance_id,
      old.account_id,
      v_reason,
      'account_assignments_trigger'
    );

    perform public.audit_schedule_capacity_event(
      'schedule_app_instance_released',
      old.account_id,
      old.id,
      old.app_instance_id,
      case when v_instance_released then v_reason else 'no_open_assignment_after_release' end,
      jsonb_build_object(
        'source', 'account_assignments_trigger',
        'old_status', old.status,
        'new_status', new.status,
        'old_app_instance_id', old.app_instance_id,
        'new_app_instance_id', new.app_instance_id,
        'app_instance_released', v_instance_released
      )
    );
  end if;

  return new;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."sync_client_subscription_entitlements"("p_subscription_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_subscription public.client_subscriptions%rowtype;
  v_subscription_active boolean;
  v_row record;
  v_entitlement_type text;
  v_upserted integer := 0;
  v_disabled integer := 0;
begin
  select *
  into v_subscription
  from public.client_subscriptions
  where id = p_subscription_id;

  if not found then
    raise exception 'subscription not found: %', p_subscription_id;
  end if;

  v_subscription_active :=
    v_subscription.status = 'active'
    and v_subscription.starts_at <= now()
    and (v_subscription.ends_at is null or v_subscription.ends_at > now());

  for v_row in
    select
      csa.id as subscription_account_id,
      csa.account_id,
      csa.status as account_status,
      csm.id as subscription_module_id,
      csm.feature_code,
      csm.enabled,
      csm.entitlement_type
    from public.client_subscription_accounts csa
    join public.client_subscription_modules csm
      on csm.subscription_id = csa.subscription_id
    where csa.subscription_id = p_subscription_id
  loop
    v_entitlement_type := case
      when v_row.entitlement_type = 'addon' then 'addon'
      else 'bundle'
    end;

    if v_subscription_active
       and v_row.account_status = 'active'
       and v_row.enabled = true then
      -- Prefer an existing row from this subscription/module/account.
      update public.client_entitlements
      set active = true,
          entitlement_type = v_entitlement_type,
          valid_from = v_subscription.starts_at,
          valid_until = v_subscription.ends_at,
          metadata = jsonb_set(
            jsonb_set(
              coalesce(metadata, '{}'::jsonb),
              '{source}',
              '"client_subscription"'::jsonb,
              true
            ),
            '{subscription_type}',
            to_jsonb(v_subscription.subscription_type),
            true
          ),
          updated_at = now()
      where client_id = v_subscription.client_id
        and account_id = v_row.account_id
        and feature_code = v_row.feature_code
        and source_subscription_id = p_subscription_id
        and source_subscription_account_id = v_row.subscription_account_id
        and source_subscription_module_id = v_row.subscription_module_id;

      if not found then
        -- If a manual active account-scoped entitlement already exists, attach
        -- it to this subscription instead of creating a second active row.
        update public.client_entitlements
        set entitlement_type = v_entitlement_type,
            valid_from = v_subscription.starts_at,
            valid_until = v_subscription.ends_at,
            metadata = jsonb_set(
              jsonb_set(
                coalesce(metadata, '{}'::jsonb),
                '{source}',
                '"client_subscription"'::jsonb,
                true
              ),
              '{subscription_type}',
              to_jsonb(v_subscription.subscription_type),
              true
            ),
            source_subscription_id = p_subscription_id,
            source_subscription_account_id = v_row.subscription_account_id,
            source_subscription_module_id = v_row.subscription_module_id,
            updated_at = now()
        where client_id = v_subscription.client_id
          and account_id = v_row.account_id
          and feature_code = v_row.feature_code
          and active = true;

        if not found then
          insert into public.client_entitlements (
            client_id,
            account_id,
            feature_code,
            entitlement_type,
            active,
            valid_from,
            valid_until,
            metadata,
            source_subscription_id,
            source_subscription_account_id,
            source_subscription_module_id
          )
          values (
            v_subscription.client_id,
            v_row.account_id,
            v_row.feature_code,
            v_entitlement_type,
            true,
            v_subscription.starts_at,
            v_subscription.ends_at,
            jsonb_build_object(
              'source', 'client_subscription',
              'subscription_type', v_subscription.subscription_type
            ),
            p_subscription_id,
            v_row.subscription_account_id,
            v_row.subscription_module_id
          );
        end if;
      end if;

      v_upserted := v_upserted + 1;
    end if;
  end loop;

  update public.client_entitlements ce
  set active = false,
      updated_at = now()
  where ce.source_subscription_id = p_subscription_id
    and ce.active = true
    and not exists (
      select 1
      from public.client_subscription_accounts csa
      join public.client_subscription_modules csm
        on csm.subscription_id = csa.subscription_id
      where csa.subscription_id = p_subscription_id
        and csa.id = ce.source_subscription_account_id
        and csm.id = ce.source_subscription_module_id
        and csa.account_id = ce.account_id
        and csm.feature_code = ce.feature_code
        and v_subscription_active = true
        and csa.status = 'active'
        and csm.enabled = true
    );

  get diagnostics v_disabled = row_count;

  return jsonb_build_object(
    'ok', true,
    'subscription_id', p_subscription_id,
    'subscription_active', v_subscription_active,
    'entitlements_upserted', v_upserted,
    'entitlements_disabled', v_disabled
  );
end;
$$;




COMMENT ON FUNCTION "public"."sync_client_subscription_entitlements"("p_subscription_id" "uuid") IS 'Entry 2B explicit admin/service-role sync from product subscription modules to runtime client_entitlements. Not a trigger.';



CREATE OR REPLACE FUNCTION "public"."sync_ig_account_target_followbacks"("p_account_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_target record;
  v_results jsonb := '[]'::jsonb;
  v_one jsonb;
  v_synced integer := 0;
  v_certified integer := 0;
begin
  if p_account_id is null then
    return jsonb_build_object('ok', false, 'reason', 'missing_account_id');
  end if;

  for v_target in
    select t.id
    from public.ig_targets t
    where t.account_id = p_account_id
      and coalesce(t.follows_sent_count, 0) > 0
      and t.followbacks_metrics_reliable_at is null
      and exists (
        select 1
        from public.ig_interacted_users iu
        where iu.account_id = t.account_id
          and iu.is_following_back = true
          and iu.followed_by_bot = true
          and coalesce(iu.follow_status, 'following') = 'following'
          and iu.unfollowed_at is null
          and (
            iu.source_target_id = t.id
            or (
              iu.source_target_id is null
              and iu.source_target_username is not null
              and lower(trim(both '@' from iu.source_target_username)) = lower(t.normalized_username)
            )
          )
      )
    order by t.follows_sent_count desc, t.id
  loop
    v_one := public.sync_ig_target_followbacks_count(v_target.id, false);
    v_results := v_results || jsonb_build_array(v_one);
    if coalesce(v_one->>'ok', 'false') = 'true' then
      v_synced := v_synced + 1;
      if coalesce(v_one->>'certified', 'false') = 'true' then
        v_certified := v_certified + 1;
      end if;
    end if;
  end loop;

  return jsonb_build_object(
    'ok', true,
    'account_id', p_account_id,
    'synced_targets', v_synced,
    'certified_targets', v_certified,
    'results', v_results
  );
end;
$$;




COMMENT ON FUNCTION "public"."sync_ig_account_target_followbacks"("p_account_id" "uuid") IS 'Positive-only account sync: certifies only CT rows with attributable followbacks_count > 0.';



CREATE OR REPLACE FUNCTION "public"."sync_ig_target_followbacks_count"("p_target_id" "uuid", "p_certify_zero_coverage" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_target record;
  v_count integer := 0;
  v_now timestamptz := now();
  v_certify boolean := false;
begin
  select id, account_id, normalized_username, follows_sent_count
  into v_target
  from public.ig_targets
  where id = p_target_id;

  if not found then
    return jsonb_build_object('ok', false, 'reason', 'target_not_found', 'target_id', p_target_id);
  end if;

  select count(*)::integer
  into v_count
  from public.ig_interacted_users iu
  where iu.account_id = v_target.account_id
    and iu.is_following_back = true
    and iu.followed_by_bot = true
    and coalesce(iu.follow_status, 'following') = 'following'
    and iu.unfollowed_at is null
    and (
      iu.source_target_id = v_target.id
      or (
        iu.source_target_id is null
        and iu.source_target_username is not null
        and lower(trim(both '@' from iu.source_target_username)) = lower(v_target.normalized_username)
      )
    );

  v_certify := v_count > 0 or coalesce(p_certify_zero_coverage, false);

  if not v_certify then
    return jsonb_build_object(
      'ok', true,
      'target_id', p_target_id,
      'account_id', v_target.account_id,
      'normalized_username', v_target.normalized_username,
      'follows_sent_count', v_target.follows_sent_count,
      'followbacks_count', v_count,
      'certified', false,
      'reason', 'no_positive_attribution_without_scan_coverage'
    );
  end if;

  update public.ig_targets
  set
    followbacks_count = v_count,
    followbacks_metrics_reliable_at = v_now,
    metrics_updated_at = v_now
  where id = p_target_id;

  return jsonb_build_object(
    'ok', true,
    'target_id', p_target_id,
    'account_id', v_target.account_id,
    'normalized_username', v_target.normalized_username,
    'follows_sent_count', v_target.follows_sent_count,
    'followbacks_count', v_count,
    'followbacks_metrics_reliable_at', v_now,
    'certified', true,
    'certify_zero_coverage', coalesce(p_certify_zero_coverage, false)
  );
end;
$$;




COMMENT ON FUNCTION "public"."sync_ig_target_followbacks_count"("p_target_id" "uuid", "p_certify_zero_coverage" boolean) IS 'Recompute CT followbacks_count. Certifies followbacks_metrics_reliable_at only when count > 0 or explicit zero-coverage proof.';



CREATE OR REPLACE FUNCTION "public"."sync_instagram_account_runtime_settings_after_provisioning"("p_account_id" "uuid", "p_actor_type" "text" DEFAULT 'system'::"text", "p_reason" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor_type text := lower(coalesce(nullif(trim(p_actor_type), ''), 'system'));
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
  v_metadata jsonb := coalesce(p_metadata, '{}'::jsonb);
  v_package_name text;
  v_app_instance_id uuid;
  v_device_id uuid;
  v_settings_updated boolean := false;
  v_dm_settings_updated boolean := false;
  v_unfollow_settings_updated boolean := false;
begin
  if p_account_id is null then
    raise exception 'account_id_required'
      using errcode = '22023';
  end if;

  if v_actor_type not in ('client', 'admin', 'assistant', 'ops', 'internal', 'system', 'worker', 'provisioner') then
    raise exception 'invalid_runtime_settings_actor_type'
      using errcode = '22023';
  end if;

  if v_reason is not null and char_length(v_reason) > 500 then
    raise exception 'reason too long'
      using errcode = '22023';
  end if;

  if jsonb_typeof(v_metadata) is distinct from 'object' then
    raise exception 'metadata must be a json object'
      using errcode = '22023';
  end if;

  select pai.package_name, pai.id, pai.device_id
    into v_package_name, v_app_instance_id, v_device_id
  from public.account_assignments as aa
  join public.phone_app_instances as pai
    on pai.id = aa.app_instance_id
  where aa.account_id = p_account_id
    and aa.released_at is null
    and aa.status in ('reserved', 'active')
    and nullif(trim(coalesce(pai.package_name, '')), '') is not null
  order by aa.assigned_at desc nulls last, aa.created_at desc
  limit 1;

  if nullif(trim(coalesce(v_package_name, '')), '') is null then
    return jsonb_build_object(
      'ok', false,
      'applied', false,
      'reason', 'active_assignment_package_missing',
      'account_id', p_account_id
    );
  end if;

  update public.ig_account_settings as s
  set
    app_package = v_package_name,
    follow_enabled = true,
    like_enabled = true,
    mute_posts_after_follow = true,
    mute_stories_after_follow = true,
    welcome_dm_enabled = false,
    cold_dm_enabled = false,
    unfollow_enabled = false,
    updated_at = now()
  where s.account_id = p_account_id;
  get diagnostics v_settings_updated = row_count;

  update public.ig_account_dm_settings as d
  set
    welcome_enabled = false,
    outreach_enabled = false,
    updated_at = now()
  where d.account_id = p_account_id;
  get diagnostics v_dm_settings_updated = row_count;

  update public.ig_account_unfollow_settings as u
  set
    unfollow_enabled = false,
    updated_at = now()
  where u.account_id = p_account_id;
  get diagnostics v_unfollow_settings_updated = row_count;

  return jsonb_build_object(
    'ok', true,
    'applied', true,
    'reason', 'runtime_settings_synced_after_provisioning',
    'account_id', p_account_id,
    'package_name', v_package_name,
    'app_instance_id', v_app_instance_id,
    'device_id', v_device_id,
    'settings_updated', v_settings_updated,
    'dm_settings_updated', v_dm_settings_updated,
    'unfollow_settings_updated', v_unfollow_settings_updated,
    'follow_enabled', true,
    'like_enabled', true,
    'mute_posts_after_follow', true,
    'mute_stories_after_follow', true,
    'welcome_enabled', false,
    'outreach_enabled', false,
    'unfollow_enabled', false
  );
end;
$$;




COMMENT ON FUNCTION "public"."sync_instagram_account_runtime_settings_after_provisioning"("p_account_id" "uuid", "p_actor_type" "text", "p_reason" "text", "p_metadata" "jsonb") IS 'After successful login provisioning, sync runtime-safe account settings from the active assignment: assigned app package, Follow ON, Mute posts/stories ON, Like ON, Welcome/Outreach/Unfollow OFF. Does not read or expose credentials.';



CREATE OR REPLACE FUNCTION "public"."transition_account_dashboard_action"("p_action_id" "uuid", "p_new_status" "text", "p_actor_type" "text", "p_actor_id" "uuid" DEFAULT NULL::"uuid", "p_reason" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "public"."account_dashboard_actions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_new_status text := lower(coalesce(nullif(trim(p_new_status), ''), ''));
  v_actor_type text := lower(coalesce(nullif(trim(p_actor_type), ''), ''));
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
  v_metadata jsonb := coalesce(p_metadata, '{}'::jsonb);
  v_transition_at timestamptz := now();
  v_transition_metadata jsonb := '{}'::jsonb;
  v_existing_status text;
  v_row public.account_dashboard_actions;
begin
  if p_action_id is null then
    raise exception 'dashboard_action_not_found'
      using errcode = '22023';
  end if;

  if v_new_status not in ('acknowledged', 'dismissed', 'resolved', 'ignored') then
    raise exception 'invalid_dashboard_action_status'
      using errcode = '22023';
  end if;

  if v_actor_type not in ('client', 'admin', 'assistant', 'ops', 'internal', 'system') then
    raise exception 'invalid_dashboard_action_actor_type'
      using errcode = '22023';
  end if;

  if v_reason is not null and char_length(v_reason) > 500 then
    raise exception 'reason too long'
      using errcode = '22023';
  end if;

  if jsonb_typeof(v_metadata) is distinct from 'object' then
    raise exception 'metadata must be a json object'
      using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_object_keys(v_metadata) as k(key)
    where lower(k.key) in (
      'password',
      'secret',
      'secret_ref',
      'raw_secret',
      'token',
      'cookie',
      'webhook',
      'webhook_url',
      'vault',
      'service_role',
      'authorization',
      'bearer',
      'raw_xml',
      'xml',
      'screenshot'
    )
  ) then
    raise exception 'metadata contains a forbidden key'
      using errcode = '22023';
  end if;

  select ada.status
    into v_existing_status
  from public.account_dashboard_actions as ada
  where ada.id = p_action_id
  for update;

  if v_existing_status is null then
    raise exception 'dashboard_action_not_found'
      using errcode = 'P0002';
  end if;

  if v_existing_status in ('resolved', 'dismissed', 'ignored') then
    raise exception 'invalid_dashboard_action_transition'
      using errcode = '22023';
  end if;

  if v_existing_status = 'pending' and v_new_status not in ('acknowledged', 'dismissed', 'resolved', 'ignored') then
    raise exception 'invalid_dashboard_action_transition'
      using errcode = '22023';
  end if;

  if v_existing_status = 'acknowledged' and v_new_status not in ('acknowledged', 'dismissed', 'resolved', 'ignored') then
    raise exception 'invalid_dashboard_action_transition'
      using errcode = '22023';
  end if;

  if v_existing_status = 'pending_verification' and v_new_status not in ('acknowledged', 'dismissed', 'resolved', 'ignored') then
    raise exception 'invalid_dashboard_action_transition'
      using errcode = '22023';
  end if;

  v_transition_metadata := jsonb_build_object(
    'last_transition',
    v_new_status,
    'actor_type',
    v_actor_type,
    'transition_at',
    to_jsonb(v_transition_at)
  );

  if p_actor_id is not null then
    v_transition_metadata := v_transition_metadata || jsonb_build_object('actor_id', p_actor_id::text);
  end if;

  if v_reason is not null then
    v_transition_metadata := v_transition_metadata || jsonb_build_object('reason', v_reason);
  end if;

  update public.account_dashboard_actions as ada
  set
    status = v_new_status,
    updated_at = v_transition_at,
    acknowledged_at = case
      when v_new_status = 'acknowledged' then coalesce(ada.acknowledged_at, v_transition_at)
      else ada.acknowledged_at
    end,
    dismissed_at = case
      when v_new_status = 'dismissed' then v_transition_at
      else ada.dismissed_at
    end,
    resolved_at = case
      when v_new_status = 'resolved' then v_transition_at
      else ada.resolved_at
    end,
    metadata = coalesce(ada.metadata, '{}'::jsonb) || v_metadata || v_transition_metadata
  where ada.id = p_action_id
  returning ada.* into v_row;

  return v_row;
end;
$$;




COMMENT ON FUNCTION "public"."transition_account_dashboard_action"("p_action_id" "uuid", "p_new_status" "text", "p_actor_type" "text", "p_actor_id" "uuid", "p_reason" "text", "p_metadata" "jsonb") IS 'Entry 2D-4D-1 service-role RPC for atomic account_dashboard_actions status transitions. Ownership is enforced by Edge/API callers, not by this RPC.';



CREATE OR REPLACE FUNCTION "public"."transition_account_incident_human_review_v1"("p_incident_id" "uuid", "p_action" "text", "p_expected_version" bigint, "p_actor_type" "text", "p_actor_id" "uuid", "p_source" "text", "p_note" "text", "p_resolution_reason" "text", "p_idempotency_key" "text", "p_channel" "text" DEFAULT NULL::"text", "p_notification_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_incident public.account_incidents%rowtype;
  v_action text := lower(coalesce(nullif(trim(p_action), ''), ''));
  v_actor_type text := lower(coalesce(nullif(trim(p_actor_type), ''), 'ops'));
  v_source text := lower(coalesce(nullif(trim(p_source), ''), 'botapp_relay'));
  v_note text := nullif(trim(coalesce(p_note, '')), '');
  v_resolution_reason text := nullif(trim(coalesce(p_resolution_reason, '')), '');
  v_idempotency_key text := nullif(trim(coalesce(p_idempotency_key, '')), '');
  v_channel text := lower(coalesce(nullif(trim(p_channel), ''), ''));
  v_event_id uuid := gen_random_uuid();
  v_event_type text;
  v_previous_status text;
  v_new_status text;
  v_version bigint;
  v_existing public.account_incident_review_events%rowtype;
  v_delivery public.account_incident_notifications%rowtype;
  v_linked_action_ids uuid[] := '{}'::uuid[];
  v_now timestamptz := now();
  v_channel_row record;
begin
  if p_incident_id is null or v_idempotency_key is null then
    raise exception 'incident_human_review_payload_invalid' using errcode = '22023';
  end if;
  if char_length(v_idempotency_key) > 180 then
    raise exception 'incident_human_review_idempotency_key_too_long' using errcode = '22023';
  end if;
  if v_action not in ('acknowledge', 'add_note', 'resolve', 'retry_notification') then
    raise exception 'incident_human_review_action_invalid' using errcode = '22023';
  end if;
  if v_actor_type not in ('admin', 'ops', 'system') then
    raise exception 'incident_human_review_actor_invalid' using errcode = '22023';
  end if;
  if v_source not in ('admin_dashboard', 'botapp_relay', 'system') then
    raise exception 'incident_human_review_source_invalid' using errcode = '22023';
  end if;
  if v_note is not null and char_length(v_note) > 1000 then
    raise exception 'incident_human_review_note_too_long' using errcode = '22023';
  end if;
  if v_resolution_reason is not null and char_length(v_resolution_reason) > 160 then
    raise exception 'incident_human_review_resolution_reason_too_long' using errcode = '22023';
  end if;

  select e.* into v_existing
  from public.account_incident_review_events e
  where e.incident_id = p_incident_id and e.idempotency_key = v_idempotency_key;

  if v_existing.id is not null then
    select i.* into v_incident from public.account_incidents i where i.id = p_incident_id;
    return jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'event_id', v_existing.id,
      'incident_id', p_incident_id,
      'status', v_incident.status,
      'version', v_incident.lifecycle_version,
      'notification_ids', coalesce((
        select jsonb_agg(n.id order by n.channel)
        from public.account_incident_notifications n
        where n.metadata ->> 'human_review_event_id' = v_existing.id::text
      ), '[]'::jsonb)
    );
  end if;

  select i.* into v_incident
  from public.account_incidents i
  where i.id = p_incident_id and i.archived_at is null
  for update;

  if v_incident.id is null then
    raise exception 'incident_not_found' using errcode = 'P0002';
  end if;
  if p_expected_version is null or p_expected_version <> v_incident.lifecycle_version then
    raise exception 'incident_version_conflict' using errcode = '40001';
  end if;

  v_previous_status := v_incident.status;
  v_new_status := v_incident.status;
  v_version := v_incident.lifecycle_version;

  if v_action = 'acknowledge' then
    if v_incident.status <> 'open' then
      raise exception 'incident_acknowledge_conflict' using errcode = '40001';
    end if;
    v_event_type := 'acknowledged';
    v_new_status := 'acknowledged';
    v_version := v_version + 1;
    update public.account_incidents
    set status = 'acknowledged',
        acknowledged_at = coalesce(acknowledged_at, v_now),
        acknowledged_by = coalesce(p_actor_id, acknowledged_by),
        lifecycle_version = v_version,
        updated_at = v_now
    where id = p_incident_id;

    update public.account_dashboard_actions
    set status = case when status = 'pending' then 'acknowledged' else status end,
        acknowledged_at = coalesce(acknowledged_at, v_now),
        updated_at = v_now,
        metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
          'last_transition', 'acknowledged',
          'transition_at', v_now,
          'actor_type', v_actor_type,
          'source', v_source
        )
    where incident_id = p_incident_id
      and status in ('pending', 'acknowledged', 'pending_verification', 'code_submitted');

  elsif v_action = 'add_note' then
    if v_note is null then
      raise exception 'incident_note_required' using errcode = '22023';
    end if;
    v_event_type := 'note_added';

  elsif v_action = 'resolve' then
    if v_incident.status not in ('open', 'acknowledged') then
      raise exception 'incident_resolve_conflict' using errcode = '40001';
    end if;
    if v_resolution_reason is null then
      raise exception 'incident_resolution_reason_required' using errcode = '22023';
    end if;
    v_event_type := 'resolved';
    v_new_status := 'resolved';
    v_version := v_version + 1;
    update public.account_incidents
    set status = 'resolved',
        resolved_at = v_now,
        resolved_by = p_actor_id,
        resolution_reason = v_resolution_reason,
        resolution_note = v_note,
        lifecycle_version = v_version,
        updated_at = v_now
    where id = p_incident_id;

    update public.account_dashboard_actions
    set status = 'resolved',
        blocking_campaign = false,
        requires_client_action = false,
        resolved_at = coalesce(resolved_at, v_now),
        updated_at = v_now,
        metadata = coalesce(metadata, '{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
          'last_transition', 'resolved',
          'transition_at', v_now,
          'actor_type', v_actor_type,
          'source', v_source,
          'reason', v_resolution_reason,
          'human_review_event_id', v_event_id::text
        ))
    where incident_id = p_incident_id
      and status in ('pending', 'acknowledged', 'pending_verification', 'code_submitted');

    select coalesce(array_agg(a.id order by a.created_at), '{}'::uuid[])
      into v_linked_action_ids
    from public.account_dashboard_actions a
    where a.incident_id = p_incident_id and a.status = 'resolved';

  else
    if v_channel not in ('slack', 'discord') or p_notification_id is null then
      raise exception 'incident_notification_retry_payload_invalid' using errcode = '22023';
    end if;
    select n.* into v_delivery
    from public.account_incident_notifications n
    where n.id = p_notification_id
      and n.incident_id = p_incident_id
      and n.channel = v_channel
    for update;
    if v_delivery.id is null then
      raise exception 'incident_notification_not_found' using errcode = 'P0002';
    end if;
    if v_delivery.status <> 'failed' or v_delivery.attempt_count >= 3 then
      raise exception 'incident_notification_retry_conflict' using errcode = '40001';
    end if;
    v_event_type := 'notification_retry';
    update public.account_incident_notifications
    set status = 'pending',
        attempt_count = attempt_count + 1,
        last_attempt_at = v_now,
        last_error = null,
        response_status = null,
        response_body_preview = null,
        updated_at = v_now
    where id = v_delivery.id;
  end if;

  insert into public.account_incident_review_events (
    id, incident_id, event_type, previous_status, new_status,
    resolution_reason, note, actor_type, actor_id, source,
    idempotency_key, incident_version, metadata_safe, created_at
  ) values (
    v_event_id, p_incident_id, v_event_type, v_previous_status, v_new_status,
    v_resolution_reason, v_note, v_actor_type, p_actor_id, v_source,
    v_idempotency_key, v_version,
    jsonb_strip_nulls(jsonb_build_object(
      'channel', nullif(v_channel, ''),
      'notification_id', p_notification_id,
      'linked_action_ids', v_linked_action_ids
    )),
    v_now
  );

  if v_action = 'resolve' then
    for v_channel_row in
      select channel
      from public.incident_notification_channel_settings
      where channel in ('slack', 'discord') and enabled = true and configured = true
    loop
      insert into public.account_incident_notifications (
        incident_id, channel, status, target, delivery_key, attempt_count,
        payload, metadata, created_at, updated_at
      ) values (
        p_incident_id,
        v_channel_row.channel,
        'pending',
        'redacted',
        v_channel_row.channel || ':' || p_incident_id::text || ':human_review_resolved:' || v_event_id::text,
        0,
        jsonb_build_object(
          'notification_type', 'incident_human_review_resolved',
          'incident_id_short', left(p_incident_id::text, 8),
          'account_username', v_incident.account_username,
          'incident_type', v_incident.incident_type,
          'reason', coalesce(v_incident.reason, v_incident.failure_reason),
          'resolution_reason', v_resolution_reason,
          'operator_id_short', case when p_actor_id is null then null else left(p_actor_id::text, 8) end,
          'resolved_at', v_now
        ),
        jsonb_build_object(
          'human_review_event_id', v_event_id::text,
          'notification_type', 'incident_human_review_resolved',
          'redacted', true
        ),
        v_now,
        v_now
      ) on conflict (delivery_key) do nothing;
    end loop;
  end if;

  insert into public.ig_action_logs (
    account_id, run_id, target_username, action_type, status, message, payload, created_at
  ) values (
    v_incident.account_id,
    v_incident.run_id,
    null,
    'incident_human_review_' || v_event_type,
    'success',
    'incident_human_review_event_recorded',
    jsonb_strip_nulls(jsonb_build_object(
      'incident_id', p_incident_id,
      'event_id', v_event_id,
      'actor_type', v_actor_type,
      'actor_id', p_actor_id,
      'source', v_source,
      'previous_status', v_previous_status,
      'new_status', v_new_status,
      'resolution_reason', v_resolution_reason,
      'note_present', v_note is not null,
      'channel', nullif(v_channel, '')
    )),
    v_now
  );

  return jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'event_id', v_event_id,
    'incident_id', p_incident_id,
    'status', v_new_status,
    'version', v_version,
    'notification_ids', coalesce((
      select jsonb_agg(n.id order by n.channel)
      from public.account_incident_notifications n
      where n.metadata ->> 'human_review_event_id' = v_event_id::text
    ), case when p_notification_id is null then '[]'::jsonb else jsonb_build_array(p_notification_id) end)
  );
end
$$;




CREATE OR REPLACE FUNCTION "public"."update_client_instagram_account_status"("p_account_id" "uuid", "p_login_status" "text" DEFAULT NULL::"text", "p_provisioning_status" "text" DEFAULT NULL::"text", "p_onboarding_status" "text" DEFAULT NULL::"text", "p_reauth_required" boolean DEFAULT NULL::boolean, "p_reauth_reason" "text" DEFAULT NULL::"text", "p_actor_type" "text" DEFAULT 'system'::"text", "p_reason" "text" DEFAULT NULL::"text", "p_external_request_id" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor_type text := lower(coalesce(nullif(trim(p_actor_type), ''), 'system'));
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
  v_metadata jsonb := coalesce(p_metadata, '{}'::jsonb);
  v_effective_reauth_required boolean := p_reauth_required;
  v_client_id uuid;
  v_login_status text;
  v_provisioning_status text;
  v_onboarding_status text;
  v_sync_result jsonb;
  v_runtime_settings_sync jsonb := jsonb_build_object(
    'ok', true,
    'applied', false,
    'reason', 'not_connected_ready'
  );
begin
  if p_account_id is null then
    raise exception 'account_id_required'
      using errcode = '22023';
  end if;

  if v_actor_type not in ('client', 'admin', 'assistant', 'ops', 'internal', 'system', 'worker', 'provisioner') then
    raise exception 'invalid_status_actor_type'
      using errcode = '22023';
  end if;

  if v_reason is not null and char_length(v_reason) > 500 then
    raise exception 'reason too long'
      using errcode = '22023';
  end if;

  if jsonb_typeof(v_metadata) is distinct from 'object' then
    raise exception 'metadata must be a json object'
      using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_object_keys(v_metadata) as k(key)
    where lower(k.key) in (
      'password',
      'secret',
      'secret_ref',
      'raw_secret',
      'token',
      'cookie',
      'webhook',
      'webhook_url',
      'vault',
      'service_role',
      'authorization',
      'bearer',
      'raw_xml',
      'xml',
      'screenshot',
      'device_udid',
      'adb_serial'
    )
  ) then
    raise exception 'metadata contains a forbidden key'
      using errcode = '22023';
  end if;

  select cia.client_id
    into v_client_id
  from public.client_instagram_accounts as cia
  where cia.account_id = p_account_id
  for update;

  if v_client_id is null then
    raise exception 'client_instagram_account_not_found'
      using errcode = 'P0002';
  end if;

  if lower(coalesce(nullif(trim(p_login_status), ''), '')) = 'connected'
     and p_reauth_required is null then
    v_effective_reauth_required := false;
  end if;

  update public.client_instagram_accounts as cia
  set
    login_status = coalesce(nullif(trim(p_login_status), ''), cia.login_status),
    provisioning_status = coalesce(nullif(trim(p_provisioning_status), ''), cia.provisioning_status),
    onboarding_status = coalesce(nullif(trim(p_onboarding_status), ''), cia.onboarding_status),
    updated_at = now()
  where cia.account_id = p_account_id
  returning cia.login_status, cia.provisioning_status, cia.onboarding_status
    into v_login_status, v_provisioning_status, v_onboarding_status;

  if v_effective_reauth_required is not null then
    update public.account_credentials as ac
    set
      reauth_required = v_effective_reauth_required,
      reauth_reason = case
        when v_effective_reauth_required then nullif(trim(coalesce(p_reauth_reason, '')), '')
        else null
      end,
      updated_at = now()
    where ac.account_id = p_account_id
      and ac.provider = 'instagram'
      and ac.status = 'active';
  end if;

  if nullif(trim(coalesce(p_onboarding_status, '')), '') is null
     and lower(coalesce(v_login_status, '')) = 'connected'
     and lower(coalesce(v_provisioning_status, '')) = 'ready'
     and lower(coalesce(v_onboarding_status, '')) not in ('ready', 'blocked', 'support_required')
     and exists (
       select 1
       from public.account_credentials as ac
       where ac.account_id = p_account_id
         and ac.provider = 'instagram'
         and ac.status = 'active'
         and coalesce(ac.reauth_required, false) = false
     )
     and exists (
       select 1
       from public.account_assignments as aa
       join public.phone_app_instances as pai
         on pai.id = aa.app_instance_id
       where aa.account_id = p_account_id
         and aa.released_at is null
         and aa.status in ('reserved', 'active')
         and nullif(trim(coalesce(pai.package_name, '')), '') is not null
     )
  then
    update public.client_instagram_accounts as cia
    set
      onboarding_status = 'ready',
      updated_at = now()
    where cia.account_id = p_account_id
    returning cia.onboarding_status into v_onboarding_status;
  end if;

  if lower(coalesce(v_login_status, '')) = 'connected'
     and lower(coalesce(v_provisioning_status, '')) = 'ready'
     and lower(coalesce(v_onboarding_status, '')) = 'ready' then
    v_runtime_settings_sync := public.sync_instagram_account_runtime_settings_after_provisioning(
      p_account_id := p_account_id,
      p_actor_type := v_actor_type,
      p_reason := coalesce(v_reason, 'login_provisioning_connected'),
      p_metadata := v_metadata
    );
  end if;

  v_sync_result := public.sync_account_dashboard_actions_from_status(
    p_account_id := p_account_id,
    p_actor_type := v_actor_type,
    p_reason := v_reason,
    p_external_request_id := p_external_request_id,
    p_metadata := v_metadata
  );

  return v_sync_result || jsonb_build_object(
    'ok', true,
    'account_id', p_account_id,
    'login_status', v_login_status,
    'provisioning_status', v_provisioning_status,
    'onboarding_status', v_onboarding_status,
    'runtime_settings_sync', v_runtime_settings_sync
  );
end;
$$;




COMMENT ON FUNCTION "public"."update_client_instagram_account_status"("p_account_id" "uuid", "p_login_status" "text", "p_provisioning_status" "text", "p_onboarding_status" "text", "p_reauth_required" boolean, "p_reauth_reason" "text", "p_actor_type" "text", "p_reason" "text", "p_external_request_id" "text", "p_metadata" "jsonb") IS 'Entry 2E-2A service-role RPC that updates safe Instagram account statuses, optionally clears/sets active credential reauth state, then syncs dashboard actions.';



CREATE OR REPLACE FUNCTION "public"."upsert_account_dashboard_action"("p_account_id" "uuid", "p_action_type" "text", "p_title" "text", "p_dedupe_key" "text", "p_client_id" "uuid" DEFAULT NULL::"uuid", "p_incident_id" "uuid" DEFAULT NULL::"uuid", "p_status" "text" DEFAULT 'pending'::"text", "p_severity" "text" DEFAULT 'warning'::"text", "p_audience" "text" DEFAULT 'client'::"text", "p_requires_client_action" boolean DEFAULT true, "p_blocking_campaign" boolean DEFAULT false, "p_safe_client_message" "text" DEFAULT NULL::"text", "p_assistant_message" "text" DEFAULT NULL::"text", "p_admin_message" "text" DEFAULT NULL::"text", "p_action_label" "text" DEFAULT NULL::"text", "p_action_deep_link" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "public"."account_dashboard_actions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_action_type text := nullif(trim(p_action_type), '');
  v_title text := nullif(trim(p_title), '');
  v_dedupe_key text := nullif(trim(p_dedupe_key), '');
  v_status text := lower(coalesce(nullif(trim(p_status), ''), 'pending'));
  v_severity text := lower(coalesce(nullif(trim(p_severity), ''), 'warning'));
  v_audience text := lower(coalesce(nullif(trim(p_audience), ''), 'client'));
  v_metadata jsonb := coalesce(p_metadata, '{}'::jsonb);
  v_now timestamptz;
  v_existing_id uuid;
  v_existing_account_id uuid;
  v_row public.account_dashboard_actions;
begin
  if p_account_id is null then
    raise exception 'account_id is required'
      using errcode = '22023';
  end if;

  if v_action_type is null then
    raise exception 'action_type must be non-empty'
      using errcode = '22023';
  end if;

  if v_title is null then
    raise exception 'title must be non-empty'
      using errcode = '22023';
  end if;

  if v_dedupe_key is null then
    raise exception 'dedupe_key must be non-empty'
      using errcode = '22023';
  end if;

  if jsonb_typeof(v_metadata) is distinct from 'object' then
    raise exception 'metadata must be a JSON object'
      using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_object_keys(v_metadata) as k(key)
    where lower(k.key) in (
      'password',
      'secret',
      'secret_ref',
      'raw_secret',
      'token',
      'cookie',
      'webhook',
      'webhook_url',
      'vault',
      'service_role',
      'authorization',
      'bearer',
      'raw_xml',
      'xml',
      'screenshot'
    )
  ) then
    raise exception 'metadata contains a forbidden key'
      using errcode = '22023';
  end if;

  if v_status not in ('pending', 'acknowledged', 'pending_verification', 'resolved', 'dismissed', 'ignored') then
    raise exception 'invalid dashboard action status: %', v_status
      using errcode = '22023';
  end if;

  if v_severity not in ('info', 'warning', 'error', 'critical') then
    raise exception 'invalid dashboard action severity: %', v_severity
      using errcode = '22023';
  end if;

  if v_audience not in ('client', 'admin', 'assistant', 'ops') then
    raise exception 'invalid dashboard action audience: %', v_audience
      using errcode = '22023';
  end if;

  loop
    v_now := now();
    v_existing_id := null;
    v_existing_account_id := null;

    select ada.id, ada.account_id
      into v_existing_id, v_existing_account_id
    from public.account_dashboard_actions as ada
    where ada.dedupe_key = v_dedupe_key
      and ada.status in ('pending', 'acknowledged', 'pending_verification')
    order by ada.created_at desc
    limit 1
    for update;

    if v_existing_id is not null then
      if v_existing_account_id <> p_account_id then
        raise exception 'dedupe_key belongs to another account'
          using errcode = '22023';
      end if;

      update public.account_dashboard_actions as ada
      set
        updated_at = v_now,
        client_id = coalesce(p_client_id, ada.client_id),
        incident_id = coalesce(p_incident_id, ada.incident_id),
        action_type = v_action_type,
        status = case
          when v_status in ('pending', 'acknowledged', 'pending_verification') then v_status
          else ada.status
        end,
        severity = case
          when (
            case ada.severity
              when 'info' then 1
              when 'warning' then 2
              when 'error' then 3
              when 'critical' then 4
            end
          ) >= (
            case v_severity
              when 'info' then 1
              when 'warning' then 2
              when 'error' then 3
              when 'critical' then 4
            end
          )
          then ada.severity
          else v_severity
        end,
        audience = v_audience,
        requires_client_action = coalesce(p_requires_client_action, ada.requires_client_action),
        blocking_campaign = coalesce(p_blocking_campaign, ada.blocking_campaign),
        title = v_title,
        safe_client_message = coalesce(nullif(trim(p_safe_client_message), ''), ada.safe_client_message),
        assistant_message = coalesce(nullif(trim(p_assistant_message), ''), ada.assistant_message),
        admin_message = coalesce(nullif(trim(p_admin_message), ''), ada.admin_message),
        action_label = coalesce(nullif(trim(p_action_label), ''), ada.action_label),
        action_deep_link = coalesce(nullif(trim(p_action_deep_link), ''), ada.action_deep_link),
        metadata = coalesce(ada.metadata, '{}'::jsonb) || v_metadata
      where ada.id = v_existing_id
      returning ada.* into v_row;

      return v_row;
    end if;

    begin
      insert into public.account_dashboard_actions (
        created_at,
        updated_at,
        account_id,
        client_id,
        incident_id,
        action_type,
        status,
        severity,
        audience,
        requires_client_action,
        blocking_campaign,
        title,
        safe_client_message,
        assistant_message,
        admin_message,
        action_label,
        action_deep_link,
        dedupe_key,
        metadata
      )
      values (
        v_now,
        v_now,
        p_account_id,
        p_client_id,
        p_incident_id,
        v_action_type,
        v_status,
        v_severity,
        v_audience,
        coalesce(p_requires_client_action, true),
        coalesce(p_blocking_campaign, false),
        v_title,
        nullif(trim(p_safe_client_message), ''),
        nullif(trim(p_assistant_message), ''),
        nullif(trim(p_admin_message), ''),
        nullif(trim(p_action_label), ''),
        nullif(trim(p_action_deep_link), ''),
        v_dedupe_key,
        v_metadata
      )
      returning * into v_row;

      return v_row;
    exception
      when unique_violation then
        -- A concurrent writer inserted the active dedupe row after our lookup.
        -- Retry so the next loop locks and updates that row atomically.
    end;
  end loop;
end;
$$;




COMMENT ON FUNCTION "public"."upsert_account_dashboard_action"("p_account_id" "uuid", "p_action_type" "text", "p_title" "text", "p_dedupe_key" "text", "p_client_id" "uuid", "p_incident_id" "uuid", "p_status" "text", "p_severity" "text", "p_audience" "text", "p_requires_client_action" boolean, "p_blocking_campaign" boolean, "p_safe_client_message" "text", "p_assistant_message" "text", "p_admin_message" "text", "p_action_label" "text", "p_action_deep_link" "text", "p_metadata" "jsonb") IS 'Entry 2D-4C-1 service-role RPC for atomic account_dashboard_actions active dedupe. It avoids PostgREST upsert because active dedupe uses a partial unique index.';



CREATE TABLE IF NOT EXISTS "public"."ig_account_followers" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "account_id" "uuid" NOT NULL,
    "follower_username" "text" NOT NULL,
    "follower_username_normalized" "text" GENERATED ALWAYS AS ("lower"(TRIM(BOTH FROM "follower_username"))) STORED,
    "first_seen_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "last_seen_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "baseline_existing" boolean DEFAULT false NOT NULL,
    "welcome_dm_status" "public"."welcome_dm_status" DEFAULT 'pending'::"public"."welcome_dm_status" NOT NULL,
    "welcomed_at" timestamp with time zone,
    "dm_thread_checked_at" timestamp with time zone,
    "skip_reason" "text",
    "last_error" "text",
    "source_scan_run_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "ig_account_followers_username_nonempty" CHECK (("char_length"(TRIM(BOTH FROM "follower_username")) > 0)),
    CONSTRAINT "ig_account_followers_username_normalized_nonempty" CHECK (("char_length"("follower_username_normalized") > 0)),
    CONSTRAINT "ig_account_followers_welcomed_at_when_sent" CHECK ((("welcome_dm_status" <> 'sent'::"public"."welcome_dm_status") OR ("welcomed_at" IS NOT NULL)))
);




COMMENT ON TABLE "public"."ig_account_followers" IS 'V4 Welcome: long-term follower memory per ig_accounts row; baseline vs incremental scans.';



CREATE OR REPLACE FUNCTION "public"."upsert_account_follower_seen"("p_account_id" "uuid", "p_follower_username" "text", "p_source_scan_run_id" "uuid" DEFAULT NULL::"uuid", "p_is_baseline_scan" boolean DEFAULT false) RETURNS "public"."ig_account_followers"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_username text := trim(p_follower_username);
  v_row public.ig_account_followers;
  v_now timestamptz := now();
begin
  if v_username is null or char_length(v_username) = 0 then
    raise exception 'follower_username must be non-empty';
  end if;

  insert into public.ig_account_followers (
    account_id,
    follower_username,
    first_seen_at,
    last_seen_at,
    baseline_existing,
    welcome_dm_status,
    source_scan_run_id
  )
  values (
    p_account_id,
    v_username,
    v_now,
    v_now,
    coalesce(p_is_baseline_scan, false),
    case
      when coalesce(p_is_baseline_scan, false) then 'not_eligible_baseline'::public.welcome_dm_status
      else 'pending'::public.welcome_dm_status
    end,
    p_source_scan_run_id
  )
  on conflict (account_id, follower_username_normalized)
  do update set
    last_seen_at = v_now,
    source_scan_run_id = coalesce(excluded.source_scan_run_id, ig_account_followers.source_scan_run_id),
    baseline_existing = ig_account_followers.baseline_existing
      or excluded.baseline_existing,
    welcome_dm_status = case
      when ig_account_followers.welcome_dm_status in ('sent', 'reserved')
        then ig_account_followers.welcome_dm_status
      when ig_account_followers.baseline_existing
        or excluded.baseline_existing
        then 'not_eligible_baseline'::public.welcome_dm_status
      when ig_account_followers.welcome_dm_status = 'not_eligible_baseline'
        and not excluded.baseline_existing
        then 'pending'::public.welcome_dm_status
      else ig_account_followers.welcome_dm_status
    end,
    updated_at = v_now
  returning * into v_row;

  return v_row;
end;
$$;




CREATE TABLE IF NOT EXISTS "public"."account_incidents" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "first_seen_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "last_seen_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "resolved_at" timestamp with time zone,
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "severity" "text" DEFAULT 'warning'::"text" NOT NULL,
    "incident_type" "text" NOT NULL,
    "dedupe_key" "text" NOT NULL,
    "occurrence_count" integer DEFAULT 1 NOT NULL,
    "client_id" "uuid",
    "account_id" "uuid",
    "account_username" "text",
    "run_id" "uuid",
    "assignment_id" "uuid",
    "device_id" "uuid",
    "clone_id" "uuid",
    "source_event_id" "uuid",
    "source" "text",
    "reason" "text",
    "failure_reason" "text",
    "action_required" "text",
    "safe_client_message" "text",
    "assistant_message" "text",
    "admin_message" "text",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "acknowledged_at" timestamp with time zone,
    "acknowledged_by" "uuid",
    "resolved_by" "uuid",
    "archived_at" timestamp with time zone,
    "legal_hold" boolean DEFAULT false NOT NULL,
    "retention_class" "text" DEFAULT 'normal'::"text" NOT NULL,
    "retention_policy_version" "text",
    "purge_after" timestamp with time zone,
    "lifecycle_version" bigint DEFAULT 1 NOT NULL,
    "resolution_reason" "text",
    "resolution_note" "text",
    CONSTRAINT "account_incidents_dedupe_key_nonempty" CHECK (("char_length"(TRIM(BOTH FROM "dedupe_key")) > 0)),
    CONSTRAINT "account_incidents_incident_type_nonempty" CHECK (("char_length"(TRIM(BOTH FROM "incident_type")) > 0)),
    CONSTRAINT "account_incidents_metadata_object_check" CHECK (("jsonb_typeof"("metadata") = 'object'::"text")),
    CONSTRAINT "account_incidents_occurrence_count_positive" CHECK (("occurrence_count" >= 1)),
    CONSTRAINT "account_incidents_retention_class_check" CHECK (("retention_class" = ANY (ARRAY['normal'::"text", 'critical'::"text", 'technical_nonblocking'::"text", 'legal_audit'::"text"]))),
    CONSTRAINT "account_incidents_severity_check" CHECK (("severity" = ANY (ARRAY['info'::"text", 'warning'::"text", 'error'::"text", 'critical'::"text"]))),
    CONSTRAINT "account_incidents_status_check" CHECK (("status" = ANY (ARRAY['open'::"text", 'acknowledged'::"text", 'resolved'::"text", 'ignored'::"text"])))
);




COMMENT ON TABLE "public"."account_incidents" IS 'ORF-3A durable account-level incident lifecycle table. Service-role only in ORF-3A; safe admin/assistant/client views and RPCs are added later.';



COMMENT ON COLUMN "public"."account_incidents"."dedupe_key" IS 'Stable incident identity for active dedupe. PostgREST upsert with a partial unique index is not reliable; ORF-3B should use a SECURITY DEFINER upsert_account_incident RPC for atomic dedupe.';



COMMENT ON COLUMN "public"."account_incidents"."run_id" IS 'Nullable run correlation only. No FK in ORF-3A because ig_runs compatibility is not guaranteed across deployments.';



COMMENT ON COLUMN "public"."account_incidents"."safe_client_message" IS 'Optional sanitized client-facing summary for future safe views. Never store raw credentials, device routing details, stack traces, or service-role errors here.';



COMMENT ON COLUMN "public"."account_incidents"."metadata" IS 'Structured incident context for operators. Do not store passwords, service-role keys, credentials, tokens, cookies, raw session data, or client-visible device internals.';



CREATE OR REPLACE FUNCTION "public"."upsert_account_incident"("p_incident_type" "text", "p_dedupe_key" "text", "p_severity" "text" DEFAULT 'warning'::"text", "p_status" "text" DEFAULT 'open'::"text", "p_client_id" "uuid" DEFAULT NULL::"uuid", "p_account_id" "uuid" DEFAULT NULL::"uuid", "p_account_username" "text" DEFAULT NULL::"text", "p_run_id" "uuid" DEFAULT NULL::"uuid", "p_assignment_id" "uuid" DEFAULT NULL::"uuid", "p_device_id" "uuid" DEFAULT NULL::"uuid", "p_clone_id" "uuid" DEFAULT NULL::"uuid", "p_source_event_id" "uuid" DEFAULT NULL::"uuid", "p_source" "text" DEFAULT NULL::"text", "p_reason" "text" DEFAULT NULL::"text", "p_failure_reason" "text" DEFAULT NULL::"text", "p_action_required" "text" DEFAULT NULL::"text", "p_safe_client_message" "text" DEFAULT NULL::"text", "p_assistant_message" "text" DEFAULT NULL::"text", "p_admin_message" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "public"."account_incidents"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_incident_type text := nullif(trim(p_incident_type), '');
  v_dedupe_key text := nullif(trim(p_dedupe_key), '');
  v_severity text := lower(coalesce(nullif(trim(p_severity), ''), 'warning'));
  v_status text := lower(coalesce(nullif(trim(p_status), ''), 'open'));
  v_metadata jsonb := coalesce(p_metadata, '{}'::jsonb);
  v_now timestamptz;
  v_existing_id uuid;
  v_row public.account_incidents;
begin
  if v_incident_type is null then
    raise exception 'incident_type must be non-empty'
      using errcode = '22023';
  end if;

  if v_dedupe_key is null then
    raise exception 'dedupe_key must be non-empty'
      using errcode = '22023';
  end if;

  if jsonb_typeof(v_metadata) is distinct from 'object' then
    raise exception 'metadata must be a JSON object'
      using errcode = '22023';
  end if;

  if v_status not in ('open', 'acknowledged', 'resolved', 'ignored') then
    raise exception 'invalid account incident status: %', v_status
      using errcode = '22023';
  end if;

  if v_severity not in ('info', 'warning', 'error', 'critical') then
    raise exception 'invalid account incident severity: %', v_severity
      using errcode = '22023';
  end if;

  loop
    v_now := now();
    v_existing_id := null;

    select ai.id
      into v_existing_id
    from public.account_incidents as ai
    where ai.dedupe_key = v_dedupe_key
      and ai.status in ('open', 'acknowledged')
    order by ai.created_at desc
    limit 1
    for update;

    if v_existing_id is not null then
      update public.account_incidents as ai
      set
        severity = case
          when (
            case ai.severity
              when 'info' then 1
              when 'warning' then 2
              when 'error' then 3
              when 'critical' then 4
            end
          ) >= (
            case v_severity
              when 'info' then 1
              when 'warning' then 2
              when 'error' then 3
              when 'critical' then 4
            end
          )
          then ai.severity
          else v_severity
        end,
        occurrence_count = ai.occurrence_count + 1,
        last_seen_at = v_now,
        updated_at = v_now,
        client_id = coalesce(p_client_id, ai.client_id),
        account_id = coalesce(p_account_id, ai.account_id),
        account_username = coalesce(nullif(trim(p_account_username), ''), ai.account_username),
        run_id = coalesce(p_run_id, ai.run_id),
        assignment_id = coalesce(p_assignment_id, ai.assignment_id),
        device_id = coalesce(p_device_id, ai.device_id),
        clone_id = coalesce(p_clone_id, ai.clone_id),
        source_event_id = coalesce(p_source_event_id, ai.source_event_id),
        source = coalesce(nullif(trim(p_source), ''), ai.source),
        reason = coalesce(nullif(trim(p_reason), ''), ai.reason),
        failure_reason = coalesce(nullif(trim(p_failure_reason), ''), ai.failure_reason),
        action_required = coalesce(nullif(trim(p_action_required), ''), ai.action_required),
        safe_client_message = coalesce(nullif(trim(p_safe_client_message), ''), ai.safe_client_message),
        assistant_message = coalesce(nullif(trim(p_assistant_message), ''), ai.assistant_message),
        admin_message = coalesce(nullif(trim(p_admin_message), ''), ai.admin_message),
        metadata = coalesce(ai.metadata, '{}'::jsonb) || v_metadata
      where ai.id = v_existing_id
      returning ai.* into v_row;

      return v_row;
    end if;

    begin
      insert into public.account_incidents (
        created_at,
        updated_at,
        first_seen_at,
        last_seen_at,
        status,
        severity,
        incident_type,
        dedupe_key,
        occurrence_count,
        client_id,
        account_id,
        account_username,
        run_id,
        assignment_id,
        device_id,
        clone_id,
        source_event_id,
        source,
        reason,
        failure_reason,
        action_required,
        safe_client_message,
        assistant_message,
        admin_message,
        metadata
      )
      values (
        v_now,
        v_now,
        v_now,
        v_now,
        v_status,
        v_severity,
        v_incident_type,
        v_dedupe_key,
        1,
        p_client_id,
        p_account_id,
        nullif(trim(p_account_username), ''),
        p_run_id,
        p_assignment_id,
        p_device_id,
        p_clone_id,
        p_source_event_id,
        nullif(trim(p_source), ''),
        nullif(trim(p_reason), ''),
        nullif(trim(p_failure_reason), ''),
        nullif(trim(p_action_required), ''),
        nullif(trim(p_safe_client_message), ''),
        nullif(trim(p_assistant_message), ''),
        nullif(trim(p_admin_message), ''),
        v_metadata
      )
      returning * into v_row;

      return v_row;
    exception
      when unique_violation then
        -- A concurrent writer inserted the active dedupe row after our lookup.
        -- Retry so the next loop locks and updates that row atomically.
    end;
  end loop;
end;
$$;




COMMENT ON FUNCTION "public"."upsert_account_incident"("p_incident_type" "text", "p_dedupe_key" "text", "p_severity" "text", "p_status" "text", "p_client_id" "uuid", "p_account_id" "uuid", "p_account_username" "text", "p_run_id" "uuid", "p_assignment_id" "uuid", "p_device_id" "uuid", "p_clone_id" "uuid", "p_source_event_id" "uuid", "p_source" "text", "p_reason" "text", "p_failure_reason" "text", "p_action_required" "text", "p_safe_client_message" "text", "p_assistant_message" "text", "p_admin_message" "text", "p_metadata" "jsonb") IS 'ORF-3B-1 service-role RPC for atomic account_incidents active dedupe. It avoids PostgREST upsert because active dedupe uses a partial unique index.';



CREATE OR REPLACE FUNCTION "public"."upsert_login_challenge_dashboard_action"("p_account_id" "uuid", "p_action_type" "text", "p_title" "text", "p_dedupe_key" "text", "p_client_id" "uuid" DEFAULT NULL::"uuid", "p_status" "text" DEFAULT 'pending'::"text", "p_severity" "text" DEFAULT 'warning'::"text", "p_audience" "text" DEFAULT 'client'::"text", "p_requires_client_action" boolean DEFAULT true, "p_blocking_campaign" boolean DEFAULT true, "p_safe_client_message" "text" DEFAULT NULL::"text", "p_assistant_message" "text" DEFAULT NULL::"text", "p_admin_message" "text" DEFAULT NULL::"text", "p_action_label" "text" DEFAULT NULL::"text", "p_action_deep_link" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "public"."account_dashboard_actions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_action_type text := nullif(trim(p_action_type), '');
begin
  if auth.role() <> 'service_role' then
    raise exception 'service_role_required';
  end if;

  if v_action_type not in ('enter_email_verification_code', 'review_login_challenge') then
    raise exception 'unsupported_login_challenge_action_type';
  end if;

  return public.upsert_account_dashboard_action(
    p_account_id := p_account_id,
    p_client_id := p_client_id,
    p_action_type := v_action_type,
    p_status := coalesce(nullif(trim(p_status), ''), 'pending'),
    p_severity := coalesce(nullif(trim(p_severity), ''), 'warning'),
    p_audience := coalesce(nullif(trim(p_audience), ''), 'client'),
    p_requires_client_action := coalesce(p_requires_client_action, true),
    p_blocking_campaign := coalesce(p_blocking_campaign, true),
    p_title := p_title,
    p_safe_client_message := p_safe_client_message,
    p_assistant_message := p_assistant_message,
    p_admin_message := p_admin_message,
    p_action_label := p_action_label,
    p_action_deep_link := p_action_deep_link,
    p_dedupe_key := p_dedupe_key,
    p_metadata := coalesce(p_metadata, '{}'::jsonb)
  );
end;
$$;




CREATE OR REPLACE FUNCTION "public"."upsert_operator_stop_suppression"("p_account_id" "uuid", "p_assignment_id" "uuid", "p_scheduled_window_start" timestamp with time zone, "p_scheduled_window_end" timestamp with time zone, "p_request_id" "uuid" DEFAULT NULL::"uuid", "p_run_id" "uuid" DEFAULT NULL::"uuid", "p_reason_code" "text" DEFAULT 'operator_stop_suppressed'::"text", "p_expires_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_metadata_safe" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "public"."operator_stop_suppressions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ declare v_row public.operator_stop_suppressions%rowtype; v_expires timestamptz := coalesce(p_expires_at, p_scheduled_window_end); begin update public.operator_stop_suppressions set status = 'expired', released_at = coalesce(released_at, now()), updated_at = now() where account_id = p_account_id and status = 'active' and scheduled_window_start <> p_scheduled_window_start; select * into v_row from public.operator_stop_suppressions where account_id = p_account_id and scheduled_window_start = p_scheduled_window_start and status = 'active' limit 1; if found then update public.operator_stop_suppressions set assignment_id = coalesce(p_assignment_id, assignment_id), scheduled_window_end = p_scheduled_window_end, request_id = coalesce(p_request_id, request_id), run_id = coalesce(p_run_id, run_id), reason_code = coalesce(p_reason_code, reason_code), expires_at = v_expires, metadata_safe = metadata_safe || coalesce(p_metadata_safe, '{}'::jsonb), updated_at = now() where id = v_row.id returning * into v_row; return v_row; end if; insert into public.operator_stop_suppressions (account_id, assignment_id, scheduled_window_start, scheduled_window_end, request_id, run_id, status, reason_code, expires_at, metadata_safe, updated_at) values (p_account_id, p_assignment_id, p_scheduled_window_start, p_scheduled_window_end, p_request_id, p_run_id, 'active', coalesce(p_reason_code, 'operator_stop_suppressed'), v_expires, coalesce(p_metadata_safe, '{}'::jsonb), now()) returning * into v_row; return v_row; end; $$;




CREATE OR REPLACE FUNCTION "public"."upsert_scheduled_session_preflight"("p_account_id" "uuid", "p_assignment_id" "uuid", "p_device_id" "uuid", "p_app_instance_id" "uuid", "p_expected_package" "text", "p_expected_username" "text", "p_scheduled_window_start" timestamp with time zone, "p_scheduled_window_end" timestamp with time zone, "p_business_action_deadline" timestamp with time zone, "p_preflight_start" timestamp with time zone, "p_status" "text" DEFAULT 'preflight_due'::"text", "p_reason_code" "text" DEFAULT NULL::"text", "p_expires_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_metadata_safe" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "public"."scheduled_session_preflights"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_row public.scheduled_session_preflights%rowtype;
  v_expires timestamptz := coalesce(p_expires_at, p_scheduled_window_start);
begin
  insert into public.scheduled_session_preflights (
    account_id, assignment_id, device_id, app_instance_id,
    expected_package, expected_username,
    scheduled_window_start, scheduled_window_end,
    business_action_deadline, preflight_start,
    status, reason_code, expires_at, metadata_safe, updated_at
  ) values (
    p_account_id, p_assignment_id, p_device_id, p_app_instance_id,
    coalesce(p_expected_package, ''), coalesce(p_expected_username, ''),
    p_scheduled_window_start, p_scheduled_window_end,
    p_business_action_deadline, p_preflight_start,
    coalesce(p_status, 'preflight_due'), p_reason_code, v_expires,
    coalesce(p_metadata_safe, '{}'::jsonb), now()
  )
  on conflict (assignment_id, scheduled_window_start) do update set
    device_id = excluded.device_id,
    app_instance_id = excluded.app_instance_id,
    expected_package = excluded.expected_package,
    expected_username = excluded.expected_username,
    scheduled_window_end = excluded.scheduled_window_end,
    business_action_deadline = excluded.business_action_deadline,
    preflight_start = excluded.preflight_start,
    status = case
      when scheduled_session_preflights.status in ('preflight_ready', 'preflight_running')
        then scheduled_session_preflights.status
      else excluded.status
    end,
    reason_code = case
      when scheduled_session_preflights.status in ('preflight_ready', 'preflight_running')
        then scheduled_session_preflights.reason_code
      else excluded.reason_code
    end,
    expires_at = excluded.expires_at,
    metadata_safe = scheduled_session_preflights.metadata_safe || excluded.metadata_safe,
    updated_at = now()
  returning * into v_row;
  return v_row;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."validate_account_assignment"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_subscription_account_account_id uuid;
  v_subscription_id uuid;
  v_subscription_type text;
  v_subscription_status text;
  v_device_pool_type text;
  v_slot_kind text;
  v_app_instance_device_id uuid;
  v_app_instance_status text;
  v_app_instance_account_id uuid;
  v_app_instance_usable boolean;
  v_app_instance_launchable boolean;
  v_clone_device_id uuid;
begin
  select csa.account_id, csa.subscription_id, cs.subscription_type, cs.status
  into v_subscription_account_account_id, v_subscription_id, v_subscription_type, v_subscription_status
  from public.client_subscription_accounts csa
  join public.client_subscriptions cs on cs.id = csa.subscription_id
  where csa.id = new.subscription_account_id;

  if v_subscription_account_account_id is null then
    raise exception 'account_assignments.subscription_account_id does not reference an active account subscription';
  end if;

  if new.subscription_id <> v_subscription_id then
    raise exception 'account_assignments.subscription_id must match client_subscription_accounts.subscription_id';
  end if;

  if v_subscription_status <> 'active' then
    raise exception 'account_assignments.subscription_id must reference an active subscription';
  end if;

  if new.account_id <> v_subscription_account_account_id then
    raise exception 'account_assignments.account_id must match client_subscription_accounts.account_id';
  end if;

  if new.assignment_type <> v_subscription_type then
    raise exception 'account_assignments.assignment_type must match client_subscriptions.subscription_type';
  end if;

  if new.schedule_mode = 'manual_only' then
    if new.slot_kind <> 'manual_only' then
      raise exception 'manual_only assignments require slot_kind=manual_only';
    end if;
    if new.starts_at is not null or new.ends_at is not null then
      raise exception 'manual_only assignments require null starts_at and ends_at';
    end if;
    if new.app_instance_id is null then
      raise exception 'manual_only_requires_app_instance';
    end if;
  else
    v_slot_kind := case
      when new.slot_kind = 'outreach_40m' then 'outreach_short'
      else new.slot_kind
    end;

    if new.assignment_type = 'full_cycle' and v_slot_kind <> 'full_cycle_6h' then
      raise exception 'full_cycle assignments require slot_kind=full_cycle_6h';
    end if;

    if new.assignment_type = 'outreach_only' and v_slot_kind <> 'outreach_short' then
      raise exception 'outreach_only assignments require slot_kind=outreach_short or outreach_40m';
    end if;
  end if;

  if new.app_instance_id is not null then
    select pai.device_id, pai.status, pai.current_account_id, pai.usable_for_auto_login, pai.is_launchable
    into v_app_instance_device_id, v_app_instance_status, v_app_instance_account_id, v_app_instance_usable, v_app_instance_launchable
    from public.phone_app_instances pai
    where pai.id = new.app_instance_id;

    if v_app_instance_device_id is null then
      raise exception 'account_assignments.app_instance_id does not reference an existing app instance';
    end if;

    if new.device_id <> v_app_instance_device_id then
      raise exception 'account_assignments.device_id must match phone_app_instances.device_id';
    end if;

    if new.status in ('pending', 'reserved', 'active') then
      if v_app_instance_status <> 'available'
         and not (v_app_instance_status = 'occupied' and v_app_instance_account_id = new.account_id) then
        raise exception 'app_instance_unavailable';
      end if;

      if not coalesce(v_app_instance_usable, false) or not coalesce(v_app_instance_launchable, false) then
        raise exception 'app_instance_unavailable';
      end if;

      if v_app_instance_account_id is not null and v_app_instance_account_id <> new.account_id then
        raise exception 'app_instance_unavailable';
      end if;
    end if;
  elsif new.clone_id is not null then
    select pc.device_id
    into v_clone_device_id
    from public.phone_clones pc
    where pc.id = new.clone_id;

    if v_clone_device_id is null then
      raise exception 'account_assignments.clone_id does not reference an existing clone';
    end if;

    if new.device_id <> v_clone_device_id then
      raise exception 'account_assignments.device_id must match phone_clones.device_id';
    end if;
  elsif new.status in ('pending', 'reserved', 'active') then
    raise exception 'account_assignments.app_instance_id is required for open assignments';
  end if;

  select pd.pool_type
  into v_device_pool_type
  from public.phone_devices pd
  where pd.id = new.device_id;

  if v_device_pool_type is null then
    raise exception 'account_assignments.device_id does not reference an existing phone device';
  end if;

  if v_device_pool_type <> 'shared' and v_device_pool_type <> new.assignment_type then
    raise exception 'phone_devices.pool_type is incompatible with account_assignments.assignment_type';
  end if;

  if new.schedule_mode <> 'manual_only'
     and new.status in ('pending', 'reserved', 'active')
     and not public.validate_assignment_slot_window(
    new.assignment_type,
    new.starts_at,
    new.ends_at,
    coalesce((select timezone from public.phone_devices where id = new.device_id), 'UTC')
  ) then
    raise exception 'assignment_slot_kind_window_mismatch';
  end if;

  if new.schedule_mode <> 'manual_only'
     and new.status in ('pending', 'reserved', 'active')
     and exists (
    select 1
    from public.account_assignments aa
    where aa.app_instance_id = new.app_instance_id
      and aa.status in ('pending', 'reserved', 'active')
      and aa.schedule_mode = 'scheduled'
      and aa.id <> coalesce(new.id, '00000000-0000-0000-0000-000000000000'::uuid)
      and tstzrange(aa.starts_at, aa.ends_at, '[)') && tstzrange(new.starts_at, new.ends_at, '[)')
  ) then
    raise exception 'phone app instance already has an overlapping open assignment';
  end if;

  if new.schedule_mode <> 'manual_only'
     and new.status in ('pending', 'reserved', 'active')
     and exists (
    select 1
    from public.account_assignments aa
    where aa.device_id = new.device_id
      and aa.account_id <> new.account_id
      and aa.status in ('pending', 'reserved', 'active')
      and aa.schedule_mode = 'scheduled'
      and aa.id <> coalesce(new.id, '00000000-0000-0000-0000-000000000000'::uuid)
      and tstzrange(aa.starts_at, aa.ends_at, '[)') && tstzrange(new.starts_at, new.ends_at, '[)')
  ) then
    raise exception 'phone device already has an overlapping open assignment slot';
  end if;

  return new;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."validate_assignment_slot_window"("p_assignment_type" "text", "p_starts_at" timestamp with time zone, "p_ends_at" timestamp with time zone, "p_timezone" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_tz text := coalesce(nullif(trim(p_timezone), ''), 'UTC');
  v_duration_seconds numeric;
  v_local_start timestamp;
  v_local_hour integer;
  v_local_minute integer;
  v_local_total_minutes integer;
begin
  if p_starts_at is null or p_ends_at is null or p_ends_at <= p_starts_at then
    return false;
  end if;

  if not public.is_valid_schedule_timezone(v_tz) then
    raise exception 'invalid_timezone';
  end if;

  v_duration_seconds := extract(epoch from (p_ends_at - p_starts_at));
  v_local_start := p_starts_at at time zone v_tz;
  v_local_hour := extract(hour from v_local_start)::integer;
  v_local_minute := extract(minute from v_local_start)::integer;
  v_local_total_minutes := v_local_hour * 60 + v_local_minute;

  if p_assignment_type = 'full_cycle' then
    return v_duration_seconds = 21600
      and v_local_minute = 0
      and v_local_hour in (0, 6, 12, 18);
  end if;

  if p_assignment_type = 'outreach_only' then
    return v_duration_seconds = 2400
      and (v_local_total_minutes % 40) = 0;
  end if;

  return false;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."validate_client_subscription_account"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_subscription_client_id uuid;
  v_account_client_id uuid;
  v_account_id uuid;
begin
  select cs.client_id
  into v_subscription_client_id
  from public.client_subscriptions cs
  where cs.id = new.subscription_id;

  select cia.client_id, cia.account_id
  into v_account_client_id, v_account_id
  from public.client_instagram_accounts cia
  where cia.id = new.client_instagram_account_id;

  if v_subscription_client_id is null then
    raise exception 'client_subscription_accounts.subscription_id does not reference an existing subscription';
  end if;

  if v_account_client_id is null then
    raise exception 'client_subscription_accounts.client_instagram_account_id does not reference an existing client account';
  end if;

  if v_subscription_client_id <> v_account_client_id then
    raise exception 'subscription and client_instagram_account must belong to the same client';
  end if;

  if new.account_id <> v_account_id then
    raise exception 'client_subscription_accounts.account_id must match client_instagram_accounts.account_id';
  end if;

  return new;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."validate_client_subscription_module"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_subscription_type text;
begin
  select cs.subscription_type
  into v_subscription_type
  from public.client_subscriptions cs
  where cs.id = new.subscription_id;

  if v_subscription_type is null then
    raise exception 'client_subscription_modules.subscription_id does not reference an existing subscription';
  end if;

  if v_subscription_type = 'outreach_only'
     and new.enabled = true
     and new.feature_code <> 'outreach' then
    raise exception 'outreach_only subscriptions can only enable the outreach module';
  end if;

  return new;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."validate_client_subscription_type"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  if new.subscription_type = 'outreach_only'
     and exists (
       select 1
       from public.client_subscription_modules csm
       where csm.subscription_id = new.id
         and csm.enabled = true
         and csm.feature_code <> 'outreach'
     ) then
    raise exception 'cannot set subscription_type=outreach_only while non-outreach modules are enabled';
  end if;

  return new;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."validate_phone_clone_capacity"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_max_clones integer;
begin
  select pd.max_clones
  into v_max_clones
  from public.phone_devices pd
  where pd.id = new.device_id;

  if v_max_clones is null then
    raise exception 'phone_clones.device_id does not reference an existing phone device';
  end if;

  if new.clone_index > v_max_clones then
    raise exception 'phone_clones.clone_index exceeds phone_devices.max_clones';
  end if;

  return new;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."validate_phone_device_timezone"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
begin
  if not public.is_valid_schedule_timezone(new.timezone) then
    raise exception 'invalid_timezone';
  end if;

  return new;
end;
$$;




CREATE OR REPLACE FUNCTION "public"."validate_phone_rest_window"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
begin
  if not public.is_valid_schedule_timezone(new.timezone) then
    raise exception 'invalid_timezone';
  end if;

  return new;
end;
$$;




CREATE TABLE IF NOT EXISTS "public"."account_assignments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "client_id" "uuid" NOT NULL,
    "subscription_id" "uuid" NOT NULL,
    "subscription_account_id" "uuid" NOT NULL,
    "account_id" "uuid" NOT NULL,
    "device_id" "uuid" NOT NULL,
    "clone_id" "uuid",
    "assignment_type" "text" NOT NULL,
    "slot_kind" "text" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "starts_at" timestamp with time zone,
    "ends_at" timestamp with time zone,
    "assigned_at" timestamp with time zone,
    "released_at" timestamp with time zone,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "assignment_source" "text" DEFAULT 'manual_dashboard'::"text" NOT NULL,
    "app_instance_id" "uuid",
    "schedule_mode" "text" DEFAULT 'scheduled'::"text" NOT NULL,
    CONSTRAINT "account_assignments_assignment_source_check" CHECK (("assignment_source" = ANY (ARRAY['manual_dashboard'::"text", 'onboarding_auto'::"text", 'ops'::"text", 'legacy_unknown'::"text", 'auto_assign_rpc'::"text"]))),
    CONSTRAINT "account_assignments_release_check" CHECK ((("released_at" IS NULL) OR ("released_at" >= "assigned_at") OR ("assigned_at" IS NULL))),
    CONSTRAINT "account_assignments_schedule_mode_check" CHECK (("schedule_mode" = ANY (ARRAY['scheduled'::"text", 'manual_only'::"text"]))),
    CONSTRAINT "account_assignments_schedule_shape_check" CHECK (((("schedule_mode" = 'scheduled'::"text") AND ("starts_at" IS NOT NULL) AND ("ends_at" IS NOT NULL) AND ("ends_at" > "starts_at") AND ("slot_kind" <> 'manual_only'::"text")) OR (("schedule_mode" = 'manual_only'::"text") AND ("starts_at" IS NULL) AND ("ends_at" IS NULL) AND ("app_instance_id" IS NOT NULL) AND ("slot_kind" = 'manual_only'::"text")))),
    CONSTRAINT "account_assignments_slot_kind_check" CHECK (("slot_kind" = ANY (ARRAY['full_cycle_6h'::"text", 'outreach_short'::"text", 'outreach_40m'::"text", 'manual_only'::"text"]))),
    CONSTRAINT "account_assignments_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'reserved'::"text", 'active'::"text", 'paused'::"text", 'failed'::"text", 'released'::"text", 'canceled'::"text", 'expired'::"text", 'archived'::"text"]))),
    CONSTRAINT "account_assignments_type_check" CHECK (("assignment_type" = ANY (ARRAY['full_cycle'::"text", 'outreach_only'::"text"])))
);




COMMENT ON TABLE "public"."account_assignments" IS 'Entry 2C assignment of an account-scoped subscription to a device clone and reserved time window. Does not dispatch workers or provision logins.';



COMMENT ON COLUMN "public"."account_assignments"."slot_kind" IS 'Scheduling hint only in Entry 2C: full_cycle_6h or outreach_short. Runtime enforcement is added later.';



COMMENT ON COLUMN "public"."account_assignments"."schedule_mode" IS 'scheduled reserves a recurring assignment window; manual_only reserves device/app_instance placement without an automatic timeslot.';



CREATE TABLE IF NOT EXISTS "public"."account_commercial_addons" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "account_id" "uuid" NOT NULL,
    "addon_code" "text" NOT NULL,
    "addon_variant" "text",
    "source_type" "text",
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "starts_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "ends_at" timestamp with time zone,
    "source" "text" DEFAULT 'operator'::"text" NOT NULL,
