);




CREATE TABLE IF NOT EXISTS "public"."account_follow_source_settings" (
    "account_id" "uuid" NOT NULL,
    "max_follows_per_target_per_run" integer DEFAULT 2 NOT NULL,
    "max_targets_per_run" integer DEFAULT 3 NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_by" "text",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    CONSTRAINT "account_follow_source_settings_max_follows_per_target_per_run_c" CHECK ((("max_follows_per_target_per_run" >= 1) AND ("max_follows_per_target_per_run" <= 50))),
    CONSTRAINT "account_follow_source_settings_max_targets_per_run_check" CHECK ((("max_targets_per_run" >= 1) AND ("max_targets_per_run" <= 10))),
    CONSTRAINT "account_follow_source_settings_metadata_object_check" CHECK (("jsonb_typeof"("metadata") = 'object'::"text"))
);




COMMENT ON TABLE "public"."account_follow_source_settings" IS 'Per-account Follow source rotation settings for runtime workers and admin dashboard.';



COMMENT ON COLUMN "public"."account_follow_source_settings"."max_follows_per_target_per_run" IS 'Maximum follows from one target during one run before trying the next target. Does not raise global follow caps.';



COMMENT ON COLUMN "public"."account_follow_source_settings"."max_targets_per_run" IS 'Maximum number of target/source accounts the worker may try during one run.';



CREATE TABLE IF NOT EXISTS "public"."account_incident_notifications" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "incident_id" "uuid" NOT NULL,
    "channel" "text" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "target" "text",
    "delivery_key" "text" NOT NULL,
    "attempt_count" integer DEFAULT 0 NOT NULL,
    "last_attempt_at" timestamp with time zone,
    "delivered_at" timestamp with time zone,
    "last_error" "text",
    "response_status" integer,
    "response_body_preview" "text",
    "payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    CONSTRAINT "account_incident_notifications_attempt_count_check" CHECK (("attempt_count" >= 0)),
    CONSTRAINT "account_incident_notifications_channel_check" CHECK (("channel" = ANY (ARRAY['slack'::"text", 'discord'::"text"]))),
    CONSTRAINT "account_incident_notifications_delivery_key_nonempty" CHECK (("char_length"(TRIM(BOTH FROM "delivery_key")) > 0)),
    CONSTRAINT "account_incident_notifications_metadata_object_check" CHECK (("jsonb_typeof"("metadata") = 'object'::"text")),
    CONSTRAINT "account_incident_notifications_payload_object_check" CHECK (("jsonb_typeof"("payload") = 'object'::"text")),
    CONSTRAINT "account_incident_notifications_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'sent'::"text", 'failed'::"text", 'skipped'::"text"])))
);




COMMENT ON TABLE "public"."account_incident_notifications" IS 'ORF-4A delivery audit table for future account incident Slack/Discord notifications. Service-role only; runtime flows must not call webhooks directly.';



COMMENT ON COLUMN "public"."account_incident_notifications"."incident_id" IS 'Source account_incidents row. Notifications consume durable incidents, not worker logs or runtime flows.';



COMMENT ON COLUMN "public"."account_incident_notifications"."delivery_key" IS 'Stable notification dedupe key. ORF-4 V1 pattern: {channel}:{incident_id}:opened.';



COMMENT ON COLUMN "public"."account_incident_notifications"."payload" IS 'Sanitized outbound payload audit. Never store webhook URLs, credentials, tokens, cookies, raw XML, raw stack traces, device_udid, or service-role details.';



COMMENT ON COLUMN "public"."account_incident_notifications"."metadata" IS 'Dispatcher-only structured metadata. Keep service-role only and do not expose directly to client dashboards.';



CREATE TABLE IF NOT EXISTS "public"."account_incident_review_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "incident_id" "uuid" NOT NULL,
    "event_type" "text" NOT NULL,
    "previous_status" "text",
    "new_status" "text",
    "resolution_reason" "text",
    "note" "text",
    "actor_type" "text" NOT NULL,
    "actor_id" "uuid",
    "source" "text" NOT NULL,
    "idempotency_key" "text" NOT NULL,
    "incident_version" bigint NOT NULL,
    "metadata_safe" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "account_incident_review_events_actor_type_check" CHECK (("actor_type" = ANY (ARRAY['admin'::"text", 'ops'::"text", 'system'::"text"]))),
    CONSTRAINT "account_incident_review_events_event_type_check" CHECK (("event_type" = ANY (ARRAY['acknowledged'::"text", 'note_added'::"text", 'resolved'::"text", 'notification_retry'::"text"]))),
    CONSTRAINT "account_incident_review_events_metadata_safe_check" CHECK ((("jsonb_typeof"("metadata_safe") = 'object'::"text") AND (NOT "public"."jsonb_has_forbidden_safe_metadata_key"("metadata_safe")))),
    CONSTRAINT "account_incident_review_events_source_check" CHECK (("source" = ANY (ARRAY['admin_dashboard'::"text", 'botapp_relay'::"text", 'system'::"text"])))
);




CREATE TABLE IF NOT EXISTS "public"."account_package_runtime_contract_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "account_id" "uuid",
    "assignment_id" "uuid",
    "request_id" "uuid",
    "event_type" "text" NOT NULL,
    "source" "text" NOT NULL,
    "idempotency_key" "text",
    "details_safe" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "account_package_runtime_contract_events_details_safe_check" CHECK ((("jsonb_typeof"("details_safe") = 'object'::"text") AND ("pg_column_size"("details_safe") <= 8192))),
    CONSTRAINT "account_package_runtime_contract_events_event_type_check" CHECK (("event_type" = ANY (ARRAY['package_runtime_contract_blocked'::"text", 'package_runtime_contract_reconciled'::"text", 'retryable_pre_run_block'::"text", 'scheduled_retry_created'::"text", 'scheduled_retry_not_needed'::"text", 'scheduled_retry_window_closed'::"text", 'scheduled_retry_limit_reached'::"text"]))),
    CONSTRAINT "account_package_runtime_contract_events_idempotency_key_check" CHECK ((("idempotency_key" IS NULL) OR (("char_length"("idempotency_key") >= 1) AND ("char_length"("idempotency_key") <= 240))))
);




CREATE TABLE IF NOT EXISTS "public"."account_warmup_settings" (
    "account_id" "uuid" NOT NULL,
    "warmup_enabled" boolean DEFAULT true NOT NULL,
    "package_started_at" timestamp with time zone,
    "warmup_profile_code" "text" DEFAULT 'follow_default_v1'::"text" NOT NULL,
    "day_1_follow_cap" integer DEFAULT 10 NOT NULL,
    "day_2_follow_cap" integer DEFAULT 20 NOT NULL,
    "day_3_follow_cap" integer DEFAULT 40 NOT NULL,
    "day_4_plus_follow_cap" integer,
    "status" "text" DEFAULT 'pending_package_start'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "account_warmup_settings_day_1_cap_check" CHECK (("day_1_follow_cap" > 0)),
    CONSTRAINT "account_warmup_settings_day_2_cap_check" CHECK (("day_2_follow_cap" > 0)),
    CONSTRAINT "account_warmup_settings_day_3_cap_check" CHECK (("day_3_follow_cap" > 0)),
    CONSTRAINT "account_warmup_settings_day_4_plus_cap_check" CHECK ((("day_4_plus_follow_cap" IS NULL) OR ("day_4_plus_follow_cap" > 0))),
    CONSTRAINT "account_warmup_settings_progression_check" CHECK ((("day_1_follow_cap" <= "day_2_follow_cap") AND ("day_2_follow_cap" <= "day_3_follow_cap") AND (("day_4_plus_follow_cap" IS NULL) OR ("day_3_follow_cap" <= "day_4_plus_follow_cap"))))
);




CREATE TABLE IF NOT EXISTS "public"."client_entitlements" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "client_id" "uuid" NOT NULL,
    "feature_code" "text" NOT NULL,
    "entitlement_type" "text" DEFAULT 'standalone'::"text" NOT NULL,
    "active" boolean DEFAULT true NOT NULL,
    "valid_from" timestamp with time zone DEFAULT "now"(),
    "valid_until" timestamp with time zone,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "account_id" "uuid",
    "source_subscription_id" "uuid",
    "source_subscription_account_id" "uuid",
    "source_subscription_module_id" "uuid",
    CONSTRAINT "client_entitlements_feature_code_check" CHECK (("feature_code" = ANY (ARRAY['outreach'::"text", 'welcome'::"text", 'follow'::"text", 'unfollow'::"text"]))),
    CONSTRAINT "client_entitlements_type_check" CHECK (("entitlement_type" = ANY (ARRAY['standalone'::"text", 'addon'::"text", 'bundle'::"text"]))),
    CONSTRAINT "client_entitlements_valid_window_check" CHECK ((("valid_until" IS NULL) OR ("valid_from" IS NULL) OR ("valid_until" > "valid_from")))
);




COMMENT ON TABLE "public"."client_entitlements" IS 'Entry 2A product entitlements. Outreach enqueue requires an active outreach entitlement plus account outreach_enabled=true.';



COMMENT ON COLUMN "public"."client_entitlements"."account_id" IS 'Nullable Entry 2B account scope. NULL keeps Entry 2A client-wide entitlement semantics for backward compatibility.';



COMMENT ON COLUMN "public"."client_entitlements"."source_subscription_id" IS 'Audit link to the product subscription that produced this runtime entitlement, when synced.';



CREATE TABLE IF NOT EXISTS "public"."client_instagram_accounts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "client_id" "uuid" NOT NULL,
    "account_id" "uuid" NOT NULL,
    "label" "text",
    "onboarding_status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "provisioning_status" "text" DEFAULT 'not_started'::"text" NOT NULL,
    "login_status" "text" DEFAULT 'unknown'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "active" boolean DEFAULT true NOT NULL,
    "onboarding_rollback_at" timestamp with time zone,
    "onboarding_rollback_id" "uuid",
    CONSTRAINT "client_instagram_accounts_login_status_check" CHECK (("login_status" = ANY (ARRAY['unknown'::"text", 'pending'::"text", 'connected'::"text", 'needs_2fa'::"text", 'checkpoint'::"text", 'failed'::"text", 'mismatch'::"text", 'logged_out'::"text", 'verification_pending'::"text"]))),
    CONSTRAINT "client_instagram_accounts_onboarding_status_check" CHECK (("onboarding_status" = ANY (ARRAY['pending'::"text", 'incomplete'::"text", 'credentials_required'::"text", 'configured'::"text", 'credentials_submitted'::"text", 'verification_pending'::"text", 'ready'::"text", 'blocked'::"text", 'support_required'::"text"]))),
    CONSTRAINT "client_instagram_accounts_provisioning_status_check" CHECK (("provisioning_status" = ANY (ARRAY['not_started'::"text", 'pending'::"text", 'provisioning'::"text", 'assigned'::"text", 'login_pending'::"text", 'login_verification_pending'::"text", 'ready'::"text", 'failed'::"text", 'blocked'::"text", 'paused'::"text"])))
);




COMMENT ON TABLE "public"."client_instagram_accounts" IS 'Entry 2A ownership mapping from SaaS clients to Instagram accounts. Does not store Instagram credentials.';



COMMENT ON COLUMN "public"."client_instagram_accounts"."onboarding_status" IS 'Entry 2E-1 client-visible onboarding state. This field is status only and must never contain password, secret_ref, Vault payload, or device identifiers.';



COMMENT ON COLUMN "public"."client_instagram_accounts"."provisioning_status" IS 'Entry 2E-1 safe provisioning/login pipeline status for account setup. Ops/device details remain service-side and must not be exposed directly to clients.';



COMMENT ON COLUMN "public"."client_instagram_accounts"."login_status" IS 'Entry 2E-1 safe Instagram login status for dashboards and future provisioning workers. Never store credentials, secret refs, Vault payloads, tokens, cookies, raw XML, or screenshots here.';



CREATE TABLE IF NOT EXISTS "public"."client_subscription_accounts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "subscription_id" "uuid" NOT NULL,
    "client_instagram_account_id" "uuid" NOT NULL,
    "account_id" "uuid" NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "client_subscription_accounts_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'paused'::"text", 'removed'::"text"])))
);




COMMENT ON TABLE "public"."client_subscription_accounts" IS 'Entry 2B account scope for subscriptions. Allows one client to have different package types per Instagram account.';



CREATE TABLE IF NOT EXISTS "public"."client_subscriptions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "client_id" "uuid" NOT NULL,
    "subscription_type" "text" NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "starts_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "ends_at" timestamp with time zone,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "client_subscriptions_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'paused'::"text", 'cancelled'::"text", 'expired'::"text"]))),
    CONSTRAINT "client_subscriptions_type_check" CHECK (("subscription_type" = ANY (ARRAY['full_cycle'::"text", 'outreach_only'::"text"]))),
    CONSTRAINT "client_subscriptions_valid_window_check" CHECK ((("ends_at" IS NULL) OR ("ends_at" > "starts_at")))
);




COMMENT ON TABLE "public"."client_subscriptions" IS 'Entry 2B product/billing subscriptions. No runtime quotas, devices, credentials, or provisioning data.';



COMMENT ON COLUMN "public"."client_subscriptions"."subscription_type" IS 'Product type: full_cycle or outreach_only. Device pools/session kinds are assigned in a later Entry 2C.';



CREATE TABLE IF NOT EXISTS "public"."commercial_packages" (
    "code" "text" NOT NULL,
    "label" "text" NOT NULL,
    "default_follow_day_cap" integer,
    "default_unfollow_day_cap" integer,
    "default_follow_session_cap" integer,
    "default_unfollow_session_cap" integer,
    "default_welcome_enabled" boolean DEFAULT false NOT NULL,
    "default_outreach_enabled" boolean DEFAULT false NOT NULL,
    "default_welcome_day_cap" integer,
    "default_outreach_day_cap" integer,
    "advanced_ct_enabled" boolean DEFAULT false NOT NULL,
    "ai_comment_enabled" boolean DEFAULT false NOT NULL,
    "ai_targeting_enabled" boolean DEFAULT false NOT NULL,
    "active" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "max_follow_day_cap" integer,
    "max_follow_session_cap" integer,
    CONSTRAINT "commercial_packages_follow_day_policy_check" CHECK (((("default_follow_day_cap" IS NULL) AND ("max_follow_day_cap" IS NULL)) OR (("default_follow_day_cap" > 0) AND ("max_follow_day_cap" > 0) AND ("default_follow_day_cap" <= "max_follow_day_cap")))),
    CONSTRAINT "commercial_packages_follow_session_policy_check" CHECK (((("default_follow_session_cap" IS NULL) AND ("max_follow_session_cap" IS NULL)) OR (("default_follow_session_cap" > 0) AND ("max_follow_session_cap" > 0) AND ("default_follow_session_cap" <= "max_follow_session_cap"))))
);




