    "unfollow_sort_mode" "text" DEFAULT 'default'::"text" NOT NULL,
    "unfollow_per_session_limit" integer DEFAULT 50 NOT NULL,
    "unfollow_per_day_limit" integer DEFAULT 200 NOT NULL,
    "package_default_snapshot" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "runtime_cap_mode" "text" DEFAULT 'prod_normal'::"text" NOT NULL,
    "runtime_safety_cap" integer,
    CONSTRAINT "ig_account_unfollow_settings_after_days_nonnegative" CHECK (("unfollow_after_days" >= 0)),
    CONSTRAINT "ig_account_unfollow_settings_day_limit_positive" CHECK (("unfollow_per_day_limit" >= 0)),
    CONSTRAINT "ig_account_unfollow_settings_mode_valid" CHECK (("unfollow_mode" = ANY (ARRAY['unfollow'::"text", 'unfollow-non-followers'::"text", 'unfollow-any'::"text", 'unfollow-any-non-followers'::"text", 'unfollow-any-followers'::"text"]))),
    CONSTRAINT "ig_account_unfollow_settings_runtime_cap_mode_check" CHECK (("runtime_cap_mode" = ANY (ARRAY['mini_run'::"text", 'prod_normal'::"text", 'incident_safety'::"text"]))),
    CONSTRAINT "ig_account_unfollow_settings_runtime_safety_cap_check" CHECK ((("runtime_safety_cap" IS NULL) OR ("runtime_safety_cap" >= 0))),
    CONSTRAINT "ig_account_unfollow_settings_session_limit_positive" CHECK (("unfollow_per_session_limit" >= 0)),
    CONSTRAINT "ig_account_unfollow_settings_sort_mode_valid" CHECK (("unfollow_sort_mode" = ANY (ARRAY['default'::"text", 'newest-to-oldest'::"text", 'oldest-to-newest'::"text"])))
);




CREATE TABLE IF NOT EXISTS "public"."ig_accounts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "username" "text" NOT NULL,
    "display_name" "text",
    "platform" "text" DEFAULT 'instagram'::"text",
    "device_name" "text",
    "device_udid" "text",
    "status" "text" DEFAULT 'inactive'::"text",
    "email" "text",
    "password" "text",
    "two_fa_enabled" boolean DEFAULT false,
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "archived_at" timestamp with time zone,
    "trashed_at" timestamp with time zone,
    "scheduled_trash_at" timestamp with time zone,
    "scheduled_delete_at" timestamp with time zone,
    "restored_at" timestamp with time zone,
    "device_id" "uuid",
    "clone_mode" "text" DEFAULT 'off'::"text",
    "login_method" "text" DEFAULT 'manual'::"text",
    "internal_label" "text",
    "username_verification_status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "username_verified_at" timestamp with time zone,
    "username_verification_reason" "text",
    "instagram_user_id" "text",
    "external_profile_id" "text",
    "is_private" boolean,
    "is_verified" boolean,
    "followers_count" integer,
    "avatar_url" "text",
    "avatar_checked_at" timestamp with time zone,
    "public_profile_metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "admin_lifecycle_status" "text" DEFAULT 'active'::"text" NOT NULL,
    CONSTRAINT "ig_accounts_admin_lifecycle_status_check" CHECK (("admin_lifecycle_status" = ANY (ARRAY['active'::"text", 'paused'::"text", 'cancelled'::"text", 'needs_assistance'::"text", 'pending_cancellation'::"text"]))),
    CONSTRAINT "ig_accounts_avatar_url_safe_check" CHECK ((("avatar_url" IS NULL) OR (("avatar_url" ~* '^https?://'::"text") AND ("char_length"("avatar_url") <= 2048) AND ("lower"("avatar_url") !~~ '%token%'::"text") AND ("lower"("avatar_url") !~~ '%secret%'::"text") AND ("lower"("avatar_url") !~~ '%signature%'::"text") AND ("lower"("avatar_url") !~~ '%authorization%'::"text") AND ("lower"("avatar_url") !~~ '%service_role%'::"text") AND ("lower"("avatar_url") !~~ '%supabase_vault://%'::"text")))),
    CONSTRAINT "ig_accounts_followers_count_nonnegative" CHECK ((("followers_count" IS NULL) OR ("followers_count" >= 0))),
    CONSTRAINT "ig_accounts_public_profile_metadata_safe_check" CHECK ((("jsonb_typeof"("public_profile_metadata") = 'object'::"text") AND (NOT "public"."jsonb_has_forbidden_safe_metadata_key"("public_profile_metadata")))),
    CONSTRAINT "ig_accounts_username_verification_status_check" CHECK (("username_verification_status" = ANY (ARRAY['pending'::"text", 'verified'::"text", 'not_found'::"text", 'username_changed'::"text", 'private_or_limited'::"text", 'inaccessible'::"text", 'verification_unavailable'::"text", 'provider_error'::"text", 'invalid_format'::"text", 'unknown'::"text"])))
);




COMMENT ON COLUMN "public"."ig_accounts"."username_verification_status" IS 'Patch 2C-5 safe public username verification status. V1 is syntax/preflight plus provider-unavailable state; no credential or device login is used.';



COMMENT ON COLUMN "public"."ig_accounts"."username_verified_at" IS 'Timestamp when a safe public/profile verification source confirmed the username. Null for pending or unavailable verification.';



COMMENT ON COLUMN "public"."ig_accounts"."username_verification_reason" IS 'Safe stable reason for public username verification state. Never store raw provider responses or request bodies.';



COMMENT ON COLUMN "public"."ig_accounts"."instagram_user_id" IS 'Optional public/stable Instagram user id when a safe provider returns one. Never inferred from credentials.';



COMMENT ON COLUMN "public"."ig_accounts"."external_profile_id" IS 'Optional provider-specific public profile id for future verified profile metadata. Never a secret or Vault reference.';



COMMENT ON COLUMN "public"."ig_accounts"."is_private" IS 'Optional public profile privacy signal when safely available.';



COMMENT ON COLUMN "public"."ig_accounts"."is_verified" IS 'Optional public verified/blue-badge signal when safely available.';



COMMENT ON COLUMN "public"."ig_accounts"."followers_count" IS 'Optional public follower count when safely available. Target-account filtering is out of scope for Patch 2C-5.';



COMMENT ON COLUMN "public"."ig_accounts"."avatar_url" IS 'Optional public avatar/profile picture URL. Must not include tokens, signatures, secret refs, Vault ids, cookies, or service-role data.';



COMMENT ON COLUMN "public"."ig_accounts"."avatar_checked_at" IS 'Timestamp when avatar_url/public profile metadata was last checked by a safe source.';



COMMENT ON COLUMN "public"."ig_accounts"."public_profile_metadata" IS 'Safe public profile metadata only. Never store passwords, tokens, Authorization headers, service-role keys, cookies/sessions, secret refs, Vault payloads, raw request bodies, raw logs, XML, screenshots, or device internals.';



COMMENT ON COLUMN "public"."ig_accounts"."admin_lifecycle_status" IS 'Manual admin lifecycle status. Paused and needs_assistance block runtime but keep assignment/app instance/slot. Cancelled may release capacity when safe. Do not mix with login/provisioning/onboarding or runtime stopped.';



