    "expected_username" "text",
    "expected_package" "text",
    "scheduled_window_start" timestamp with time zone,
    "scheduled_window_end" timestamp with time zone,
    "resume_window_key" "text",
    "source_surface" "text",
    "run_trigger" "text",
