CREATE TABLE IF NOT EXISTS "public"."ig_targets" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "account_id" "uuid",
    "target_username" "text" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text",
    "source" "text",
    "last_action_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "last_error" "text",
    "processed_at" timestamp with time zone,
    "retry_count" integer DEFAULT 0 NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "last_run_at" timestamp with time zone,
    "input_username" "text",
    "normalized_username" "text",
    "canonical_username" "text",
    "verification_status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "verification_reason" "text",
    "quality_status" "text" DEFAULT 'unknown'::"text" NOT NULL,
    "avatar_url" "text",
    "followers_count" integer,
    "is_verified" boolean,
    "is_private" boolean,
    "provider_checked_at" timestamp with time zone,
    "batch_id" "uuid",
    "actor_type" "text",
    "archive_reason" "text",
    "rejected_reason" "text",
    "archived_at" timestamp with time zone,
    "deleted_at" timestamp with time zone,
    "metadata_safe" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "follows_sent_count" integer DEFAULT 0 NOT NULL,
    "followbacks_count" integer DEFAULT 0 NOT NULL,
    "followback_ratio" numeric,
    "last_selected_at" timestamp with time zone,
    "last_used_at" timestamp with time zone,
    "last_successful_candidate_at" timestamp with time zone,
    "last_exhausted_at" timestamp with time zone,
    "exhaustion_reason" "text",
    "cooldown_until" timestamp with time zone,
    "metrics_updated_at" timestamp with time zone,
    "auto_archived_at" timestamp with time zone,
    "readd_blocked_until" timestamp with time zone,
    "followbacks_metrics_reliable_at" timestamp with time zone,
    "readd_blocked_permanently" boolean DEFAULT false NOT NULL,
    "readd_block_reason" "text",
    "readd_blocked_at" timestamp with time zone,
    "periodic_revalidation_last_terminal_at" timestamp with time zone,
    "periodic_revalidation_next_due_at" timestamp with time zone,
    "periodic_revalidation_window_key" "text"
);




COMMENT ON TABLE "public"."ig_targets" IS 'Target accounts / CT source of truth. CT-1 adds safe verification, quality, source, batch and soft-archive fields without activating worker/follow runtime.';



COMMENT ON COLUMN "public"."ig_targets"."metadata_safe" IS 'Safe target verification metadata only. Never raw provider payloads, URLs with keys, headers, cookies, sessions, tokens, secret refs, Vault ids, raw HTML, XML, screenshots or logs.';



COMMENT ON COLUMN "public"."ig_targets"."auto_archived_at" IS 'Timestamp when a target was auto-archived by the low-FBR performance policy.';



COMMENT ON COLUMN "public"."ig_targets"."readd_blocked_until" IS 'Re-add block expiry for the same account_id + normalized username after auto-archive.';



COMMENT ON COLUMN "public"."ig_targets"."followbacks_metrics_reliable_at" IS 'Set only when the worker certifies durable CT-level followbacks_count attribution.';



COMMENT ON COLUMN "public"."ig_targets"."readd_blocked_permanently" IS 'Permanent re-add block for the same account_id + normalized_username.';



COMMENT ON COLUMN "public"."ig_targets"."readd_block_reason" IS 'Stable reason code for permanent re-add block (e.g. auto_low_followback_ratio).';



COMMENT ON COLUMN "public"."ig_targets"."readd_blocked_at" IS 'Timestamp when permanent re-add block was set.';



COMMENT ON COLUMN "public"."ig_targets"."periodic_revalidation_last_terminal_at" IS 'UTC timestamp of the last successful terminal periodic CT revalidation.';



COMMENT ON COLUMN "public"."ig_targets"."periodic_revalidation_next_due_at" IS 'UTC timestamp when the next periodic CT revalidation becomes due.';



COMMENT ON COLUMN "public"."ig_targets"."periodic_revalidation_window_key" IS 'Idempotence key for the current periodic revalidation enqueue window.';



CREATE TABLE IF NOT EXISTS "public"."phone_devices" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "device_kind" "text" NOT NULL,
    "name" "text" NOT NULL,
    "device_name" "text",
    "adb_serial" "text",
    "device_udid" "text",
    "host_machine" "text",
    "hub_label" "text",
    "hub_port" "text",
    "pool_type" "text" NOT NULL,
    "max_clones" integer DEFAULT 4 NOT NULL,
    "status" "text" DEFAULT 'available'::"text" NOT NULL,
    "status_reason" "text",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "timezone" "text" DEFAULT 'Africa/Johannesburg'::"text" NOT NULL,
    "retired_at" timestamp with time zone,
    CONSTRAINT "phone_devices_adb_serial_nonempty" CHECK ((("adb_serial" IS NULL) OR ("char_length"(TRIM(BOTH FROM "adb_serial")) > 0))),
    CONSTRAINT "phone_devices_device_udid_nonempty" CHECK ((("device_udid" IS NULL) OR ("char_length"(TRIM(BOTH FROM "device_udid")) > 0))),
    CONSTRAINT "phone_devices_kind_check" CHECK (("device_kind" = ANY (ARRAY['emulator'::"text", 'physical_phone'::"text"]))),
    CONSTRAINT "phone_devices_max_clones_positive" CHECK (("max_clones" >= 1)),
    CONSTRAINT "phone_devices_name_nonempty" CHECK (("char_length"(TRIM(BOTH FROM "name")) > 0)),
    CONSTRAINT "phone_devices_pool_type_check" CHECK (("pool_type" = ANY (ARRAY['full_cycle'::"text", 'outreach_only'::"text", 'shared'::"text"]))),
    CONSTRAINT "phone_devices_status_check" CHECK (("status" = ANY (ARRAY['available'::"text", 'reserved'::"text", 'active'::"text", 'maintenance'::"text", 'offline'::"text", 'unauthorized'::"text", 'disabled'::"text", 'retired'::"text"]))),
    CONSTRAINT "phone_devices_timezone_check" CHECK (("char_length"(TRIM(BOTH FROM "timezone")) > 0))
);




COMMENT ON TABLE "public"."phone_devices" IS 'Entry 2C admin-only inventory for emulator and physical-phone capacity. Never expose adb_serial/device_udid/hub details to client dashboards.';



COMMENT ON COLUMN "public"."phone_devices"."device_kind" IS 'Device class: emulator for dev/test (e.g. emulator-5554) or physical_phone for production USB phone farm.';



COMMENT ON COLUMN "public"."phone_devices"."adb_serial" IS 'ADB serial for operator/worker routing. Not a durable identity by itself and not client-visible.';



COMMENT ON COLUMN "public"."phone_devices"."device_udid" IS 'Optional ops identifier, useful for legacy ig_accounts.device_udid compatibility. Not client-visible.';



COMMENT ON COLUMN "public"."phone_devices"."hub_port" IS 'Physical USB hub port label for production phone farm operations. Not client-visible.';



COMMENT ON COLUMN "public"."phone_devices"."pool_type" IS 'Assignment pool: full_cycle, outreach_only, or shared. Worker dispatch is added later.';



COMMENT ON COLUMN "public"."phone_devices"."timezone" IS 'IANA business timezone used to interpret assignment slot windows for this phone/device. Default: Africa/Johannesburg.';



COMMENT ON COLUMN "public"."phone_devices"."retired_at" IS 'Timestamp when the phone was retired from operational inventory. Released assignment history remains linked for audit.';



CREATE OR REPLACE VIEW "public"."activity_log_interaction_evidence_admin_v1" WITH ("security_invoker"='true') AS
 WITH "latest_assignment" AS (
         SELECT DISTINCT ON ("aa"."account_id") "aa"."account_id",
            "aa"."device_id",
            COALESCE(NULLIF("pd"."name", ''::"text"), NULLIF("pd"."device_name", ''::"text"), 'assigned phone'::"text") AS "assignment_device_label"
           FROM ("public"."account_assignments" "aa"
             LEFT JOIN "public"."phone_devices" "pd" ON (("pd"."id" = "aa"."device_id")))
          WHERE ("aa"."status" = ANY (ARRAY['reserved'::"text", 'active'::"text"]))
          ORDER BY "aa"."account_id", "aa"."created_at" DESC
        ), "event_records" AS (
         SELECT "event"."id" AS "source_record_id",
            'ig_interaction_events'::"text" AS "evidence_source_table",
            "event"."account_id",
            "cia"."client_id",
            COALESCE(NULLIF("ia"."username", ''::"text"), NULLIF("cia"."label", ''::"text")) AS "client_account_username",
            COALESCE("event"."ct_id", "event"."source_target_id", "event"."target_id") AS "ct_id",
            COALESCE(NULLIF("event"."source_target_username", ''::"text"), "target"."normalized_username", "target"."target_username", NULLIF("event"."source_profile", ''::"text")) AS "ct_username",
            "event"."username" AS "interacted_username",
            COALESCE(NULLIF("event"."interaction_type", ''::"text"), NULLIF("event"."event_type", ''::"text"), 'unknown'::"text") AS "action_type",
            COALESCE(NULLIF("event"."interaction_status", ''::"text"), NULLIF("event"."event_status", ''::"text"), 'unknown'::"text") AS "action_status",
            "event"."event_at" AS "occurred_at",
            "event"."run_id",
            "event"."request_id",
            COALESCE(NULLIF("event"."safe_device_label", ''::"text"), "la"."assignment_device_label") AS "safe_device_label",
            COALESCE(NULLIF("event"."evidence_source", ''::"text"), 'ig_interaction_events'::"text") AS "evidence_source",
            COALESCE(NULLIF("event"."evidence_confidence", ''::"text"), 'unknown'::"text") AS "evidence_confidence",
            COALESCE(NULLIF("event"."evidence_summary", ''::"text"), "event"."event_reason", 'Interaction event persisted by worker.'::"text") AS "evidence_summary",
            COALESCE("event"."metadata_safe", '{}'::"jsonb") AS "metadata_safe"
           FROM (((("public"."ig_interaction_events" "event"
             LEFT JOIN "public"."client_instagram_accounts" "cia" ON (("cia"."account_id" = "event"."account_id")))
             LEFT JOIN "public"."ig_accounts" "ia" ON (("ia"."id" = "event"."account_id")))
             LEFT JOIN "public"."ig_targets" "target" ON (("target"."id" = COALESCE("event"."source_target_id", "event"."target_id", "event"."ct_id"))))
             LEFT JOIN "latest_assignment" "la" ON (("la"."account_id" = "event"."account_id")))
        ), "state_records" AS (
         SELECT "interacted"."id" AS "source_record_id",
            'ig_interacted_users'::"text" AS "evidence_source_table",
            "interacted"."account_id",
            "cia"."client_id",
            COALESCE(NULLIF("ia"."username", ''::"text"), NULLIF("cia"."label", ''::"text")) AS "client_account_username",
            COALESCE("interacted"."ct_id", "interacted"."source_target_id") AS "ct_id",
            COALESCE(NULLIF("interacted"."source_target_username", ''::"text"), "target"."normalized_username", "target"."target_username", NULLIF("interacted"."last_source_profile", ''::"text"), NULLIF("interacted"."source_profile", ''::"text")) AS "ct_username",
            "interacted"."username" AS "interacted_username",
            COALESCE(NULLIF("interacted"."interaction_type", ''::"text"), 'unknown'::"text") AS "action_type",
            COALESCE(NULLIF("interacted"."interaction_status", ''::"text"), NULLIF("interacted"."follow_status", ''::"text"), 'unknown'::"text") AS "action_status",
            COALESCE("interacted"."last_interaction_at", "interacted"."updated_at", "interacted"."created_at") AS "occurred_at",
            COALESCE("interacted"."last_run_id", "interacted"."run_id") AS "run_id",
            "interacted"."request_id",
            COALESCE(NULLIF("interacted"."safe_device_label", ''::"text"), "la"."assignment_device_label") AS "safe_device_label",
            COALESCE(NULLIF("interacted"."evidence_source", ''::"text"), 'ig_interacted_users'::"text") AS "evidence_source",
            COALESCE(NULLIF("interacted"."evidence_confidence", ''::"text"), 'unknown'::"text") AS "evidence_confidence",
            COALESCE(NULLIF("interacted"."evidence_summary", ''::"text"), 'Interaction state persisted by worker.'::"text") AS "evidence_summary",
            COALESCE("interacted"."metadata_safe", '{}'::"jsonb") AS "metadata_safe"
           FROM (((("public"."ig_interacted_users" "interacted"
             LEFT JOIN "public"."client_instagram_accounts" "cia" ON (("cia"."account_id" = "interacted"."account_id")))
             LEFT JOIN "public"."ig_accounts" "ia" ON (("ia"."id" = "interacted"."account_id")))
             LEFT JOIN "public"."ig_targets" "target" ON (("target"."id" = COALESCE("interacted"."source_target_id", "interacted"."ct_id"))))
             LEFT JOIN "latest_assignment" "la" ON (("la"."account_id" = "interacted"."account_id")))
        )
 SELECT "event_records"."source_record_id",
    "event_records"."evidence_source_table",
    "event_records"."account_id",
    "event_records"."client_id",
    "event_records"."client_account_username",
    "event_records"."ct_id",
    "event_records"."ct_username",
    "event_records"."interacted_username",
    "event_records"."action_type",
    "event_records"."action_status",
    "event_records"."occurred_at",
    "event_records"."run_id",
    "event_records"."request_id",
    "event_records"."safe_device_label",
    "event_records"."evidence_source",
    "event_records"."evidence_confidence",
    "event_records"."evidence_summary",
    "event_records"."metadata_safe"
   FROM "event_records"
UNION ALL
 SELECT "state_records"."source_record_id",
    "state_records"."evidence_source_table",
    "state_records"."account_id",
    "state_records"."client_id",
    "state_records"."client_account_username",
    "state_records"."ct_id",
    "state_records"."ct_username",
    "state_records"."interacted_username",
    "state_records"."action_type",
    "state_records"."action_status",
    "state_records"."occurred_at",
    "state_records"."run_id",
    "state_records"."request_id",
    "state_records"."safe_device_label",
    "state_records"."evidence_source",
    "state_records"."evidence_confidence",
    "state_records"."evidence_summary",
    "state_records"."metadata_safe"
   FROM "state_records";




COMMENT ON VIEW "public"."activity_log_interaction_evidence_admin_v1" IS 'Admin-safe interaction evidence projection for Activity Log investigation. Does not expose internal device identifiers, worker payloads, sensitive runtime artifacts, or cross-client joins outside caller filtering.';



CREATE TABLE IF NOT EXISTS "public"."add_profile_audit_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "account_id" "uuid",
    "username" "text" NOT NULL,
    "request_id" "text" NOT NULL,
    "credential_request_id" "text",
    "source_surface" "text" DEFAULT 'admin_dashboard'::"text" NOT NULL,
    "operation" "text" DEFAULT 'add_profile'::"text" NOT NULL,
    "result_status" "text" NOT NULL,
    "failure_reason" "text",
    "actor_type" "text",
    "actor_id" "uuid",
    "metadata_safe" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    CONSTRAINT "add_profile_audit_actor_type_check" CHECK ((("actor_type" IS NULL) OR ("actor_type" = ANY (ARRAY['admin'::"text", 'client'::"text", 'system'::"text", 'backend'::"text"])))),
    CONSTRAINT "add_profile_audit_credential_request_id_safe_length" CHECK ((("credential_request_id" IS NULL) OR ("char_length"("credential_request_id") <= 120))),
    CONSTRAINT "add_profile_audit_metadata_safe_check" CHECK ((("jsonb_typeof"("metadata_safe") = 'object'::"text") AND (NOT "public"."jsonb_has_forbidden_safe_metadata_key"("metadata_safe")))),
    CONSTRAINT "add_profile_audit_operation_check" CHECK (("operation" = 'add_profile'::"text")),
    CONSTRAINT "add_profile_audit_request_id_nonempty" CHECK (("char_length"(TRIM(BOTH FROM "request_id")) > 0)),
    CONSTRAINT "add_profile_audit_request_id_safe_length" CHECK (("char_length"("request_id") <= 120)),
    CONSTRAINT "add_profile_audit_result_status_check" CHECK (("result_status" = ANY (ARRAY['success'::"text", 'failed'::"text", 'compensated'::"text", 'duplicate'::"text"]))),
    CONSTRAINT "add_profile_audit_source_surface_check" CHECK (("source_surface" = 'admin_dashboard'::"text")),
    CONSTRAINT "add_profile_audit_username_nonempty" CHECK (("char_length"(TRIM(BOTH FROM "username")) > 0))
);




COMMENT ON TABLE "public"."add_profile_audit_events" IS 'Patch 2C-4 safe Add Profile audit trail. Stores only safe outcome metadata; never passwords, tokens, Authorization headers, full secret refs, Vault payloads, cookies, sessions, service-role data, raw XML/screenshots, or raw request bodies.';



COMMENT ON COLUMN "public"."add_profile_audit_events"."account_id" IS 'Optional Add Profile account id. Uses ON DELETE SET NULL so compensated/deleted account audits remain available without preserving lifecycle state.';



COMMENT ON COLUMN "public"."add_profile_audit_events"."request_id" IS 'Safe Add Profile idempotency/correlation id truncated to 120 characters.';



COMMENT ON COLUMN "public"."add_profile_audit_events"."credential_request_id" IS 'Optional safe credential ingestion request id truncated to 120 characters.';



COMMENT ON COLUMN "public"."add_profile_audit_events"."metadata_safe" IS 'Safe metadata only. Forbidden keys include password, token, secret_ref, raw request body, raw logs/XML, screenshots, Vault payloads, cookies, sessions, and service-role data.';



CREATE TABLE IF NOT EXISTS "public"."agent_logs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "customer_id" "uuid" NOT NULL,
    "conversation_id" "uuid",
    "patient_id" "uuid",
    "agent_name" "text" NOT NULL,
    "input_json" "jsonb",
    "output_json" "jsonb",
    "success" boolean DEFAULT true,
    "error_message" "text",
    "latency_ms" integer,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);




CREATE TABLE IF NOT EXISTS "public"."restaurant_call_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "call_session_id" "uuid" NOT NULL,
    "event_type" "public"."restaurant_call_event_type" NOT NULL,
    "tool_name" "text",
    "payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "tenant_id" "uuid"
);




CREATE OR REPLACE VIEW "public"."analytics_agent_performance" AS
 SELECT ("payload" ->> 'agent_name'::"text") AS "agent_name",
    "count"(*) AS "total_calls"
   FROM "public"."restaurant_call_events" "rce"
  WHERE ("event_type" = 'agent_called'::"public"."restaurant_call_event_type")
  GROUP BY ("payload" ->> 'agent_name'::"text")
  ORDER BY ("count"(*)) DESC;




CREATE OR REPLACE VIEW "public"."analytics_call_quality" AS
 SELECT "avg"((("payload" ->> 'frustration_score'::"text"))::numeric) AS "avg_frustration",
    "count"(*) FILTER (WHERE (("payload" ->> 'escalate'::"text") = 'true'::"text")) AS "escalated_calls",
    "count"(*) AS "total_calls"
   FROM "public"."restaurant_call_events"
  WHERE ("event_type" = 'call_completed'::"public"."restaurant_call_event_type");




CREATE TABLE IF NOT EXISTS "public"."restaurant_call_sessions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "location_id" "uuid",
    "customer_id" "uuid",
    "vapi_call_id" "text",
    "external_call_id" "text",
    "caller_phone" "text",
    "direction" "text" DEFAULT 'inbound'::"text" NOT NULL,
    "detected_intent" "text",
    "status" "public"."restaurant_call_status" DEFAULT 'started'::"public"."restaurant_call_status" NOT NULL,
    "transcript" "text",
    "summary" "text",
    "started_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "ended_at" timestamp with time zone,
    "duration_seconds" integer,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "restaurant_call_sessions_direction_check" CHECK (("direction" = ANY (ARRAY['inbound'::"text", 'outbound'::"text"])))
);




CREATE OR REPLACE VIEW "public"."analytics_calls_by_location" AS
 WITH "session_base" AS (
         SELECT "rcs"."id" AS "call_session_id",
            "rcs"."tenant_id",
            "rcs"."location_id",
            "rcs"."started_at"
           FROM "public"."restaurant_call_sessions" "rcs"
        ), "event_base" AS (
         SELECT "rce"."call_session_id",
            "rce"."event_type",
            "rce"."created_at",
            "rce"."payload"
           FROM "public"."restaurant_call_events" "rce"
        ), "call_flags" AS (
         SELECT "sb"."call_session_id",
            "sb"."tenant_id",
            "sb"."location_id",
            "sb"."started_at",
            "max"(
                CASE
                    WHEN ("eb"."event_type" = 'call_completed'::"public"."restaurant_call_event_type") THEN 1
                    ELSE 0
                END) AS "has_call_completed",
            "max"(
                CASE
                    WHEN ("eb"."event_type" = 'escalation_detected'::"public"."restaurant_call_event_type") THEN 1
                    ELSE 0
                END) AS "has_escalation",
            "max"(
                CASE
                    WHEN ("eb"."event_type" = 'fallback_triggered'::"public"."restaurant_call_event_type") THEN 1
                    ELSE 0
                END) AS "has_fallback",
            "max"(
                CASE
                    WHEN ("eb"."event_type" = 'agent_called'::"public"."restaurant_call_event_type") THEN 1
                    ELSE 0
                END) AS "has_agent_called"
           FROM ("session_base" "sb"
             LEFT JOIN "event_base" "eb" ON (("sb"."call_session_id" = "eb"."call_session_id")))
          GROUP BY "sb"."call_session_id", "sb"."tenant_id", "sb"."location_id", "sb"."started_at"
        )
 SELECT "tenant_id",
    "location_id",
    "count"(*) AS "total_calls",
    COALESCE("sum"("has_call_completed"), (0)::bigint) AS "total_completed_calls",
    COALESCE("sum"("has_escalation"), (0)::bigint) AS "total_escalations",
    COALESCE("sum"("has_fallback"), (0)::bigint) AS "total_fallbacks",
    COALESCE("sum"(
        CASE
            WHEN (("has_call_completed" = 1) AND ("has_escalation" = 0)) THEN 1
            ELSE 0
        END), (0)::bigint) AS "total_auto_handled_calls"
   FROM "call_flags" "cf"
  GROUP BY "tenant_id", "location_id";




CREATE OR REPLACE VIEW "public"."analytics_calls_by_tenant" AS
 WITH "session_base" AS (
         SELECT "rcs"."id" AS "call_session_id",
            "rcs"."tenant_id",
            "rcs"."location_id",
            "rcs"."started_at"
           FROM "public"."restaurant_call_sessions" "rcs"
        ), "event_base" AS (
         SELECT "rce"."call_session_id",
            "rce"."event_type",
            "rce"."created_at",
            "rce"."payload"
           FROM "public"."restaurant_call_events" "rce"
        ), "call_flags" AS (
         SELECT "sb"."call_session_id",
            "sb"."tenant_id",
            "sb"."location_id",
            "sb"."started_at",
            "max"(
                CASE
                    WHEN ("eb"."event_type" = 'call_completed'::"public"."restaurant_call_event_type") THEN 1
                    ELSE 0
                END) AS "has_call_completed",
            "max"(
                CASE
                    WHEN ("eb"."event_type" = 'escalation_detected'::"public"."restaurant_call_event_type") THEN 1
                    ELSE 0
                END) AS "has_escalation",
            "max"(
                CASE
                    WHEN ("eb"."event_type" = 'fallback_triggered'::"public"."restaurant_call_event_type") THEN 1
                    ELSE 0
                END) AS "has_fallback",
            "max"(
                CASE
                    WHEN ("eb"."event_type" = 'agent_called'::"public"."restaurant_call_event_type") THEN 1
                    ELSE 0
                END) AS "has_agent_called"
           FROM ("session_base" "sb"
             LEFT JOIN "event_base" "eb" ON (("sb"."call_session_id" = "eb"."call_session_id")))
          GROUP BY "sb"."call_session_id", "sb"."tenant_id", "sb"."location_id", "sb"."started_at"
        )
 SELECT "tenant_id",
    "count"(*) AS "total_calls",
    COALESCE("sum"("has_call_completed"), (0)::bigint) AS "total_completed_calls",
    COALESCE("sum"("has_escalation"), (0)::bigint) AS "total_escalations",
    COALESCE("sum"("has_fallback"), (0)::bigint) AS "total_fallbacks",
    COALESCE("sum"(
        CASE
            WHEN (("has_call_completed" = 1) AND ("has_escalation" = 0)) THEN 1
            ELSE 0
        END), (0)::bigint) AS "total_auto_handled_calls"
   FROM "call_flags" "cf"
  GROUP BY "tenant_id";




CREATE OR REPLACE VIEW "public"."analytics_calls_overview" AS
 SELECT "tenant_id",
    ("count"(*))::integer AS "total_calls",
    ("count"(*) FILTER (WHERE ("status" = 'completed'::"public"."restaurant_call_status")))::integer AS "total_completed",
    ("count"(*) FILTER (WHERE (EXISTS ( SELECT 1
           FROM "public"."restaurant_call_events" "rce"
          WHERE (("rce"."call_session_id" = "rcs"."id") AND ("rce"."event_type" = ANY (ARRAY['handoff_created'::"public"."restaurant_call_event_type", 'handoff_escalated'::"public"."restaurant_call_event_type"])))))))::integer AS "total_escalations",
    ("count"(*) FILTER (WHERE (EXISTS ( SELECT 1
           FROM "public"."restaurant_call_events" "rce"
          WHERE (("rce"."call_session_id" = "rcs"."id") AND ("rce"."event_type" = 'fallback_returned'::"public"."restaurant_call_event_type"))))))::integer AS "total_fallbacks",
    ("count"(*) FILTER (WHERE (("status" = 'completed'::"public"."restaurant_call_status") AND (NOT (EXISTS ( SELECT 1
           FROM "public"."restaurant_call_events" "rce"
          WHERE (("rce"."call_session_id" = "rcs"."id") AND ("rce"."event_type" = ANY (ARRAY['handoff_created'::"public"."restaurant_call_event_type", 'handoff_escalated'::"public"."restaurant_call_event_type", 'fallback_returned'::"public"."restaurant_call_event_type"])))))))))::integer AS "total_auto_handled"
   FROM "public"."restaurant_call_sessions" "rcs"
  GROUP BY "tenant_id";




CREATE OR REPLACE VIEW "public"."analytics_fallback_detailed" AS
 SELECT ("payload" ->> 'reason'::"text") AS "reason",
    "count"(*) AS "total"
   FROM "public"."restaurant_call_events"
  WHERE ("event_type" = 'fallback_triggered'::"public"."restaurant_call_event_type")
  GROUP BY ("payload" ->> 'reason'::"text")
  ORDER BY ("count"(*)) DESC;




CREATE TABLE IF NOT EXISTS "public"."auto_login_internal_failure_details" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "request_id" "uuid" NOT NULL,
    "run_id" "uuid",
    "account_id" "uuid" NOT NULL,
    "internal_worker_reason" "text" NOT NULL,
    "phase" "text" NOT NULL,
    "exit_code" integer,
    "source" "text" DEFAULT 'run_dispatcher'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "auto_login_internal_failure_phase_canonical" CHECK (((("char_length"("phase") >= 1) AND ("char_length"("phase") <= 80)) AND ("phase" ~ '^[a-z][a-z0-9_]*$'::"text"))),
    CONSTRAINT "auto_login_internal_failure_reason_canonical" CHECK (((("char_length"("internal_worker_reason") >= 1) AND ("char_length"("internal_worker_reason") <= 160)) AND ("internal_worker_reason" ~ '^[a-z][a-z0-9_]*$'::"text"))),
    CONSTRAINT "auto_login_internal_failure_source_safe" CHECK (((("char_length"("source") >= 1) AND ("char_length"("source") <= 80)) AND ("source" !~* '(token|secret|authorization|cookie|service_role|vault|password)'::"text")))
);

ALTER TABLE ONLY "public"."auto_login_internal_failure_details" FORCE ROW LEVEL SECURITY;




COMMENT ON TABLE "public"."auto_login_internal_failure_details" IS 'Server-only exact Auto Login worker failure diagnostics. Never project to client or notification payloads.';



COMMENT ON COLUMN "public"."auto_login_internal_failure_details"."internal_worker_reason" IS 'Exact internal worker reason. Service-role/operator diagnostics only; never use as account_run_requests.error_code.';



