CREATE TABLE IF NOT EXISTS "public"."auto_restart_settings" (
    "id" "text" DEFAULT 'global'::"text" NOT NULL,
    "auto_restart_enabled" boolean DEFAULT false NOT NULL,
    "mode" "text" DEFAULT 'production'::"text" NOT NULL,
    "check_every_minutes" integer DEFAULT 20 NOT NULL,
    "restart_delay_minutes" integer DEFAULT 20 NOT NULL,
    "max_attempts_per_session" integer DEFAULT 2 NOT NULL,
    "max_restarts_per_day_per_account" integer DEFAULT 3 NOT NULL,
    "max_restarts_per_window_per_account" integer DEFAULT 2 NOT NULL,
    "restart_yellow_accounts" boolean DEFAULT false NOT NULL,
    "restart_red_accounts" boolean DEFAULT false NOT NULL,
    "respect_blackout_windows" boolean DEFAULT true NOT NULL,
    "respect_six_hour_window" boolean DEFAULT true NOT NULL,
    "resume_follow_if_quota_remaining" boolean DEFAULT true NOT NULL,
    "resume_unfollow_if_quota_remaining" boolean DEFAULT true NOT NULL,
    "block_on_challenge" boolean DEFAULT true NOT NULL,
    "block_on_restriction" boolean DEFAULT true NOT NULL,
    "block_on_account_mismatch" boolean DEFAULT true NOT NULL,
    "block_on_device_offline" boolean DEFAULT true NOT NULL,
    "notify_on_blocked_restart" boolean DEFAULT true NOT NULL,
    "phone_rest_enabled" boolean DEFAULT false NOT NULL,
    "phone_rest_max_session_minutes" integer,
    "phone_rest_min_rest_minutes" integer,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_by" "uuid",
    "max_retries_after_initial_failure" integer DEFAULT 2 NOT NULL,
    CONSTRAINT "auto_restart_settings_check_every_minutes_check" CHECK ((("check_every_minutes" >= 1) AND ("check_every_minutes" <= 1440))),
    CONSTRAINT "auto_restart_settings_id_check" CHECK (("id" = 'global'::"text")),
    CONSTRAINT "auto_restart_settings_max_attempts_per_session_check" CHECK ((("max_attempts_per_session" >= 0) AND ("max_attempts_per_session" <= 20))),
    CONSTRAINT "auto_restart_settings_max_restarts_per_day_check" CHECK ((("max_restarts_per_day_per_account" >= 0) AND ("max_restarts_per_day_per_account" <= 50))),
    CONSTRAINT "auto_restart_settings_max_restarts_per_window_check" CHECK ((("max_restarts_per_window_per_account" >= 0) AND ("max_restarts_per_window_per_account" <= 50))),
    CONSTRAINT "auto_restart_settings_max_retries_after_initial_failure_check" CHECK ((("max_retries_after_initial_failure" >= 0) AND ("max_retries_after_initial_failure" <= 20))),
    CONSTRAINT "auto_restart_settings_mode_check" CHECK (("mode" = ANY (ARRAY['production'::"text", 'disabled'::"text", 'active'::"text", 'dry_run'::"text"]))),
    CONSTRAINT "auto_restart_settings_restart_delay_minutes_check" CHECK ((("restart_delay_minutes" >= 1) AND ("restart_delay_minutes" <= 1440)))
);




COMMENT ON TABLE "public"."auto_restart_settings" IS 'Canonical Auto Restart policy for phone-farm operators. Disabled by default.';



COMMENT ON COLUMN "public"."auto_restart_settings"."max_retries_after_initial_failure" IS 'Automatic retries after the initial failure. Locked product value: 2; total possible attempts: 3.';



