    CONSTRAINT "client_account_entitlements_commercial_package_code_check" CHECK (("commercial_package_code" = ANY (ARRAY['growth'::"text", 'pro'::"text", 'premium'::"text"]))),
    CONSTRAINT "client_account_entitlements_outreach_addon_key_check" CHECK (("outreach_addon_key" = ANY (ARRAY['outreach_standard'::"text", 'outreach_ai'::"text"]))),
    CONSTRAINT "client_account_entitlements_outreach_variant_check" CHECK (("outreach_variant" = ANY (ARRAY['client_list'::"text", 'ai_list'::"text"]))),
    CONSTRAINT "client_account_entitlements_pack_monthly_discounted_cents_check" CHECK (("pack_monthly_discounted_cents" >= 0)),
    CONSTRAINT "client_account_entitlements_pack_period_total_cents_check" CHECK (("pack_period_total_cents" >= 0)),
    CONSTRAINT "client_account_entitlements_plan_key_check" CHECK (("plan_key" = ANY (ARRAY['growth'::"text", 'pro'::"text", 'premium'::"text"]))),
    CONSTRAINT "client_account_entitlements_status_check" CHECK (("status" = ANY (ARRAY['entitlement_reserved'::"text", 'entitlement_consumed'::"text", 'entitlement_cancelled'::"text"]))),
    CONSTRAINT "client_account_entitlements_total_period_cents_check" CHECK (("total_period_cents" >= 0))
);




