    CONSTRAINT "client_email_send_intents_parent_exclusivity" CHECK ((NOT (("sequence_id" IS NOT NULL) AND ("lifecycle_episode_id" IS NOT NULL)))),
    CONSTRAINT "client_email_send_intents_reminder_index_check" CHECK ((("reminder_index" IS NULL) OR (("reminder_index" >= 0) AND ("reminder_index" <= 5)))),
    CONSTRAINT "client_email_send_intents_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'scheduled'::"text", 'claimed'::"text", 'dispatch_uncertain'::"text", 'sent'::"text", 'canceled'::"text", 'failed'::"text"]))),
    CONSTRAINT "client_email_send_intents_support_email_snapshot_check" CHECK ((("support_email_snapshot" IS NULL) OR ("support_email_snapshot" ~* '^[^@]+@[^@]+\.[^@]+$'::"text"))),
    CONSTRAINT "client_email_send_intents_test_kind_requires_no_refs" CHECK ((("intent_kind" = 'client'::"text") OR (("client_id" IS NULL) AND ("account_id" IS NULL) AND ("sequence_id" IS NULL) AND ("lifecycle_episode_id" IS NULL) AND ("trigger" = 'manual_test'::"text")))),
    CONSTRAINT "client_email_send_intents_trigger_check" CHECK (("trigger" = ANY (ARRAY['manual'::"text", 'automatic'::"text", 'reminder'::"text", 'manual_test'::"text", 'automatic_initial'::"text", 'automatic_reminder'::"text"]))),
    CONSTRAINT "client_email_send_intents_uncertain_clears_active_lease" CHECK ((("status" <> 'dispatch_uncertain'::"text") OR (("claim_token" IS NULL) AND ("claimed_at" IS NULL) AND ("claim_expires_at" IS NULL)))),
    CONSTRAINT "client_email_send_intents_uncertain_has_no_provider_message" CHECK ((("status" <> 'dispatch_uncertain'::"text") OR ("provider_message_id" IS NULL))),
    CONSTRAINT "client_email_send_intents_uncertain_state_requires_timestamp" CHECK (((("status" = 'dispatch_uncertain'::"text") AND ("dispatch_uncertain_at" IS NOT NULL)) OR (("status" <> 'dispatch_uncertain'::"text") AND ("dispatch_uncertain_at" IS NULL))))
);




COMMENT ON TABLE "public"."client_email_send_intents" IS 'Canonical email outbox. No provider sends are wired in TASK 5A.';



COMMENT ON COLUMN "public"."client_email_send_intents"."intent_kind" IS 'client = lifecycle send; test = allowlisted internal Postmark test delivery only.';



COMMENT ON COLUMN "public"."client_email_send_intents"."sequence_id" IS 'FK to client_email_needs_more_targets_sequences for needs_more_target_accounts client intents.';



COMMENT ON COLUMN "public"."client_email_send_intents"."from_email_snapshot" IS 'Immutable snapshot of the active From address applied when the intent was created.';



COMMENT ON COLUMN "public"."client_email_send_intents"."support_email_snapshot" IS 'Immutable snapshot of {{support_email}} applied when the intent was created.';



COMMENT ON COLUMN "public"."client_email_send_intents"."lifecycle_episode_id" IS 'FK to client_email_lifecycle_episodes for account_paused, account_canceled, and needs_assistance client intents.';



COMMENT ON COLUMN "public"."client_email_send_intents"."claimed_at" IS 'When a dispatch worker atomically claimed this intent for provider send.';



COMMENT ON COLUMN "public"."client_email_send_intents"."claim_token" IS 'Opaque lease token required to finalize or release a claimed intent. Never a provider secret.';



COMMENT ON COLUMN "public"."client_email_send_intents"."claim_expires_at" IS 'Lease expiry for claimed intents. After expiry, reclaim is allowed only after revalidation.';



COMMENT ON COLUMN "public"."client_email_send_intents"."dispatch_attempt_count" IS 'Bounded count of dispatch attempts. Does not authorize retry after dispatch_uncertain.';



COMMENT ON COLUMN "public"."client_email_send_intents"."dispatch_last_attempt_at" IS 'Timestamp of the latest dispatch attempt (success, failure, or ambiguous).';



COMMENT ON COLUMN "public"."client_email_send_intents"."dispatch_last_error_code" IS 'Stable redacted dispatch error code for ops filtering. Never raw provider payloads.';



COMMENT ON COLUMN "public"."client_email_send_intents"."dispatch_uncertain_at" IS 'When provider outcome became ambiguous (timeout/network). Blocks automatic retry/resend.';



COMMENT ON COLUMN "public"."client_email_send_intents"."provider_accepted_at" IS 'When provider acceptance was recorded (HTTP MessageID or correlated webhook), distinct from sent_at when needed.';



CREATE TABLE IF NOT EXISTS "public"."client_email_templates" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
