CREATE TABLE IF NOT EXISTS "public"."commercial_checkout_sessions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "idempotency_key" "text" NOT NULL,
    "flow_type" "text" NOT NULL,
    "status" "text" NOT NULL,
    "client_id" "uuid",
    "auth_user_id" "uuid",
    "purchaser_email" "text" NOT NULL,
    "plan_key" "text",
    "billing_interval_months" integer NOT NULL,
    "outreach_addon_key" "text",
    "billable_account_count" integer NOT NULL,
    "term_discount_percent" numeric(5,4) DEFAULT 0 NOT NULL,
    "agency_discount_percent" numeric(5,4) DEFAULT 0 NOT NULL,
    "applied_discount_percent" numeric(5,4) DEFAULT 0 NOT NULL,
    "applied_discount_type" "text" NOT NULL,
    "pack_base_monthly_cents" integer,
    "pack_monthly_discounted_cents" integer,
    "pack_period_total_cents" integer,
    "outreach_base_monthly_cents" integer,
    "outreach_monthly_discounted_cents" integer,
    "outreach_period_total_cents" integer,
    "total_period_cents" integer NOT NULL,
    "catalog_snapshot" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "activated_at" timestamp with time zone,
    "pricing_snapshot" "jsonb",
    "commercial_mode" "text",
    "stripe_pricing_mode" "text",
    "pricing_snapshot_fingerprint" "text",
    CONSTRAINT "commercial_checkout_sessions_applied_discount_type_check" CHECK (("applied_discount_type" = ANY (ARRAY['none'::"text", 'term'::"text", 'agency'::"text"]))),
    CONSTRAINT "commercial_checkout_sessions_billable_account_count_check" CHECK (("billable_account_count" >= 1)),
    CONSTRAINT "commercial_checkout_sessions_billing_interval_months_check" CHECK (("billing_interval_months" = ANY (ARRAY[1, 3, 6, 12]))),
    CONSTRAINT "commercial_checkout_sessions_commercial_mode_check" CHECK ((("commercial_mode" IS NULL) OR ("commercial_mode" = ANY (ARRAY['full_cycle'::"text", 'outreach_only'::"text"])))),
    CONSTRAINT "commercial_checkout_sessions_commercial_mode_shape_check" CHECK ((((("commercial_mode" IS NULL) OR ("commercial_mode" = 'full_cycle'::"text")) AND ("plan_key" IS NOT NULL) AND ("plan_key" = ANY (ARRAY['growth'::"text", 'pro'::"text", 'premium'::"text"])) AND ("pack_base_monthly_cents" IS NOT NULL) AND ("pack_monthly_discounted_cents" IS NOT NULL) AND ("pack_period_total_cents" IS NOT NULL)) OR (("commercial_mode" = 'outreach_only'::"text") AND ("plan_key" IS NULL) AND ("outreach_addon_key" IS NOT NULL) AND ("outreach_addon_key" = ANY (ARRAY['outreach_standard'::"text", 'outreach_ai'::"text"])) AND (COALESCE("pack_base_monthly_cents", 0) = 0) AND (COALESCE("pack_monthly_discounted_cents", 0) = 0) AND (COALESCE("pack_period_total_cents", 0) = 0)))),
    CONSTRAINT "commercial_checkout_sessions_flow_type_check" CHECK (("flow_type" = ANY (ARRAY['first_purchase'::"text", 'additional_account'::"text", 'plan_change'::"text"]))),
    CONSTRAINT "commercial_checkout_sessions_outreach_addon_key_check" CHECK (("outreach_addon_key" = ANY (ARRAY['outreach_standard'::"text", 'outreach_ai'::"text"]))),
    CONSTRAINT "commercial_checkout_sessions_outreach_base_monthly_cents_check" CHECK ((("outreach_base_monthly_cents" IS NULL) OR ("outreach_base_monthly_cents" >= 0))),
    CONSTRAINT "commercial_checkout_sessions_pack_base_monthly_cents_check" CHECK (("pack_base_monthly_cents" >= 0)),
    CONSTRAINT "commercial_checkout_sessions_pack_monthly_discounted_cent_check" CHECK (("pack_monthly_discounted_cents" >= 0)),
    CONSTRAINT "commercial_checkout_sessions_pack_period_total_cents_check" CHECK (("pack_period_total_cents" >= 0)),
    CONSTRAINT "commercial_checkout_sessions_plan_key_check" CHECK (("plan_key" = ANY (ARRAY['growth'::"text", 'pro'::"text", 'premium'::"text"]))),
    CONSTRAINT "commercial_checkout_sessions_status_check" CHECK (("status" = ANY (ARRAY['checkout_pending'::"text", 'checkout_activated_test'::"text", 'checkout_cancelled'::"text", 'checkout_pending_payment'::"text", 'checkout_paid'::"text", 'checkout_expired'::"text", 'checkout_failed'::"text", 'checkout_refunded'::"text"]))),
    CONSTRAINT "commercial_checkout_sessions_stripe_pricing_mode_check" CHECK ((("stripe_pricing_mode" IS NULL) OR ("stripe_pricing_mode" = ANY (ARRAY['public_catalog'::"text", 'immutable_snapshot'::"text"])))),
    CONSTRAINT "commercial_checkout_sessions_total_period_cents_check" CHECK (("total_period_cents" >= 0))
);




COMMENT ON COLUMN "public"."commercial_checkout_sessions"."pricing_snapshot" IS 'Immutable CommercialPricingSnapshot captured at checkout activation. Legacy rows remain null.';



COMMENT ON CONSTRAINT "commercial_checkout_sessions_commercial_mode_shape_check" ON "public"."commercial_checkout_sessions" IS 'Allows Stripe Test outreach_only sessions without a package while preserving full_cycle package requirements.';



