    CONSTRAINT "commercial_package_runtime_settings_likes_per_day_limit_check" CHECK (("likes_per_day_limit" >= 0)),
    CONSTRAINT "commercial_package_runtime_settings_likes_per_follow_min_check" CHECK (("likes_per_follow_min" >= 0)),
    CONSTRAINT "commercial_package_runtime_settings_max_targets_per_run_check" CHECK ((("max_targets_per_run" >= 1) AND ("max_targets_per_run" <= 10))),
