    CONSTRAINT "commercial_package_runtime_settings_schedule_mode_check" CHECK (("schedule_mode" = ANY (ARRAY['scheduled'::"text", 'manual_only'::"text"]))),
    CONSTRAINT "commercial_package_runtime_settings_slot_kind_check" CHECK (("slot_kind" = ANY (ARRAY['full_cycle_6h'::"text", 'outreach_short'::"text", 'outreach_40m'::"text", 'manual_only'::"text"]))),
    CONSTRAINT "commercial_package_runtime_settings_unfollow_after_days_check" CHECK (("unfollow_after_days" >= 0)),
    CONSTRAINT "commercial_package_runtime_settings_warmup_day_1_cap_check" CHECK (("warmup_day_1_cap" > 0)),
    CONSTRAINT "commercial_package_runtime_settings_warmup_day_2_cap_check" CHECK (("warmup_day_2_cap" > 0)),
    CONSTRAINT "commercial_package_runtime_settings_warmup_day_3_cap_check" CHECK (("warmup_day_3_cap" > 0))
);




