    CONSTRAINT "commercial_plan_change_quote_target_full_period_price_cen_check" CHECK (("target_full_period_price_cents" >= 0)),
    CONSTRAINT "commercial_plan_change_quotes_amount_due_cents_check" CHECK (("amount_due_cents" >= 0)),
