    CONSTRAINT "commercial_plan_change_quotes_change_scope_check" CHECK (("change_scope" = ANY (ARRAY['workspace'::"text", 'per_account'::"text"]))),
    CONSTRAINT "commercial_plan_change_quotes_credit_applied_cents_check" CHECK (("credit_applied_cents" >= 0)),
