    CONSTRAINT "commercial_plan_change_quotes_remaining_credit_cents_check" CHECK (("remaining_credit_cents" >= 0)),
    CONSTRAINT "commercial_plan_change_quotes_remaining_ratio_bps_check" CHECK ((("remaining_ratio_bps" >= 0) AND ("remaining_ratio_bps" <= 10000))),
