    CONSTRAINT "commercial_stripe_component_price_catalog_environment_check" CHECK (("environment" = ANY (ARRAY['test'::"text", 'live'::"text"]))),
    CONSTRAINT "commercial_stripe_component_price_catalog_kind_keys_check" CHECK (((("component_kind" = 'package'::"text") AND ("package_key" IS NOT NULL) AND ("outreach_key" IS NULL)) OR (("component_kind" = 'outreach'::"text") AND ("outreach_key" IS NOT NULL) AND ("package_key" IS NULL)))),
    CONSTRAINT "commercial_stripe_component_price_catalog_outreach_key_check" CHECK ((("outreach_key" IS NULL) OR ("outreach_key" = ANY (ARRAY['outreach_standard'::"text", 'outreach_ai'::"text"])))),
    CONSTRAINT "commercial_stripe_component_price_catalog_package_key_check" CHECK ((("package_key" IS NULL) OR ("package_key" = ANY (ARRAY['growth'::"text", 'pro'::"text", 'premium'::"text"])))),
    CONSTRAINT "commercial_stripe_component_price_catalog_product_key_check" CHECK (("product_key" = ANY (ARRAY['boost_ai_growth'::"text", 'boost_ai_pro'::"text", 'boost_ai_premium'::"text", 'instagram_outreach_standard'::"text", 'instagram_outreach_ai'::"text"]))),
    CONSTRAINT "commercial_stripe_component_price_catalog_product_key_component" CHECK (((("product_key" = 'boost_ai_growth'::"text") AND ("component_kind" = 'package'::"text") AND ("package_key" = 'growth'::"text")) OR (("product_key" = 'boost_ai_pro'::"text") AND ("component_kind" = 'package'::"text") AND ("package_key" = 'pro'::"text")) OR (("product_key" = 'boost_ai_premium'::"text") AND ("component_kind" = 'package'::"text") AND ("package_key" = 'premium'::"text")) OR (("product_key" = 'instagram_outreach_standard'::"text") AND ("component_kind" = 'outreach'::"text") AND ("outreach_key" = 'outreach_standard'::"text")) OR (("product_key" = 'instagram_outreach_ai'::"text") AND ("component_kind" = 'outreach'::"text") AND ("outreach_key" = 'outreach_ai'::"text"))))
);




