    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "action_id" "uuid",
    "account_id" "uuid" NOT NULL,
    "token_hash" "text" NOT NULL,
    "expires_at" timestamp with time zone NOT NULL,
    "used_at" timestamp with time zone,
    "revoked_at" timestamp with time zone,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "created_by_actor_type" "text",
    "created_by_actor_id" "text",
    "delivery_status" "text",
    "metadata_safe" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "credential_update_requests_actor_type_check" CHECK ((("created_by_actor_type" IS NULL) OR ("created_by_actor_type" = ANY (ARRAY['admin'::"text", 'client'::"text", 'system'::"text", 'migration'::"text", 'backend'::"text"])))),
    CONSTRAINT "credential_update_requests_expires_at_valid" CHECK (("expires_at" > "created_at")),
    CONSTRAINT "credential_update_requests_metadata_safe_check" CHECK ((("jsonb_typeof"("metadata_safe") = 'object'::"text") AND (NOT "public"."jsonb_has_forbidden_safe_metadata_key"("metadata_safe")))),
    CONSTRAINT "credential_update_requests_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'submitted'::"text", 'expired'::"text", 'revoked'::"text"]))),
    CONSTRAINT "credential_update_requests_token_hash_nonempty" CHECK (("char_length"(TRIM(BOTH FROM "token_hash")) >= 32))
);




COMMENT ON TABLE "public"."credential_update_requests" IS 'Credential Secure Pipeline V1 one-time update request metadata. Stores token_hash only; never raw tokens, passwords, secret_ref, Vault payloads, or raw request bodies.';



COMMENT ON COLUMN "public"."credential_update_requests"."token_hash" IS 'Hash of the one-time update token. The raw token is generated by a future Edge/API and is never stored.';



COMMENT ON COLUMN "public"."credential_update_requests"."metadata_safe" IS 'Safe metadata only. Forbidden keys include password, token, secret_ref, raw request body, raw logs/XML, screenshots, and device internals.';



