    CONSTRAINT "ct_target_audit_actor_type_check" CHECK (("actor_type" = ANY (ARRAY['admin'::"text", 'client'::"text", 'system'::"text"]))),
    CONSTRAINT "ct_target_audit_counts_object_check" CHECK ((("counts" IS NULL) OR ("jsonb_typeof"("counts") = 'object'::"text"))),
    CONSTRAINT "ct_target_audit_metadata_safe_check" CHECK ((("jsonb_typeof"("metadata_safe") = 'object'::"text") AND (NOT "public"."jsonb_has_forbidden_safe_metadata_key"("metadata_safe")))),
    CONSTRAINT "ct_target_audit_operation_check" CHECK (("operation" = ANY (ARRAY['target_add_single'::"text", 'target_add_bulk'::"text", 'target_verify'::"text", 'target_archive'::"text", 'target_restore'::"text", 'target_reset'::"text"]))),
    CONSTRAINT "ct_target_audit_result_check" CHECK (("result" = ANY (ARRAY['accepted'::"text", 'duplicate'::"text", 'rejected'::"text", 'review'::"text", 'failed'::"text", 'archived'::"text", 'restored'::"text"])))
);




COMMENT ON TABLE "public"."ct_target_audit_events" IS 'Safe CT target add/bulk/verify/archive/restore/reset audit events. Stores counts and reasons only, never raw provider responses, secrets, tokens, cookies, sessions, raw HTML, XML, screenshots or logs.';



