    CONSTRAINT "device_heartbeats_status_check" CHECK (("status" = ANY (ARRAY['online'::"text", 'offline'::"text", 'unauthorized'::"text", 'busy'::"text", 'maintenance'::"text", 'unknown'::"text", 'error'::"text"])))
);




COMMENT ON TABLE "public"."device_heartbeats" IS 'ORF-1 device presence table for future admin dashboards. adb_serial and host_machine are ops-only and must not be exposed to clients.';



COMMENT ON COLUMN "public"."device_heartbeats"."adb_serial" IS 'Ops-only ADB routing hint. Future client-safe views must redact this field.';



CREATE TABLE IF NOT EXISTS "public"."device_outreach_rest_policies" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
