    CONSTRAINT "device_outreach_rest_policies_reserved_indexes_check" CHECK ((("array_length"("reserved_slot_indexes", 1) IS NULL) OR ((0 < ALL ("reserved_slot_indexes")) AND (36 >= ALL ("reserved_slot_indexes"))))),
    CONSTRAINT "device_outreach_rest_policies_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'disabled'::"text"])))
);




COMMENT ON TABLE "public"."device_outreach_rest_policies" IS 'Optional outreach-only rest policy. Disabled by default. Future operators may reserve specific 40-minute slots or configure buffer metadata without affecting full-cycle capacity.';



