CREATE TABLE IF NOT EXISTS "public"."ig_account_follow_limit_overrides" (
    "account_id" "uuid" NOT NULL,
    "classification" "text" DEFAULT 'explicit'::"text" NOT NULL,
    "follow_day_cap_override" integer,
    "follow_session_cap_override" integer,
    "max_follow_per_run_legacy" integer,
    "source" "text" NOT NULL,
    "source_surface" "text",
    "updated_by" "uuid",
    "reason" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "ig_account_follow_limit_overrides_cap_present" CHECK ((("follow_day_cap_override" IS NOT NULL) OR ("follow_session_cap_override" IS NOT NULL) OR ("max_follow_per_run_legacy" IS NOT NULL))),
    CONSTRAINT "ig_account_follow_limit_overrides_classification_bounded" CHECK (("classification" = ANY (ARRAY['explicit'::"text", 'legacy_unclassified'::"text"]))),
    CONSTRAINT "ig_account_follow_limit_overrides_day_positive" CHECK ((("follow_day_cap_override" IS NULL) OR ("follow_day_cap_override" > 0))),
    CONSTRAINT "ig_account_follow_limit_overrides_run_positive" CHECK ((("max_follow_per_run_legacy" IS NULL) OR ("max_follow_per_run_legacy" > 0))),
    CONSTRAINT "ig_account_follow_limit_overrides_session_positive" CHECK ((("follow_session_cap_override" IS NULL) OR ("follow_session_cap_override" > 0))),
    CONSTRAINT "ig_account_follow_limit_overrides_source_bounded" CHECK (("source" = ANY (ARRAY['admin'::"text", 'support'::"text", 'migration_confirmed'::"text", 'migration_unclassified'::"text"])))
);




COMMENT ON TABLE "public"."ig_account_follow_limit_overrides" IS 'Explicit human Follow cap overrides and preserved unclassified legacy values. No row means package inheritance. Warmup never writes here.';



CREATE TABLE IF NOT EXISTS "public"."ig_account_follow_settings" (
