    CONSTRAINT "ig_account_follow_settings_max_followers_nonnegative" CHECK ((("max_followers" IS NULL) OR ("max_followers" >= 0))),
    CONSTRAINT "ig_account_follow_settings_min_followers_nonnegative" CHECK ((("min_followers" IS NULL) OR ("min_followers" >= 0))),
    CONSTRAINT "ig_account_follow_settings_min_posts_nonnegative" CHECK ((("min_posts" IS NULL) OR ("min_posts" >= 0)))
);




CREATE TABLE IF NOT EXISTS "public"."ig_account_follower_snapshots" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
