);




COMMENT ON TABLE "public"."ig_account_follower_snapshots" IS 'Append-only follower count observations. Never derived from bot actions.';



COMMENT ON COLUMN "public"."ig_account_follower_snapshots"."source" IS 'Observation source: device_profile_read, public_profile_lookup, or admin_manual_verified.';



COMMENT ON COLUMN "public"."ig_account_follower_snapshots"."observation_kind" IS 'Collection cadence: baseline, daily, or intraday.';



CREATE TABLE IF NOT EXISTS "public"."ig_account_social_profile_snapshots" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "account_id" "uuid" NOT NULL,
    "username_normalized" "text" NOT NULL,
    "followers_count" integer,
    "following_count" integer,
    "posts_count" integer,
    "observed_at" timestamp with time zone NOT NULL,
    "snapshot_local_date" "date" NOT NULL,
    "account_timezone" "text" NOT NULL,
    "timezone_source" "text" NOT NULL,
    "source_provider" "text" NOT NULL,
    "source_trigger" "text" NOT NULL,
    "source_event_id" "text",
    "source_run_id" "uuid",
    "source_business_session_id" "uuid",
    "lookup_status" "text" NOT NULL,
    "freshness_status" "text" NOT NULL,
    "idempotency_key" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "ig_account_social_profile_snapshots_followers_count_check" CHECK ((("followers_count" IS NULL) OR ("followers_count" >= 0))),
    CONSTRAINT "ig_account_social_profile_snapshots_following_count_check" CHECK ((("following_count" IS NULL) OR ("following_count" >= 0))),
    CONSTRAINT "ig_account_social_profile_snapshots_freshness_status_check" CHECK (("freshness_status" = ANY (ARRAY['fresh'::"text", 'stale'::"text", 'partial'::"text"]))),
    CONSTRAINT "ig_account_social_profile_snapshots_has_metric" CHECK ((("followers_count" IS NOT NULL) OR ("following_count" IS NOT NULL) OR ("posts_count" IS NOT NULL))),
    CONSTRAINT "ig_account_social_profile_snapshots_lookup_status_check" CHECK (("lookup_status" = 'found'::"text")),
    CONSTRAINT "ig_account_social_profile_snapshots_posts_count_check" CHECK ((("posts_count" IS NULL) OR ("posts_count" >= 0))),
    CONSTRAINT "ig_account_social_profile_snapshots_source_provider_check" CHECK (("source_provider" = ANY (ARRAY['searchapi'::"text", 'http'::"text", 'device_profile_read'::"text", 'legacy_follower_snapshot'::"text"]))),
    CONSTRAINT "ig_account_social_profile_snapshots_source_trigger_check" CHECK (("source_trigger" = ANY (ARRAY['onboarding_lookup'::"text", 'explicit_reanalysis'::"text", 'session_end'::"text", 'daily_fallback'::"text", 'admin_manual_refresh'::"text", 'legacy_import'::"text", 'baseline_one_shot'::"text"]))),
    CONSTRAINT "ig_account_social_profile_snapshots_timezone_source_check" CHECK (("timezone_source" = ANY (ARRAY['device_assignment'::"text", 'schedule'::"text", 'platform_default'::"text"]))),
    CONSTRAINT "ig_account_social_profile_snapshots_username_normalized_check" CHECK ((("username_normalized" = "lower"(TRIM(BOTH FROM "username_normalized"))) AND ("username_normalized" ~ '^[a-z0-9._]{1,30}$'::"text")))
);




COMMENT ON TABLE "public"."ig_account_social_profile_snapshots" IS 'Append-only absolute Instagram public profile observations; never derived from follow or unfollow actions.';



COMMENT ON CONSTRAINT "ig_account_social_profile_snapshots_source_provider_check" ON "public"."ig_account_social_profile_snapshots" IS 'Bounded provider provenance including the reliable legacy follower snapshot import.';



