CREATE TABLE IF NOT EXISTS "public"."ig_target_followers_resume_checkpoint_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "checkpoint_id" "uuid" NOT NULL,
    "account_id" "uuid" NOT NULL,
    "target_id" "uuid" NOT NULL,
    "run_id" "uuid",
    "event_type" "text" NOT NULL,
    "mode" "text",
    "previous_optimistic_version" bigint,
    "new_optimistic_version" bigint,
    "previous_depth" integer,
    "new_depth" integer,
    "reason" "text" NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "ig_target_followers_resume_checkpoint_events_depth_check" CHECK (((("previous_depth" IS NULL) OR (("previous_depth" >= 0) AND ("previous_depth" <= 80))) AND (("new_depth" IS NULL) OR (("new_depth" >= 0) AND ("new_depth" <= 80))))),
    CONSTRAINT "ig_target_followers_resume_checkpoint_events_mode_check" CHECK ((("mode" IS NULL) OR ("mode" = ANY (ARRAY['shadow'::"text", 'enforce'::"text"])))),
    CONSTRAINT "ig_target_followers_resume_checkpoint_events_reason_check" CHECK (("reason" ~ '^[a-z0-9_:-]{1,120}$'::"text")),
    CONSTRAINT "ig_target_followers_resume_checkpoint_events_type_check" CHECK (("event_type" = ANY (ARRAY['claimed'::"text", 'renewed'::"text", 'reclaimed'::"text", 'committed'::"text", 'released'::"text", 'invalidated'::"text", 'reset'::"text"]))),
    CONSTRAINT "ig_target_followers_resume_checkpoint_events_version_check" CHECK (((("previous_optimistic_version" IS NULL) OR ("previous_optimistic_version" >= 1)) AND (("new_optimistic_version" IS NULL) OR ("new_optimistic_version" >= 1)))),
    CONSTRAINT "ig_tfr_checkpoint_events_metadata_bounds_check" CHECK ((("jsonb_typeof"("metadata") = 'object'::"text") AND ("pg_column_size"("metadata") <= 4096)))
);




CREATE TABLE IF NOT EXISTS "public"."ig_target_followers_resume_checkpoints" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "account_id" "uuid" NOT NULL,
    "target_id" "uuid" NOT NULL,
    "surface" "text" DEFAULT 'followers'::"text" NOT NULL,
    "checkpoint_version" integer DEFAULT 2 NOT NULL,
    "last_safe_depth" integer DEFAULT 0 NOT NULL,
    "last_safe_anchor" "text",
    "anchor_fingerprint" "text",
    "last_visible_anchor_hashes" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "shadow_last_safe_depth" integer DEFAULT 0 NOT NULL,
    "shadow_last_safe_anchor" "text",
    "shadow_anchor_fingerprint" "text",
    "shadow_visible_anchor_hashes" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "last_run_id" "uuid",
    "last_reached_at" timestamp with time zone,
    "last_instagram_version" "text",
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "invalidation_reason" "text",
    "optimistic_version" bigint DEFAULT 1 NOT NULL,
    "lease_owner_run_id" "uuid",
    "lease_mode" "text",
    "lease_expires_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "last_verified_at" timestamp with time zone,
    "end_reached" boolean DEFAULT false NOT NULL,
    "lease_heartbeat_at" timestamp with time zone,
    "lease_generation" bigint DEFAULT 0 NOT NULL,
    CONSTRAINT "ig_target_followers_resume_checkpoint_anchor_arrays_check" CHECK ((("jsonb_typeof"("last_visible_anchor_hashes") = 'array'::"text") AND ("jsonb_array_length"("last_visible_anchor_hashes") <= 12) AND ("jsonb_typeof"("shadow_visible_anchor_hashes") = 'array'::"text") AND ("jsonb_array_length"("shadow_visible_anchor_hashes") <= 12))),
    CONSTRAINT "ig_target_followers_resume_checkpoint_anchor_bounds_check" CHECK (((COALESCE("length"("last_safe_anchor"), 0) <= 64) AND (COALESCE("length"("anchor_fingerprint"), 0) <= 64) AND (COALESCE("length"("shadow_last_safe_anchor"), 0) <= 64) AND (COALESCE("length"("shadow_anchor_fingerprint"), 0) <= 64))),
    CONSTRAINT "ig_target_followers_resume_checkpoint_depth_check" CHECK (((("last_safe_depth" >= 0) AND ("last_safe_depth" <= 80)) AND (("shadow_last_safe_depth" >= 0) AND ("shadow_last_safe_depth" <= 80)))),
    CONSTRAINT "ig_target_followers_resume_checkpoint_lease_check" CHECK (((("lease_owner_run_id" IS NULL) AND ("lease_mode" IS NULL) AND ("lease_expires_at" IS NULL) AND ("lease_heartbeat_at" IS NULL)) OR (("lease_owner_run_id" IS NOT NULL) AND ("lease_mode" = ANY (ARRAY['shadow'::"text", 'enforce'::"text"])) AND ("lease_expires_at" IS NOT NULL) AND ("lease_heartbeat_at" IS NOT NULL)))),
    CONSTRAINT "ig_target_followers_resume_checkpoint_lease_generation_check" CHECK (("lease_generation" >= 0)),
    CONSTRAINT "ig_target_followers_resume_checkpoint_optimistic_version_check" CHECK (("optimistic_version" >= 1)),
    CONSTRAINT "ig_target_followers_resume_checkpoint_reason_bounds_check" CHECK ((COALESCE("length"("invalidation_reason"), 0) <= 120)),
    CONSTRAINT "ig_target_followers_resume_checkpoint_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'stale'::"text", 'reset_required'::"text", 'exhausted'::"text", 'invalidated'::"text"]))),
    CONSTRAINT "ig_target_followers_resume_checkpoint_surface_check" CHECK (("surface" = 'followers'::"text")),
    CONSTRAINT "ig_target_followers_resume_checkpoint_timestamps_check" CHECK (("updated_at" >= "created_at")),
    CONSTRAINT "ig_target_followers_resume_checkpoint_version_check" CHECK (("checkpoint_version" = 3)),
    CONSTRAINT "ig_tfr_checkpoint_instagram_version_bounds_check" CHECK ((COALESCE("length"("last_instagram_version"), 0) <= 80))
);




