    CONSTRAINT "phone_rest_windows_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'disabled'::"text"]))),
    CONSTRAINT "phone_rest_windows_timezone_nonempty_check" CHECK (("char_length"(TRIM(BOTH FROM "timezone")) > 0)),
