CREATE TABLE IF NOT EXISTS "public"."prospecting_call_logs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "created_at" timestamp without time zone DEFAULT "now"(),
    "restaurant_name" "text",
    "phone" "text",
    "call_status" "text",
    "intent" "text",
    "conversion" boolean DEFAULT false,
    "channel" "text",
    "call_duration" integer,
    "cost" numeric,
    "notes" "text",
    "cost_vapi" numeric,
    "cost_twilio" numeric,
    "cost_total" numeric,
    "call_cost_usd" numeric DEFAULT 0,
    "sms_cost_usd" numeric DEFAULT 0,
    "email_cost_usd" numeric DEFAULT 0,
    "api_cost_usd" numeric DEFAULT 0,
    "total_variable_cost_usd" numeric GENERATED ALWAYS AS ((((COALESCE("call_cost_usd", (0)::numeric) + COALESCE("sms_cost_usd", (0)::numeric)) + COALESCE("email_cost_usd", (0)::numeric)) + COALESCE("api_cost_usd", (0)::numeric))) STORED
);




CREATE OR REPLACE VIEW "public"."prospecting_dashboard" AS
 SELECT "date_trunc"('day'::"text", "created_at") AS "day",
    "count"(*) AS "total_calls",
    "count"(*) FILTER (WHERE ("call_status" = 'completed'::"text")) AS "completed_calls",
    "count"(*) FILTER (WHERE ("intent" = 'interested'::"text")) AS "interested",
    "count"(*) FILTER (WHERE ("conversion" = true)) AS "conversions",
    "count"(*) FILTER (WHERE ("channel" = 'sms'::"text")) AS "sms_sent",
    "count"(*) FILTER (WHERE ("channel" = 'email'::"text")) AS "email_sent",
    "sum"("cost") AS "total_cost",
    "round"(((("count"(*) FILTER (WHERE ("conversion" = true)))::numeric / (NULLIF("count"(*), 0))::numeric) * (100)::numeric), 2) AS "conversion_rate"
   FROM "public"."prospecting_call_logs"
  GROUP BY ("date_trunc"('day'::"text", "created_at"))
  ORDER BY ("date_trunc"('day'::"text", "created_at")) DESC;




CREATE TABLE IF NOT EXISTS "public"."prospecting_fixed_costs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "month" "text" NOT NULL,
    "tool_name" "text" NOT NULL,
    "cost_usd" numeric NOT NULL,
    "notes" "text",
    "created_at" timestamp without time zone DEFAULT "now"()
);




CREATE OR REPLACE VIEW "public"."prospecting_roi_dashboard" AS
 SELECT "to_char"("now"(), 'YYYY-MM'::"text") AS "month",
    "count"(*) AS "total_calls",
    "count"(*) FILTER (WHERE ("call_status" = 'completed'::"text")) AS "completed_calls",
    "count"(*) FILTER (WHERE ("intent" = 'interested'::"text")) AS "interested_leads",
    COALESCE("sum"("total_variable_cost_usd"), (0)::numeric) AS "total_variable_cost",
    COALESCE(( SELECT "sum"("prospecting_fixed_costs"."cost_usd") AS "sum"
           FROM "public"."prospecting_fixed_costs"
          WHERE ("prospecting_fixed_costs"."month" = "to_char"("now"(), 'YYYY-MM'::"text"))), (0)::numeric) AS "total_fixed_cost",
    (COALESCE("sum"("total_variable_cost_usd"), (0)::numeric) + COALESCE(( SELECT "sum"("prospecting_fixed_costs"."cost_usd") AS "sum"
           FROM "public"."prospecting_fixed_costs"
          WHERE ("prospecting_fixed_costs"."month" = "to_char"("now"(), 'YYYY-MM'::"text"))), (0)::numeric)) AS "total_cost",
    "round"((COALESCE("sum"("total_variable_cost_usd"), (0)::numeric) / (NULLIF("count"(*), 0))::numeric), 4) AS "variable_cost_per_call",
    "round"(((COALESCE("sum"("total_variable_cost_usd"), (0)::numeric) + COALESCE(( SELECT "sum"("prospecting_fixed_costs"."cost_usd") AS "sum"
           FROM "public"."prospecting_fixed_costs"
          WHERE ("prospecting_fixed_costs"."month" = "to_char"("now"(), 'YYYY-MM'::"text"))), (0)::numeric)) / (NULLIF("count"(*), 0))::numeric), 4) AS "full_cost_per_call",
    "round"(((COALESCE("sum"("total_variable_cost_usd"), (0)::numeric) + COALESCE(( SELECT "sum"("prospecting_fixed_costs"."cost_usd") AS "sum"
           FROM "public"."prospecting_fixed_costs"
          WHERE ("prospecting_fixed_costs"."month" = "to_char"("now"(), 'YYYY-MM'::"text"))), (0)::numeric)) / (NULLIF("count"(*) FILTER (WHERE ("intent" = 'interested'::"text")), 0))::numeric), 4) AS "cost_per_interested_lead"
   FROM "public"."prospecting_call_logs"
  WHERE ("created_at" >= "date_trunc"('month'::"text", "now"()));




