    "location_id" "uuid" NOT NULL,
    "day_of_week" integer NOT NULL,
    "open_time" time without time zone NOT NULL,
    "close_time" time without time zone NOT NULL,
    "is_closed" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "restaurant_business_hours_day_of_week_check" CHECK ((("day_of_week" >= 0) AND ("day_of_week" <= 6)))
);




CREATE TABLE IF NOT EXISTS "public"."restaurant_prospect_events" (
    "id" bigint NOT NULL,
    "external_id" "text",
    "campaign_id" "text",
    "event_type" "text" NOT NULL,
    "payload" "jsonb",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "prospect_id" "uuid"
);




COMMENT ON TABLE "public"."restaurant_prospect_events" IS 'Append-only event log. One row per action taken on a lead. Never updated or deleted. Used for debugging, analytics, and pipeline reporting.';



COMMENT ON COLUMN "public"."restaurant_prospect_events"."event_type" IS 'Event classifier. Current values: outreach_prepared, workflow_error. Extend as needed: email_sent, reply_received, demo_booked.';



COMMENT ON COLUMN "public"."restaurant_prospect_events"."payload" IS 'Full n8n $json snapshot at time of event. Contains all lead fields, analysis, outreach copy, and any error details.';



CREATE OR REPLACE VIEW "public"."restaurant_conversion_funnel" AS
 SELECT "count"(DISTINCT "prospect_id") FILTER (WHERE ("event_type" = 'booking_link_sent'::"text")) AS "links_sent",
    "count"(DISTINCT "prospect_id") FILTER (WHERE ("event_type" = 'link_clicked'::"text")) AS "link_clicks",
    "count"(DISTINCT "prospect_id") FILTER (WHERE ("event_type" = 'demo_booked'::"text")) AS "demos_booked",
    "round"(((("count"(DISTINCT "prospect_id") FILTER (WHERE ("event_type" = 'link_clicked'::"text")))::numeric / (NULLIF("count"(DISTINCT "prospect_id") FILTER (WHERE ("event_type" = 'booking_link_sent'::"text")), 0))::numeric) * (100)::numeric), 2) AS "click_rate_percent",
    "round"(((("count"(DISTINCT "prospect_id") FILTER (WHERE ("event_type" = 'demo_booked'::"text")))::numeric / (NULLIF("count"(DISTINCT "prospect_id") FILTER (WHERE ("event_type" = 'booking_link_sent'::"text")), 0))::numeric) * (100)::numeric), 2) AS "booking_rate_percent"
   FROM "public"."restaurant_prospect_events"
  WHERE ("campaign_id" = 'restaurant_call_assistant_v2'::"text");




CREATE OR REPLACE VIEW "public"."restaurant_prospect_funnel" AS
 SELECT "prospect_id",
    "min"("created_at") FILTER (WHERE ("event_type" = 'booking_link_sent'::"text")) AS "link_sent_at",
    "min"("created_at") FILTER (WHERE ("event_type" = 'link_clicked'::"text")) AS "first_clicked_at",
    "min"("created_at") FILTER (WHERE ("event_type" = 'demo_booked'::"text")) AS "booked_at",
    "bool_or"(("event_type" = 'booking_link_sent'::"text")) AS "link_sent",
    "bool_or"(("event_type" = 'link_clicked'::"text")) AS "clicked",
    "bool_or"(("event_type" = 'demo_booked'::"text")) AS "booked"
   FROM "public"."restaurant_prospect_events"
  WHERE ("prospect_id" IS NOT NULL)
  GROUP BY "prospect_id";




CREATE OR REPLACE VIEW "public"."restaurant_conversion_speed" AS
 SELECT "prospect_id",
    (EXTRACT(epoch FROM ("booked_at" - "first_clicked_at")) / (60)::numeric) AS "minutes_to_convert"
   FROM "public"."restaurant_prospect_funnel" "p"
  WHERE (("booked_at" IS NOT NULL) AND ("first_clicked_at" IS NOT NULL));




CREATE OR REPLACE VIEW "public"."restaurant_conversion_timeseries" AS
 SELECT "date"("created_at") AS "day",
    "count"(DISTINCT "prospect_id") FILTER (WHERE ("event_type" = 'booking_link_sent'::"text")) AS "links_sent",
    "count"(DISTINCT "prospect_id") FILTER (WHERE ("event_type" = 'link_clicked'::"text")) AS "clicks",
    "count"(DISTINCT "prospect_id") FILTER (WHERE ("event_type" = 'demo_booked'::"text")) AS "bookings"
   FROM "public"."restaurant_prospect_events"
  WHERE ("campaign_id" = 'restaurant_call_assistant_v2'::"text")
  GROUP BY ("date"("created_at"))
  ORDER BY ("date"("created_at"));




