CREATE OR REPLACE VIEW "public"."restaurant_dashboard_summary" AS
 SELECT "t"."id" AS "tenant_id",
    "t"."name" AS "tenant_name",
    "t"."slug" AS "tenant_slug",
    "t"."plan",
    "t"."monthly_call_limit",
    "l"."id" AS "location_id",
    "l"."name" AS "location_name",
    "count"(DISTINCT "cs"."id") AS "total_calls",
    "count"(DISTINCT "r"."id") AS "total_reservations",
    "count"(DISTINCT "h"."id") AS "total_escalations",
    "count"(DISTINCT "f"."id") FILTER (WHERE (("f"."channel" = 'sms'::"text") AND ("f"."status" = 'sent'::"text"))) AS "sms_followups_sent",
    "count"(DISTINCT "f"."id") FILTER (WHERE (("f"."channel" = 'whatsapp'::"text") AND ("f"."status" = 'sent'::"text"))) AS "whatsapp_followups_sent",
    "count"(DISTINCT "f"."id") FILTER (WHERE ("f"."status" = 'failed'::"text")) AS "failed_followups",
    "round"(
        CASE
            WHEN ("count"(DISTINCT "cs"."id") = 0) THEN (0)::numeric
            ELSE ((("count"(DISTINCT "r"."id"))::numeric / ("count"(DISTINCT "cs"."id"))::numeric) * (100)::numeric)
        END, 2) AS "call_to_booking_rate",
    "round"(
        CASE
            WHEN (("t"."monthly_call_limit" IS NULL) OR ("t"."monthly_call_limit" = 0)) THEN (0)::numeric
            ELSE ((("count"(DISTINCT "cs"."id"))::numeric / ("t"."monthly_call_limit")::numeric) * (100)::numeric)
        END, 2) AS "quota_usage_percent",
    "t"."average_ticket_eur",
    "round"((("count"(DISTINCT "r"."id"))::numeric * COALESCE("t"."average_ticket_eur", (25)::numeric)), 2) AS "estimated_revenue_eur",
    "round"(((("count"(DISTINCT "f"."id") FILTER (WHERE (("f"."channel" = ANY (ARRAY['sms'::"text", 'whatsapp'::"text"])) AND ("f"."status" = 'sent'::"text"))))::numeric * COALESCE("t"."average_ticket_eur", (25)::numeric)) * 0.30), 2) AS "estimated_followup_recovered_revenue_eur",
    "t"."average_ticket_usd",
    "t"."average_ticket_zar",
    "round"((("count"(DISTINCT "r"."id"))::numeric * COALESCE("t"."average_ticket_usd", (27)::numeric)), 2) AS "estimated_revenue_usd",
    "round"((("count"(DISTINCT "r"."id"))::numeric * COALESCE("t"."average_ticket_zar", (500)::numeric)), 2) AS "estimated_revenue_zar",
    "round"(((("count"(DISTINCT "f"."id") FILTER (WHERE (("f"."channel" = ANY (ARRAY['sms'::"text", 'whatsapp'::"text"])) AND ("f"."status" = 'sent'::"text"))))::numeric * COALESCE("t"."average_ticket_usd", (27)::numeric)) * 0.30), 2) AS "estimated_followup_recovered_revenue_usd",
    "round"(((("count"(DISTINCT "f"."id") FILTER (WHERE (("f"."channel" = ANY (ARRAY['sms'::"text", 'whatsapp'::"text"])) AND ("f"."status" = 'sent'::"text"))))::numeric * COALESCE("t"."average_ticket_zar", (500)::numeric)) * 0.30), 2) AS "estimated_followup_recovered_revenue_zar"
   FROM ((((("public"."restaurant_tenants" "t"
     LEFT JOIN "public"."restaurant_locations" "l" ON (("l"."tenant_id" = "t"."id")))
     LEFT JOIN "public"."restaurant_call_sessions" "cs" ON ((("cs"."tenant_id" = "t"."id") AND ("cs"."location_id" = "l"."id") AND ("cs"."started_at" >= "date_trunc"('month'::"text", "now"())))))
     LEFT JOIN "public"."restaurant_reservations" "r" ON ((("r"."tenant_id" = "t"."id") AND ("r"."location_id" = "l"."id") AND ("r"."created_at" >= "date_trunc"('month'::"text", "now"())))))
     LEFT JOIN "public"."restaurant_handoffs" "h" ON ((("h"."tenant_id" = "t"."id") AND ("h"."location_id" = "l"."id") AND ("h"."created_at" >= "date_trunc"('month'::"text", "now"())))))
     LEFT JOIN "public"."restaurant_followups" "f" ON ((("f"."tenant_id" = "t"."id") AND ("f"."location_id" = "l"."id") AND ("f"."created_at" >= "date_trunc"('month'::"text", "now"())))))
  GROUP BY "t"."id", "t"."name", "t"."slug", "t"."plan", "t"."monthly_call_limit", "t"."average_ticket_eur", "t"."average_ticket_usd", "t"."average_ticket_zar", "l"."id", "l"."name";




CREATE OR REPLACE VIEW "public"."restaurant_dashboard_filtered" AS
 SELECT "tenant_id",
    "tenant_name",
    "tenant_slug",
    "plan",
    "location_id",
    "location_name",
    "total_calls",
    "total_reservations",
    "total_escalations",
    "call_to_booking_rate",
    "quota_usage_percent",
        CASE
            WHEN ("plan" = ANY (ARRAY['pro'::"public"."restaurant_app_plan", 'enterprise'::"public"."restaurant_app_plan"])) THEN "sms_followups_sent"
            ELSE NULL::bigint
        END AS "sms_followups_sent",
        CASE
            WHEN ("plan" = ANY (ARRAY['pro'::"public"."restaurant_app_plan", 'enterprise'::"public"."restaurant_app_plan"])) THEN "whatsapp_followups_sent"
            ELSE NULL::bigint
        END AS "whatsapp_followups_sent",
        CASE
            WHEN ("plan" = ANY (ARRAY['pro'::"public"."restaurant_app_plan", 'enterprise'::"public"."restaurant_app_plan"])) THEN "failed_followups"
            ELSE NULL::bigint
        END AS "failed_followups",
        CASE
            WHEN ("plan" = ANY (ARRAY['pro'::"public"."restaurant_app_plan", 'enterprise'::"public"."restaurant_app_plan"])) THEN "average_ticket_eur"
            ELSE NULL::numeric
        END AS "average_ticket_eur",
        CASE
            WHEN ("plan" = ANY (ARRAY['pro'::"public"."restaurant_app_plan", 'enterprise'::"public"."restaurant_app_plan"])) THEN "estimated_revenue_eur"
            ELSE NULL::numeric
        END AS "estimated_revenue_eur",
        CASE
            WHEN ("plan" = ANY (ARRAY['pro'::"public"."restaurant_app_plan", 'enterprise'::"public"."restaurant_app_plan"])) THEN "estimated_followup_recovered_revenue_eur"
            ELSE NULL::numeric
        END AS "estimated_followup_recovered_revenue_eur"
   FROM "public"."restaurant_dashboard_summary";




