CREATE TABLE IF NOT EXISTS "public"."restaurant_prospect_leads" (
    "id" bigint NOT NULL,
    "external_id" "text" NOT NULL,
    "campaign_id" "text",
    "restaurant_name" "text" NOT NULL,
    "phone" "text",
    "email" "text",
    "website" "text",
    "address" "text",
    "cuisine" "text",
    "rating" numeric(3,1),
    "reviews_count" integer,
    "lead_score" integer,
    "priority" "public"."lead_priority",
    "status" "public"."lead_status" DEFAULT 'new'::"public"."lead_status" NOT NULL,
    "last_channel_used" "text",
    "contacted_at" timestamp with time zone,
    "analysis" "jsonb",
    "outreach" "jsonb",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "restaurant_prospect_leads_lead_score_check" CHECK ((("lead_score" >= 0) AND ("lead_score" <= 100)))
);




COMMENT ON TABLE "public"."restaurant_prospect_leads" IS 'One row per restaurant lead. Upserted on external_id. Tracks full lifecycle from raw lead to booked demo.';



COMMENT ON COLUMN "public"."restaurant_prospect_leads"."external_id" IS 'Stable dedup key from source (Apify placeId, Apollo id, etc). Used as upsert key in n8n nodes 14, 17, 21, 24, 27.';



COMMENT ON COLUMN "public"."restaurant_prospect_leads"."status" IS 'CRM lifecycle: new → qualified/low_score → contacted → replied → booked/closed/not_interested.';



COMMENT ON COLUMN "public"."restaurant_prospect_leads"."analysis" IS 'Raw JSON from node 12 AI Lead Analyzer. Fields: lead_score, priority, reason, pain_points, recommended_channel, personalization_angle.';



COMMENT ON COLUMN "public"."restaurant_prospect_leads"."outreach" IS 'Raw JSON from node 16 Parse Outreach Copy. Fields: email_subject, email_body, whatsapp_message, call_opening_script.';



