    "id" bigint NOT NULL,
    "external_id" "text" NOT NULL,
    "campaign_id" "text",
    "task_type" "text" NOT NULL,
    "status" "public"."task_status" DEFAULT 'pending_review'::"public"."task_status" NOT NULL,
    "due_at" timestamp with time zone,
    "reviewed_by" "text",
    "reviewed_at" timestamp with time zone,
    "payload" "jsonb",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);




COMMENT ON TABLE "public"."restaurant_prospect_tasks" IS 'Follow-up task queue. One row per scheduled action. Reviewed by a human (or auto-approved) before execution by a separate cron flow.';



COMMENT ON COLUMN "public"."restaurant_prospect_tasks"."task_type" IS 'Task classifier. Current values: follow_up_j2. Extend for: follow_up_j5, follow_up_j10, manual_call, demo_reminder.';



COMMENT ON COLUMN "public"."restaurant_prospect_tasks"."status" IS 'HITL lifecycle: pending_review → approved → sent. Or: pending_review → cancelled. Or: approved → failed.';



COMMENT ON COLUMN "public"."restaurant_prospect_tasks"."due_at" IS 'Target execution timestamp. Set by node 31 to now() + 2 days. The follow-up cron flow queries WHERE status = pending_review AND due_at <= now().';



COMMENT ON COLUMN "public"."restaurant_prospect_tasks"."payload" IS 'Full n8n $json at time of task creation. Includes original lead, analysis, initial outreach, and follow-up copy generated by node 30.';



