CREATE OR REPLACE VIEW "public"."v_pipeline_summary" AS
 SELECT "campaign_id",
    "count"(*) AS "total_leads",
    "count"(*) FILTER (WHERE ("status" = 'low_score'::"public"."lead_status")) AS "low_score",
    "count"(*) FILTER (WHERE ("status" = 'qualified'::"public"."lead_status")) AS "qualified",
    "count"(*) FILTER (WHERE ("status" = 'contacted'::"public"."lead_status")) AS "contacted",
    "count"(*) FILTER (WHERE ("status" = 'replied'::"public"."lead_status")) AS "replied",
    "count"(*) FILTER (WHERE ("status" = 'booked'::"public"."lead_status")) AS "booked",
    "count"(*) FILTER (WHERE ("status" = 'not_interested'::"public"."lead_status")) AS "not_interested",
    "round"("avg"("lead_score"), 1) AS "avg_score",
    "round"(((100.0 * ("count"(*) FILTER (WHERE ("status" = 'booked'::"public"."lead_status")))::numeric) / (NULLIF("count"(*) FILTER (WHERE ("status" = 'contacted'::"public"."lead_status")), 0))::numeric), 1) AS "booking_rate_pct"
   FROM "public"."restaurant_prospect_leads"
  GROUP BY "campaign_id"
  ORDER BY "campaign_id";




COMMENT ON VIEW "public"."v_pipeline_summary" IS 'Conversion funnel per campaign. Useful for measuring pipeline health at a glance.';



CREATE OR REPLACE VIEW "public"."v_tasks_due" AS
 SELECT "t"."id",
    "t"."external_id",
    "t"."campaign_id",
    "t"."task_type",
    "t"."due_at",
    "t"."payload",
    "l"."restaurant_name",
    "l"."email",
    "l"."phone",
    "l"."last_channel_used",
    "l"."lead_score",
    "l"."priority"
   FROM ("public"."restaurant_prospect_tasks" "t"
     LEFT JOIN "public"."restaurant_prospect_leads" "l" USING ("external_id"))
  WHERE (("t"."status" = 'pending_review'::"public"."task_status") AND ("t"."due_at" <= "now"()))
  ORDER BY "t"."due_at";




COMMENT ON VIEW "public"."v_tasks_due" IS 'Follow-up tasks that are past due_at and still pending review. Query this in the follow-up cron flow.';



